func (s *Server) withWorkClassTxTaggedForViewer(ctx context.Context, class foundationcontract.WorkClass, lane string, retry database.RetryOptions, accountID, profileID string, tags []string, fn func(*sql.Tx) error) error {
	if ctx == nil {
		ctx = context.Background()
	}
	start := time.Now()
	release, err := s.dbWriteScheduler.acquire(ctx, class)
	if err != nil {
		s.recordSQLiteWriteMetrics(lane, database.RetryStats{}, time.Since(start), err)
		return err
	}
	db := s.dbHandle()
	if db == nil {
		release()
		err := errors.New("sqlite handle is not available")
		s.recordSQLiteWriteMetrics(lane, database.RetryStats{}, time.Since(start), err)
		return err
	}
	stats, err := database.WithTxRetryStats(ctx, db, retry, fn)
	release()
	s.recordSQLiteWriteMetrics(lane, stats, time.Since(start), err)
	if err == nil {
		s.invalidateAuthorizationCachesForMutation("", tags)
	}
	if err == nil && len(tags) > 0 {
		s.publishDataChangedForViewer("data.changed", tags, "database", "", nil, accountID, profileID)
	}
	return err
}

func (s *Server) execBackgroundWrite(ctx context.Context, query string, args ...any) (sql.Result, error) {
	return s.execBackgroundWriteTagged(ctx, nil, query, args...)
}

func (s *Server) execBackgroundWriteTagged(ctx context.Context, tags []string, query string, args ...any) (sql.Result, error) {
	return s.execWorkClassWriteTaggedForViewer(ctx, foundationcontract.WorkClassBackgroundMedia, "background", database.BackgroundWriteRetry, "", "", tags, query, args...)
}

func (s *Server) withBackgroundTx(ctx context.Context, fn func(*sql.Tx) error) error {
	return s.withBackgroundTxTagged(ctx, []string{"database", "background"}, fn)
}

func (s *Server) withBackgroundTxTagged(ctx context.Context, tags []string, fn func(*sql.Tx) error) error {
	return s.withWorkClassTxTaggedForViewer(ctx, foundationcontract.WorkClassBackgroundMedia, "background_tx", database.BackgroundWriteRetry, "", "", tags, fn)
}

func (s *Server) recordSQLiteReadMetrics(lane string, elapsed time.Duration, err error) {
	if elapsed <= 0 && err == nil {
		return
	}
	s.latencyMetrics.observeSQLiteRead(lane, elapsed)
	s.sqliteMetricsMu.Lock()
	metrics := &s.sqliteMetrics
	metrics.ReadOperations++
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		metrics.ReadErrors++
		metrics.LastError = err.Error()
		metrics.LastErrorKind = string(database.ClassifyError(err))
		metrics.LastErrorAt = time.Now().UTC().Format(time.RFC3339)
	}
	elapsedMillis := elapsed.Milliseconds()
	if elapsedMillis > metrics.SlowestReadMillis {
		metrics.SlowestReadMillis = elapsedMillis
		metrics.SlowestReadLane = lane
	}
	s.sqliteMetricsMu.Unlock()

	if s.log != nil && (elapsed >= 250*time.Millisecond || (err != nil && !errors.Is(err, sql.ErrNoRows))) {
		fields := []any{"lane", lane, "duration_ms", elapsed.Milliseconds()}
		if err != nil {
			fields = append(fields, "error", err, "kind", database.ClassifyError(err))
		}
		s.log.Warn("foreground SQLite read delayed", fields...)
	}
}

func (s *Server) recordSQLiteWriteMetrics(lane string, retryStats database.RetryStats, elapsed time.Duration, err error) {
	if retryStats.Attempts == 0 && elapsed <= 0 && err == nil {
		return
	}
	s.latencyMetrics.observeSQLiteWrite(lane, elapsed)
	s.sqliteMetricsMu.Lock()
	defer s.sqliteMetricsMu.Unlock()
	metrics := &s.sqliteMetrics
	metrics.WriteOperations++
	metrics.WriteAttempts += int64(retryStats.Attempts)
	metrics.LockRetries += int64(retryStats.Retries)
	metrics.LockRetryWaitMillis += retryStats.Wait.Milliseconds()
	if retryStats.Retries > 0 {
		metrics.LastRetryAt = time.Now().UTC().Format(time.RFC3339)
		metrics.LastRetryLane = lane
		metrics.LastRetryWaitMillis = retryStats.Wait.Milliseconds()
	}
	elapsedMillis := elapsed.Milliseconds()
	if elapsedMillis > metrics.SlowestWriteMillis {
		metrics.SlowestWriteMillis = elapsedMillis
		metrics.SlowestWriteLane = lane
	}
	if err != nil {
		metrics.LastError = err.Error()
		metrics.LastErrorKind = string(database.ClassifyError(err))
		metrics.LastErrorAt = time.Now().UTC().Format(time.RFC3339)
	}
}

func (s *Server) sqliteDiagnostics() SQLiteDiagnostics {
	s.sqliteMetricsMu.Lock()
	metrics := s.sqliteMetrics
	s.sqliteMetricsMu.Unlock()
	metrics.ReadLatency = s.latencyMetrics.sqliteReadSnapshot()
	metrics.WriteLatency = s.latencyMetrics.sqliteWriteSnapshot()
	db := s.dbHandle()
	if db == nil {
		return metrics
	}
	stats := db.Stats()
	metrics.MaxOpenConnections = stats.MaxOpenConnections
	metrics.OpenConnections = stats.OpenConnections
	metrics.InUseConnections = stats.InUse
	metrics.IdleConnections = stats.Idle
	metrics.WaitCount = stats.WaitCount
	metrics.WaitDurationMillis = stats.WaitDuration.Milliseconds()
	metrics.DatabaseBytes = fileSizeQuiet(s.cfg.DatabasePath)
	metrics.WALBytes = fileSizeQuiet(s.cfg.DatabasePath + "-wal")
	metrics.SHMBytes = fileSizeQuiet(s.cfg.DatabasePath + "-shm")
	_ = db.QueryRow(`PRAGMA journal_mode`).Scan(&metrics.JournalMode)
	_ = db.QueryRow(`PRAGMA wal_autocheckpoint`).Scan(&metrics.WALAutoCheckpointPages)
	// cache_size and mmap_size are connection-local. Read the whole profile on
	// one pinned connection so diagnostics never combine unrelated pooled
	// connection state.
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	if conn, err := db.Conn(ctx); err == nil {
		defer conn.Close()
		_ = conn.QueryRowContext(ctx, `PRAGMA page_size`).Scan(&metrics.PageSizeBytes)
		_ = conn.QueryRowContext(ctx, `PRAGMA page_count`).Scan(&metrics.PageCount)
		_ = conn.QueryRowContext(ctx, `PRAGMA freelist_count`).Scan(&metrics.FreePageCount)
		_ = conn.QueryRowContext(ctx, `PRAGMA cache_size`).Scan(&metrics.ConnectionCachePages)
		_ = conn.QueryRowContext(ctx, `PRAGMA mmap_size`).Scan(&metrics.ConnectionMmapBytes)
	}
	if metrics.PageCount > 0 {
		metrics.FreePageRatio = float64(metrics.FreePageCount) / float64(metrics.PageCount)
	}
	return metrics
}

func (s *Server) sqliteExclusiveMaintenanceAllowed() bool {
	if s.dbWriteScheduler.activeOrWaiting() {
		return false
	}
	s.streamMu.Lock()
	defer s.streamMu.Unlock()
	for _, active := range s.streamActive {
		if active > 0 {
			return false
		}
	}
	return true
}

func fileSizeQuiet(path string) int64 {
	if strings.TrimSpace(path) == "" {
		return 0
	}
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return 0
	}
	return info.Size()
}

