// NewServer constructs and starts a normal serving generation. The host uses
// NewInertServer while a replacement database is being opened and health
// checked; no background worker is allowed to observe that generation before
// the host explicitly activates it.
func NewServer(cfg config.Config, db *sql.DB, log *slog.Logger) *Server {
	server := newServer(cfg, db, log, false)
	server.ActivateRuntimeGeneration()
	return server
}

// NewInertServer constructs a fully initialized generation without starting
// schedulers, listeners, watchdogs, or deferred maintenance. It is the only
// safe constructor for restore replacement and startup recovery boundaries.
func NewInertServer(cfg config.Config, db *sql.DB, log *slog.Logger) *Server {
	return newServer(cfg, db, log, false)
}

func newServer(cfg config.Config, db *sql.DB, log *slog.Logger, startBackground bool) *Server {
	backgroundCtx, backgroundCancel := context.WithCancel(context.Background())
	server := &Server{
		cfg:                         cfg,
		secretProvider:              NewSecretKeyProvider(cfg.AppDataDir),
		db:                          db,
		sqliteDBOpener:              database.OpenRuntimeHandleContext,
		startedAt:                   time.Now().UTC(),
		startupPhases:               map[string]startupPhaseState{},
		log:                         log,
		backgroundCtx:               backgroundCtx,
		backgroundCancel:            backgroundCancel,
		ffmpegProbeCache:            map[string]ffmpegProbeCacheEntry{},
		ffmpegProbeRefreshes:        map[string]bool{},
		playbackHardwareRuntime:     newPlaybackHardwareRuntime(nil),
		homeCache:                   map[string]homeCacheEntry{},
		homeInFlight:                map[string]chan struct{}{},
		mediaDetailCache:            map[string]mediaDetailCacheEntry{},
		mediaDetailInFlight:         map[string]chan struct{}{},
		hostedDocumentPublicKeys:    copyHostedDocumentPublicKeys(cfg.HostedDocumentPublicKeys),
		porticoAttachmentHandshakes: map[string]*porticoAttachmentHandshakeState{},
		suggestionsCache:            map[string]suggestionsCacheEntry{},
		suggestionsInFlight:         map[string]chan struct{}{},
		smartPlaylistCache:          map[string]smartPlaylistCacheEntry{},
		dashboardCache:              map[string]dashboardCacheEntry{},
		dashboardInFlight:           map[string]chan struct{}{},
		dashboardUsageCache:         map[string]dashboardOverviewUsageCacheEntry{},
		dashboardUsageInFlight:      map[string]chan struct{}{},
		metadataHealthCache:         map[string]metadataHealthCacheEntry{},
		metadataHealthRefreshes:     map[string]chan struct{}{},
		categoryCache:               map[string]categoryCacheEntry{},
		categoryInFlight:            map[string]chan struct{}{},
		artworkIngestInFlight:       map[string]*artworkIngestCall{},
		artworkTransformInFlight:    map[string]*artworkTransformCall{},
		artworkWorkSlots:            make(chan struct{}, artworkTransformConcurrency()),
		artworkNegativeCache:        map[string]time.Time{},
		artworkResolutionInFlight:   map[string]*artworkResolutionCall{},
		readModelRepairs:            map[string]chan struct{}{},
		workloadLanes:               newWorkloadLanes(),
		dlnaBrowseActive:            map[string]int{},
		searchInFlight:              map[string]*searchInFlightCall{},
		playbackCommandWatchers:     map[string]map[chan struct{}]struct{}{},
		watchWithFriendsWatchers:    map[string]map[chan struct{}]struct{}{},
		logSubscribers:              map[chan LogEvent]bool{},
		serverDiagnosticQueue:       make(chan serverDiagnosticRecord, 512),
		clientDiagnosticQueue:       make(chan clientDiagnosticRecord, 256),
		clientDiagnosticWindows:     map[string]clientDiagnosticWindow{},
		appEventSubscribers:         map[chan AppEvent]bool{},
		appEventSubscriberAudience:  map[chan AppEvent]appEventSubscriberAudience{},
		longPoll:                    newLongPollRuntime(),
		gpuInfo:                     detectGPUInfo(),
		scannerWatch:                map[string]string{},
		scannerWatchCursor:          map[string]string{},
		scheduledJobs:               map[string]bool{},
		scheduledJobReservationAt:   map[string]time.Time{},
		presenceTouches:             map[string]time.Time{},
		liveTVHLSReferences:         map[string]liveTVHLSReference{},
		jobWake:                     make(chan struct{}, 1),
		jobRuns:                     map[string]struct{}{},
		jobWorkerID:                 randomID("worker"),
		jobRecoveryReady:            make(chan struct{}),
		jobCancels:                  map[string]context.CancelFunc{},
		transcodes:                  map[string]*transcodeSession{},
		preparedHandoffs:            map[string]preparedPlaybackHandoff{},
		loginAttempts:               map[string][]time.Time{},
		apiKeyAttempts:              map[string][]time.Time{},
		apiKeyUsagePending:          map[string]time.Time{},
	}
	server.ffmpegSupervisor = newTranscodeSupervisorV2(backgroundCtx, ffmpegsupervisor.Config{
		InterruptGrace:  3 * time.Second,
		VODAbandonment:  2 * time.Minute,
		LiveAbandonment: 30 * time.Second,
		StallAfter:      45 * time.Second,
		SnapshotLimit:   200,
	})
	server.recordLog("info", "Portico API initialized", map[string]string{
		"addr":     cfg.Addr,
		"appData":  cfg.AppDataDir,
		"database": cfg.DatabasePath,
		"webDist":  cfg.WebDistDir,
	})
	server.markStartupPhaseComplete("server_constructed", "Server constructed", nil)
	// Build the generated route registry before any background heartbeat may
	// publish capabilities. Handler returns this immutable instance thereafter.
	server.Handler()
	if !startBackground {
		return server
	}
	server.ActivateRuntimeGeneration()
	return server
}

// ActivateRuntimeGeneration starts the complete normal application worker
// set exactly once. Restore replacement constructs an inert generation first,
// runs database/application health checks, and calls this method only after
// those checks pass. Keeping this list beside NewServer preserves parity
// between ordinary startup and host-owned generation replacement.
func (s *Server) ActivateRuntimeGeneration() {
	if s == nil {
		return
	}
	s.runtimeActivationOnce.Do(func() {
		s.setJobRuntimeActive(true)
		s.queueStartupRemoteAccessCertificateMaintenance()
		// Optimized publication markers must be reconciled before the job worker
		// can admit another generation for the same media/preset identity.
		optimizedPublicationsReady := true
		if err := s.reconcileOptimizedV2Publications(s.backgroundCtx); err != nil {
			s.log.Error("optimized publication startup reconciliation failed", "error", err)
			optimizedPublicationsReady = false
		}
		s.startBackground("server-diagnostic-writer", s.runServerDiagnosticWriter)
		s.startBackground("client-diagnostic-writer", s.runClientDiagnosticWriter)
		s.startBackground("startup-job-recovery", s.runStartupJobRecovery)
		s.startBackground("runtime-dependency-prewarm", s.runRuntimeDependencyPrewarm)
		s.startBackground("filesystem-publication-reconciler", s.reconcileFilesystemPublications)
		s.startBackground("ffmpeg-supervisor-sweeper", s.runFFmpegSupervisorSweeper)
		if ffmpegPath := firstNonEmpty(s.cfg.FFmpegPath, "ffmpeg"); strings.TrimSpace(ffmpegPath) != "" {
			s.startBackground("ffmpeg-capability-prewarm", func(ctx context.Context) {
				s.runFFmpegCapabilityPrewarm(ctx, ffmpegPath)
			})
		}
		s.startBackground("dlna-ssdp", s.runDLNASSDP)
		s.startBackground("portico-local-discovery", s.runPorticoLocalDiscovery)
		s.startBackground("telemetry-sampler", s.runTelemetrySampler)
		s.startBackground("discovery-refresher", s.runDiscoveryRefresher)
		s.startBackground("library-startup-scan-catchup", s.runLibraryStartupScanCatchup)
		s.startBackground("library-change-watcher", s.runLibraryChangeWatcher)
		s.startBackground("scheduled-task-scheduler", s.runScheduledTaskScheduler)
		s.startBackground("dvr-scheduler", s.runDVRScheduler)
		s.startBackground("live-tv-lifecycle-reaper", s.runLiveTVLifecycleReaper)
		s.startBackground("library-channel-maintainer", s.runLibraryChannelMaintenance)
		s.startBackground("remote-access-heartbeat", s.runRemoteAccessHeartbeat)
		s.startBackground("remote-access-network-monitor", s.runRemoteAccessNetworkMonitor)
		s.startBackground("remote-tls-listener-repair", s.runRemoteTLSListenerRepair)
		s.startBackground("api-key-usage-writer", s.runAPIKeyUsageWriter)
		if optimizedPublicationsReady {
			s.startBackground("job-worker", s.runJobWorker)
		}
	})
}

type startupPhaseState struct {
	ID          string
	Label       string
	Status      string
	StartedAt   time.Time
	CompletedAt time.Time
	Error       string
}

func (s *Server) markStartupPhaseStarted(id, label string) {
	id = strings.TrimSpace(id)
	if id == "" {
		return
	}
	now := time.Now().UTC()
	s.startupMu.Lock()
	defer s.startupMu.Unlock()
	if s.startupPhases == nil {
		s.startupPhases = map[string]startupPhaseState{}
	}
	s.startupPhases[id] = startupPhaseState{
		ID:        id,
		Label:     firstNonEmpty(strings.TrimSpace(label), id),
		Status:    "running",
		StartedAt: now,
	}
}

func (s *Server) markStartupPhaseComplete(id, label string, phaseErr error) {
	id = strings.TrimSpace(id)
	if id == "" {
		return
	}
	now := time.Now().UTC()
	status := "complete"
	errorText := ""
	if phaseErr != nil {
		status = "failed"
		errorText = phaseErr.Error()
	}
	s.startupMu.Lock()
	defer s.startupMu.Unlock()
	if s.startupPhases == nil {
		s.startupPhases = map[string]startupPhaseState{}
	}
	phase := s.startupPhases[id]
	if phase.ID == "" {
		phase.ID = id
		phase.StartedAt = now
	}
	phase.Label = firstNonEmpty(strings.TrimSpace(label), phase.Label, id)
	phase.Status = status
	phase.CompletedAt = now
	phase.Error = errorText
	s.startupPhases[id] = phase
}

func (s *Server) MarkHTTPReady(addr string) {
	now := time.Now().UTC()
	s.startupMu.Lock()
	s.startupHTTPReadyAt = now
	s.startupHTTPAddr = strings.TrimSpace(addr)
	s.startupMu.Unlock()
	s.markStartupPhaseComplete("http_ready", "HTTP listener ready", nil)
	s.startSQLiteHealthWatchdog()
}

func (s *Server) StartDeferredStartupMaintenance() {
	s.startBackground("startup-sqlite-maintenance", s.runStartupSQLiteMaintenance)
	s.startBackground("startup-operational-retention", s.runStartupOperationalRetention)
	s.startBackground("startup-transcode-generation-cleanup", s.runStartupTranscodeGenerationCleanup)
	s.startBackground("scheduled-operational-retention", s.runScheduledOperationalRetention)
}

func (s *Server) runStartupTranscodeGenerationCleanup(ctx context.Context) {
	if !s.waitForForegroundPressureToEase(ctx) {
		return
	}
	removed, err := s.pruneOrphanedTranscodeGenerations(6 * time.Hour)
	if err != nil {
		s.log.Warn("startup transcode generation cleanup failed", "error", err)
		return
	}
	if removed > 0 {
		s.log.Info("startup transcode generation cleanup completed", "removed", removed)
	}
}

func (s *Server) runStartupSQLiteMaintenance(ctx context.Context) {
	if err := ctx.Err(); err != nil {
		return
	}
	s.markStartupPhaseStarted("startup_sqlite_maintenance", "Deferred SQLite maintenance")
	if !s.waitForForegroundPressureToEase(ctx) {
		return
	}
	started := time.Now()
	_, err := s.execBackgroundWrite(ctx, `
		PRAGMA analysis_limit = 1000;
		PRAGMA optimize;
		ANALYZE;
		PRAGMA wal_checkpoint(PASSIVE);
	`)
	if err != nil {
		s.markStartupPhaseComplete("startup_sqlite_maintenance", "Deferred SQLite maintenance", err)
		s.log.Warn("startup sqlite maintenance failed", "error", err, "duration", time.Since(started).String())
		return
	}
	s.markStartupPhaseComplete("startup_sqlite_maintenance", "Deferred SQLite maintenance", nil)
	s.log.Info("startup sqlite maintenance completed", "duration", time.Since(started).String())
}

func (s *Server) runStartupOperationalRetention(ctx context.Context) {
	if err := ctx.Err(); err != nil {
		return
	}
	s.markStartupPhaseStarted("startup_operational_retention", "Operational table retention")
	if !s.waitForForegroundPressureToEase(ctx) {
		return
	}
	started := time.Now()
	if err := s.pruneOperationalTables(ctx); err != nil {
		s.markStartupPhaseComplete("startup_operational_retention", "Operational table retention", err)
		s.log.Warn("startup operational retention failed", "error", err, "duration", time.Since(started).String())
		return
	}
	s.markStartupPhaseComplete("startup_operational_retention", "Operational table retention", nil)
	s.log.Info("startup operational retention completed", "duration", time.Since(started).String())
}

func (s *Server) runScheduledOperationalRetention(ctx context.Context) {
	ticker := time.NewTicker(6 * time.Hour)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if !s.waitForForegroundPressureToEase(ctx) {
				return
			}
			if err := s.pruneOperationalTables(ctx); err != nil {
				s.log.Warn("scheduled operational retention failed", "error", err)
			}
		}
	}
}

const (
	backgroundForegroundYieldMaximum = 2 * time.Second
	backgroundForegroundPollInterval = 100 * time.Millisecond
)

// foregroundWorkActive is intentionally a memory-only signal. The former
// per-item pressure check rebuilt full resource diagnostics (including several
// SQLite queries), causing the scanner itself to add database pressure. The
// dispatcher still performs the comprehensive diagnostic check before it
// starts jobs; inner background loops only need to know whether foreground
// request lanes currently have work.
func (s *Server) foregroundWorkActive() bool {
	s.workloadMu.Lock()
	defer s.workloadMu.Unlock()
	for _, id := range []string{
		workloadLaneSecurityFence,
		workloadLaneAuth,
		workloadLaneBrowsing,
		workloadLaneExpensive,
		workloadLanePlayback,
		workloadLaneMedia,
		workloadLaneMediaBody,
		workloadLaneBulkTransfer,
		workloadLaneDLNA,
		workloadLaneAdmin,
		workloadLaneAdminHeavy,
		workloadLaneDefault,
	} {
		if lane := s.workloadLanes[id]; lane != nil && len(lane.tokens) > 0 {
			return true
		}
	}
	return false
}

func (s *Server) waitForForegroundPressureToEase(ctx context.Context) bool {
	if ctx == nil {
		ctx = context.Background()
	}
	// SQLite health is a safety fence, not ordinary contention. Do not publish
	// more background state until the watchdog has observed recovery.
	for !sqliteHealthAllowsBackground(s.sqliteHealthSnapshot()) {
		if !sleepContext(ctx, 2*time.Second) {
			return false
		}
	}
	if !s.foregroundWorkActive() {
		return true
	}
	// Give short navigation and playback-control requests an uncontested
	// window. Persistent direct play cannot starve a scan forever: after the
	// window, one already-bounded background unit may advance before yielding
	// again at its next checkpoint.
	deadline := time.Now().Add(backgroundForegroundYieldMaximum)
	for s.foregroundWorkActive() && time.Now().Before(deadline) {
		if !sleepContext(ctx, backgroundForegroundPollInterval) {
			return false
		}
	}
	return true
}

const (
	sqliteHealthStatusHealthy    = "healthy"
	sqliteHealthStatusRecovering = "recovering"
	sqliteHealthStatusDegraded   = "degraded"
	sqliteHealthStatusFailed     = "failed"
	sqliteHealthStatusCorrupt    = "corrupt"

	sqliteHealthProbeTimeout             = 750 * time.Millisecond
	sqliteHealthProbeInterval            = 5 * time.Second
	sqliteHealthDegradedFailureThreshold = 2
	sqliteHealthRecoverySuccessThreshold = 2
	sqliteHealthEvidenceStackBufferBytes = 1 << 20
	sqliteHandleRecycleTimeout           = 5 * time.Second
	sqliteHandleRecycleMinInterval       = 30 * time.Second
)

func (s *Server) startSQLiteHealthWatchdog() {
	if s == nil || s.backgroundCtx == nil {
		return
	}
	s.sqliteWatchdogOnce.Do(func() {
		s.startBackground("sqlite-health-watchdog", s.runSQLiteHealthWatchdog)
	})
}

func (s *Server) runSQLiteHealthWatchdog(ctx context.Context) {
	if ctx == nil {
		ctx = context.Background()
	}
	s.runSQLiteHealthProbeOnce(ctx)
	ticker := time.NewTicker(sqliteHealthProbeInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			s.runSQLiteHealthProbeOnce(ctx)
		}
	}
}

func (s *Server) runSQLiteHealthProbeOnce(ctx context.Context) SQLiteHealthDiagnostic {
	if ctx == nil {
		ctx = context.Background()
	}
	probeCtx, cancel := context.WithTimeout(ctx, sqliteHealthProbeTimeout)
	defer cancel()
	started := time.Now()
	err := s.probeSQLiteHealth(probeCtx)
	health := s.updateSQLiteHealth(err, time.Since(started))
	if sqliteHealthShouldRecycle(health) {
		s.startSQLiteHandleRecycle(health)
	}
	return health
}

func (s *Server) probeSQLiteHealth(ctx context.Context) error {
	if s.sqliteHealthProbe != nil {
		return s.sqliteHealthProbe(ctx)
	}
	return s.probeSQLiteHandle(ctx, s.dbHandle())
}

func (s *Server) probeSQLiteHandle(ctx context.Context, db *sql.DB) error {
	if db == nil {
		return errors.New("sqlite handle is not available")
	}
	var ok int
	if err := db.QueryRowContext(ctx, `SELECT 1`).Scan(&ok); err != nil {
		return err
	}
	if ok != 1 {
		return fmt.Errorf("unexpected sqlite watchdog probe result %d", ok)
	}
	var users int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM users`).Scan(&users); err != nil {
		return err
	}
	return nil
}

func (s *Server) dbHandle() *sql.DB {
	if s == nil {
		return nil
	}
	s.dbHandleMu.RLock()
	db := s.db
	s.dbHandleMu.RUnlock()
	return db
}

func (s *Server) swapSQLiteDBHandle(next *sql.DB) *sql.DB {
	s.dbHandleMu.Lock()
	old := s.db
	s.db = next
	s.dbHandleMu.Unlock()
	return old
}

func (s *Server) updateSQLiteHealth(err error, elapsed time.Duration) SQLiteHealthDiagnostic {
	now := time.Now().UTC()
	nowText := now.Format(time.RFC3339)
	errorKind := ""
	var evidence SQLiteHealthDiagnostic
	captureEvidence := false

	s.sqliteHealthMu.Lock()
	health := s.sqliteHealth
	if strings.TrimSpace(health.Status) == "" {
		health.Status = sqliteHealthStatusHealthy
		health.LastTransitionAt = nowText
	}
	previousStatus := health.Status
	health.LastProbeDurationMillis = elapsed.Milliseconds()

	if err == nil {
		health.LastSuccessfulProbeAt = nowText
		health.ConsecutiveSuccesses++
		health.ConsecutiveFailures = 0
		if previousStatus == sqliteHealthStatusHealthy {
			health.Status = sqliteHealthStatusHealthy
		} else if health.ConsecutiveSuccesses >= sqliteHealthRecoverySuccessThreshold {
			health.Status = sqliteHealthStatusHealthy
			health.LastRecoveryAction = "watchdog_probe_recovered"
		} else {
			health.Status = sqliteHealthStatusRecovering
		}
	} else {
		errorKind = sqliteHealthErrorKind(err)
		health.LastFailureAt = nowText
		health.LastFailureKind = errorKind
		health.LastFailureMessage = err.Error()
		health.ConsecutiveFailures++
		health.ConsecutiveSuccesses = 0
		switch {
		case errorKind == string(database.ErrorKindCorrupt):
			health.Status = sqliteHealthStatusCorrupt
		case health.ConsecutiveFailures >= sqliteHealthDegradedFailureThreshold:
			health.Status = sqliteHealthStatusDegraded
		case previousStatus == sqliteHealthStatusDegraded || previousStatus == sqliteHealthStatusRecovering || previousStatus == sqliteHealthStatusFailed || previousStatus == sqliteHealthStatusCorrupt:
			health.Status = previousStatus
		default:
			health.Status = sqliteHealthStatusHealthy
		}
	}

	if health.Status != previousStatus {
		health.LastTransitionAt = nowText
		switch health.Status {
		case sqliteHealthStatusDegraded, sqliteHealthStatusCorrupt:
			health.EvidenceCaptures++
			captureEvidence = true
			evidence = health
		}
	}
	s.sqliteHealth = health
	s.sqliteHealthMu.Unlock()

	if captureEvidence {
		s.captureSQLiteHealthEvidence("health_transition", err, evidence)
	}
	return health
}

func sqliteHealthErrorKind(err error) string {
	switch {
	case err == nil:
		return ""
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, context.Canceled):
		return "canceled"
	default:
		return string(database.ClassifyError(err))
	}
}

func (s *Server) sqliteHealthSnapshot() SQLiteHealthDiagnostic {
	s.sqliteHealthMu.Lock()
	health := s.sqliteHealth
	s.sqliteHealthMu.Unlock()
	if strings.TrimSpace(health.Status) == "" {
		health.Status = sqliteHealthStatusHealthy
	}
	return health
}

func sqliteHealthAllowsBackground(health SQLiteHealthDiagnostic) bool {
	status := strings.TrimSpace(health.Status)
	return status == "" || status == sqliteHealthStatusHealthy
}

func sqliteHealthShouldRecycle(health SQLiteHealthDiagnostic) bool {
	if strings.TrimSpace(health.Status) != sqliteHealthStatusDegraded {
		return false
	}
	switch strings.TrimSpace(health.LastFailureKind) {
	case string(database.ErrorKindBusy), string(database.ErrorKindLocked), "timeout":
		return true
	default:
		return false
	}
}

func (s *Server) startSQLiteHandleRecycle(trigger SQLiteHealthDiagnostic) {
	if s == nil || !s.sqliteRecycleRunning.CompareAndSwap(false, true) {
		return
	}
	if !s.startBackground("sqlite-handle-recycle", func(workerCtx context.Context) {
		defer s.sqliteRecycleRunning.Store(false)
		s.attemptSQLiteHandleRecycle(workerCtx, trigger)
	}) {
		s.sqliteRecycleRunning.Store(false)
	}
}

func (s *Server) attemptSQLiteHandleRecycle(parent context.Context, trigger SQLiteHealthDiagnostic) {
	if parent == nil {
		parent = context.Background()
	}
	if !sqliteHealthShouldRecycle(trigger) {
		return
	}
	now := time.Now()
	s.sqliteRecycleMu.Lock()
	if !s.sqliteLastRecycleAttempt.IsZero() && now.Sub(s.sqliteLastRecycleAttempt) < sqliteHandleRecycleMinInterval {
		s.sqliteRecycleMu.Unlock()
		return
	}
	s.sqliteLastRecycleAttempt = now
	s.sqliteRecycleMu.Unlock()

	started := time.Now()
	trigger = s.recordSQLiteRecycleStarted(trigger)
	s.captureSQLiteHealthEvidence("before_recycle", nil, trigger)
	s.cancelRunningJobsForSQLiteRecycle()

	recycleCtx, cancel := context.WithTimeout(parent, sqliteHandleRecycleTimeout)
	defer cancel()
	next, err := s.openSQLiteRuntimeHandleWithTimeout(recycleCtx)
	if err != nil {
		s.recordSQLiteRecycleFailed(err, time.Since(started))
		s.captureSQLiteHealthEvidence("recycle_failed", err, s.sqliteHealthSnapshot())
		return
	}
	if err := s.probeSQLiteHandle(recycleCtx, next); err != nil {
		_ = next.Close()
		s.recordSQLiteRecycleFailed(err, time.Since(started))
		s.captureSQLiteHealthEvidence("recycle_probe_failed", err, s.sqliteHealthSnapshot())
		return
	}

	old := s.swapSQLiteDBHandle(next)
	s.recordSQLiteRecycleSucceeded(time.Since(started))
	s.captureSQLiteHealthEvidence("after_recycle", nil, s.sqliteHealthSnapshot())
	if old != nil && old != next {
		if !s.startOwnedAsync("sqlite-handle-close", func(context.Context) {
			if err := old.Close(); err != nil && s.log != nil {
				s.log.Warn("old sqlite handle close failed after recycle", "error", err)
			}
		}) {
			_ = old.Close()
		}
	}
}

func (s *Server) recordSQLiteRecycleStarted(trigger SQLiteHealthDiagnostic) SQLiteHealthDiagnostic {
	now := time.Now().UTC().Format(time.RFC3339Nano)
	s.sqliteHealthMu.Lock()
	health := s.sqliteHealth
	if strings.TrimSpace(health.Status) == "" {
		health = trigger
	}
	health.Status = sqliteHealthStatusDegraded
	health.RecycleAttempts++
	health.LastRecycleAt = now
	health.LastRecycleError = ""
	health.LastRecycleMillis = 0
	health.LastRecoveryAction = "db_handle_recycle_started"
	s.sqliteHealth = health
	s.sqliteHealthMu.Unlock()
	return health
}

func (s *Server) recordSQLiteRecycleSucceeded(elapsed time.Duration) {
	now := time.Now().UTC().Format(time.RFC3339)
	s.sqliteHealthMu.Lock()
	health := s.sqliteHealth
	previousStatus := health.Status
	health.Status = sqliteHealthStatusRecovering
	health.LastSuccessfulProbeAt = now
	health.ConsecutiveSuccesses = 1
	health.ConsecutiveFailures = 0
	health.RecycleSuccesses++
	health.LastRecycleAt = now
	health.LastRecycleError = ""
	health.LastRecycleMillis = elapsed.Milliseconds()
	health.LastRecoveryAction = "db_handle_recycled"
	if previousStatus != health.Status {
		health.LastTransitionAt = now
	}
	s.sqliteHealth = health
	s.sqliteHealthMu.Unlock()
}

func (s *Server) recordSQLiteRecycleFailed(err error, elapsed time.Duration) {
	now := time.Now().UTC().Format(time.RFC3339)
	s.sqliteHealthMu.Lock()
	health := s.sqliteHealth
	previousStatus := health.Status
	health.Status = sqliteHealthStatusFailed
	health.LastFailureAt = now
	health.LastFailureKind = sqliteHealthErrorKind(err)
	if err != nil {
		health.LastFailureMessage = err.Error()
		health.LastRecycleError = err.Error()
	}
	health.LastRecycleAt = now
	health.LastRecycleMillis = elapsed.Milliseconds()
	health.LastRecoveryAction = "db_handle_recycle_failed"
	if previousStatus != health.Status {
		health.LastTransitionAt = now
	}
	s.sqliteHealth = health
	s.sqliteHealthMu.Unlock()
}

func (s *Server) openSQLiteRuntimeHandleWithTimeout(ctx context.Context) (*sql.DB, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	opener := s.sqliteDBOpener
	if opener == nil {
		opener = database.OpenRuntimeHandleContext
	}
	return opener(ctx, s.cfg)
}

func (s *Server) cancelRunningJobsForSQLiteRecycle() {
	s.jobCancelMu.Lock()
	cancels := make([]context.CancelFunc, 0, len(s.jobCancels))
	for _, cancel := range s.jobCancels {
		cancels = append(cancels, cancel)
	}
	s.jobCancelMu.Unlock()
	for _, cancel := range cancels {
		cancel()
	}
	if len(cancels) > 0 && s.log != nil {
		s.log.Warn("cancelled running background jobs before sqlite handle recycle", "jobs", len(cancels))
	}
}

func (s *Server) captureSQLiteHealthEvidence(stage string, err error, health SQLiteHealthDiagnostic) {
	if s == nil || s.log == nil {
		return
	}
	stack := make([]byte, sqliteHealthEvidenceStackBufferBytes)
	n := runtime.Stack(stack, true)
	stats := sql.DBStats{}
	if db := s.dbHandle(); db != nil {
		stats = db.Stats()
	}
	ioPressure := s.ioPressureDiagnostics()
	s.log.Warn(
		"sqlite health evidence captured",
		"stage", stage,
		"status", health.Status,
		"error", err,
		"errorKind", health.LastFailureKind,
		"consecutiveFailures", health.ConsecutiveFailures,
		"recycleAttempts", health.RecycleAttempts,
		"recycleSuccesses", health.RecycleSuccesses,
		"openConnections", stats.OpenConnections,
		"inUseConnections", stats.InUse,
		"idleConnections", stats.Idle,
		"waitCount", stats.WaitCount,
		"waitDuration", stats.WaitDuration.String(),
		"ioPressureStatus", ioPressure.Status,
		"ioPressureSomeAvg10", ioPressure.CurrentSomeAvg10,
		"ioPressureFullAvg10", ioPressure.CurrentFullAvg10,
		"ioPressureLastHighAt", ioPressure.LastHighPressureAt,
		"diskStatsSupported", ioPressure.DiskStatsSupported,
		"goroutines", runtime.NumGoroutine(),
		"stack", string(stack[:n]),
	)
}

func (s *Server) pruneOperationalTables(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}
	now := s.operationalRetentionNow()
	retention := s.ownerRetentionSettings()
	if retention.AuditHistoryDays > 0 {
		auditCutoff := now.AddDate(0, 0, -retention.AuditHistoryDays).Format(time.RFC3339Nano)
		if _, err := s.execBackgroundWrite(ctx, `DELETE FROM audit_events WHERE created_at < ?`, auditCutoff); err != nil {
			return err
		}
	}
	if retention.JobHistoryDays > 0 {
		jobCutoff := now.AddDate(0, 0, -retention.JobHistoryDays).Format(time.RFC3339Nano)
		if _, err := s.execBackgroundWrite(ctx, `
			DELETE FROM jobs
			WHERE status IN ('complete', 'succeeded', 'failed', 'cancelled', 'interrupted', 'degraded')
				AND updated_at < ?`, jobCutoff); err != nil {
			return err
		}
	}
	// A zero retention value is an explicit owner decision to retain the lane
	// indefinitely. Capacity ceilings apply only to time-bounded lanes.
	if retention.AuditHistoryDays > 0 {
		if err := s.pruneAuditEventsPastLimit(ctx, auditEventRetentionMax); err != nil {
			return err
		}
	}
	if retention.JobHistoryDays > 0 {
		if err := s.pruneJobsPastLimit(ctx, jobRetentionMax); err != nil {
			return err
		}
	}
	if retention.AuditHistoryDays > 0 {
		if err := s.pruneSecurityAuditEventsPastLimit(ctx, auditEventRetentionMax); err != nil {
			return err
		}
	}
	if err := s.pruneDiagnosticTables(ctx); err != nil {
		return err
	}
	if err := s.pruneViewerCommunicationContext(ctx); err != nil {
		return err
	}
	if err := s.pruneDownloadStateContext(ctx, now); err != nil {
		return err
	}
	if err := s.prunePlaybackReplacementPayloads(ctx, now); err != nil {
		return err
	}
	return s.prunePrivacySensitiveOperationalData(ctx, now)
}

func (s *Server) pruneAuditEventsPastLimit(ctx context.Context, limit int) error {
	if limit <= 0 {
		return nil
	}
	var createdAt, id string
	err := s.queryUserRow(ctx, `
		SELECT created_at, id
		FROM audit_events
		ORDER BY created_at DESC, id DESC
		LIMIT 1 OFFSET ?`, limit).Scan(&createdAt, &id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	if err != nil {
		return err
	}
	_, err = s.execBackgroundWrite(ctx, `
		DELETE FROM audit_events
		WHERE created_at < ?
			OR (created_at = ? AND id <= ?)`,
		createdAt, createdAt, id)
	return err
}

func (s *Server) pruneJobsPastLimit(ctx context.Context, limit int) error {
	if limit <= 0 {
		return nil
	}
	var updatedAt, id string
	err := s.queryUserRow(ctx, `
		SELECT updated_at, id
		FROM jobs
		WHERE status IN ('complete', 'succeeded', 'failed', 'cancelled', 'interrupted', 'degraded')
		ORDER BY updated_at DESC, id DESC
		LIMIT 1 OFFSET ?`, limit).Scan(&updatedAt, &id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	if err != nil {
		return err
	}
	_, err = s.execBackgroundWrite(ctx, `
		DELETE FROM jobs
		WHERE status IN ('complete', 'succeeded', 'failed', 'cancelled', 'interrupted', 'degraded')
			AND (updated_at < ? OR (updated_at = ? AND id <= ?))`,
		updatedAt, updatedAt, id)
	return err
}

func (s *Server) runStartupJobRecovery(ctx context.Context) {
	if s.jobRecoveryReady != nil {
		defer s.jobRecoveryReadyOnce.Do(func() { close(s.jobRecoveryReady) })
	}
	if err := ctx.Err(); err != nil {
		return
	}
	s.markStartupPhaseStarted("startup_job_recovery", "Startup job recovery")
	started := time.Now()
	if err := s.requeueRunningJobsOnStartup(); err != nil {
		s.markStartupPhaseComplete("startup_job_recovery", "Startup job recovery", err)
		s.log.Warn("startup job recovery failed", "error", err, "duration", time.Since(started).String())
		return
	}
	if err := s.recoverScannerBacklogClaims(); err != nil {
		s.markStartupPhaseComplete("startup_job_recovery", "Startup job recovery", err)
		s.log.Warn("scanner backlog recovery failed", "error", err, "duration", time.Since(started).String())
		return
	}
	s.markStartupPhaseComplete("startup_job_recovery", "Startup job recovery", nil)
	s.log.Info("startup job recovery completed", "duration", time.Since(started).String())
}

func (s *Server) startBackground(name string, run func(context.Context)) bool {
	if s == nil || run == nil {
		return false
	}
	// Add must happen under the same close gate that BeginShutdown uses. This
	// prevents a late metadata refresh/deferred worker from racing Wait after
	// shutdown has crossed the join boundary.
	s.backgroundMu.Lock()
	if s.backgroundClosing {
		s.backgroundMu.Unlock()
		return false
	}
	s.backgroundWG.Add(1)
	s.backgroundMu.Unlock()
	go func() {
		started := time.Now()
		s.log.Info("background worker starting", "worker", name)
		defer func() {
			s.log.Info("background worker stopped", "worker", name, "duration", time.Since(started).String())
			s.backgroundWG.Done()
		}()
		defer func() {
			if recovered := recover(); recovered != nil {
				s.log.Error("background worker panicked", "worker", name, "panic", recovered, "stack", string(debug.Stack()))
				s.recordLog("error", "Background worker panicked", map[string]string{"worker": name})
			}
		}()
		run(s.backgroundCtx)
	}()
	return true
}

// startOwnedAsync covers generation-owned one-shot work that is not a
// long-lived startBackground loop. BeginShutdown closes admission to this
// registry before waiting, eliminating the Add-vs-Wait race and proving that
// detached database/network writers have joined before a restore snapshot or
// handle close begins.
func (s *Server) startOwnedAsync(name string, run func(context.Context)) bool {
	if s == nil || run == nil {
		return false
	}
	s.ownedAsyncMu.Lock()
	if s.ownedAsyncClosing {
		s.ownedAsyncMu.Unlock()
		return false
	}
	ctx := s.backgroundCtx
	if ctx == nil {
		ctx = context.Background()
	}
	s.ownedAsyncWG.Add(1)
	s.ownedAsyncMu.Unlock()
	go func() {
		defer s.ownedAsyncWG.Done()
		defer func() {
			if recovered := recover(); recovered != nil && s.log != nil {
				s.log.Error("owned async task panicked", "task", name, "panic", recovered, "stack", string(debug.Stack()))
			}
		}()
		run(ctx)
	}()
	return true
}

func (s *Server) closeOwnedAsync() {
	if s == nil {
		return
	}
	s.ownedAsyncMu.Lock()
	s.ownedAsyncClosing = true
	s.ownedAsyncMu.Unlock()
	done := make(chan struct{})
	go func() {
		s.ownedAsyncWG.Wait()
		close(done)
	}()
	<-done
}

func (s *Server) queueLibraryReadModelRepair(libraryID string) {
	libraryID = strings.TrimSpace(libraryID)
	if libraryID == "" {
		return
	}
	s.readModelRepairMu.Lock()
	if s.readModelRepairs == nil {
		s.readModelRepairs = map[string]chan struct{}{}
	}
	if _, exists := s.readModelRepairs[libraryID]; exists {
		s.readModelRepairMu.Unlock()
		return
	}
	done := make(chan struct{})
	s.readModelRepairs[libraryID] = done
	s.readModelRepairMu.Unlock()

	if _, err := s.createJobFor("library_read_model_repair", "Repair library read models.", "library", libraryID); err != nil {
		s.completeLibraryReadModelRepair(libraryID, done)
		s.log.Warn("queue library read-model repair failed", "library", libraryID, "error", err)
		return
	}
	// Normal generations have a supervised worker and use the coalesced wake.
	// A few narrow database-backed test/inert fixtures predate the runtime
	// activation constructor and intentionally have no background context; keep
	// their one-shot dispatch behavior without waking an inert production
	// generation during restore.
	if s.jobRuntimeIsActive() {
		s.signalJobWake()
	} else if s.backgroundCtx == nil {
		s.startOwnedAsync("library-repair-dispatch", func(context.Context) { s.runDueJobsOnce() })
	}
}

func (s *Server) completeLibraryReadModelRepair(libraryID string, done chan struct{}) {
	s.readModelRepairMu.Lock()
	shouldClose := false
	if s.readModelRepairs[libraryID] == done {
		delete(s.readModelRepairs, libraryID)
		shouldClose = true
	}
	s.readModelRepairMu.Unlock()
	if shouldClose {
		close(done)
	}
}

func (s *Server) waitForLibraryReadModelRepair(ctx context.Context, libraryID string) error {
	libraryID = strings.TrimSpace(libraryID)
	if libraryID == "" {
		return nil
	}
	for {
		s.readModelRepairMu.Lock()
		done := s.readModelRepairs[libraryID]
		s.readModelRepairMu.Unlock()
		if done == nil {
			return nil
		}
		select {
		case <-done:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

func (s *Server) runLibraryReadModelRepair(ctx context.Context, job Job) {
	libraryID := strings.TrimSpace(job.ResourceID)
	if job.ResourceType != "library" || libraryID == "" {
		_ = s.setJobMessage(job.ID, "failed", 100, "Library read-model repair failed because no library was selected.")
		return
	}
	s.readModelRepairMu.Lock()
	done := s.readModelRepairs[libraryID]
	s.readModelRepairMu.Unlock()
	completeWaiter := func() {
		if done != nil {
			s.completeLibraryReadModelRepair(libraryID, done)
		}
	}

	if err := ctx.Err(); err != nil {
		if s.deferMaintenanceJob(job.ID, err) {
			return
		}
		_ = s.setJobMessage(job.ID, "failed", 100, "Library read-model repair was interrupted.")
		completeWaiter()
		return
	}
	_ = s.setJobMessage(job.ID, "running", 10, "Repairing library category and source read models.")
	started := time.Now()
	if err := s.rebuildLibraryCategoryFacetsContext(ctx, libraryID); err != nil {
		if s.deferMaintenanceJob(job.ID, err) {
			return
		}
		_ = s.setJobMessage(job.ID, "failed", 100, "Library category read-model repair failed: "+err.Error())
		s.log.Warn("library category read-model repair failed", "library", libraryID, "error", err)
		completeWaiter()
		return
	}
	s.invalidateCategoryCache()
	_ = s.setJobMessage(job.ID, "running", 70, "Repairing library source read model.")
	if err := s.rebuildLibrarySourceGroupsContext(ctx, libraryID); err != nil {
		if s.deferMaintenanceJob(job.ID, err) {
			return
		}
		_ = s.setJobMessage(job.ID, "failed", 100, "Library source-group read-model repair failed: "+err.Error())
		s.log.Warn("library source-group read-model repair failed", "library", libraryID, "error", err)
		completeWaiter()
		return
	}
	_ = s.setJobMessage(job.ID, "complete", 100, "Library read-model repair completed.")
	s.log.Info("library read-model repair completed", "library", libraryID, "duration", time.Since(started).String())
	completeWaiter()
}

func (s *Server) Shutdown(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}
	// Close every owned admission point before cancelling/joining generation
	// work. In particular, this seals the dispatcher-before-register window so
	// no newly claimed job can begin using SQLite after the host's join boundary.
	s.BeginShutdown()
	if err := s.ffmpegSupervisor.Shutdown(ctx); err != nil {
		return err
	}
	if err := s.restoreBarrier.quiesce(ctx); err != nil {
		return err
	}
	if err := waitForRestoreJobs(ctx, &s.jobCancelMu, s.jobCancels); err != nil {
		return err
	}
	if err := s.waitForJobRuns(ctx); err != nil {
		return err
	}
	if err := s.recordInterruptedOwnedJobs(ctx); err != nil {
		return err
	}
	// Background cancellation is not sufficient for one-shot generation-owned
	// writers; wait for the guarded registry before handing the DB to the host.
	ownedDone := make(chan struct{})
	go func() {
		s.closeOwnedAsync()
		close(ownedDone)
	}()
	done := make(chan struct{})
	go func() {
		s.backgroundWG.Wait()
		close(done)
	}()
	select {
	case <-ownedDone:
		select {
		case <-done:
		case <-ctx.Done():
			return ctx.Err()
		}
	case <-done:
		select {
		case <-ownedDone:
		case <-ctx.Done():
			return ctx.Err()
		}
	case <-ctx.Done():
		return ctx.Err()
	}
	return nil
}

func (s *Server) BeginShutdown() {
	s.shutdownOnce.Do(func() {
		s.transcodeMu.Lock()
		s.transcodeClosing = true
		s.transcodeMu.Unlock()
		s.jobLifecycleMu.Lock()
		s.jobAdmissionClosed = true
		s.jobRuntimeActive = false
		wake := s.jobWake
		s.jobLifecycleMu.Unlock()
		s.diagnosticMu.Lock()
		s.diagnosticClosing = true
		s.diagnosticMu.Unlock()
		if wake != nil {
			select {
			case wake <- struct{}{}:
			default:
			}
		}
		s.backgroundMu.Lock()
		s.backgroundClosing = true
		s.backgroundMu.Unlock()
		s.ownedAsyncMu.Lock()
		s.ownedAsyncClosing = true
		s.ownedAsyncMu.Unlock()
		if s.backgroundCancel != nil {
			s.backgroundCancel()
		}
		s.jobCancelMu.Lock()
		cancels := make([]context.CancelFunc, 0, len(s.jobCancels))
		for _, cancel := range s.jobCancels {
			cancels = append(cancels, cancel)
		}
		s.jobCancelMu.Unlock()
		for _, cancel := range cancels {
			cancel()
		}
	})
}

func (s *Server) shutdownDone() <-chan struct{} {
	if s == nil || s.backgroundCtx == nil {
		return nil
	}
	return s.backgroundCtx.Done()
}

func sleepContext(ctx context.Context, duration time.Duration) bool {
	timer := time.NewTimer(duration)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return false
	case <-timer.C:
		return true
	}
}

var (
	sensitiveLogKeyPattern     = regexp.MustCompile(`(?i)(password|passwd|secret|token|credential|authorization|api[_-]?key|private[_-]?key|media[_-]?grant|download[_-]?grant|pin|code)`)
	sensitiveLogValuePattern   = regexp.MustCompile(`(?i)\b(code|pin|token|secret|authorization|api[_-]?key|media[_-]?grant|download[_-]?grant)=([^&\s]+)`)
	quickConnectCodeLogPattern = regexp.MustCompile(`\b[A-HJKMNP-Z2-9]{4}-[A-HJKMNP-Z2-9]{4}\b|\b[A-HJKMNP-Z2-9]{8}\b|\b[A-HJ-NP-Z2-9]{6}\b`)
)

func redactLogFields(fields map[string]string) map[string]string {
	if fields == nil {
		return nil
	}
	redacted := make(map[string]string, len(fields))
	for key, value := range fields {
		cleanKey := strings.TrimSpace(key)
		if sensitiveLogKeyPattern.MatchString(cleanKey) {
			redacted[cleanKey] = "[redacted]"
			continue
		}
		redacted[cleanKey] = redactLogValue(value)
	}
	return redacted
}

func redactLogValue(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return value
	}
	value = redaction.RedactPorticoCredentials(value)
	value = sensitiveLogValuePattern.ReplaceAllString(value, "$1=[redacted]")
	return quickConnectCodeLogPattern.ReplaceAllString(value, "[redacted-code]")
}

func (s *Server) requeueRunningJobsOnStartup() error {
	nowTime := time.Now().UTC()
	now := nowTime.Format(time.RFC3339Nano)
	staleCutoff := nowTime.Add(-2 * time.Hour).Format(time.RFC3339Nano)
	result, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'interrupted',
			phase = 'interrupted',
			progress_current = progress,
			retry_eligible = 1,
			interrupted_at = ?,
			error_code = 'restart_interrupted',
			message = CASE
				WHEN message = '' THEN 'Job recovered after server restart.'
				ELSE message || ' Recovered after server restart.'
			END,
			leased_by = '',
			lease_expires_at = '',
			last_error = CASE WHEN last_error = '' THEN 'Server restarted while this job was running.' ELSE last_error END,
			retention_until = CASE WHEN retention_until = '' THEN ? ELSE retention_until END,
			updated_at = ?
		WHERE status = 'running'
			AND ((lease_expires_at <> '' AND lease_expires_at <= ?)
				OR (lease_expires_at = '' AND updated_at <= ?))`,
		now, s.jobRetentionDeadline(nowTime), now, now, staleCutoff)
	if err != nil {
		return err
	}
	if affected := rowsAffected(result); affected > 0 {
		s.recordLog("warn", "Recovered running jobs after server restart.", map[string]string{"jobs": strconv.FormatInt(affected, 10)})
	}
	result, err = s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'queued', phase = 'queued', next_run_at = ?,
			leased_by = '', lease_expires_at = '', retention_until = '', updated_at = ?
		WHERE status = 'interrupted' AND retry_eligible = 1
			AND cancellation_requested_at = ''
			AND error_code IN ('shutdown_interrupted', 'restart_interrupted', 'restore_interrupted')
			AND (
				active_key = ''
				OR (
					NOT EXISTS (
						SELECT 1 FROM jobs active
						WHERE active.active_key = jobs.active_key
							AND active.status IN ('queued', 'running')
					)
					AND id = (
						SELECT candidate.id FROM jobs candidate
						WHERE candidate.active_key = jobs.active_key
							AND candidate.status = 'interrupted'
							AND candidate.retry_eligible = 1
							AND candidate.cancellation_requested_at = ''
							AND candidate.error_code IN ('shutdown_interrupted', 'restart_interrupted', 'restore_interrupted')
						ORDER BY candidate.created_at, candidate.id LIMIT 1
					)
				)
			)`, now, now)
	if err != nil {
		return err
	}
	if affected := rowsAffected(result); affected > 0 {
		s.recordLog("info", "Requeued retryable jobs after server restart.", map[string]string{"jobs": strconv.FormatInt(affected, 10)})
	}
	return nil
}

func (s *Server) Handler() http.Handler {
	s.handlerOnce.Do(func() {
		mux := http.NewServeMux()
		// Authentication adapters are constructed at each registration because the
		// existing authed handler signature includes the resolved User. The registry
		// still owns the auth declaration and refuses routes missing from contract.
		registry := apiroute.New(mux, nil, nil)
		s.apiRegistry = registry
		// Restore status is a narrow opaque-capability route. It must remain
		// reachable after a database generation swap even when the restored DB no
		// longer contains the initiating session; all other backup routes remain
		// behind their normal interactive authentication declaration.
		registry.Session("/api/backups/restore/upload", s.withAuth(s.handleBackups))
		registry.Public("/api/backups/restore/", s.handleRestoreStatusCapability)
		s.registerAuthRoutes(registry)
		s.registerAccountRoutes(registry)
		s.registerSystemRoutes(registry)
		s.registerRemoteAccessRoutes(registry)
		s.registerLibraryAndMediaRoutes(registry)
		s.registerPlaybackRoutes(registry)
		s.registerLiveTVRoutes(registry)
		s.registerAdminRoutes(registry)
		s.registerDLNARoutes(mux)
		mux.HandleFunc("/desktop/status", s.handleDesktopStatus)
		mux.HandleFunc("/", s.handleStatic)
		s.handler = s.requestBodyDeadline(s.requestTransport(s.requestIdentity(s.securityHeaders(s.requestTiming(s.responseCompression(s.restoreAdmission(s.workloadAdmission(mux))))))))
	})
	return s.handler
}

const ordinaryRequestBodyTimeout = 45 * time.Second

// requestBodyDeadline gives the HTTP server a conservative default body
// deadline while allowing the supervised restore upload its independently
// validated, longer I/O budget. The process host also sets http.Server's
// ReadTimeout; this handler resets the connection deadline after headers have
// been admitted and refreshes it for each body read so a slow body cannot hold
// a connection forever while a healthy restore is still allowed to progress.
func (s *Server) requestBodyDeadline(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		timeout := ordinaryRequestBodyTimeout
		if r.URL != nil && r.URL.Path == "/api/backups/restore/upload" {
			timeout = s.restoreIOTimeout()
		}
		if r.Body == nil || (r.ContentLength == 0 && r.Header.Get("Transfer-Encoding") == "") {
			next.ServeHTTP(w, r)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), timeout)
		defer cancel()
		body := &requestDeadlineBody{
			ReadCloser: r.Body,
			controller: http.NewResponseController(w),
			timeout:    timeout,
		}
		_ = body.resetDeadline()
		r.Body = body
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

type requestDeadlineBody struct {
	io.ReadCloser
	controller *http.ResponseController
	timeout    time.Duration
}

func (b *requestDeadlineBody) Read(p []byte) (int, error) {
	_ = b.resetDeadline()
	n, err := b.ReadCloser.Read(p)
	if err == nil {
		_ = b.resetDeadline()
	}
	return n, err
}

func (b *requestDeadlineBody) resetDeadline() error {
	if b == nil || b.controller == nil || b.timeout <= 0 {
		return nil
	}
	return b.controller.SetReadDeadline(time.Now().Add(b.timeout))
}

// APIRoutes returns the exact-method runtime catalog built by Handler. It is
// intended for contract tests and diagnostics, not for request dispatch.
func (s *Server) APIRoutes() []apiroute.Route {
	if s.apiRegistry == nil {
		return nil
	}
	return s.apiRegistry.Routes()
}

func (s *Server) DeclaredAPIOperationCount() int {
	if s.apiRegistry == nil {
		return 0
	}
	return s.apiRegistry.DeclaredOperationCount()
}

const requestIDHeader = "X-Request-ID"

var requestIDPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$`)

type requestTimingContextKey struct{}

type requestTimingState struct {
	queueNanos atomic.Int64
	reads      requestReadMemo
}

type requestReadMemo struct {
	mu                  sync.Mutex
	playbackProgress    map[string]PlaybackProgressPreferences
	libraryRestrictions map[string]sqlRestrictionMemo
}

type sqlRestrictionMemo struct {
	clause string
	args   []any
}

func requestReadMemoFromContext(ctx context.Context) *requestReadMemo {
	if ctx == nil {
		return nil
	}
	timing, _ := ctx.Value(requestTimingContextKey{}).(*requestTimingState)
	if timing == nil {
		return nil
	}
	return &timing.reads
}

func (s *Server) requestIdentity(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requestID := strings.TrimSpace(r.Header.Get(requestIDHeader))
		if !requestIDPattern.MatchString(requestID) {
			requestID = randomID("req")
		}
		r.Header.Set(requestIDHeader, requestID)
		w.Header().Set(requestIDHeader, requestID)
		next.ServeHTTP(w, r)
	})
}

type statusRecordingWriter struct {
	http.ResponseWriter
	status       int
	bytes        int
	beforeCommit func()
}

func (w *statusRecordingWriter) prepareCommit() {
	if w.status == 0 && w.beforeCommit != nil {
		w.beforeCommit()
	}
}

func (w *statusRecordingWriter) WriteHeader(status int) {
	if w.status != 0 {
		return
	}
	w.prepareCommit()
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

func (w *statusRecordingWriter) Write(body []byte) (int, error) {
	if w.status == 0 {
		w.prepareCommit()
		w.status = http.StatusOK
	}
	n, err := w.ResponseWriter.Write(body)
	w.bytes += n
	return n, err
}

func (w *statusRecordingWriter) Flush() {
	if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
		if w.status == 0 {
			w.prepareCommit()
			w.status = http.StatusOK
		}
		flusher.Flush()
	}
}

func (w *statusRecordingWriter) Unwrap() http.ResponseWriter {
	return w.ResponseWriter
}

const responseCompressionThreshold = 1024

// bufferedCompressionWriter delays the first commit until it has enough body
// data to make a compression decision. The buffer is capped by
// responseCompressionThreshold: larger responses immediately switch to a
// streaming gzip writer, so a large API response is never duplicated in RAM.
type bufferedCompressionWriter struct {
	http.ResponseWriter
	request       *http.Request
	status        int
	buffer        bytes.Buffer
	committed     bool
	compressed    bool
	streaming     bool
	negotiable    bool
	compressionOK bool
	gzipWriter    *gzip.Writer
}

func (w *bufferedCompressionWriter) WriteHeader(status int) {
	if w.status != 0 || w.committed {
		return
	}
	w.status = status
}

func (w *bufferedCompressionWriter) Write(body []byte) (int, error) {
	if w.status == 0 {
		w.status = http.StatusOK
	}
	if w.committed {
		if w.compressed {
			return w.gzipWriter.Write(body)
		}
		return w.ResponseWriter.Write(body)
	}
	if _, err := w.buffer.Write(body); err != nil {
		return 0, err
	}
	if w.buffer.Len() < responseCompressionThreshold {
		return len(body), nil
	}
	if err := w.commit(); err != nil {
		return 0, err
	}
	return len(body), nil
}

func (w *bufferedCompressionWriter) Flush() {
	// A handler that explicitly flushes is streaming. Preserve its immediate
	// delivery semantics and do not make a streaming response a compression
	// oracle or hold it behind a compression buffer.
	w.streaming = true
	if w.status == 0 {
		w.status = http.StatusOK
	}
	if err := w.commit(); err != nil {
		return
	}
	if w.compressed && w.gzipWriter != nil {
		_ = w.gzipWriter.Flush()
	}
	if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
		flusher.Flush()
	}
}

func (w *bufferedCompressionWriter) Unwrap() http.ResponseWriter {
	return w.ResponseWriter
}

func (w *bufferedCompressionWriter) finish() {
	if w.status == 0 {
		w.status = http.StatusOK
	}
	if err := w.commit(); err != nil {
		return
	}
	if w.gzipWriter != nil {
		_ = w.gzipWriter.Close()
	}
}

func (w *bufferedCompressionWriter) commit() error {
	if w.committed {
		return nil
	}
	w.committed = true
	status := w.status
	if status == 0 {
		status = http.StatusOK
	}
	w.compressed = w.compressionEligible(status)
	if w.negotiable && status >= http.StatusOK && status < http.StatusBadRequest && responseContentTypeCompressible(w.Header().Get("Content-Type")) {
		w.Header().Add("Vary", "Accept-Encoding")
	}
	if w.compressed {
		w.Header().Del("Content-Length")
		w.Header().Set("Content-Encoding", "gzip")
		writer, err := gzip.NewWriterLevel(w.ResponseWriter, gzip.BestSpeed)
		if err != nil {
			return err
		}
		w.gzipWriter = writer
	}
	w.ResponseWriter.WriteHeader(status)
	if w.buffer.Len() == 0 {
		return nil
	}
	var err error
	if w.compressed {
		_, err = w.gzipWriter.Write(w.buffer.Bytes())
	} else {
		_, err = w.ResponseWriter.Write(w.buffer.Bytes())
	}
	w.buffer.Reset()
	return err
}

func (w *bufferedCompressionWriter) compressionEligible(status int) bool {
	if !w.compressionOK || w.streaming || w.buffer.Len() < responseCompressionThreshold {
		return false
	}
	if w.request == nil || w.request.Method == http.MethodHead || w.request.Header.Get("Range") != "" {
		return false
	}
	if status < http.StatusOK || status >= http.StatusBadRequest || status == http.StatusNoContent || status == http.StatusPartialContent || status == http.StatusNotModified {
		return false
	}
	if w.Header().Get("Content-Encoding") != "" || w.Header().Get("Upgrade") != "" {
		return false
	}
	return responseContentTypeCompressible(w.Header().Get("Content-Type"))
}

func responseContentTypeCompressible(contentType string) bool {
	contentType = strings.ToLower(strings.TrimSpace(strings.SplitN(contentType, ";", 2)[0]))
	if contentType == "text/event-stream" {
		return false
	}
	return contentType == "application/json" || strings.HasSuffix(contentType, "+json") || strings.HasPrefix(contentType, "text/")
}

func requestAcceptsGzip(request *http.Request) bool {
	if request == nil {
		return false
	}
	for _, value := range strings.Split(request.Header.Get("Accept-Encoding"), ",") {
		parts := strings.Split(value, ";")
		if !strings.EqualFold(strings.TrimSpace(parts[0]), "gzip") {
			continue
		}
		accepted := true
		for _, parameter := range parts[1:] {
			name, raw, ok := strings.Cut(strings.TrimSpace(parameter), "=")
			if ok && strings.EqualFold(strings.TrimSpace(name), "q") {
				quality, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
				if err != nil || quality <= 0 || quality > 1 {
					accepted = false
				}
			}
		}
		return accepted
	}
	return false
}

func responseCompressionSensitivePath(path string) bool {
	for _, prefix := range []string{
		"/api/auth/",
		"/api/backups/restore/",
		"/api/download-preparations",
		"/api/dvr/",
		"/api/filesystem/",
		"/api/offline-download-authorizations/",
		"/api/library-channels/",
		"/api/live-tv/",
		"/api/media/",
		"/api/account/profile-admin-proofs",
		"/api/account/profile-trusts",
		"/api/playback/",
		"/api/playback-sessions",
		"/api/remote-access/",
		"/api/watch-with-friends/",
	} {
		if strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

// responseCompression reduces large, bounded JSON and text projections for
// browsers and native clients that connect directly to Portico. Secret-bearing
// bootstrap/auth routes and all error responses stay uncompressed so reflected
// input cannot be used as a compression oracle.
func (s *Server) responseCompression(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := ""
		if r.URL != nil {
			path = r.URL.Path
		}
		negotiable := !responseCompressionSensitivePath(path)
		writer := &bufferedCompressionWriter{
			ResponseWriter: w,
			request:        r,
			negotiable:     negotiable,
			compressionOK:  negotiable && requestAcceptsGzip(r),
		}
		next.ServeHTTP(writer, r)
		writer.finish()
	})
}

func (s *Server) requestTiming(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		timing := &requestTimingState{}
		r = r.WithContext(context.WithValue(r.Context(), requestTimingContextKey{}, timing))
		recorder := &statusRecordingWriter{ResponseWriter: w}
		recorder.beforeCommit = func() {
			elapsed := time.Since(start)
			queue := time.Duration(timing.queueNanos.Load())
			handler := elapsed - queue
			if handler < 0 {
				handler = 0
			}
			recorder.Header().Add("Server-Timing", fmt.Sprintf(
				"portico;dur=%.3f, queue;dur=%.3f, handler;dur=%.3f",
				float64(elapsed)/float64(time.Millisecond),
				float64(queue)/float64(time.Millisecond),
				float64(handler)/float64(time.Millisecond),
			))
		}
		next.ServeHTTP(recorder, r)
		if recorder.status == 0 {
			recorder.prepareCommit()
			recorder.status = http.StatusOK
		}
		status := recorder.status
		if status == 0 {
			status = http.StatusOK
		}
		duration := time.Since(start)
		descriptor := s.requestWork(r)
		queue := time.Duration(timing.queueNanos.Load())
		handlerDuration := duration - queue
		if handlerDuration < 0 {
			handlerDuration = 0
		}
		s.latencyMetrics.observeRouteService(descriptor.Lane, handlerDuration)
		requestID := recorder.Header().Get(requestIDHeader)
		sample := sha256.Sum256([]byte(requestID))
		// Always retain failures and slow requests. Sample routine successful API
		// traffic at roughly 1% so observability remains representative without
		// turning normal browse/heartbeat volume into an unbounded log workload.
		if duration >= 250*time.Millisecond || status >= http.StatusBadRequest || (strings.HasPrefix(r.URL.Path, "/api/") && sample[0] < 3) {
			s.log.Info("request completed",
				"request_id", requestID,
				"method", r.Method,
				"path", requestLogPath(r.URL.Path),
				"operation", descriptor.Route.OperationID,
				"lane", descriptor.Lane,
				"status", status,
				"duration_ms", duration.Milliseconds(),
				"queue_ms", queue.Milliseconds(),
				"handler_ms", handlerDuration.Milliseconds(),
				"bytes", recorder.bytes,
				"auth", s.requestAuthMode(r),
			)
		}
	})
}

func (s *Server) workloadAdmission(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		descriptor := s.requestWork(r)
		laneID := descriptor.Lane
		if laneID == "" {
			next.ServeHTTP(w, r)
			return
		}
		lane := s.workloadLane(laneID)
		if lane == nil {
			next.ServeHTTP(w, r)
			return
		}
		acquired := lane.tryAcquireUncounted()
		if !acquired && requestWorkMayQueue(r, descriptor) {
			queueStarted := time.Now()
			lane.queued.Add(1)
			queueWait := workloadInteractiveQueueWait
			if descriptor.Class == foundationcontract.WorkClassSecurityFence ||
				descriptor.Class == foundationcontract.WorkClassEstablishedPlayback ||
				descriptor.Class == foundationcontract.WorkClassPlaybackStart {
				queueWait = 9 * time.Second
			}
			queueCtx, cancel := context.WithTimeout(r.Context(), queueWait)
			acquired = lane.acquireContext(queueCtx)
			cancel()
			queueWaitNanos := time.Since(queueStarted).Nanoseconds()
			if queueWaitNanos < 0 {
				queueWaitNanos = 0
			}
			lane.waitNanos.Add(uint64(queueWaitNanos))
			s.latencyMetrics.observeRouteQueue(laneID, time.Duration(queueWaitNanos))
			if timing, ok := r.Context().Value(requestTimingContextKey{}).(*requestTimingState); ok && timing != nil {
				timing.queueNanos.Store(queueWaitNanos)
			}
		}
		if !acquired {
			lane.rejected.Add(1)
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, "server_busy", "Server is busy handling "+strings.ToLower(lane.label)+". Try again shortly.")
			return
		}
		defer lane.release()
		if timeout := requestBudgetForWork(descriptor); timeout > 0 {
			ctx, cancel := context.WithTimeout(r.Context(), timeout)
			defer cancel()
			r = r.WithContext(ctx)
		}
		next.ServeHTTP(w, r)
	})
}

const workloadInteractiveQueueWait = 1500 * time.Millisecond

func (lane *workloadLane) tryAcquire() bool {
	if lane.tryAcquireUncounted() {
		return true
	}
	lane.rejected.Add(1)
	return false
}

func (lane *workloadLane) tryAcquireUncounted() bool {
	select {
	case lane.tokens <- struct{}{}:
		return true
	default:
		return false
	}
}

func (lane *workloadLane) acquireContext(ctx context.Context) bool {
	if lane == nil {
		return false
	}
	select {
	case lane.tokens <- struct{}{}:
		return true
	case <-ctx.Done():
		return false
	}
}

func (lane *workloadLane) release() {
	select {
	case <-lane.tokens:
	default:
	}
}

func (s *Server) workloadLaneForRequest(r *http.Request) *workloadLane {
	id := s.requestWork(r).Lane
	if id == "" {
		return nil
	}
	return s.workloadLane(id)
}

func (s *Server) workloadLane(id string) *workloadLane {
	s.workloadMu.Lock()
	defer s.workloadMu.Unlock()
	if s.workloadLanes == nil {
		s.workloadLanes = newWorkloadLanes()
	}
	lane := s.workloadLanes[id]
	if lane == nil {
		lane = s.workloadLanes[workloadLaneDefault]
	}
	return lane
}

func requestLogPath(path string) string {
	if path == "" {
		return "/"
	}
	if strings.HasPrefix(path, "/api/artwork/") {
		return "/api/artwork/{id}"
	}
	if strings.HasPrefix(path, "/api/media/") {
		return "/api/media/{id}"
	}
	if strings.HasPrefix(path, "/api/libraries/") {
		return "/api/libraries/{id}"
	}
	if strings.HasPrefix(path, "/api/playback-sessions/") {
		return "/api/playback-sessions/{id}"
	}
	if strings.HasPrefix(path, "/api/playback/") {
		return "/api/playback/{id}"
	}
	return path
}

func (s *Server) requestAuthMode(r *http.Request) string {
	if strings.TrimSpace(r.Header.Get("Authorization")) != "" {
		return "bearer"
	}
	if len(s.requestSessionCookies(r)) > 0 {
		return "cookie"
	}
	return "anonymous"
}

func (s *Server) securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if origin := r.Header.Get("Origin"); origin != "" {
			if s.castReceiverOriginAllowed(origin) && castCORSPath(r.URL.Path) {
				if !s.applyCastCORS(w, r, origin) {
					writeError(w, http.StatusForbidden, "cast_cors_denied", "The Cast request is not allowed for this resource.")
					return
				}
				if r.Method == http.MethodOptions {
					w.WriteHeader(http.StatusNoContent)
					return
				}
			} else {
				if !s.isAllowedOriginForRequest(origin, r) {
					writeError(w, http.StatusForbidden, "origin_not_allowed", "Request origin is not allowed.")
					return
				}
				w.Header().Set("Access-Control-Allow-Origin", origin)
				w.Header().Add("Vary", "Origin")
				w.Header().Set("Access-Control-Allow-Credentials", "true")
				w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Accept-Encoding, Range, "+csrfHeaderName+", "+requestIDHeader+", "+profileAdministrationHeader+", "+restoreStatusHeader)
				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
				w.Header().Set("Access-Control-Expose-Headers", requestIDHeader+", "+csrfHeaderName+", Server-Timing, Content-Length, Content-Range, Accept-Ranges, Content-Type")
				w.Header().Set("Access-Control-Allow-Private-Network", "true")
				if r.Method == http.MethodOptions {
					w.WriteHeader(http.StatusNoContent)
					return
				}
			}
		} else if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		if !s.csrfAllowed(r) {
			writeError(w, http.StatusForbidden, "csrf_required", "A CSRF protection header is required.")
			return
		}
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Referrer-Policy", "same-origin")
		w.Header().Set("X-Frame-Options", "DENY")
		w.Header().Set("Content-Security-Policy", porticoContentSecurityPolicy)
		next.ServeHTTP(w, r)
	})
}

const porticoContentSecurityPolicy = "default-src 'self'; img-src 'self' data: https://image.tmdb.org https://*.direct.getportico.tv https://*.direct.getportico.tv:*; media-src 'self' blob: https://*.direct.getportico.tv https://*.direct.getportico.tv:*; connect-src 'self' https://api.getportico.tv https://*.direct.getportico.tv https://*.direct.getportico.tv:* http://127.0.0.1:* http://localhost:*; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; frame-ancestors 'none'"

func (s *Server) applyCastCORS(w http.ResponseWriter, r *http.Request, origin string) bool {
	path := strings.TrimSuffix(r.URL.Path, "/")
	allowedMethods := "GET, HEAD, OPTIONS"
	allowedHeaders := "Authorization, Content-Type, Accept-Encoding, Range"
	if strings.HasPrefix(path, "/api/playback/cast/") {
		allowedMethods = "POST, OPTIONS"
		allowedHeaders = "Authorization, Content-Type"
		if strings.HasPrefix(path, "/api/playback/cast/sessions/") {
			allowedMethods = "GET, POST, DELETE, OPTIONS"
		}
	}
	if r.Method == http.MethodOptions {
		requestedMethod := strings.ToUpper(strings.TrimSpace(r.Header.Get("Access-Control-Request-Method")))
		if requestedMethod != "" && !strings.Contains(", "+allowedMethods+", ", ", "+requestedMethod+", ") {
			return false
		}
		allowed := map[string]bool{}
		for _, value := range strings.Split(allowedHeaders, ",") {
			allowed[strings.ToLower(strings.TrimSpace(value))] = true
		}
		for _, value := range strings.Split(r.Header.Get("Access-Control-Request-Headers"), ",") {
			if value = strings.ToLower(strings.TrimSpace(value)); value != "" && !allowed[value] {
				return false
			}
		}
	}
	w.Header().Set("Access-Control-Allow-Origin", origin)
	w.Header().Add("Vary", "Origin")
	w.Header().Add("Vary", "Access-Control-Request-Method")
	w.Header().Add("Vary", "Access-Control-Request-Headers")
	w.Header().Set("Access-Control-Allow-Credentials", "true")
	w.Header().Set("Access-Control-Allow-Headers", allowedHeaders)
	w.Header().Set("Access-Control-Allow-Methods", allowedMethods)
	w.Header().Set("Access-Control-Max-Age", "600")
	w.Header().Set("Access-Control-Expose-Headers", "Server-Timing, Content-Length, Content-Range, Accept-Ranges, Content-Type")
	return true
}

func (s *Server) csrfAllowed(r *http.Request) bool {
	if r.Method == http.MethodGet || r.Method == http.MethodHead || r.Method == http.MethodOptions {
		return true
	}
	// Portico attachment sessions are authenticated by the one-time,
	// origin-bound encrypted handshake claimed inside the handler. Browser
	// connectors intentionally omit ambient cookies and bearer credentials, so
	// requiring the cookie-session CSRF header here would reject the protected
	// exchange before its cryptographic proof can be evaluated.
	if r.Method == http.MethodPost && strings.TrimSpace(r.URL.Path) == "/api/auth/portico/sessions" {
		return true
	}
	hasCSRFHeader := r.Header.Get(csrfHeaderName) != ""
	hasSessionCookie := len(s.requestSessionCookies(r)) > 0
	hasBrowserVaultCookie := len(s.requestBrowserVaultCookies(r)) > 0
	hasBearerAuth := strings.TrimSpace(r.Header.Get("Authorization")) != ""
	if r != nil && strings.HasPrefix(strings.TrimSpace(r.URL.Path), "/api/playback/cast/") && s.castReceiverOriginAllowed(r.Header.Get("Origin")) {
		return true
	}
	// A browser vault can mint a fresh user session, so it remains a
	// cookie-authenticated request even if another Authorization header exists.
	if hasBrowserVaultCookie {
		return hasCSRFHeader
	}
	if hasSessionCookie && !hasBearerAuth {
		return hasCSRFHeader
	}
	if hasBearerAuth && !hasSessionCookie {
		return true
	}
	if strings.EqualFold(r.Header.Get("Sec-Fetch-Site"), "cross-site") {
		origin := r.Header.Get("Origin")
		return origin != "" && hasCSRFHeader && s.isAllowedOriginForRequest(origin, r)
	}
	return r.Header.Get("Origin") == "" && r.Header.Get("Referer") == "" || hasCSRFHeader
}

func (s *Server) isAllowedOriginForRequest(origin string, r *http.Request) bool {
	if s.isAllowedOrigin(origin) {
		return true
	}
	if r != nil && s.castReceiverOriginAllowed(origin) && castCORSPath(r.URL.Path) {
		return true
	}
	parsed, err := url.Parse(origin)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" {
		return false
	}
	if s.isLoopbackWebDevOrigin(parsed, r) {
		return true
	}
	scheme := "http"
	if s.requestScheme(r) == "https" {
		scheme = "https"
	}
	return strings.EqualFold(parsed.Scheme, scheme) && strings.EqualFold(parsed.Host, r.Host)
}

func (s *Server) isLoopbackWebDevOrigin(origin *url.URL, r *http.Request) bool {
	if origin.Scheme != "http" {
		return false
	}
	originHost, originPort, err := net.SplitHostPort(origin.Host)
	if err != nil {
		return false
	}
	if originPort != "19105" {
		return false
	}
	requestHost, _, err := net.SplitHostPort(r.Host)
	if err != nil {
		requestHost = r.Host
	}
	return isLoopbackHost(originHost) && isLoopbackHost(requestHost)
}

func (s *Server) isAllowedOrigin(origin string) bool {
	for _, allowed := range s.cfg.AllowedOrigins {
		if allowed == origin {
			return true
		}
	}
	return false
}

func (s *Server) castReceiverOriginAllowed(origin string) bool {
	origin = strings.TrimSpace(origin)
	if origin == "" {
		return false
	}
	parsed, err := url.Parse(origin)
	if err != nil || parsed.Scheme != "https" || parsed.Host == "" || parsed.User != nil || parsed.Path != "" || parsed.RawQuery != "" || parsed.Fragment != "" {
		return false
	}
	for _, configured := range s.cfg.CastReceiverOrigins {
		if strings.TrimRight(strings.TrimSpace(configured), "/") == strings.TrimRight(origin, "/") {
			return true
		}
	}
	return false
}

func castCORSPath(pathValue string) bool {
	pathValue = strings.TrimSuffix(strings.TrimSpace(pathValue), "/")
	if strings.HasPrefix(pathValue, "/api/playback/cast/") {
		return true
	}
	if strings.HasPrefix(pathValue, "/api/media/") {
		parts := strings.Split(strings.Trim(strings.TrimPrefix(pathValue, "/api/media/"), "/"), "/")
		return len(parts) >= 2 && (parts[1] == "stream" || parts[1] == "hls" || parts[1] == "subtitles" || parts[1] == "trickplay")
	}
	return strings.HasPrefix(pathValue, "/api/live-tv/hls/") ||
		strings.HasPrefix(pathValue, "/api/live-tv/streams/") ||
		strings.Contains(pathValue, "/api/library-channels/") && strings.Contains(pathValue, "/hls/") ||
		strings.Contains(pathValue, "/api/dvr/recordings/") && (strings.Contains(pathValue, "/stream") || strings.Contains(pathValue, "/hls/"))
}

func (s *Server) withAuth(next authedHandler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, ok, err := s.currentUserWithError(w, r)
		if !ok {
			if err != nil {
				if errors.Is(err, errHostedProfileDirectoryUnavailable) {
					w.Header().Set("Retry-After", strconv.Itoa(hostedProfileRetryAfterSeconds))
					writeProductError(w, http.StatusServiceUnavailable, "server_unavailable", "Portico could not refresh this server's profile access. Try again shortly.")
					return
				}
				if errors.Is(err, errHostedProfileAccessRevoked) {
					writeProductError(w, http.StatusForbidden, "profile_not_available_on_server", "This profile can no longer use this server.")
					return
				}
				writeDatabaseAccessError(w, err, http.StatusServiceUnavailable, "authentication_unavailable", "Authentication could not be verified. Try again shortly.")
				return
			}
			writeError(w, http.StatusUnauthorized, "unauthorized", "Authentication is required.")
			return
		}
		if !s.enforceRoutePolicy(w, r, user) {
			return
		}
		if !apiKeyAllowsRequest(user, r) {
			writeError(w, http.StatusForbidden, "api_key_scope_denied", "This API key is not scoped for that request.")
			return
		}
		if !s.enforceAPIKeyRequestLimit(w, user) {
			return
		}
		s.observeAuthorizedAPIKeyUse(user)
		leasedContext, releaseProfileLease, err := s.profileRuntime.acquire(r.Context(), accountIDForUser(user), viewerProfileID(user))
		if err != nil {
			writeProductError(w, http.StatusConflict, "profile_erasure_in_progress", "This profile is being permanently erased and cannot start new work.")
			return
		}
		defer releaseProfileLease()
		if !s.viewerFeedbackPolicyContext(leasedContext).Enabled {
			user.AllowFeedback = false
		}
		r = r.WithContext(contextWithMediaActionUser(leasedContext, user))
		next(w, r, user)
	}
}

func (s *Server) currentUser(w http.ResponseWriter, r *http.Request) (User, bool) {
	user, ok, _ := s.currentUserWithError(w, r)
	return user, ok
}

func (s *Server) currentUserWithError(w http.ResponseWriter, r *http.Request) (User, bool, error) {
	// Authorization is an explicit caller-selected authority. Never let an
	// ambient browser cookie replace, broaden, or revive that credential: a
	// malformed, expired, revoked, or narrowly scoped bearer must fail as itself.
	if strings.TrimSpace(r.Header.Get("Authorization")) != "" {
		user, ok, err := s.currentLocalBearerUserWithError(r)
		if err != nil || !ok {
			return User{}, false, err
		}
		s.publishBearerSessionCookie(w, r)
		return user, true, nil
	}
	cookies := s.requestSessionCookies(r)
	if len(cookies) == 0 {
		if user, ok, err := s.currentLocalBearerUserWithError(r); ok || err != nil {
			if err != nil {
				return User{}, false, err
			}
			s.publishBearerSessionCookie(w, r)
			return user, true, nil
		}
		return User{}, false, nil
	}

	preferredCookieName := s.sessionCookieNameContext(r.Context())
	var transientErr error
	for _, cookie := range cookies {
		if cookie.Value == "" {
			continue
		}
		user, expires, ok, lookupErr := s.userForSessionTokenWithError(r, cookie.Value)
		if !ok {
			if transientSessionLookupError(lookupErr) {
				transientErr = lookupErr
			} else {
				s.clearSessionCookies(r.Context(), w, cookie.Name)
			}
			continue
		}
		if s.porticoAccountMode() && !isPorticoPrincipal(user) {
			s.clearSessionCookies(r.Context(), w, cookie.Name)
			continue
		}
		if cookie.Name != preferredCookieName {
			s.setSessionCookie(r.Context(), w, preferredCookieName, cookie.Value, expires)
		}
		s.rollBrowserSession(r.Context(), w, r, cookie, user.ID)
		return user, true, nil
	}
	if user, ok, err := s.currentLocalBearerUserWithError(r); ok || err != nil {
		if err != nil {
			return User{}, false, err
		}
		s.publishBearerSessionCookie(w, r)
		return user, true, nil
	}
	if transientErr != nil {
		return User{}, false, transientErr
	}
	return User{}, false, nil
}

func (s *Server) publishBearerSessionCookie(w http.ResponseWriter, r *http.Request) {
	token, ok := bearerTokenFromRequest(r)
	if !ok || !strings.HasPrefix(token, "ptc_loc_") {
		return
	}
	var rawExpires string
	if err := s.queryUserRow(r.Context(), `SELECT expires_at FROM sessions WHERE token_hash = ?`, hashToken(token)).Scan(&rawExpires); err != nil {
		return
	}
	expires, err := parseCredentialTime(rawExpires)
	if err != nil || !expires.After(time.Now().UTC()) {
		return
	}
	s.setSessionCookie(r.Context(), w, s.sessionCookieNameContext(r.Context()), token, expires)
}

func (s *Server) currentLocalBearerUser(r *http.Request) (User, bool) {
	user, ok, _ := s.currentLocalBearerUserWithError(r)
	return user, ok
}

func (s *Server) currentLocalBearerUserWithError(r *http.Request) (User, bool, error) {
	token, ok := bearerTokenFromRequest(r)
	if !ok {
		return User{}, false, nil
	}
	if token == "" || strings.HasPrefix(token, "ptc_clt_") {
		return User{}, false, nil
	}
	// A ptc_loc credential is issued and validated by this server. It remains
	// usable in Portico Account mode so an established client does not depend on
	// Hosted Services for every request or refresh.
	if strings.HasPrefix(token, "ptc_loc_") {
		user, _, ok, err := s.userForSessionTokenWithError(r, token)
		return user, ok, err
	}
	// API keys are scoped credentials issued and revoked by this Server. They do
	// not become Hosted credentials when Portico Account mode is enabled, and
	// their compact local authorization fence remains authoritative in either
	// account mode. Keep this branch ahead of the Hosted-only bearer boundary.
	if strings.HasPrefix(token, "ptc_api_") {
		user, ok := s.userForAPIKey(r, token)
		return user, ok, nil
	}
	if s.porticoAccountMode() {
		return User{}, false, nil
	}
	user, _, ok, err := s.userForSessionTokenWithError(r, token)
	return user, ok, err
}

func (s *Server) userForSessionToken(r *http.Request, token string) (User, time.Time, bool) {
	user, expires, ok, _ := s.userForSessionTokenWithError(r, token)
	return user, expires, ok
}

func (s *Server) userForSessionTokenWithError(r *http.Request, token string) (User, time.Time, bool, error) {
	hash := hashToken(token)
	ctx := context.Background()
	if r != nil {
		ctx = r.Context()
	}
	// Session, device, and profile revocation are security boundaries. Always
	// revalidate the compact authorization fence; the cached snapshot still
	// avoids rebuilding the full principal when the fence is unchanged.
	strictSessionRevalidation := true
	if user, expires, ok, err := s.cachedSessionPrincipal(ctx, hash, time.Now().UTC(), strictSessionRevalidation); err != nil {
		return User{}, time.Time{}, false, err
	} else if ok {
		s.touchPresence(hash, user.DeviceID, clientIPFromRequest(r))
		return user, expires, true, nil
	}
	row := s.queryUserRow(ctx, `
		SELECT s.id, u.id, s.profile_id, s.profile_identity_id, s.auth_provider,
			u.username, u.email, u.display_name, COALESCE(u.profile_image_path, ''), COALESCE(u.profile_image_url, ''), u.role, COALESCE(u.auth_origin, 'local'), COALESCE(u.portico_user_id, ''), COALESCE(u.portico_membership_id, ''), u.password_hash IS NOT NULL AND u.password_hash <> '', u.permissions_json, u.preferences_json, COALESCE(u.max_content_rating, ''), COALESCE(u.max_active_sessions, 0), COALESCE(u.max_active_streams, 0), COALESCE(u.remote_bitrate_limit_mbps, 0), s.expires_at, s.device_id
		FROM sessions s
		JOIN users u ON u.id = s.user_id
		WHERE s.token_hash = ? AND s.profile_id <> '' AND s.profile_identity_id <> '' AND s.auth_provider IN ('local', 'portico') AND COALESCE(u.disabled_at, '') = ''`, hash)

	var user User
	var permissionsJSON string
	var preferencesJSON string
	var expiresAt string
	var deviceID string
	var profileImagePath string
	var profileImageURL string
	var sessionID string
	if err := row.Scan(&sessionID, &user.ID, &user.ProfileID, &user.ProfileIdentityID, &user.AuthProvider, &user.Username, &user.Email, &user.DisplayName, &profileImagePath, &profileImageURL, &user.Role, &user.AuthOrigin, &user.PorticoUserID, &user.PorticoMembershipID, &user.HasLocalPassword, &permissionsJSON, &preferencesJSON, &user.MaxContentRating, &user.MaxActiveSessions, &user.MaxActiveStreams, &user.RemoteBitrateLimitMbps, &expiresAt, &deviceID); err != nil {
		if err := ctx.Err(); err != nil {
			return User{}, time.Time{}, false, err
		}
		if errors.Is(err, sql.ErrNoRows) {
			return User{}, time.Time{}, false, nil
		}
		return User{}, time.Time{}, false, err
	}
	user.DeviceID = deviceID
	user.AuthSessionID = sessionID
	if strings.HasPrefix(sessionID, "nativesess_") {
		record, err := s.nativeRefreshByIDContext(ctx, strings.TrimPrefix(sessionID, "nativesess_"))
		if err != nil || record.UserID != user.ID || record.ProfileID != user.ProfileID || record.DeviceID != deviceID {
			_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE id = ?`, sessionID)
			return User{}, time.Time{}, false, nil
		}
		expectedToken, _, err := s.nativeAccessTokenValue(record)
		if err != nil || subtle.ConstantTimeCompare([]byte(expectedToken), []byte(token)) != 1 {
			_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE id = ?`, sessionID)
			return User{}, time.Time{}, false, nil
		}
	}

	expires, err := time.Parse(time.RFC3339, expiresAt)
	if err != nil || time.Now().UTC().After(expires) {
		_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
		return User{}, time.Time{}, false, nil
	}
	if normalizeAuthProvider(user.AuthProvider) == "portico" {
		if err := s.ensureHostedProfileDirectoryFreshness(ctx, user.ID, time.Now().UTC()); err != nil {
			return User{}, time.Time{}, false, err
		}
	}
	if err := json.Unmarshal([]byte(permissionsJSON), &user.Permissions); err != nil {
		user.Permissions = map[string]bool{}
	}
	applyStoredUserPreferences(&user, preferencesJSON)
	user.ProfileImageURL = profileImageURLForPath(profileImagePath, profileImageURL)
	principal, err := s.resolveRequestPrincipalContext(ctx, user.ID, user.ProfileID)
	if err != nil {
		if errors.Is(err, errProfileNotFound) || errors.Is(err, errProfileNotAllowed) {
			_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
			return User{}, time.Time{}, false, nil
		}
		return User{}, time.Time{}, false, err
	}
	applyRequestPrincipal(&user, principal)
	user.SignInMethods = fallbackSignInMethods(user)

	if !userAccessScheduleAllows(user.AccessSchedule, time.Now().UTC()) {
		_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
		return User{}, time.Time{}, false, nil
	}

	requireTrustedDevices := s.requireTrustedDevicesContext(ctx)
	if err := ctx.Err(); err != nil {
		return User{}, time.Time{}, false, err
	}
	if requireTrustedDevices && !s.deviceTrustedContext(ctx, deviceID) {
		if err := ctx.Err(); err != nil {
			return User{}, time.Time{}, false, err
		}
		_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
		return User{}, time.Time{}, false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(user.Role), "owner") && !s.userDevicePolicyAllowsContext(ctx, user.ID, deviceID) {
		if err := ctx.Err(); err != nil {
			return User{}, time.Time{}, false, err
		}
		_, _ = s.execSecurityFenceWrite(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
		return User{}, time.Time{}, false, nil
	}

	s.rememberSessionPrincipal(ctx, hash, sessionID, deviceID, user, expires)
	s.touchPresence(hash, deviceID, clientIPFromRequest(r))
	return user, expires, true, nil
}

// rollBrowserSession gives successful first-party browser activity a fresh
// six-month window. Network, Hosted Services, and transient database failures
// never enter this path and therefore never clear or revoke remembered state.
func (s *Server) rollBrowserSession(ctx context.Context, w http.ResponseWriter, r *http.Request, sessionCookie *http.Cookie, userID string) {
	if sessionCookie == nil || strings.TrimSpace(sessionCookie.Value) == "" {
		return
	}
	if !s.browserSessionMayRoll(ctx) {
		// Plain-LAN sessions are deliberately short-lived and require a fresh
		// sign-in rather than becoming a remembered bearer credential through
		// ordinary activity.
		return
	}
	now := time.Now().UTC()
	expires := now.Add(s.browserSessionTTLContext(ctx))
	s.setSessionCookie(ctx, w, s.sessionCookieNameContext(ctx), sessionCookie.Value, expires)
	for _, vaultCookie := range s.requestBrowserVaultCookies(r) {
		s.setBrowserVaultCookie(ctx, w, s.browserVaultCookieNameContext(ctx), vaultCookie.Value, expires)
		break
	}
	if !s.shouldTouchPresence("browser-session-roll:"+hashToken(sessionCookie.Value), now) {
		return
	}
	var vaultID string
	err := s.withUserTxTagged(ctx, []string{}, func(tx *sql.Tx) error {
		if err := tx.QueryRowContext(ctx, `SELECT COALESCE(browser_vault_id, '') FROM sessions WHERE token_hash = ? AND user_id = ?`, hashToken(sessionCookie.Value), userID).Scan(&vaultID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `UPDATE sessions SET expires_at = ?, last_seen_at = ? WHERE token_hash = ? AND user_id = ?`, expires.Format(time.RFC3339), now.Format(time.RFC3339), hashToken(sessionCookie.Value), userID); err != nil {
			return err
		}
		if vaultID == "" {
			return nil
		}
		if _, err := tx.ExecContext(ctx, `UPDATE browser_account_vaults SET expires_at = ?, last_seen_at = ? WHERE id = ? AND revoked_at = ''`, expires.Format(time.RFC3339), now.Format(time.RFC3339), vaultID); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, `UPDATE browser_account_entries SET expires_at = ? WHERE vault_id = ? AND revoked_at = ''`, expires.Format(time.RFC3339), vaultID)
		return err
	})
	if err != nil {
		s.log.Warn("browser session rolling refresh failed", "error", err)
	}
}

func transientSessionLookupError(err error) bool {
	// Terminal lookup results return (ok=false, err=nil). Any concrete error is
	// operationally ambiguous and must preserve the durable browser credential.
	return err != nil
}

const (
	presenceTouchInterval  = 5 * time.Minute
	presenceTouchRetention = 3 * presenceTouchInterval
	presenceTouchMaximum   = 8192
)

func (s *Server) touchPresence(sessionHash, deviceID, clientIP string) {
	now := time.Now().UTC()
	touchSession := s.shouldTouchPresence("session:"+sessionHash, now)
	touchDevice := s.shouldTouchPresence("device:"+deviceID, now)
	if !touchSession && !touchDevice {
		return
	}
	s.startOwnedAsync("session-presence", func(ctx context.Context) {
		timestamp := now.Format(time.RFC3339)
		if touchSession && strings.TrimSpace(sessionHash) != "" {
			if _, err := s.execUserWriteTagged(ctx, []string{}, `UPDATE sessions SET last_seen_at = ? WHERE token_hash = ?`, timestamp, sessionHash); err != nil {
				s.log.Warn("session presence touch failed", "error", err)
			}
		}
		if touchDevice {
			s.touchDeviceAt(deviceID, clientIP, timestamp)
		}
	})
}

func (s *Server) shouldTouchPresence(key string, now time.Time) bool {
	key = strings.TrimSpace(key)
	if key == "" {
		return false
	}
	s.presenceTouchMu.Lock()
	defer s.presenceTouchMu.Unlock()
	if s.presenceTouches == nil {
		s.presenceTouches = map[string]time.Time{}
	}
	if s.presenceLastPrune.IsZero() || now.Before(s.presenceLastPrune) || now.Sub(s.presenceLastPrune) >= presenceTouchInterval || len(s.presenceTouches) >= presenceTouchMaximum {
		cutoff := now.Add(-presenceTouchRetention)
		for candidate, touchedAt := range s.presenceTouches {
			if touchedAt.Before(cutoff) || touchedAt.After(now.Add(presenceTouchInterval)) {
				delete(s.presenceTouches, candidate)
			}
		}
		s.presenceLastPrune = now
	}
	// A deliberately rotating device/session identifier cannot grow this map
	// without bound between expiry sweeps. Evict the oldest observation before
	// admitting another key; this only causes an early durable presence refresh.
	if _, exists := s.presenceTouches[key]; !exists && len(s.presenceTouches) >= presenceTouchMaximum {
		oldestKey := ""
		var oldest time.Time
		for candidate, touchedAt := range s.presenceTouches {
			if oldestKey == "" || touchedAt.Before(oldest) {
				oldestKey, oldest = candidate, touchedAt
			}
		}
		delete(s.presenceTouches, oldestKey)
	}
	if last, ok := s.presenceTouches[key]; ok && now.Sub(last) < presenceTouchInterval {
		return false
	}
	s.presenceTouches[key] = now
	return true
}

func authResponse(authenticated bool, setupRequired bool, user *User) AuthMeResponse {
	response := AuthMeResponse{
		Authenticated: authenticated,
		SetupRequired: setupRequired,
		User:          user,
	}
	if user != nil {
		response.AccountMode = accountModeForUser(*user)
		response.AuthProvider = user.AuthProvider
		response.Authority = viewerAuthorityForAuthProvider(user.AuthProvider)
		response.AccountID = strings.TrimSpace(user.AccountID)
		response.ProfileID = user.ProfileID
		response.ProfileIdentityID = user.ProfileIdentityID
		response.SignInMethods = user.SignInMethods
	}
	return response
}

func viewerAuthorityForAuthProvider(provider string) string {
	if normalizeAuthProvider(provider) == "portico" {
		return "hosted"
	}
	return "local"
}

// publicViewerIdentityForUserContext projects the server-private account and
// profile keys used for authorization onto the stable cross-server identities
// issued by Hosted Services. Internal keys must never escape as the canonical
// viewer scope: clients compare this scope with the signed profile-selection
// envelope before publishing credentials or profile-owned state.
func (s *Server) publicViewerIdentityForUserContext(ctx context.Context, user User, provider string) (string, string, error) {
	internalAccountID := strings.TrimSpace(user.AccountID)
	internalProfileID := strings.TrimSpace(user.ProfileID)
	if internalAccountID == "" || internalProfileID == "" {
		return "", "", errors.New("canonical viewer identity is unavailable")
	}
	provider = normalizeAuthProvider(provider)
	if provider == "" {
		return "", "", errors.New("canonical authentication provider is unavailable")
	}
	if provider != "portico" {
		return internalAccountID, internalProfileID, nil
	}

	publicAccountID := strings.TrimSpace(user.PorticoUserID)
	if publicAccountID == "" {
		_ = s.queryUserRow(ctx, `SELECT COALESCE(portico_user_id, '') FROM users WHERE id = ?`, internalAccountID).Scan(&publicAccountID)
		publicAccountID = strings.TrimSpace(publicAccountID)
	}
	if publicAccountID == "" {
		return "", "", errors.New("Hosted account identity is unavailable")
	}

	publicProfileID := ""
	_ = s.queryUserRow(ctx, `
		SELECT COALESCE(external_profile_id, '')
		FROM profiles
		WHERE id = ? AND account_id = ? AND origin = 'hosted' AND COALESCE(disabled_at, '') = ''`,
		internalProfileID, internalAccountID).Scan(&publicProfileID)
	publicProfileID = strings.TrimSpace(publicProfileID)
	if publicProfileID == "" {
		return "", "", errors.New("Hosted profile identity is unavailable")
	}
	return publicAccountID, publicProfileID, nil
}

func (s *Server) publicServerIDForAuthProviderContext(ctx context.Context, settings map[string]any, provider string) (string, error) {
	if normalizeAuthProvider(provider) == "portico" {
		remoteAccess, _ := settings[remoteAccessSettingsKey].(map[string]any)
		if hostedServerID := strings.TrimSpace(settingString(remoteAccess, "serverId", "")); hostedServerID != "" {
			return hostedServerID, nil
		}
	}
	return s.localServerIDContext(ctx, settings)
}

func (s *Server) authResponseWithServerContext(ctx context.Context, authenticated bool, setupRequired bool, user *User) AuthMeResponse {
	if user != nil {
		s.enrichUserSignInMethodsContext(ctx, user)
		// Prime the state-presence fence while authentication is already doing
		// bounded identity reads. Navigation can then join an authorization-safe
		// empty-state projection without adding a per-profile query to a burst.
		_, _ = s.profileHasMediaStateContext(ctx, viewerProfileID(*user))
	}
	response := authResponse(authenticated, setupRequired, user)
	settings, err := s.loadSettingsContext(ctx)
	if err != nil {
		response.ServerFriendlyName = "Portico"
		return response
	}
	response.ServerFriendlyName = serverFriendlyNameFromSettings(settings)
	provider := ""
	if user != nil {
		provider = user.AuthProvider
	}
	if serverID, err := s.publicServerIDForAuthProviderContext(ctx, settings, provider); err == nil {
		response.ServerID = serverID
	}
	if user != nil {
		response.AuthorizationRevision = s.authorizationRevisionForUserContext(ctx, *user)
		publicAccountID, publicProfileID, identityErr := s.publicViewerIdentityForUserContext(ctx, *user, user.AuthProvider)
		if identityErr != nil {
			response.Authenticated = false
			response.User = nil
			response.AccountID = ""
			response.ProfileID = ""
			return response
		}
		response.AccountID, response.ProfileID = publicAccountID, publicProfileID
		publicUser := *user
		publicUser.ProfileID = response.ProfileID
		response.User = &publicUser
	}
	return response
}

func (s *Server) authorizationRevisionForUserContext(ctx context.Context, user User) string {
	revision, err := s.authorizationRevisionForUserContextStrict(ctx, user)
	if err == nil {
		return revision
	}
	// Compatibility callers use this value for response metadata. Security
	// gates call the strict variant and fail closed instead of trusting this
	// process-local projection when SQLite cannot be consulted.
	encoded, _ := json.Marshal(user)
	digest := sha256.Sum256(encoded)
	return "authz_unverified_" + hex.EncodeToString(digest[:16])
}

func (s *Server) authorizationRevisionForUserContextStrict(ctx context.Context, user User) (string, error) {
	return authorizationRevisionForUserRow(user, s.queryUserRow(ctx, authorizationRevisionQuery, authorizationRevisionIdentity(user)...))
}

const authorizationRevisionQuery = `
	SELECT u.updated_at, u.permissions_json, COALESCE(u.disabled_at, ''), COALESCE(u.allow_account_profiles, 1),
		p.updated_at, p.policy_updated_at, p.restrictions_json, COALESCE(p.disabled_at, ''), p.pin_revision,
		COALESCE((SELECT revision FROM hosted_profile_snapshot_state WHERE account_id = u.id AND quarantined_at = ''), 0),
		COALESCE((SELECT group_concat(library_id, ',') FROM (SELECT library_id FROM user_library_access WHERE user_id = u.id ORDER BY library_id)), ''),
		COALESCE((SELECT group_concat(id, ',') FROM (SELECT id FROM libraries ORDER BY id)), '')
	FROM users u JOIN profiles p ON p.account_id = u.id
	WHERE u.id = ? AND p.id = ?`

type authorizationRevisionRow interface {
	Scan(dest ...any) error
}

func authorizationRevisionIdentity(user User) []any {
	accountID := strings.TrimSpace(user.AccountID)
	if accountID == "" {
		accountID = user.ID
	}
	profileID := strings.TrimSpace(user.ProfileID)
	if profileID == "" {
		profileID = accountID
	}
	return []any{accountID, profileID}
}

func authorizationRevisionForUserRow(user User, row authorizationRevisionRow) (string, error) {
	identity := authorizationRevisionIdentity(user)
	accountID, _ := identity[0].(string)
	profileID, _ := identity[1].(string)
	var userUpdated, permissions, accountDisabled, profileUpdated, profilePolicyUpdated, restrictions, profileDisabled string
	var profilesAllowed, pinRevision, hostedRevision int64
	var libraryGrantRevision, libraryCatalogueRevision string
	err := row.Scan(
		&userUpdated, &permissions, &accountDisabled, &profilesAllowed,
		&profileUpdated, &profilePolicyUpdated, &restrictions, &profileDisabled, &pinRevision, &hostedRevision, &libraryGrantRevision, &libraryCatalogueRevision)
	if err != nil {
		return "", err
	}
	material := strings.Join([]string{accountID, profileID, userUpdated, permissions, accountDisabled,
		strconv.FormatInt(profilesAllowed, 10), profileUpdated, profilePolicyUpdated, restrictions, profileDisabled,
		strconv.FormatInt(pinRevision, 10), strconv.FormatInt(hostedRevision, 10), libraryGrantRevision, libraryCatalogueRevision}, "\x00")
	digest := sha256.Sum256([]byte(material))
	return "authz_" + hex.EncodeToString(digest[:16]), nil
}

func authorizationRevisionForUserTx(ctx context.Context, tx *sql.Tx, user User) (string, error) {
	identity := authorizationRevisionIdentity(user)
	return authorizationRevisionForUserRow(user, tx.QueryRowContext(ctx, authorizationRevisionQuery, identity...))
}

func accountModeForUser(user User) string {
	hasPortico := false
	for _, method := range user.SignInMethods {
		switch method.Provider {
		case "portico":
			hasPortico = true
		}
	}
	if hasPortico {
		return "portico"
	}
	return "this_server"
}

func (s *Server) inspectSetupRequired(ctx context.Context, endpoint string) (bool, error) {
	start := time.Now()
	setupRequired, err := database.HasNoUsersContext(ctx, s.db)
	elapsed := time.Since(start)
	if elapsed >= 250*time.Millisecond || err != nil {
		fields := []any{"endpoint", endpoint, "duration_ms", elapsed.Milliseconds()}
		if err != nil {
			fields = append(fields, "error", err, "kind", setupCheckErrorKind(err))
		}
		s.log.Warn("auth setup-state check delayed", fields...)
	}
	return setupRequired, err
}

func writeSetupCheckError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, context.DeadlineExceeded), errors.Is(err, context.Canceled):
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusGatewayTimeout, "request_timeout", "The server took too long to inspect setup state. Try again shortly.")
	case database.IsRetryableLock(err):
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusServiceUnavailable, "database_busy", "The database is busy. Try again shortly.")
	default:
		writeError(w, http.StatusInternalServerError, "setup_check_failed", "Unable to inspect setup state.")
	}
}

func writeDatabaseAccessError(w http.ResponseWriter, err error, fallbackStatus int, fallbackCode string, fallbackMessage string) {
	switch {
	case errors.Is(err, context.DeadlineExceeded), errors.Is(err, context.Canceled):
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusGatewayTimeout, "request_timeout", "The server took too long to access the database. Try again shortly.")
	case database.IsRetryableLock(err):
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusServiceUnavailable, "database_busy", "The database is busy. Try again shortly.")
	default:
		writeError(w, fallbackStatus, fallbackCode, fallbackMessage)
	}
}

func setupCheckErrorKind(err error) string {
	switch {
	case err == nil:
		return ""
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, context.Canceled):
		return "canceled"
	default:
		return string(database.ClassifyError(err))
	}
}

func (s *Server) handleAuthMe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}

	setupRequired, err := s.inspectSetupRequired(r.Context(), r.URL.Path)
	if err != nil {
		writeSetupCheckError(w, err)
		return
	}

	if user, ok := s.currentUser(w, r); ok {
		response := s.authResponseWithServerContext(r.Context(), true, setupRequired, &user)
		writeJSON(w, http.StatusOK, response)
		return
	}

	serverFriendlyName := s.serverFriendlyNameContext(r.Context())
	if setupRequired {
		serverFriendlyName = s.setupServerFriendlyNameContext(r.Context())
	}
	writeJSON(w, http.StatusOK, AuthMeResponse{
		Authenticated:      false,
		SetupRequired:      setupRequired,
		ServerFriendlyName: serverFriendlyName,
	})
}

func (s *Server) serverFriendlyName() string {
	return s.serverFriendlyNameContext(context.Background())
}

func (s *Server) serverFriendlyNameContext(ctx context.Context) string {
	settings, err := s.loadSettingsContext(ctx)
	if err != nil {
		return "Portico"
	}
	return serverFriendlyNameFromSettings(settings)
}

func serverFriendlyNameFromSettings(settings map[string]any) string {
	if serverMap, ok := settings["server"].(map[string]any); ok {
		if value, ok := serverMap["friendlyName"].(string); ok && strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return "Portico"
}

func suggestedSetupServerName() string {
	hostname, err := os.Hostname()
	if err != nil {
		return "Portico"
	}
	hostname = strings.TrimSpace(hostname)
	if hostname == "" || len([]rune(hostname)) > 120 {
		return "Portico"
	}
	return hostname
}

func (s *Server) setupServerFriendlyNameContext(ctx context.Context) string {
	settings, err := s.loadSettingsContext(ctx)
	if err == nil {
		friendlyName := serverFriendlyNameFromSettings(settings)
		if friendlyName != "Portico" {
			return friendlyName
		}
	}
	return suggestedSetupServerName()
}

func (s *Server) saveSetupServerNameContext(ctx context.Context, value string) error {
	friendlyName := strings.TrimSpace(value)
	if err := validateSettingFieldPolicy("server", "friendlyName", friendlyName); err != nil {
		return err
	}
	settings, err := s.loadSettingsContext(ctx)
	if err != nil {
		return err
	}
	currentServerSettings, _ := settings["server"].(map[string]any)
	serverSettings := make(map[string]any, len(currentServerSettings)+1)
	for key, currentValue := range currentServerSettings {
		serverSettings[key] = currentValue
	}
	serverSettings["friendlyName"] = friendlyName
	encoded, err := json.Marshal(serverSettings)
	if err != nil {
		return err
	}
	_, err = s.execUserWrite(ctx, `INSERT INTO settings (key, value_json, updated_at) VALUES ('server', ?, ?) ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, updated_at = excluded.updated_at`, string(encoded), time.Now().UTC().Format(time.RFC3339Nano))
	return err
}

func (s *Server) localServerIDContext(ctx context.Context, settings map[string]any) (string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	identityMap, _ := settings["identity"].(map[string]any)
	serverID, _ := identityMap["serverId"].(string)
	serverID = strings.TrimSpace(serverID)
	if serverID != "" {
		return serverID, nil
	}
	serverID = randomID("srv")
	value := map[string]any{
		"serverId":  serverID,
		"createdAt": time.Now().UTC().Format(time.RFC3339),
	}
	bytes, err := json.Marshal(value)
	if err != nil {
		return "", err
	}
	if _, err := s.execUserWrite(ctx, `INSERT INTO settings (key, value_json, updated_at) VALUES ('identity', ?, ?) ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, updated_at = excluded.updated_at`, string(bytes), time.Now().UTC().Format(time.RFC3339)); err != nil {
		return "", err
	}
	return serverID, nil
}

func (s *Server) handleAuthCapabilities(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	setupRequired, err := s.inspectSetupRequired(r.Context(), r.URL.Path)
	if err != nil {
		writeSetupCheckError(w, err)
		return
	}
	localCredentialsEnabled := !setupRequired
	porticoAccountAuthEnabled := false
	if settings, err := s.remoteAccessSettings(); err == nil {
		porticoAccountAuthEnabled = settings.Enabled &&
			settings.ClaimStatus == "claimed" &&
			settings.ServerID != "" &&
			s.secretSetting(remoteAccessCredentialKey) != "" &&
			settings.PreferredRemoteAuthMode == "portico"
		if porticoAccountAuthEnabled {
			localCredentialsEnabled = false
		}
	}
	writeJSON(w, http.StatusOK, AuthCapabilitiesResponse{
		SetupRequired:             setupRequired,
		LocalCredentialsEnabled:   localCredentialsEnabled,
		PorticoAccountAuthEnabled: porticoAccountAuthEnabled,
		ServerFriendlyName: func() string {
			if setupRequired {
				return s.setupServerFriendlyNameContext(r.Context())
			}
			return s.serverFriendlyNameContext(r.Context())
		}(),
		PublicUserPickerEnabled: false,
		VisibleUsers:            []PublicLoginUser{},
		GeneratedAt:             time.Now().UTC().Format(time.RFC3339),
	})
}

func (s *Server) handleSetup(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	setupRequired, err := s.inspectSetupRequired(r.Context(), r.URL.Path)
	if err != nil {
		writeSetupCheckError(w, err)
		return
	}
	if !setupRequired {
		writeError(w, http.StatusConflict, "already_configured", "The owner account already exists.")
		return
	}
	if s.porticoAccountMode() {
		writeError(w, http.StatusForbidden, "portico_account_mode", "This server uses Portico accounts. Local account setup is disabled.")
		return
	}

	var req struct {
		ServerName            string `json:"serverName"`
		Username              string `json:"username"`
		Email                 string `json:"email"`
		DisplayName           string `json:"displayName"`
		Password              string `json:"password"`
		SetupMode             string `json:"setupMode"`
		LocalOnlyAcknowledged bool   `json:"localOnlyAcknowledged"`
		RememberOnBrowser     *bool  `json:"rememberOnBrowser,omitempty"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	if req.SetupMode == "local_only" && !req.LocalOnlyAcknowledged {
		writeError(w, http.StatusBadRequest, "local_only_acknowledgement_required", "Direct server setup requires acknowledging the owner-managed access limitations.")
		return
	}
	if err := s.saveSetupServerNameContext(r.Context(), req.ServerName); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_server_name", "Server name must be between 1 and 120 characters.")
		return
	}

	req.Email = strings.ToLower(strings.TrimSpace(req.Email))
	username := normalizeUsername(req.Username)
	if username == "" && req.Email != "" {
		username = normalizeUsername(strings.Split(req.Email, "@")[0])
	}
	req.DisplayName = strings.TrimSpace(req.DisplayName)
	if username == "" {
		writeError(w, http.StatusBadRequest, "invalid_username", "Username must be 3 to 32 letters, numbers, dots, dashes, or underscores.")
		return
	}
	if req.Email != "" && !strings.Contains(req.Email, "@") {
		writeError(w, http.StatusBadRequest, "invalid_email", "Enter a valid email address.")
		return
	}
	if len(req.DisplayName) < 2 {
		writeError(w, http.StatusBadRequest, "invalid_display_name", "Display name must be at least two characters.")
		return
	}
	if !validAccountPassword(req.Password) {
		writeError(w, http.StatusBadRequest, "weak_password", accountPasswordPolicyMessage)
		return
	}

	passwordHash, err := hashAccountPassword(r.Context(), kdfAccountSetupHash, req.Password)
	if err != nil {
		if writeKDFUnavailable(w, err) {
			return
		}
		writeError(w, http.StatusInternalServerError, "password_hash_failed", "Unable to create owner account.")
		return
	}

	user := User{
		ID:               randomID("usr"),
		Username:         username,
		Email:            req.Email,
		DisplayName:      req.DisplayName,
		Role:             "owner",
		AuthOrigin:       "local",
		HasLocalPassword: true,
		Permissions:      ownerPermissions(),
		Preferences:      defaultUserPreferences(),
	}
	permissions, _ := json.Marshal(user.Permissions)
	preferences, _ := json.Marshal(user.Preferences)
	now := time.Now().UTC().Format(time.RFC3339)
	if _, err := s.execUserWrite(r.Context(), `INSERT INTO users (id, username, email, display_name, password_hash, role, auth_origin, permissions_json, preferences_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		user.ID, user.Username, user.Email, user.DisplayName, passwordHash, user.Role, user.AuthOrigin, string(permissions), string(preferences), now, now); err != nil {
		writeError(w, http.StatusInternalServerError, "create_user_failed", "Unable to create owner account.")
		return
	}
	if settings, err := s.remoteAccessSettings(); err == nil {
		settings.PreferredRemoteAuthMode = "local"
		_ = s.saveRemoteAccessSettings(settings)
	}
	if err := s.seedUserMediaState(user.ID); err != nil {
		s.log.Warn("seed user media state failed", "error", err)
	}
	s.populateUserLibraryIDs(&user)
	s.enrichUserAuthContext(&user, "local")
	sessionToken, err := s.createSession(w, r, user.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "session_failed", "Unable to create session.")
		return
	}
	if rememberBrowserAccount(req.RememberOnBrowser) {
		if err := s.rememberBrowserAccountForSession(r.Context(), w, r, user.ID, "local", sessionToken); err != nil {
			s.discardBrowserSession(w, r.Context(), sessionToken)
			writeError(w, http.StatusInternalServerError, "browser_account_enrollment_failed", "The owner account was created, but could not be remembered on this browser. Sign in again to continue.")
			return
		}
	}
	s.recordLog("info", "Owner account created", map[string]string{"user": user.Email})

	writeJSON(w, http.StatusCreated, s.authResponseWithServerContext(r.Context(), true, false, &user))
}

func (s *Server) handlePorticoSetupClaimStart(w http.ResponseWriter, r *http.Request) {
	if !setupRequestFromLoopback(r) {
		writeError(w, http.StatusForbidden, "setup_local_access_required", "Initial server setup is available only on this computer.")
		return
	}
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	setupRequired, err := s.inspectSetupRequired(r.Context(), r.URL.Path)
	if err != nil {
		writeSetupCheckError(w, err)
		return
	}
	if !setupRequired {
		writeError(w, http.StatusConflict, "already_configured", "The owner account already exists.")
		return
	}
	var req struct {
		ServerName string `json:"serverName"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	requestedName := strings.TrimSpace(req.ServerName)
	if err := validateSettingFieldPolicy("server", "friendlyName", requestedName); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_server_name", "Server name must be between 1 and 120 characters.")
		return
	}
	if claim := s.currentRemoteAccessClaim(); claim != nil && claim.Status == "pending" && claim.ServerName != "" && claim.ServerName != requestedName {
		writeJSON(w, http.StatusConflict, map[string]any{
			"type": "https://portico.media/problems/claim-name-locked", "title": "Server name is locked while setup is pending",
			"status": http.StatusConflict, "code": "claim_name_locked",
			"detail":     "Finish or cancel the current Portico Account setup before changing this server name.",
			"serverName": claim.ServerName,
		})
		return
	}
	if err := s.saveSetupServerNameContext(r.Context(), req.ServerName); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_server_name", "Server name must be between 1 and 120 characters.")
		return
	}
	status, err := s.startPorticoSetupClaim(r.Context())
	if err != nil {
		code, detail := porticoSetupClaimProblem(err)
		s.log.Warn("Portico Account setup claim failed", "code", code, "error", err)
		writeError(w, http.StatusBadGateway, code, detail)
		return
	}
	if status.Claim != nil {
		status.Claim.ClaimURL = porticoSetupClaimURL(status.Claim.ClaimURL, s.requestPublicOrigin(r))
	}
	// Keep the setup endpoint aligned with its public contract. Remote-access
	// endpoints return the status directly, while this first-run auth endpoint
	// names it explicitly so clients can distinguish it from future setup state.
	writeJSON(w, http.StatusCreated, map[string]any{"remoteAccess": status})
}

func (s *Server) handlePorticoSetupStatus(w http.ResponseWriter, r *http.Request) {
	if !setupRequestFromLoopback(r) {
		writeError(w, http.StatusForbidden, "setup_local_access_required", "Initial server setup is available only on this computer.")
		return
	}
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	setupRequired, err := s.inspectSetupRequired(r.Context(), r.URL.Path)
	if err != nil {
		writeSetupCheckError(w, err)
		return
	}
	status, statusErr := s.remoteAccessStatus()
	if statusErr != nil {
		writeError(w, http.StatusInternalServerError, "remote_access_failed", "Unable to load Remote Access status.")
		return
	}
	if status.PorticoConnected {
		if ownerErr := s.finishPorticoSetupActivation(r.Context(), status); ownerErr != nil {
			s.log.Warn("Portico Account setup owner activation is not ready", "error", ownerErr)
			writeError(w, http.StatusServiceUnavailable, "owner_link_pending", "Portico has activated this server, but the owner profile is still syncing. Portico will retry automatically.")
			return
		}
		setupRequired, _ = s.inspectSetupRequired(r.Context(), r.URL.Path)
	}
	writeJSON(w, http.StatusOK, map[string]any{"setupRequired": setupRequired, "remoteAccess": status})
}

func setupRequestFromLoopback(r *http.Request) bool {
	if r == nil {
		return false
	}
	host, _, err := net.SplitHostPort(strings.TrimSpace(r.RemoteAddr))
	if err != nil {
		return false
	}
	address, err := netip.ParseAddr(strings.Trim(host, "[]"))
	return err == nil && address.IsLoopback()
}

func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if s.porticoAccountMode() {
		writeError(w, http.StatusForbidden, "unsupported_auth_mode", "This server is configured for Portico account sign-in. Use web.getportico.tv or switch Remote Access to This Server sign-in.")
		return
	}
	var req BrowserLoginRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	identifier := strings.ToLower(strings.TrimSpace(req.Login))
	loginKey := loginRateKey("browser-login", r, identifier)
	if !s.allowLoginAttempt(loginKey) {
		w.Header().Set("Retry-After", "60")
		writeError(w, http.StatusTooManyRequests, "rate_limited", "Too many login attempts.")
		return
	}

	row := s.queryUserRow(r.Context(), `
		SELECT id, username, email, display_name, COALESCE(password_hash, ''), role, COALESCE(auth_origin, 'local'), COALESCE(portico_user_id, ''), COALESCE(portico_membership_id, ''), password_hash IS NOT NULL AND password_hash <> '', permissions_json, preferences_json, COALESCE(max_content_rating, ''), COALESCE(max_active_sessions, 0), COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0)
		FROM users
		WHERE lower(username) = ? OR lower(email) = ?
		ORDER BY CASE WHEN lower(username) = ? THEN 0 ELSE 1 END
		LIMIT 1`, identifier, identifier, identifier)
	var user User
	var passwordHash string
	var permissionsJSON string
	var preferencesJSON string
	if err := row.Scan(&user.ID, &user.Username, &user.Email, &user.DisplayName, &passwordHash, &user.Role, &user.AuthOrigin, &user.PorticoUserID, &user.PorticoMembershipID, &user.HasLocalPassword, &permissionsJSON, &preferencesJSON, &user.MaxContentRating, &user.MaxActiveSessions, &user.MaxActiveStreams, &user.RemoteBitrateLimitMbps); err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "login_failed", "Unable to inspect login credentials.")
			return
		}
		_, kdfErr := verifyAccountPassword(r.Context(), kdfBrowserLoginCompare, "", req.Password)
		if writeKDFUnavailable(w, kdfErr) {
			return
		}
		s.recordLoginFailure(loginKey)
		writeError(w, http.StatusUnauthorized, "bad_credentials", "Username/email or password is incorrect.")
		return
	}
	if strings.TrimSpace(passwordHash) == "" {
		_, kdfErr := verifyAccountPassword(r.Context(), kdfBrowserLoginCompare, "", req.Password)
		if writeKDFUnavailable(w, kdfErr) {
			return
		}
		s.recordLoginFailure(loginKey)
		writeError(w, http.StatusUnauthorized, "bad_credentials", "Username/email or password is incorrect.")
		return
	}
	passwordValid, verifiedPasswordHash, err := s.verifyCanonicalPasswordSnapshot(r.Context(), kdfBrowserLoginCompare, passwordHash, req.Password)
	if err != nil {
		if writeKDFUnavailable(w, err) {
			return
		}
		writeDatabaseAccessError(w, err, http.StatusInternalServerError, "login_failed", "Unable to verify login credentials.")
		return
	}
	if !passwordValid {
		s.recordLoginFailure(loginKey)
		writeError(w, http.StatusUnauthorized, "bad_credentials", "Username/email or password is incorrect.")
		return
	}
	passwordHash = verifiedPasswordHash
	selectionRequired, err := s.accountRequiresExplicitProfileSelectionContext(r.Context(), user.ID)
	if err != nil {
		writeDatabaseAccessError(w, err, http.StatusInternalServerError, "login_failed", "Unable to inspect the available profiles.")
		return
	}
	if selectionRequired {
		writeError(w, http.StatusConflict, "profile_selection_required", "Choose a profile before creating this session.")
		return
	}
	if err := json.Unmarshal([]byte(permissionsJSON), &user.Permissions); err != nil {
		user.Permissions = map[string]bool{}
	}
	applyStoredUserPreferences(&user, preferencesJSON)
	s.populateUserLibraryIDsContext(r.Context(), &user)
	s.enrichUserAuthContextContext(r.Context(), &user, "local")
	sessionToken, err := s.createSessionForProviderWithSessionOptions(w, r, user.ID, "local", sessionCreateOptions{ExpectedLocalPasswordHash: passwordHash})
	if err != nil {
		if errors.Is(err, errDeviceNotTrusted) {
			writeError(w, http.StatusForbidden, "device_not_trusted", "This server only allows trusted devices. Ask an owner to approve this device in Settings > Devices.")
			return
		}
		if errors.Is(err, errDeviceNotAllowed) {
			writeError(w, http.StatusForbidden, "device_not_allowed", "This account is not allowed to use this device.")
			return
		}
		if errors.Is(err, errActiveSessionLimit) {
			writeError(w, http.StatusForbidden, "active_session_limit", "This account has reached its maximum active session limit.")
			return
		}
		if errors.Is(err, errAccessSchedule) {
			writeError(w, http.StatusForbidden, "access_schedule_blocked", "This account is outside its allowed access schedule.")
			return
		}
		if errors.Is(err, errBrowserAccountDisabled) {
			writeError(w, http.StatusForbidden, "account_disabled", "This account is disabled.")
			return
		}
		if errors.Is(err, errPasswordCredentialChanged) {
			writeError(w, http.StatusUnauthorized, "credentials_changed", "The account password changed while Portico was signing in. Sign in again.")
			return
		}
		writeError(w, http.StatusInternalServerError, "session_failed", "Unable to create session.")
		return
	}
	if rememberBrowserAccount(req.RememberOnBrowser) {
		if err := s.rememberBrowserAccountForSession(r.Context(), w, r, user.ID, "local", sessionToken); err != nil {
			s.discardBrowserSession(w, r.Context(), sessionToken)
			writeError(w, http.StatusInternalServerError, "browser_account_enrollment_failed", "Signed in credentials were valid, but this account could not be remembered on the browser.")
			return
		}
	}
	s.clearLoginFailures(loginKey)
	s.recordLog("info", "User signed in", map[string]string{"user": user.Email})

	response := s.authResponseWithServerContext(r.Context(), true, false, &user)
	writeJSON(w, http.StatusOK, response)
}

func (s *Server) handleQuickConnectStart(w http.ResponseWriter, r *http.Request) {
	quickConnectNoStore(w)
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if !s.allowQuickConnectPublicRequest(w, r, quickConnectRateStart) {
		return
	}
	var req QuickConnectStartRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	installationID := normalizeUntrustedNativeInstallationID(req.InstallationID)
	if installationID == "" {
		var generatedErr error
		installationID, generatedErr = nativeSecureRandomID(s.nativeCredentialEntropyReader(), "install")
		if generatedErr != nil {
			writeError(w, http.StatusInternalServerError, "quick_connect_entropy_unavailable", "Unable to securely create a Quick Connect request.")
			return
		}
	}
	now := time.Now().UTC()
	expires := now.Add(5 * time.Minute)
	secret, err := randomQuickConnectSecret(s.quickConnectEntropyReader())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "quick_connect_entropy_unavailable", "Unable to securely create a Quick Connect request.")
		return
	}
	defaultApp, defaultPlatform := classifyUserAgent(r.UserAgent())
	device := cleanQuickConnectLabel(req.DeviceName, firstNonEmpty(defaultPlatform, defaultApp, "Unknown device"))
	app := cleanQuickConnectLabel(req.App, firstNonEmpty(defaultApp, "Portico"))
	platform := cleanQuickConnectLabel(req.Platform, firstNonEmpty(defaultPlatform, "Unknown platform"))
	code, err := s.createQuickConnectRequest(secret, installationID, device, app, platform, r.UserAgent(), clientIPFromRequest(r), now, expires)
	if err != nil {
		if errors.Is(err, errQuickConnectEntropyUnavailable) {
			writeError(w, http.StatusInternalServerError, "quick_connect_entropy_unavailable", "Unable to securely create a Quick Connect request.")
			return
		}
		if errors.Is(err, errQuickConnectCodeSpaceBusy) {
			w.Header().Set("Retry-After", "2")
			writeError(w, http.StatusServiceUnavailable, "quick_connect_unavailable", "Quick Connect is temporarily unavailable.")
			return
		}
		writeError(w, http.StatusInternalServerError, "quick_connect_failed", "Unable to create quick connect code.")
		return
	}
	approvalURL, deepLinkURL := s.quickConnectApprovalLinks(r)
	writeJSON(w, http.StatusCreated, QuickConnectStartResponse{Code: code, ProtocolVersion: 1, Secret: secret, ExpiresAt: expires.Format(time.RFC3339), ApprovalURL: approvalURL, DeepLinkURL: deepLinkURL})
}

func (s *Server) handleQuickConnectStatus(w http.ResponseWriter, r *http.Request) {
	quickConnectNoStore(w)
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if !s.allowQuickConnectPublicRequest(w, r, quickConnectRateStatus) {
		return
	}
	var req struct {
		Secret string `json:"secret"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	secret := strings.TrimSpace(req.Secret)
	status, err := s.quickConnectStatus(secret)
	if err != nil {
		writeError(w, http.StatusNotFound, "quick_connect_not_found", "Quick connect request was not found.")
		return
	}
	writeJSON(w, http.StatusOK, status)
}

func (s *Server) handleQuickConnectExchange(w http.ResponseWriter, r *http.Request) {
	quickConnectNoStore(w)
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if !s.allowQuickConnectPublicRequest(w, r, quickConnectRateExchange) {
		return
	}
	var req struct {
		Secret string `json:"secret"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	result, credentials, err := s.exchangeQuickConnectCredentials(r, req.Secret)
	if err != nil {
		s.recordAudit(r, User{ID: result.UserID}, "quick_connect.exchange_failed", "quick_connect", result.RequestID, "warn", map[string]string{"reason": err.Error(), "device": result.Device, "app": result.App, "platform": result.Platform})
		if errors.Is(err, errDeviceNotTrusted) || errors.Is(err, errDeviceNotAllowed) || errors.Is(err, errActiveSessionLimit) || errors.Is(err, errAccessSchedule) || errors.Is(err, errNativeAccountDisabled) {
			s.writeNativeSessionCreationError(w, err)
		} else if errors.Is(err, errInvalidNativeRefreshToken) {
			writeError(w, http.StatusForbidden, "quick_connect_receipt_unavailable", "This Quick Connect exchange can no longer be recovered.")
		} else if errors.Is(err, errQuickConnectNotFound) || errors.Is(err, errQuickConnectNotApproved) || errors.Is(err, errQuickConnectExpired) || errors.Is(err, errQuickConnectAlreadyUsed) {
			writeError(w, http.StatusForbidden, "quick_connect_not_authorized", "Quick Connect is not ready to finish.")
		} else {
			writeError(w, http.StatusInternalServerError, "session_failed", "Unable to create native session.")
		}
		return
	}
	s.recordAudit(r, credentials.User, "quick_connect.exchanged", "quick_connect", result.RequestID, "info", map[string]string{"device": result.Device, "app": result.App, "platform": result.Platform})
	writeJSON(w, http.StatusOK, credentials)
}

func (s *Server) handleQuickConnectPending(w http.ResponseWriter, r *http.Request, user User) {
	quickConnectNoStore(w)
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	if !s.userCanApproveQuickConnect(user) {
		writeError(w, http.StatusForbidden, "quick_connect_approval_denied", "This account cannot approve Quick Connect requests.")
		return
	}
	requests, err := s.pendingQuickConnectRequests()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "quick_connect_failed", "Unable to list pending quick connect requests.")
		return
	}
	writeJSON(w, http.StatusOK, ListResponse[QuickConnectRequest]{Items: requests, Total: len(requests)})
}

func (s *Server) handleQuickConnectAuthorize(w http.ResponseWriter, r *http.Request, user User) {
	s.handleQuickConnectDecision(w, r, user, "approved")
}

func (s *Server) handleQuickConnectDeny(w http.ResponseWriter, r *http.Request, user User) {
	s.handleQuickConnectDecision(w, r, user, "denied")
}

func (s *Server) handleQuickConnectDecision(w http.ResponseWriter, r *http.Request, user User, status string) {
	quickConnectNoStore(w)
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if !s.userCanApproveQuickConnect(user) {
		writeError(w, http.StatusForbidden, "quick_connect_approval_denied", "This account cannot approve Quick Connect requests.")
		return
	}
	var req struct {
		Code string `json:"code"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	request, err := s.updateQuickConnectStatus(req.Code, user.ID, status)
	if err != nil {
		writeError(w, http.StatusNotFound, "quick_connect_not_found", "Pending quick connect code was not found or has expired.")
		return
	}
	verb := "approved"
	if status == "denied" {
		verb = "denied"
	}
	s.recordLog("info", "Quick Connect "+verb, map[string]string{"user": user.Email, "device": request.Device, "code": request.Code})
	action := "quick_connect.approved"
	severity := "info"
	if status == "denied" {
		action = "quick_connect.denied"
		severity = "warn"
	}
	s.recordAudit(r, user, action, "quick_connect", request.ID, severity, map[string]string{"device": request.Device, "app": request.App, "platform": request.Platform})
	writeJSON(w, http.StatusOK, request)
}

func (s *Server) handleLogout(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	for _, cookie := range s.requestSessionCookies(r) {
		tokenHash := hashToken(cookie.Value)
		var vaultID string
		_ = s.queryUserRow(r.Context(), `SELECT COALESCE(browser_vault_id, '') FROM sessions WHERE token_hash = ?`, tokenHash).Scan(&vaultID)
		_, _ = s.execSecurityFenceWrite(r.Context(), `DELETE FROM sessions WHERE token_hash = ?`, tokenHash)
		if vaultID != "" {
			_, _ = s.execUserWrite(r.Context(), `UPDATE browser_account_vaults SET active_user_id = NULL, last_seen_at = ? WHERE id = ? AND active_user_id = ? AND revoked_at = ''`, time.Now().UTC().Format(time.RFC3339), vaultID, user.ID)
		}
	}
	if header := strings.TrimSpace(r.Header.Get("Authorization")); strings.HasPrefix(header, "Bearer ") {
		token := strings.TrimSpace(strings.TrimPrefix(header, "Bearer "))
		if token != "" && !strings.HasPrefix(token, "ptc_clt_") {
			tokenHash := hashToken(token)
			var familyID string
			if err := s.queryUserRow(r.Context(), `
				SELECT rft.family_id
				FROM sessions sess
				JOIN native_refresh_tokens rft ON sess.id = 'nativesess_' || rft.id
				WHERE sess.token_hash = ?`, tokenHash).Scan(&familyID); err == nil {
				_ = s.revokeNativeCredentialFamily(r.Context(), familyID, time.Now().UTC())
			} else {
				_, _ = s.execSecurityFenceWrite(r.Context(), `DELETE FROM sessions WHERE token_hash = ?`, tokenHash)
			}
		}
	}
	s.clearSessionCookies(r.Context(), w)
	s.recordLog("info", "User signed out", map[string]string{"user": user.Email})
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

func (s *Server) allowLoginAttempt(key string) bool {
	s.loginLimiterMu.Lock()
	defer s.loginLimiterMu.Unlock()
	if s.loginAttempts == nil {
		s.loginAttempts = map[string][]time.Time{}
	}
	now := time.Now().UTC()
	cutoff := now.Add(-10 * time.Minute)
	if s.loginLimiterLastPrune.IsZero() || now.Sub(s.loginLimiterLastPrune) >= time.Minute || len(s.loginAttempts) >= 4096 {
		for candidate, existing := range s.loginAttempts {
			recent := existing[:0]
			for _, attempt := range existing {
				if attempt.After(cutoff) {
					recent = append(recent, attempt)
				}
			}
			if len(recent) == 0 {
				delete(s.loginAttempts, candidate)
			} else {
				s.loginAttempts[candidate] = recent
			}
		}
		s.loginLimiterLastPrune = now
	}
	attempts := s.loginAttempts[key][:0]
	for _, attempt := range s.loginAttempts[key] {
		if attempt.After(cutoff) {
			attempts = append(attempts, attempt)
		}
	}
	if len(attempts) == 0 {
		delete(s.loginAttempts, key)
	} else {
		s.loginAttempts[key] = attempts
	}
	if len(attempts) == 0 && len(s.loginAttempts) >= 4096 {
		return false
	}
	return len(attempts) < 8
}

func (s *Server) recordLoginFailure(key string) {
	s.loginLimiterMu.Lock()
	defer s.loginLimiterMu.Unlock()
	if s.loginAttempts == nil {
		s.loginAttempts = map[string][]time.Time{}
	}
	if _, exists := s.loginAttempts[key]; !exists && len(s.loginAttempts) >= 4096 {
		return
	}
	s.loginAttempts[key] = append(s.loginAttempts[key], time.Now().UTC())
}

func loginRateKey(scope string, r *http.Request, subject string) string {
	subject = strings.ToLower(strings.TrimSpace(subject))
	digest := hashToken(subject)
	if len(digest) > 16 {
		digest = digest[:16]
	}
	return strings.Join([]string{scope, clientIPFromRequest(r), digest}, ":")
}

func (s *Server) clearLoginFailures(key string) {
	s.loginLimiterMu.Lock()
	defer s.loginLimiterMu.Unlock()
	if s.loginAttempts == nil {
		return
	}
	delete(s.loginAttempts, key)
}

func (s *Server) handleLibraryNavigationPreferences(w http.ResponseWriter, r *http.Request, user User) {
	switch r.Method {
	case http.MethodGet:
		preferences, err := s.libraryNavigationPreferencesContext(r.Context(), user)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_navigation_failed", "Unable to load library navigation preferences.")
			return
		}
		writeJSON(w, http.StatusOK, preferences)
	case http.MethodPatch:
		var req LibraryNavigationPreferencesRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		preferences, err := s.saveLibraryNavigationPreferencesContext(r.Context(), user, req)
		if err != nil {
			if errors.Is(err, errInvalidLibraryNavigation) {
				writeError(w, http.StatusBadRequest, "invalid_library_navigation", err.Error())
				return
			}
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_navigation_failed", "Unable to save library navigation preferences.")
			return
		}
		s.recordAudit(r, user, "account.library_navigation_updated", "user", user.ID, "info", map[string]string{"pinnedLibraries": strconv.Itoa(len(preferences.PinnedLibraryIDs))})
		writeJSON(w, http.StatusOK, preferences)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or PATCH for this endpoint.")
	}
}

var errInvalidLibraryNavigation = errors.New("library navigation includes a library that is not available to this account")

func (s *Server) libraryNavigationPreferencesContext(ctx context.Context, user User) (LibraryNavigationPreferences, error) {
	libraries, err := s.listLibrariesForUserContext(ctx, user)
	if err != nil {
		return LibraryNavigationPreferences{}, err
	}
	if err := s.ensureLibraryNavigationRowsContext(ctx, accountIDForUser(user), viewerProfileID(user), libraries); err != nil {
		return LibraryNavigationPreferences{}, err
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT n.library_id
		FROM user_library_navigation n
		WHERE n.profile_id = ? AND n.pinned = 1
		  AND EXISTS (SELECT 1 FROM libraries l WHERE l.id = n.library_id)
		ORDER BY n.sort_order ASC, n.library_id ASC`, viewerProfileID(user))
	if err != nil {
		return LibraryNavigationPreferences{}, err
	}
	defer rows.Close()
	available := make(map[string]bool, len(libraries))
	for _, library := range libraries {
		available[library.ID] = true
	}
	result := LibraryNavigationPreferences{PinnedLibraryIDs: []string{}}
	for rows.Next() {
		var libraryID string
		if err := rows.Scan(&libraryID); err != nil {
			return LibraryNavigationPreferences{}, err
		}
		if available[libraryID] {
			result.PinnedLibraryIDs = append(result.PinnedLibraryIDs, libraryID)
		}
	}
	return result, rows.Err()
}

func (s *Server) ensureLibraryNavigationRowsContext(ctx context.Context, accountID, profileID string, libraries []Library) error {
	if len(libraries) == 0 {
		return nil
	}
	now := time.Now().UTC().Format(time.RFC3339)
	return s.withUserTxTaggedForViewer(ctx, accountID, profileID, []string{"libraries", "home"}, func(tx *sql.Tx) error {
		for index, library := range libraries {
			if _, err := tx.Exec(`
				INSERT INTO user_library_navigation (profile_id, user_id, library_id, pinned, sort_order, created_at, updated_at)
				VALUES (?, ?, ?, 1, ?, ?, ?)
				ON CONFLICT(profile_id, library_id) DO NOTHING`, profileID, accountID, library.ID, index, now, now); err != nil {
				return err
			}
		}
		return nil
	})
}

func (s *Server) saveLibraryNavigationPreferencesContext(ctx context.Context, user User, req LibraryNavigationPreferencesRequest) (LibraryNavigationPreferences, error) {
	libraries, err := s.listLibrariesForUserContext(ctx, user)
	if err != nil {
		return LibraryNavigationPreferences{}, err
	}
	available := make(map[string]bool, len(libraries))
	for _, library := range libraries {
		available[library.ID] = true
	}
	ordered := make([]string, 0, len(req.PinnedLibraryIDs))
	seen := make(map[string]bool, len(req.PinnedLibraryIDs))
	for _, raw := range req.PinnedLibraryIDs {
		libraryID := strings.TrimSpace(raw)
		if libraryID == "" || seen[libraryID] {
			continue
		}
		if !available[libraryID] {
			return LibraryNavigationPreferences{}, errInvalidLibraryNavigation
		}
		seen[libraryID] = true
		ordered = append(ordered, libraryID)
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if err := s.withUserTxTaggedForViewer(ctx, accountIDForUser(user), viewerProfileID(user), []string{"libraries", "home"}, func(tx *sql.Tx) error {
		for index, libraryID := range ordered {
			if _, err := tx.Exec(`
				INSERT INTO user_library_navigation (profile_id, user_id, library_id, pinned, sort_order, created_at, updated_at)
				VALUES (?, ?, ?, 1, ?, ?, ?)
				ON CONFLICT(profile_id, library_id) DO UPDATE SET pinned = 1, sort_order = excluded.sort_order, updated_at = excluded.updated_at`,
				viewerProfileID(user), accountIDForUser(user), libraryID, index, now, now); err != nil {
				return err
			}
		}
		for _, library := range libraries {
			if seen[library.ID] {
				continue
			}
			if _, err := tx.Exec(`
				INSERT INTO user_library_navigation (profile_id, user_id, library_id, pinned, sort_order, created_at, updated_at)
				VALUES (?, ?, ?, 0, 0, ?, ?)
				ON CONFLICT(profile_id, library_id) DO UPDATE SET pinned = 0, updated_at = excluded.updated_at`,
				viewerProfileID(user), accountIDForUser(user), library.ID, now, now); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		return LibraryNavigationPreferences{}, err
	}
	return LibraryNavigationPreferences{PinnedLibraryIDs: ordered}, nil
}

func (s *Server) handleAccountWatchHistory(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodDelete {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use DELETE for this endpoint.")
		return
	}
	response, err := s.clearAccountWatchHistoryContext(r.Context(), user)
	if err != nil {
		writeDatabaseAccessError(w, err, http.StatusInternalServerError, "watch_history_clear_failed", "Unable to clear watch history.")
		return
	}
	writeJSON(w, http.StatusOK, response)
}

func (s *Server) clearAccountWatchHistoryContext(ctx context.Context, user User) (WatchHistoryClearResponse, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	accountID := accountIDForUser(user)
	profileID := viewerProfileID(user)
	if accountID == "" || profileID == "" {
		return WatchHistoryClearResponse{}, sql.ErrNoRows
	}
	now := time.Now().UTC().Format(time.RFC3339)
	err := s.withUserTxTaggedForViewer(ctx, accountID, profileID, []string{"media-state", "playback-progress", "dashboard:history", "home", "playback"}, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, `
			DELETE FROM playback_session_history
			WHERE session_id IN (SELECT id FROM playback_sessions WHERE user_id = ? AND profile_id = ?)`, accountID, profileID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `
			DELETE FROM dashboard_playback_rollups
			WHERE session_id IN (SELECT id FROM playback_sessions WHERE user_id = ? AND profile_id = ?)`, accountID, profileID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `
			DELETE FROM playback_sessions
			WHERE user_id = ? AND profile_id = ? AND ended_at <> ''`, accountID, profileID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `
			UPDATE playback_sessions
			SET history_paused = 1
			WHERE user_id = ? AND profile_id = ? AND ended_at = ''`, accountID, profileID); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, `
			UPDATE user_media_state
			SET watched = 0,
				progress_seconds = 0,
				last_played_at = '',
				updated_at = ?
			WHERE user_id = ? AND profile_id = ?
				AND (watched <> 0 OR progress_seconds <> 0 OR COALESCE(last_played_at, '') <> '')`, now, accountID, profileID)
		return err
	})
	if err != nil {
		return WatchHistoryClearResponse{}, err
	}
	s.invalidateHomeCacheForProfile(profileID)
	s.invalidateDashboardCache()
	return WatchHistoryClearResponse{OK: true, ClearedAt: now}, nil
}

func (s *Server) handleAccountProfile(w http.ResponseWriter, r *http.Request, user User) {
	if !selectedProfileMayManageAccount(user) {
		writeError(w, http.StatusForbidden, "primary_profile_required", "Switch to the primary profile to manage account settings.")
		return
	}
	switch r.Method {
	case http.MethodGet:
		writeJSON(w, http.StatusOK, user)
	case http.MethodPatch:
		if user.AuthOrigin == "portico" || user.AuthProvider == "portico" {
			writeProductError(w, http.StatusConflict, "hosted_identity_authority", "Update this identity through Portico Account.")
			return
		}
		var req AccountProfileRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		displayName := strings.TrimSpace(req.DisplayName)
		if length := len([]rune(displayName)); length < 2 || length > 80 {
			writeError(w, http.StatusBadRequest, "invalid_display_name", "Display name must be between 2 and 80 characters.")
			return
		}
		email := strings.ToLower(strings.TrimSpace(req.Email))
		if !validAccountEmail(email) {
			writeError(w, http.StatusBadRequest, "invalid_email", "Enter a valid email address.")
			return
		}
		if req.CurrentPassword == "" || len([]byte(req.CurrentPassword)) > 72 {
			writeProductError(w, http.StatusBadRequest, "profile_reauthentication_required", "Enter the current account password.")
			return
		}
		rateKey := strings.Join([]string{"account-profile", accountIDForUser(user), clientIPFromRequest(r)}, ":")
		if !s.allowLoginAttempt(rateKey) {
			w.Header().Set("Retry-After", "600")
			writeError(w, http.StatusTooManyRequests, "rate_limited", "Too many identity verification attempts. Try again later.")
			return
		}
		var passwordHash string
		if err := s.queryUserRow(r.Context(), `SELECT COALESCE(password_hash, '') FROM users WHERE id = ?`, accountIDForUser(user)).Scan(&passwordHash); err != nil {
			writeDatabaseAccessError(w, err, http.StatusServiceUnavailable, "profile_reauthentication_unavailable", "Unable to verify the current password.")
			return
		}
		valid, verifiedPasswordHash, err := s.verifyCanonicalPasswordSnapshot(r.Context(), kdfProfileReauthCompare, passwordHash, req.CurrentPassword)
		if err != nil {
			if writeKDFUnavailable(w, err) {
				return
			}
			writeDatabaseAccessError(w, err, http.StatusServiceUnavailable, "profile_reauthentication_unavailable", "Unable to verify the current password.")
			return
		}
		if !valid {
			s.recordLoginFailure(rateKey)
			writeProductError(w, http.StatusUnauthorized, "profile_reauthentication_required", "The current account password is incorrect.")
			return
		}
		passwordHash = verifiedPasswordHash
		s.clearLoginFailures(rateKey)
		sessionID, err := s.currentSessionIDContext(r.Context(), r, user)
		if err != nil {
			writeProductError(w, http.StatusUnauthorized, "interactive_session_required", "Profile updates require a current interactive session.")
			return
		}
		now := time.Now().UTC()
		err = s.withUserTxTagged(r.Context(), []string{"users", "sessions", "devices"}, func(tx *sql.Tx) error {
			if err := validatePasswordSessionTx(tx, accountIDForUser(user), viewerProfileID(user), sessionID, passwordHash, now); err != nil {
				return err
			}
			var conflictingID string
			err := tx.QueryRow(`SELECT id FROM users WHERE lower(email) = lower(?) AND id <> ? LIMIT 1`, email, user.ID).Scan(&conflictingID)
			if err != nil && !errors.Is(err, sql.ErrNoRows) {
				return err
			}
			if conflictingID != "" {
				return errAccountEmailInUse
			}
			_, err = tx.Exec(`UPDATE users SET display_name = ?, email = ?, updated_at = ? WHERE id = ? AND COALESCE(disabled_at, '') = ''`, displayName, email, now.Format(time.RFC3339), user.ID)
			return err
		})
		if errors.Is(err, errAccountEmailInUse) {
			writeError(w, http.StatusConflict, "email_in_use", "Email address is already used by another profile.")
			return
		}
		if errors.Is(err, errPasswordCredentialChanged) || errors.Is(err, errPrivilegedSessionChanged) {
			writeProductError(w, http.StatusUnauthorized, "credentials_changed", "The account authorization changed while Portico was saving this request. Sign in again and retry.")
			return
		}
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "profile_update_failed", "Unable to update profile.")
			return
		}
		next, err := s.getUser(user.ID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "profile_update_failed", "Unable to load updated profile.")
			return
		}
		s.recordAudit(r, next, "account.profile.updated", "user", next.ID, "info", map[string]string{"email": next.Email})
		writeJSON(w, http.StatusOK, next)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or PATCH for this endpoint.")
	}
}

func validAccountEmail(email string) bool {
	if email == "" || len(email) > 254 || strings.Count(email, "@") != 1 || strings.ContainsAny(email, " \t\r\n") {
		return false
	}
	parts := strings.SplitN(email, "@", 2)
	return parts[0] != "" && parts[1] != "" && !strings.HasPrefix(parts[1], ".") && !strings.HasSuffix(parts[1], ".")
}

func (s *Server) handleDisplayPreferences(w http.ResponseWriter, r *http.Request, user User) {
	client, view, ok := displayPreferenceRouteParts(r.URL.Path)
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "Display preference route was not found.")
		return
	}
	switch r.Method {
	case http.MethodGet:
		preference, err := s.displayPreference(viewerProfileID(user), client, view)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "display_preferences_failed", "Unable to load display preferences.")
			return
		}
		writeJSON(w, http.StatusOK, preference)
	case http.MethodPatch:
		var req DisplayPreferenceRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		preferences, err := sanitizeDisplayPreferencePayload(req.Preferences)
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_display_preferences", err.Error())
			return
		}
		preference, err := s.saveDisplayPreference(viewerProfileID(user), client, view, preferences)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "display_preferences_failed", "Unable to save display preferences.")
			return
		}
		writeJSON(w, http.StatusOK, preference)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or PATCH for this endpoint.")
	}
}

func (s *Server) handleAccountImage(w http.ResponseWriter, r *http.Request, user User) {
	switch r.Method {
	case http.MethodGet, http.MethodHead:
		var path, profileImageURL, authOrigin, porticoUserID string
		if err := s.queryUserRow(r.Context(), `SELECT COALESCE(profile_image_path, ''), COALESCE(profile_image_url, ''), COALESCE(auth_origin, 'local'), COALESCE(portico_user_id, '') FROM users WHERE id = ?`, user.ID).Scan(&path, &profileImageURL, &authOrigin, &porticoUserID); err != nil {
			if !errors.Is(err, sql.ErrNoRows) {
				writeDatabaseAccessError(w, err, http.StatusNotFound, "profile_image_not_found", "Profile image was not found.")
				return
			}
			writeError(w, http.StatusNotFound, "profile_image_not_found", "Profile image was not found.")
			return
		}
		if strings.EqualFold(authOrigin, "portico") && strings.TrimSpace(profileImageURL) != "" && strings.TrimSpace(porticoUserID) != "" {
			if s.serveHostedProfileImage(w, r, porticoUserID) {
				return
			}
		}
		if strings.TrimSpace(path) == "" {
			writeError(w, http.StatusNotFound, "profile_image_not_found", "Profile image was not found.")
			return
		}
		root := filepath.Join(s.cfg.AppDataDir, "profile-images")
		if !pathInsideRoot(path, root) {
			writeError(w, http.StatusBadRequest, "profile_image_invalid", "Profile image path is invalid.")
			return
		}
		s.serveProfileImageFile(w, r, path)
	case http.MethodPost:
		s.handleAccountImageUpload(w, r, user)
	case http.MethodDelete:
		s.handleAccountImageDelete(w, r, user)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET, POST, or DELETE for this endpoint.")
	}
}

func (s *Server) serveHostedProfileImage(w http.ResponseWriter, r *http.Request, porticoUserID string) bool {
	settings, err := s.remoteAccessSettings()
	if err != nil || settings.ServerID == "" {
		return false
	}
	credential := s.secretSetting(remoteAccessCredentialKey)
	if credential == "" {
		return false
	}
	endpoint := strings.TrimRight(settings.HostedBaseURL, "/") + "/api/servers/" + url.PathEscape(settings.ServerID) + "/members/" + url.PathEscape(porticoUserID) + "/image"
	requestCtx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(requestCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return false
	}
	req.Header.Set("Authorization", "Bearer "+credential)
	resp, err := hostedServicesHTTPClient().Do(req)
	if err != nil {
		s.log.Warn("fetch hosted profile image failed", "user", porticoUserID, "error", err)
		return false
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		return false
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		s.log.Warn("fetch hosted profile image returned error", "user", porticoUserID, "status", resp.Status)
		return false
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, (2<<20)+1))
	if err != nil || len(data) == 0 || len(data) > 2<<20 {
		s.log.Warn("read hosted profile image failed", "user", porticoUserID, "error", err)
		return false
	}
	width, height, resizeRequested, err := artworkResizeParams(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_profile_image_size", err.Error())
		return true
	}
	w.Header().Set("Cache-Control", "private, max-age=3600")
	if !resizeRequested {
		contentType := resp.Header.Get("Content-Type")
		if contentType == "" {
			contentType = http.DetectContentType(data)
		}
		w.Header().Set("Content-Type", contentType)
		if r.Method != http.MethodHead {
			_, _ = w.Write(data)
		}
		return true
	}
	source, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_resize_failed", "Profile image could not be decoded.")
		return true
	}
	resized := resizeImageNearest(source, width, height)
	w.Header().Set("Content-Type", "image/jpeg")
	if r.Method == http.MethodHead {
		return true
	}
	if err := jpeg.Encode(w, resized, &jpeg.Options{Quality: 88}); err != nil {
		s.log.Warn("encode hosted profile image failed", "user", porticoUserID, "error", err)
	}
	return true
}

func (s *Server) serveProfileImageFile(w http.ResponseWriter, r *http.Request, path string) {
	width, height, resizeRequested, err := artworkResizeParams(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_profile_image_size", err.Error())
		return
	}
	w.Header().Set("Cache-Control", "private, max-age=3600")
	if !resizeRequested {
		http.ServeFile(w, r, path)
		return
	}
	if cachePath, ok := s.resizedImageCachePath("profile", path, width, height); ok {
		if _, err := os.Stat(cachePath); err == nil {
			http.ServeFile(w, r, cachePath)
			return
		}
		if r.Method != http.MethodHead {
			if err := s.writeResizedImageCache(path, cachePath, width, height); err == nil {
				http.ServeFile(w, r, cachePath)
				return
			} else {
				s.log.Warn("cache resized profile image failed", "path", path, "cachePath", cachePath, "error", err)
			}
		}
	}
	file, err := os.Open(path)
	if err != nil {
		writeError(w, http.StatusNotFound, "profile_image_not_found", "Profile image was not found.")
		return
	}
	defer file.Close()
	source, _, err := image.Decode(file)
	if err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_resize_failed", "Profile image could not be decoded.")
		return
	}
	resized := resizeImageNearest(source, width, height)
	w.Header().Set("Content-Type", "image/jpeg")
	if r.Method == http.MethodHead {
		return
	}
	if err := jpeg.Encode(w, resized, &jpeg.Options{Quality: 88}); err != nil {
		s.log.Warn("encode resized profile image failed", "path", path, "error", err)
	}
}

func (s *Server) handleAccountImageUpload(w http.ResponseWriter, r *http.Request, user User) {
	if !selectedProfileMayManageAccount(user) {
		writeError(w, http.StatusForbidden, "primary_profile_required", "Switch to the primary profile to manage account settings.")
		return
	}
	if err := r.ParseMultipartForm(2 << 20); err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_upload_failed", "Profile image upload must be a multipart image file under 2 MB.")
		return
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_upload_failed", "Profile image file is required.")
		return
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, (2<<20)+1))
	if err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_upload_failed", "Unable to read profile image.")
		return
	}
	if len(data) == 0 || len(data) > 2<<20 {
		writeError(w, http.StatusBadRequest, "profile_image_upload_failed", "Profile image upload must be under 2 MB.")
		return
	}
	extension, _, _, err := validateUploadedArtwork(data, header.Filename)
	if err != nil {
		writeError(w, http.StatusBadRequest, "profile_image_upload_failed", err.Error())
		return
	}
	var previous string
	_ = s.queryUserRow(context.Background(), `SELECT COALESCE(profile_image_path, '') FROM users WHERE id = ?`, user.ID).Scan(&previous)
	dir := filepath.Join(s.cfg.AppDataDir, "profile-images", safePathComponent(user.ID))
	if err := os.MkdirAll(dir, 0o700); err != nil {
		writeError(w, http.StatusInternalServerError, "profile_image_upload_failed", "Unable to store profile image.")
		return
	}
	path := filepath.Join(dir, randomID("profile")+"."+extension)
	if err := os.WriteFile(path, data, 0o600); err != nil {
		writeError(w, http.StatusInternalServerError, "profile_image_upload_failed", "Unable to store profile image.")
		return
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if _, err := s.execUserWrite(context.Background(), `UPDATE users SET profile_image_path = ?, profile_image_url = '', updated_at = ? WHERE id = ?`, path, now, user.ID); err != nil {
		_ = os.Remove(path)
		writeError(w, http.StatusInternalServerError, "profile_image_upload_failed", "Unable to save profile image.")
		return
	}
	removeProfileImagePath(s.cfg.AppDataDir, previous)
	next, err := s.getUser(user.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "profile_image_upload_failed", "Unable to load updated user.")
		return
	}
	writeJSON(w, http.StatusCreated, next)
}

func (s *Server) handleAccountImageDelete(w http.ResponseWriter, r *http.Request, user User) {
	if !selectedProfileMayManageAccount(user) {
		writeError(w, http.StatusForbidden, "primary_profile_required", "Switch to the primary profile to manage account settings.")
		return
	}
	var previous string
	if err := s.queryUserRow(context.Background(), `SELECT COALESCE(profile_image_path, '') FROM users WHERE id = ?`, user.ID).Scan(&previous); err != nil {
		writeError(w, http.StatusNotFound, "profile_not_found", "User profile was not found.")
		return
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if _, err := s.execUserWrite(context.Background(), `UPDATE users SET profile_image_path = '', profile_image_url = '', updated_at = ? WHERE id = ?`, now, user.ID); err != nil {
		writeError(w, http.StatusInternalServerError, "profile_image_delete_failed", "Unable to delete profile image.")
		return
	}
	removeProfileImagePath(s.cfg.AppDataDir, previous)
	next, err := s.getUser(user.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "profile_image_delete_failed", "Unable to load updated user.")
		return
	}
	writeJSON(w, http.StatusOK, next)
}

func profileImageURLForPath(path string, remoteURL ...string) string {
	if len(remoteURL) > 0 && strings.TrimSpace(remoteURL[0]) != "" {
		sum := sha256.Sum256([]byte(strings.TrimSpace(remoteURL[0])))
		return "/api/account/image?v=" + hex.EncodeToString(sum[:])[:12]
	}
	if strings.TrimSpace(path) == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(path))
	return "/api/account/image?v=" + hex.EncodeToString(sum[:])[:12]
}

func removeProfileImagePath(appDataDir, path string) {
	if strings.TrimSpace(path) == "" {
		return
	}
	root := filepath.Join(appDataDir, "profile-images")
	if pathInsideRoot(path, root) {
		_ = os.Remove(path)
	}
}

