func (s *Server) handleSystemIdentityReset(w http.ResponseWriter, r *http.Request, user User) {
	if !s.requireManageServer(w, user) {
		return
	}
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if err := s.resetServerIdentity(r.Context()); err != nil {
		writeError(w, http.StatusInternalServerError, "identity_reset_failed", "Unable to reset server identity.")
		return
	}
	s.invalidateSessionCookieCache()
	s.recordLog("warn", "Server identity reset", map[string]string{"actor": user.Email})
	s.recordAudit(r, user, "system.identity_reset", "system", "identity", "critical", nil)
	identity, err := s.systemIdentityContext(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "identity_failed", "Unable to load server identity.")
		return
	}
	writeJSON(w, http.StatusOK, identity)
}

func (s *Server) handleNetworkConnectionInfo(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view network settings.")
		return
	}
	identity, err := s.systemIdentityContext(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "network_failed", "Unable to load network information.")
		return
	}
	remoteSettings, err := s.remoteAccessSettings()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "network_failed", "Unable to load remote access information.")
		return
	}
	networkSettings := s.networkSettings()
	localURLs := []ConnectionURL{{
		Type:      "local",
		URL:       "http://" + s.cfg.Addr,
		Reachable: true,
		Note:      "Current local listener.",
	}}
	for _, accessURL := range networkSettings.CustomAccessURLs {
		localURLs = append(localURLs, ConnectionURL{
			Type:      "custom",
			URL:       accessURL,
			Reachable: false,
			Note:      "Configured client access URL. Reachability is checked by the client or deployment monitor.",
		})
	}
	remoteStatus := "disabled"
	if remoteSettings.Enabled {
		remoteStatus = "enabled"
	}
	discovery := "not_claimed"
	if remoteSettings.ServerID != "" && remoteSettings.ClaimStatus == "claimed" {
		discovery = "claimed"
	} else if remoteSettings.ClaimStatus != "" {
		discovery = remoteSettings.ClaimStatus
	}
	dynamicDNS := "not_assigned"
	if remoteSettings.AssignedHostname != "" {
		dynamicDNS = remoteSettings.AssignedHostname
	}
	tlsStatus := remoteSettings.CertificateStatus
	if tlsStatus == "" {
		tlsStatus = "not_requested"
	}
	info := NetworkConnectionInfo{
		ServerID:  identity.ServerID,
		LocalURLs: localURLs,
		RemoteAccess: RemoteAccessInfo{
			Status:      remoteStatus,
			Discovery:   discovery,
			DynamicDNS:  dynamicDNS,
			TLS:         tlsStatus,
			MediaPath:   "direct-only",
			Placeholder: false,
		},
		SecurePolicy: networkSettings.SecureConnections,
		LANNetworks:  networkSettings.LANNetworks,
		Placeholder:  false,
		Note:         "Local listener, custom access URLs, secure connection policy, LAN trust ranges, and remote-access status are runtime-backed. Portico provides discovery only; media paths stay direct.",
	}
	writeJSON(w, http.StatusOK, info)
}

type networkRuntimeSettings struct {
	SecureConnections string
	LANNetworks       []string
	CustomAccessURLs  []string
}

func (s *Server) networkSettings() networkRuntimeSettings {
	settings, err := s.loadSettings()
	if err != nil {
		return networkRuntimeSettings{SecureConnections: "preferred"}
	}
	group, _ := settings["network"].(map[string]any)
	return networkRuntimeSettings{
		SecureConnections: normalizeSecureConnectionPolicy(settingString(group, "secureConnections", "preferred")),
		LANNetworks:       parseCIDRList(settingString(group, "lanNetworks", "")),
		CustomAccessURLs:  parseAccessURLList(settingString(group, "customAccessUrls", "")),
	}
}

func normalizeSecureConnectionPolicy(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "required", "disabled":
		return strings.ToLower(strings.TrimSpace(value))
	default:
		return "preferred"
	}
}

func parseCIDRList(value string) []string {
	parts := splitSettingsList(value)
	out := []string{}
	for _, part := range parts {
		if _, _, err := net.ParseCIDR(part); err == nil {
			out = append(out, part)
		}
	}
	return out
}

func parseAccessURLList(value string) []string {
	parts := splitSettingsList(value)
	out := []string{}
	for _, part := range parts {
		parsed, err := url.Parse(part)
		if err == nil && parsed.Scheme != "" && parsed.Host != "" && (parsed.Scheme == "http" || parsed.Scheme == "https") {
			out = append(out, strings.TrimRight(parsed.String(), "/"))
		}
	}
	return out
}

func splitSettingsList(value string) []string {
	fields := strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == '\n' || r == '\r' || r == '\t'
	})
	out := []string{}
	for _, field := range fields {
		if trimmed := strings.TrimSpace(field); trimmed != "" {
			out = append(out, trimmed)
		}
	}
	return out
}

func (s *Server) handleFilesystemBrowse(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "Only the server owner can browse host folders.")
		return
	}
	requested := strings.TrimSpace(r.URL.Query().Get("path"))
	if requested == "" {
		if home, err := os.UserHomeDir(); err == nil && home != "" {
			requested = home
		} else {
			requested = string(filepath.Separator)
		}
	}
	response, filesystemErr := filesystemBrowseResponse(requested)
	if filesystemErr != nil {
		writeFilesystemAPIError(w, filesystemErr)
		return
	}
	writeJSON(w, http.StatusOK, response)
}

func (s *Server) handleFilesystemDirectories(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
		return
	}
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "Only the server owner can create host folders.")
		return
	}
	var req FilesystemCreateDirectoryRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	createdPath, filesystemErr := createFilesystemDirectory(req.Path)
	if filesystemErr != nil {
		writeFilesystemAPIError(w, filesystemErr)
		return
	}
	response, filesystemErr := filesystemBrowseResponse(createdPath)
	if filesystemErr != nil {
		writeFilesystemAPIError(w, filesystemErr)
		return
	}
	s.recordLog("info", "Filesystem folder created", map[string]string{"actor": user.Email, "path": response.Path})
	s.recordAudit(r, user, "filesystem.directory_created", "filesystem", response.Path, "info", map[string]string{"path": response.Path})
	writeJSON(w, http.StatusCreated, response)
}

type filesystemAPIError struct {
	status  int
	code    string
	message string
}

func newFilesystemAPIError(status int, code string, message string) *filesystemAPIError {
	return &filesystemAPIError{status: status, code: code, message: message}
}

func writeFilesystemAPIError(w http.ResponseWriter, err *filesystemAPIError) {
	if err == nil {
		return
	}
	writeError(w, err.status, err.code, err.message)
}

func filesystemBrowseResponse(requested string) (FilesystemBrowseResponse, *filesystemAPIError) {
	if strings.ContainsRune(requested, 0) {
		return FilesystemBrowseResponse{}, newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path is invalid.")
	}
	if !filepath.IsAbs(requested) {
		return FilesystemBrowseResponse{}, newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path must be absolute.")
	}
	resolved, err := filepath.EvalSymlinks(requested)
	if err != nil {
		return FilesystemBrowseResponse{}, newFilesystemAPIError(http.StatusBadRequest, "folder_unavailable", "Folder could not be opened.")
	}
	info, err := os.Stat(resolved)
	if err != nil || !info.IsDir() {
		return FilesystemBrowseResponse{}, newFilesystemAPIError(http.StatusBadRequest, "folder_unavailable", "Path is not a readable folder.")
	}
	dirEntries, err := os.ReadDir(resolved)
	if err != nil {
		return FilesystemBrowseResponse{}, newFilesystemAPIError(http.StatusForbidden, "folder_unavailable", "Folder could not be read.")
	}
	entries := make([]FilesystemBrowseEntry, 0, len(dirEntries))
	for _, entry := range dirEntries {
		path := filepath.Join(resolved, entry.Name())
		entryPath := path
		kind := "file"
		readable := false
		if entry.IsDir() {
			kind = "directory"
			if _, err := os.ReadDir(path); err == nil {
				readable = true
			}
		} else if entry.Type()&os.ModeSymlink != 0 {
			if targetInfo, err := os.Stat(path); err == nil && targetInfo.IsDir() {
				kind = "directory"
				readable = true
				if targetPath, err := filepath.EvalSymlinks(path); err == nil {
					entryPath = targetPath
				}
			}
		}
		if kind != "directory" {
			continue
		}
		entries = append(entries, FilesystemBrowseEntry{
			Name:     entry.Name(),
			Path:     entryPath,
			Kind:     kind,
			Readable: readable,
		})
	}
	sort.Slice(entries, func(i, j int) bool {
		return strings.ToLower(entries[i].Name) < strings.ToLower(entries[j].Name)
	})
	parent := filepath.Dir(resolved)
	if parent == resolved {
		parent = ""
	}
	return FilesystemBrowseResponse{
		Path:    resolved,
		Parent:  parent,
		Roots:   filesystemBrowseRoots(),
		Entries: entries,
	}, nil
}

func createFilesystemDirectory(requested string) (string, *filesystemAPIError) {
	requested = strings.TrimSpace(requested)
	if requested == "" {
		return "", newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path is required.")
	}
	if strings.ContainsRune(requested, 0) {
		return "", newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path is invalid.")
	}
	if !filepath.IsAbs(requested) {
		return "", newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path must be absolute.")
	}
	cleaned := filepath.Clean(requested)
	if isFilesystemRootPath(cleaned) {
		return "", newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path must name a new folder, not a filesystem root.")
	}
	parent := filepath.Dir(cleaned)
	name := filepath.Base(cleaned)
	if strings.TrimSpace(name) == "" || name == "." || name == string(filepath.Separator) {
		return "", newFilesystemAPIError(http.StatusBadRequest, "invalid_path", "Folder path is invalid.")
	}
	resolvedParent, err := filepath.EvalSymlinks(parent)
	if err != nil {
		return "", newFilesystemAPIError(http.StatusBadRequest, "parent_unavailable", "Parent folder does not exist or could not be opened.")
	}
	parentInfo, err := os.Stat(resolvedParent)
	if err != nil || !parentInfo.IsDir() {
		return "", newFilesystemAPIError(http.StatusBadRequest, "parent_unavailable", "Parent path is not a folder.")
	}
	target := filepath.Join(resolvedParent, name)
	if info, err := os.Stat(target); err == nil {
		if info.IsDir() {
			return "", newFilesystemAPIError(http.StatusConflict, "folder_exists", "Folder already exists.")
		}
		return "", newFilesystemAPIError(http.StatusConflict, "path_exists", "A file already exists at that path.")
	} else if !os.IsNotExist(err) {
		return "", newFilesystemAPIError(http.StatusForbidden, "folder_unavailable", "Folder path could not be inspected.")
	}
	if err := os.Mkdir(target, 0o700); err != nil {
		switch {
		case os.IsExist(err):
			return "", newFilesystemAPIError(http.StatusConflict, "folder_exists", "Folder already exists.")
		case os.IsPermission(err):
			return "", newFilesystemAPIError(http.StatusForbidden, "folder_create_denied", "Portico does not have permission to create that folder.")
		default:
			return "", newFilesystemAPIError(http.StatusBadRequest, "folder_create_failed", "Folder could not be created.")
		}
	}
	resolved, err := filepath.EvalSymlinks(target)
	if err != nil {
		return "", newFilesystemAPIError(http.StatusBadRequest, "folder_unavailable", "Created folder could not be opened.")
	}
	return resolved, nil
}

func isFilesystemRootPath(path string) bool {
	cleaned := filepath.Clean(path)
	return filepath.Dir(cleaned) == cleaned
}

func filesystemBrowseRoots() []FilesystemRoot {
	roots := []FilesystemRoot{}
	add := func(name, path string) {
		path = strings.TrimSpace(path)
		if path == "" {
			return
		}
		clean := filepath.Clean(path)
		for _, root := range roots {
			if sameHostPath(root.Path, clean) {
				return
			}
		}
		roots = append(roots, FilesystemRoot{Name: name, Path: clean})
	}
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		add("Home", home)
	}
	if runtime.GOOS == "windows" {
		for drive := 'A'; drive <= 'Z'; drive++ {
			path := string(drive) + `:\`
			if info, err := os.Stat(path); err == nil && info.IsDir() {
				add(path, path)
			}
		}
	} else {
		add("Computer", string(filepath.Separator))
		if runtime.GOOS == "darwin" {
			if info, err := os.Stat("/Volumes"); err == nil && info.IsDir() {
				add("Volumes", "/Volumes")
			}
		}
	}
	return roots
}

func (s *Server) handleLibraries(w http.ResponseWriter, r *http.Request, user User) {
	switch r.Method {
	case http.MethodGet:
		libraries, err := s.listLibrariesForUserContext(r.Context(), user)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "libraries_failed", "Unable to load libraries.")
			return
		}
		writeJSON(w, http.StatusOK, ListResponse[Library]{Items: libraries, Total: len(libraries)})
	case http.MethodPost:
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to create libraries.")
			return
		}
		var req CreateLibraryRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		library, err := s.createLibrary(req)
		if err != nil {
			writeError(w, http.StatusBadRequest, "library_create_failed", err.Error())
			return
		}
		s.recordLog("info", "Library created", map[string]string{"actor": user.Email, "library": library.Name, "type": library.Type})
		s.recordAudit(r, user, "library.created", "library", library.ID, "info", map[string]string{"name": library.Name, "type": library.Type})
		writeJSON(w, http.StatusCreated, library)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or POST for this endpoint.")
	}
}

func (s *Server) handleLibraryRoute(w http.ResponseWriter, r *http.Request, user User) {
	path := strings.TrimPrefix(r.URL.Path, "/api/libraries/")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 0 || parts[0] == "" {
		writeError(w, http.StatusNotFound, "not_found", "Library route was not found.")
		return
	}
	libraryID := parts[0]
	if s.handleLibraryScanOperations(w, r, user, libraryID, parts) {
		return
	}
	if len(parts) == 2 && parts[0] == "trash" && parts[1] == "empty" && r.Method == http.MethodPost {
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to empty library trash.")
			return
		}
		existing := false
		job, ok, err := s.activeJobFor("library_trash_cleanup", "maintenance", "manual")
		if err != nil {
			writeError(w, http.StatusInternalServerError, "trash_empty_failed", "Unable to inspect library trash cleanup jobs.")
			return
		}
		if ok {
			existing = true
		} else {
			job, err = s.createJobFor("library_trash_cleanup", "Library trash cleanup queued.", "maintenance", "manual")
			if err != nil {
				writeError(w, http.StatusInternalServerError, "trash_empty_failed", "Unable to queue library trash cleanup.")
				return
			}
		}
		s.recordAudit(r, user, "library.trash_cleanup_queued", "library", "all", "warn", map[string]string{"job": job.ID})
		writeJSON(w, http.StatusAccepted, map[string]any{"ok": true, "queued": true, "existing": existing, "job": job})
		return
	}

	if len(parts) == 1 && r.Method == http.MethodGet {
		ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
		defer cancel()
		allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_access_failed", "Unable to inspect library access.")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "forbidden", "This library is not shared with your account.")
			return
		}
		library, err := s.getLibraryContext(ctx, libraryID)
		if err != nil {
			writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
			return
		}
		writeJSON(w, http.StatusOK, library)
		return
	}
	if len(parts) == 1 && r.Method == http.MethodPatch {
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to edit libraries.")
			return
		}
		var req UpdateLibraryRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		library, err := s.updateLibrary(libraryID, req)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
				return
			}
			writeError(w, http.StatusBadRequest, "library_update_failed", err.Error())
			return
		}
		s.recordLog("info", "Library updated", map[string]string{"actor": user.Email, "library": library.Name, "type": library.Type})
		s.recordAudit(r, user, "library.updated", "library", library.ID, "info", map[string]string{"name": library.Name, "type": library.Type})
		writeJSON(w, http.StatusOK, library)
		return
	}
	if len(parts) == 1 && r.Method == http.MethodDelete {
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to delete libraries.")
			return
		}
		if err := s.deleteLibrary(libraryID); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
				return
			}
			writeError(w, http.StatusInternalServerError, "library_delete_failed", "Unable to delete library.")
			return
		}
		s.recordLog("warn", "Library deleted", map[string]string{"actor": user.Email, "library": libraryID})
		s.recordAudit(r, user, "library.deleted", "library", libraryID, "warn", nil)
		writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
		return
	}
	if len(parts) == 2 && parts[1] == "discover" && r.Method == http.MethodGet {
		ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
		defer cancel()
		allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_access_failed", "Unable to inspect library access.")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "forbidden", "This library is not shared with your account.")
			return
		}
		library, err := s.getLibraryContext(ctx, libraryID)
		if err != nil {
			writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
			return
		}
		limit := clampInt(queryInt(r, "limit", 48), 1, 50)
		response, err := s.cachedLibraryDiscoverContext(ctx, user, library, limit)
		if err != nil {
			if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
				w.Header().Set("Retry-After", "1")
				writeError(w, http.StatusServiceUnavailable, "library_discover_timeout", "Library discover exceeded the foreground request budget. Try again shortly.")
				return
			}
			writeError(w, http.StatusInternalServerError, "library_discover_failed", "Unable to load library discover.")
			return
		}
		writeJSON(w, http.StatusOK, response)
		return
	}
	if len(parts) == 2 && parts[1] == "sources" && r.Method == http.MethodGet {
		if _, present := r.URL.Query()["offset"]; present {
			writeError(w, http.StatusBadRequest, "offset_not_supported", "Use the opaque cursor to continue library sources.")
			return
		}
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to browse library source paths.")
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
		defer cancel()
		allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_access_failed", "Unable to inspect library access.")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "forbidden", "This library is not shared with your account.")
			return
		}
		limit := clampInt(queryInt(r, "limit", 100), 1, 250)
		offset, err := s.decodeMaterializedPageCursor(r.URL.Query().Get("cursor"), "library-sources:"+libraryID, user.ID, time.Now().UTC())
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "Library source cursor is invalid or expired.")
			return
		}
		sources, total, err := s.listLibrarySourceGroupsPage(libraryID, limit, offset)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "library_sources_failed", "Unable to load library source paths.")
			return
		}
		hasMore := offset+len(sources) < total
		var nextCursor *string
		if hasMore {
			cursor, cursorErr := s.encodeMaterializedPageCursor("library-sources:"+libraryID, user.ID, offset+len(sources), time.Now().UTC())
			if cursorErr != nil {
				writeError(w, http.StatusInternalServerError, "library_cursor_failed", "Unable to continue library sources.")
				return
			}
			nextCursor = &cursor
		}
		writeJSON(w, http.StatusOK, CursorListResponse[LibrarySourceGroup]{Items: sources, PageInfo: CursorPageInfo{NextCursor: nextCursor, HasMore: hasMore}})
		return
	}
	if len(parts) == 2 && parts[1] == "categories" && r.Method == http.MethodGet {
		ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
		defer cancel()
		allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_access_failed", "Unable to inspect library access.")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "forbidden", "This library is not shared with your account.")
			return
		}
		categories, err := s.listLibraryCategoriesForUserContext(ctx, user, libraryID)
		if err != nil {
			if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
				w.Header().Set("Retry-After", "1")
				writeError(w, http.StatusServiceUnavailable, "library_categories_timeout", "Library categories exceeded the foreground request budget. Try again shortly.")
				return
			}
			writeError(w, http.StatusInternalServerError, "library_categories_failed", "Unable to load library categories.")
			return
		}
		limit := clampInt(queryInt(r, "limit", 50), 1, 100)
		offset, err := s.decodeMaterializedPageCursor(r.URL.Query().Get("cursor"), "library-categories:"+libraryID, user.ID, time.Now().UTC())
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "Library category cursor is invalid or expired.")
			return
		}
		items, hasMore := paginateLibraryCategories(categories, limit, offset)
		nextCursor := ""
		if hasMore {
			nextCursor, err = s.encodeMaterializedPageCursor("library-categories:"+libraryID, user.ID, offset+len(items), time.Now().UTC())
			if err != nil {
				writeError(w, http.StatusInternalServerError, "library_cursor_failed", "Unable to continue library categories.")
				return
			}
		}
		writeJSON(w, http.StatusOK, ListResponse[LibraryCategory]{Items: items, Total: len(categories), Limit: limit, HasMore: hasMore, NextCursor: nextCursor})
		return
	}
	if len(parts) == 2 && (parts[1] == "authors" || parts[1] == "series") && r.Method == http.MethodGet {
		ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
		defer cancel()
		allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusInternalServerError, "library_access_failed", "Unable to inspect library access.")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "forbidden", "This library is not shared with your account.")
			return
		}
		library, err := s.getLibraryContext(ctx, libraryID)
		if err != nil {
			writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
			return
		}
		kind, supported := canonicalLibraryKind(library.Type)
		if !supported || kind != "audiobooks" {
			writeError(w, http.StatusBadRequest, "unsupported_library", "Author and series pivots are available only for audiobook libraries.")
			return
		}
		entityKind := "author"
		if parts[1] == "series" {
			entityKind = "audiobook-series"
		}
		limit := clampInt(queryInt(r, "limit", 50), 1, 100)
		scope := "library-" + parts[1] + ":" + libraryID
		var after virtualAudiobookFacetCursor
		if cursor := strings.TrimSpace(r.URL.Query().Get("cursor")); cursor != "" {
			if err := s.decodeContractCursor(cursor, scope, viewerProfileID(user), &after, time.Now().UTC()); err != nil {
				writeError(w, http.StatusBadRequest, "invalid_cursor", "Audiobook facet cursor is invalid or expired.")
				return
			}
		}
		items, total, hasMore, err := s.audiobookFacetPageContext(ctx, viewerProfileID(user), libraryID, entityKind, after, limit)
		if err != nil {
			writeDatabaseAccessError(w, err, http.StatusServiceUnavailable, "library_facets_failed", "Unable to load audiobook facets.")
			return
		}
		nextCursor := ""
		if hasMore && len(items) > 0 {
			last := items[len(items)-1]
			nextCursor, err = s.encodeContractCursor(scope, viewerProfileID(user), virtualAudiobookFacetCursor{Name: normalizeAudiobookFacetName(last.Name), ID: last.ID}, time.Now().UTC())
			if err != nil {
				writeError(w, http.StatusInternalServerError, "library_cursor_failed", "Unable to continue audiobook facets.")
				return
			}
		}
		writeJSON(w, http.StatusOK, ListResponse[LibraryFacetValue]{Items: items, Total: total, Limit: limit, HasMore: hasMore, NextCursor: nextCursor})
		return
	}
	if len(parts) == 2 && parts[1] == "scan" && r.Method == http.MethodPost {
		if !canInteractivelyManageServer(user) {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to scan libraries.")
			return
		}
		library, err := s.getLibraryContext(r.Context(), libraryID)
		if err != nil {
			writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
			return
		}
		var req LibraryScanRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		rawMode := strings.ToLower(strings.TrimSpace(req.Mode))
		mode := normalizeScanMode(rawMode)
		if rawMode == "" || mode != rawMode {
			writeError(w, http.StatusBadRequest, "invalid_scan_mode", "Scan mode must be targeted, quick, reconcile, force_full, or remove_missing.")
			return
		}
		if mode == "remove_missing" {
			if err := s.validateRemoveMissingConfirmation(r.Context(), library.ID, req.ConfirmedRunID); err != nil {
				writeError(w, http.StatusConflict, "remove_missing_confirmation_required", err.Error())
				return
			}
		}
		job, err := s.queueLibraryScan(library, mode, "api", fmt.Sprintf("Scan queued for %s.", library.Name))
		if err != nil {
			writeError(w, http.StatusInternalServerError, "job_failed", "Unable to queue scan.")
			return
		}
		s.recordAudit(r, user, "library.scan_queued", "library", library.ID, map[bool]string{true: "warn", false: "info"}[mode == "remove_missing"], map[string]string{"job": job.ID, "mode": mode})
		writeJSON(w, http.StatusCreated, job)
		return
	}
	if len(parts) == 2 && parts[1] == "lyrics" && r.Method == http.MethodPost {
		if !canInteractivelyManageServer(user) && !hasPermission(user, "editMetadata") {
			writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to fetch library lyrics.")
			return
		}
		library, err := s.getLibraryContext(r.Context(), libraryID)
		if err != nil {
			writeError(w, http.StatusNotFound, "library_not_found", "Library was not found.")
			return
		}
		if library.Type != "music" {
			writeError(w, http.StatusBadRequest, "unsupported_library", "Missing lyric fetching is only available for music libraries.")
			return
		}
		job, err := s.createJobFor("lyrics_fetch_missing", fmt.Sprintf("Missing lyric fetch queued for %s.", library.Name), "library", library.ID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "job_failed", "Unable to queue lyric fetch.")
			return
		}
		writeJSON(w, http.StatusCreated, job)
		return
	}

	writeError(w, http.StatusNotFound, "not_found", "Library route was not found.")
}

func (s *Server) handleHome(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
	defer cancel()
	response, err := s.homeManifest(ctx, user)
	if err != nil {
		writeDatabaseAccessError(w, err, http.StatusInternalServerError, "home_failed", "Unable to load home.")
		return
	}
	w.Header().Set("Cache-Control", "private, max-age=15, stale-while-revalidate=45")
	writeJSON(w, http.StatusOK, response)
}

type homeRowTask struct {
	Index int
	RowID string
}

type homeRowResult struct {
	Index int
	Row   HomeRow
}

func (s *Server) loadHomeRowsConcurrently(ctx context.Context, user User, tasks []homeRowTask) []HomeRow {
	if len(tasks) == 0 {
		return nil
	}
	results := make(chan homeRowResult, len(tasks))
	// Home composition may grow as server-defined rows are added. Keep SQLite
	// fan-out bounded even when a client asks for every row at once.
	workers := 3
	if len(tasks) < workers {
		workers = len(tasks)
	}
	workSlots := make(chan struct{}, workers)
	var wg sync.WaitGroup
	wg.Add(len(tasks))
	for _, task := range tasks {
		task := task
		go func() {
			defer wg.Done()
			select {
			case workSlots <- struct{}{}:
				defer func() { <-workSlots }()
			case <-ctx.Done():
				return
			}
			rowCtx, cancel := context.WithTimeout(ctx, homeRowRequestTimeout)
			defer cancel()
			row, err, ok := s.homeRowPageContext(rowCtx, user, task.RowID, homeRowItemLimit, 0)
			if !ok || err != nil || len(row.Items) == 0 {
				return
			}
			results <- homeRowResult{Index: task.Index, Row: row}
		}()
	}
	go func() {
		wg.Wait()
		close(results)
	}()
	collected := make([]homeRowResult, 0, len(tasks))
	for {
		select {
		case result, ok := <-results:
			if !ok {
				sort.SliceStable(collected, func(i, j int) bool {
					return collected[i].Index < collected[j].Index
				})
				rows := make([]HomeRow, 0, len(collected))
				for _, result := range collected {
					rows = append(rows, result.Row)
				}
				return rows
			}
			collected = append(collected, result)
		case <-ctx.Done():
			sort.SliceStable(collected, func(i, j int) bool {
				return collected[i].Index < collected[j].Index
			})
			rows := make([]HomeRow, 0, len(collected))
			for _, result := range collected {
				rows = append(rows, result.Row)
			}
			return rows
		}
	}
}

func homeInitialRowOrder(rowID string) int {
	switch rowID {
	case "continue":
		return 0
	case "continue_listening":
		return 1
	case "tmdb_trending":
		return 2
	case "server_watching_week":
		return 3
	case "recommended_for_you":
		return 4
	case "ondeck":
		return 5
	case "watchlist":
		return 6
	case "favorites":
		return 7
	default:
		if strings.HasPrefix(rowID, "recent_") {
			return 8
		}
		return 9
	}
}

func (s *Server) handleHomeRowRoute(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	rowID := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/home/rows/"), "/")
	if rowID == "" {
		writeError(w, http.StatusNotFound, "home_row_not_found", "Home row was not found.")
		return
	}
	limit := clampInt(queryInt(r, "limit", homeRowDefaultPageLimit), 1, 50)
	profileID := viewerProfileID(user)
	offset, err := s.decodeMaterializedPageCursor(r.URL.Query().Get("cursor"), "home:"+rowID, profileID, time.Now().UTC())
	if err != nil {
		if errors.Is(err, errCursorExpired) {
			writeError(w, http.StatusBadRequest, "cursor_expired", "The Home row cursor expired. Restart from the first page.")
		} else {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "The Home row cursor is invalid for this profile and row.")
		}
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
	defer cancel()
	row, err, ok := s.homeRowPageContext(ctx, user, rowID, limit, offset)
	if !ok {
		writeError(w, http.StatusNotFound, "home_row_not_found", "Home row was not found.")
		return
	}
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, "home_row_timeout", "Home row exceeded the foreground request budget. Try again shortly.")
			return
		}
		writeError(w, http.StatusInternalServerError, "home_row_failed", "Unable to load home row.")
		return
	}
	row.Endpoint = "/api/home/rows/" + row.ID
	row.ArtworkShape = resolvedHomeRowArtworkShape(row)
	row.CursorCapable = true
	row.DefaultVisible = true
	row.Offset = 0
	if row.HasMore {
		cursor, cursorErr := s.encodeMaterializedPageCursor("home:"+rowID, profileID, offset+len(row.Items), time.Now().UTC())
		if cursorErr != nil {
			writeError(w, http.StatusInternalServerError, "home_cursor_failed", "Unable to continue this Home row.")
			return
		}
		row.NextCursor = cursor
	}
	w.Header().Set("Cache-Control", "private, max-age=30, stale-while-revalidate=90")
	writeJSON(w, http.StatusOK, row)
}

func (s *Server) handleWatchlist(w http.ResponseWriter, r *http.Request, user User) {
	s.handleSavedMediaState(w, r, user, "watchlist", "watchlisted")
}

func (s *Server) handleFavorites(w http.ResponseWriter, r *http.Request, user User) {
	s.handleSavedMediaState(w, r, user, "favorites", "favorite")
}

func (s *Server) handleSavedMediaState(w http.ResponseWriter, r *http.Request, user User, resourceName, stateColumn string) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	limit := clampInt(queryInt(r, "limit", homeRowItemLimit), 1, 250)
	filter := strings.TrimSpace(r.URL.Query().Get("filter"))
	sortMode := strings.TrimSpace(r.URL.Query().Get("sort"))
	orderMode := strings.TrimSpace(r.URL.Query().Get("order"))
	scope := collectionCursorScope("saved-media", resourceName, strings.ToLower(filter), strings.ToLower(sortMode), strings.ToLower(orderMode))
	var after savedMediaCursor
	err := s.decodeCollectionCursor(r, scope, user.ID, time.Now().UTC(), &after)
	if err != nil {
		if errors.Is(err, errCursorExpired) {
			writeError(w, http.StatusBadRequest, "cursor_expired", "The "+resourceName+" cursor expired. Restart from the first page.")
		} else {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "The "+resourceName+" cursor is invalid for this account, filter, and sort.")
		}
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
	defer cancel()
	profileID := viewerProfileID(user)
	items, hasMore, resolvedFilter, resolvedSort, err := s.listSavedMediaStateKeysetPageContext(ctx, profileID, stateColumn, filter, sortMode, orderMode, limit, after)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, resourceName+"_timeout", strings.ToUpper(resourceName[:1])+resourceName[1:]+" exceeded the foreground request budget. Try again shortly.")
			return
		}
		writeError(w, http.StatusInternalServerError, resourceName+"_failed", "Unable to load "+resourceName+".")
		return
	}
	var next savedMediaCursor
	if hasMore && len(items) > 0 {
		next, err = s.savedMediaCursorForItem(ctx, profileID, items[len(items)-1].ID, resolvedSort)
		if err != nil {
			writeError(w, http.StatusInternalServerError, resourceName+"_cursor_failed", "Unable to continue "+resourceName+".")
			return
		}
	}
	_ = resolvedFilter
	pageInfo, err := s.collectionPageInfo(scope, user.ID, next, hasMore, nil, time.Now().UTC())
	if err != nil {
		writeError(w, http.StatusInternalServerError, resourceName+"_cursor_failed", "Unable to continue "+resourceName+".")
		return
	}
	writeJSON(w, http.StatusOK, CursorListResponse[MediaItem]{Items: items, PageInfo: pageInfo})
}

type savedMediaCursor struct {
	PrimaryText   string `json:"primaryText,omitempty"`
	PrimaryNumber int    `json:"primaryNumber,omitempty"`
	SecondaryText string `json:"secondaryText,omitempty"`
	ID            string `json:"id"`
}

func (s *Server) listSavedMediaStateKeysetPageContext(ctx context.Context, userID, stateColumn, filterMode, sortMode, orderMode string, limit int, after savedMediaCursor) ([]MediaItem, bool, string, string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	limit = clampInt(limit, 1, 250)
	if stateColumn != "watchlisted" && stateColumn != "favorite" {
		return nil, false, "all", "updated", errors.New("unsupported saved media state")
	}
	where := "WHERE ums." + stateColumn + " = 1"
	args := []any{}
	filterMode = strings.TrimSpace(filterMode)
	switch filterMode {
	case "", "all":
		filterMode = "all"
	case "unwatched":
		where += " AND COALESCE(ums.watched, 0) = 0"
	case "inProgress":
		where += " AND COALESCE(ums.progress_seconds, 0) > 0 AND COALESCE(ums.watched, 0) = 0"
	default:
		filterMode = "all"
	}
	sortMode = strings.TrimSpace(sortMode)
	direction := sortDirection(orderMode, "desc")
	primaryOperator := "<"
	if direction == "ASC" {
		primaryOperator = ">"
	}
	order := "ums.updated_at " + direction + ", m.id ASC"
	if after.ID != "" {
		where += " AND (ums.updated_at " + primaryOperator + " ? OR (ums.updated_at = ? AND m.id > ?))"
		args = append(args, after.PrimaryText, after.PrimaryText, after.ID)
	}
	switch sortMode {
	case "title":
		direction = sortDirection(orderMode, "asc")
		primaryOperator = "<"
		if direction == "ASC" {
			primaryOperator = ">"
		}
		order = "m.sort_title " + direction + ", m.id ASC"
		if after.ID != "" {
			where = strings.Split(where, " AND (ums.updated_at ")[0]
			args = args[:0]
			where += " AND (m.sort_title " + primaryOperator + " ? OR (m.sort_title = ? AND m.id > ?))"
			args = append(args, after.PrimaryText, after.PrimaryText, after.ID)
		}
	case "year", "duration", "progress":
		expr := "m.year"
		if sortMode == "duration" {
			expr = "m.duration_seconds"
		} else if sortMode == "progress" {
			expr = "COALESCE(ums.progress_seconds, 0)"
		}
		order = expr + " " + direction + ", m.sort_title ASC, m.id ASC"
		if after.ID != "" {
			where = strings.Split(where, " AND (ums.updated_at ")[0]
			args = args[:0]
			where += " AND (" + expr + " " + primaryOperator + " ? OR (" + expr + " = ? AND (m.sort_title > ? OR (m.sort_title = ? AND m.id > ?))))"
			args = append(args, after.PrimaryNumber, after.PrimaryNumber, after.SecondaryText, after.SecondaryText, after.ID)
		}
	case "", "updated":
		sortMode = "updated"
	default:
		sortMode = "updated"
	}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	args = append(args, limit+1)
	items, err := s.queryMediaListItemsContext(ctx, userID, where+" ORDER BY "+order+" LIMIT ?", args)
	if err != nil {
		return nil, false, filterMode, sortMode, err
	}
	hasMore := len(items) > limit
	if hasMore {
		items = items[:limit]
	}
	return items, hasMore, filterMode, sortMode, nil
}

func (s *Server) savedMediaCursorForItem(ctx context.Context, userID, mediaID, sortMode string) (savedMediaCursor, error) {
	var cursor savedMediaCursor
	var updatedAt, sortTitle string
	var year, duration, progress int
	err := s.queryUserRow(ctx, `
		SELECT COALESCE(ums.updated_at, ''), m.sort_title, m.year, m.duration_seconds, COALESCE(ums.progress_seconds, 0)
		FROM media_items m
		LEFT JOIN user_media_state ums ON ums.media_id = m.id AND ums.profile_id = ?
		WHERE m.id = ?`, userID, mediaID).Scan(&updatedAt, &sortTitle, &year, &duration, &progress)
	if err != nil {
		return savedMediaCursor{}, err
	}
	cursor.ID = mediaID
	switch sortMode {
	case "title":
		cursor.PrimaryText = sortTitle
	case "year":
		cursor.PrimaryNumber, cursor.SecondaryText = year, sortTitle
	case "duration":
		cursor.PrimaryNumber, cursor.SecondaryText = duration, sortTitle
	case "progress":
		cursor.PrimaryNumber, cursor.SecondaryText = progress, sortTitle
	default:
		cursor.PrimaryText = updatedAt
	}
	return cursor, nil
}

func (s *Server) listWatchlistContext(ctx context.Context, userID string, limit, offset int) ([]MediaItem, bool, error) {
	items, hasMore, _, _, err := s.listWatchlistPageContext(ctx, userID, "all", "updated", "desc", limit, offset)
	return items, hasMore, err
}

func (s *Server) listWatchlistPageContext(ctx context.Context, userID, filterMode, sortMode, orderMode string, limit, offset int) ([]MediaItem, bool, string, string, error) {
	return s.listSavedMediaStatePageContext(ctx, userID, "watchlisted", filterMode, sortMode, orderMode, limit, offset)
}

func (s *Server) listSavedMediaStatePageContext(ctx context.Context, userID, stateColumn, filterMode, sortMode, orderMode string, limit, offset int) ([]MediaItem, bool, string, string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	limit = clampInt(limit, 1, 250)
	offset = max(0, offset)
	if stateColumn != "watchlisted" && stateColumn != "favorite" {
		return nil, false, "all", "updated", errors.New("unsupported saved media state")
	}
	where := "WHERE ums." + stateColumn + " = 1"
	args := []any{}
	filterMode = strings.TrimSpace(filterMode)
	switch filterMode {
	case "", "all":
		filterMode = "all"
	case "unwatched":
		where += " AND COALESCE(ums.watched, 0) = 0"
	case "inProgress":
		where += " AND COALESCE(ums.progress_seconds, 0) > 0 AND COALESCE(ums.watched, 0) = 0"
	default:
		filterMode = "all"
	}
	sortMode = strings.TrimSpace(sortMode)
	direction := sortDirection(orderMode, "desc")
	order := "ums.updated_at " + direction + ", m.id ASC"
	switch sortMode {
	case "title":
		direction = sortDirection(orderMode, "asc")
		order = "m.sort_title " + direction + ", m.id ASC"
	case "year":
		order = "m.year " + direction + ", m.sort_title ASC, m.id ASC"
	case "duration":
		order = "m.duration_seconds " + direction + ", m.sort_title ASC, m.id ASC"
	case "progress":
		order = "COALESCE(ums.progress_seconds, 0) " + direction + ", m.sort_title ASC, m.id ASC"
	case "", "updated":
		sortMode = "updated"
	default:
		sortMode = "updated"
	}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	args = append(args, limit+1, offset)
	items, err := s.queryMediaListItemsContext(ctx, userID, where+" ORDER BY "+order+" LIMIT ? OFFSET ?", args)
	if err != nil {
		return nil, false, filterMode, sortMode, err
	}
	hasMore := len(items) > limit
	if hasMore {
		items = items[:limit]
	}
	return items, hasMore, filterMode, sortMode, nil
}

func (s *Server) homeRowPage(user User, rowID string, limit, offset int) (HomeRow, error, bool) {
	return s.homeRowPageContext(context.Background(), user, rowID, limit, offset)
}

func (s *Server) homeRowPageContext(ctx context.Context, user User, rowID string, limit, offset int) (HomeRow, error, bool) {
	if ctx == nil {
		ctx = context.Background()
	}
	rowID = strings.TrimSpace(rowID)
	title := ""
	rowType := "poster"
	where := ""
	order := ""
	args := []any{}
	resolveContinue := false
	libraryID := ""
	progressPreferences := normalizePlaybackProgressPreferences(user.Preferences.PlaybackProgress)
	continueProgressClause := " AND (m.duration_seconds <= 0 OR ((COALESCE(ums.progress_seconds, 0) * 100.0 / m.duration_seconds) >= ? AND (COALESCE(ums.progress_seconds, 0) * 100.0 / m.duration_seconds) < ?))"
	switch {
	case rowID == "continue":
		title = "Continue Watching"
		rowType = "continue"
		where = "WHERE ums.progress_seconds > 0 AND ums.watched = 0 AND m.type NOT IN ('track', 'album', 'artist', 'audiobook')" + continueProgressClause
		order = "ORDER BY COALESCE(ums.last_played_at, ums.updated_at) DESC"
		args = append(args, progressPreferences.StartedThresholdPercent, progressPreferences.PlayedThresholdPercent)
		resolveContinue = true
	case rowID == "continue_listening":
		title = "Continue Listening"
		rowType = "continue"
		where = "WHERE ums.watched = 0 AND ((m.type = 'track' AND COALESCE(ums.last_played_at, '') <> '') OR (m.type = 'audiobook' AND ums.progress_seconds > 0" + continueProgressClause + "))"
		order = "ORDER BY COALESCE(ums.last_played_at, ums.updated_at) DESC"
		args = append(args, progressPreferences.StartedThresholdPercent, progressPreferences.PlayedThresholdPercent)
		resolveContinue = true
	case rowID == "ondeck":
		title = "On Deck"
		rowType = "landscape"
		items, err := s.onDeckHomeItemsContext(ctx, viewerProfileID(user), limit, offset)
		if err != nil {
			return HomeRow{}, err, true
		}
		hasMore := len(items) > limit
		if hasMore {
			items = items[:limit]
		}
		items = s.filterItemsByLibraryVisibility(items, "home")
		return HomeRow{ID: rowID, Title: title, Type: rowType, Items: items, Total: offset + len(items) + boolInt(hasMore), Limit: limit, Offset: offset, HasMore: hasMore}, nil, true
	case rowID == "watchlist":
		title = "Watchlist"
		where = "WHERE ums.watchlisted = 1"
		order = "ORDER BY ums.updated_at DESC"
	case rowID == "favorites":
		title = "Favorites"
		where = "WHERE ums.favorite = 1"
		order = "ORDER BY ums.updated_at DESC, m.sort_title ASC"
	case rowID == "tmdb_trending":
		return paginateMaterializedHomeRow(s.trendingRowContext(ctx, user), limit, offset), nil, true
	case rowID == "server_watching_week":
		if !s.communityHomeRowEnabled(ctx) {
			return HomeRow{}, nil, false
		}
		row := s.serverWatchingRowContext(ctx, user)
		row.Kind = "people-on-this-server-are-watching"
		row.Explanation = "Titles watched by at least two activity-sharing members during the last seven days."
		row.PrivacySensitivity = "aggregated-activity"
		row.PolicyState = "enabled"
		return paginateMaterializedHomeRow(row, limit, offset), nil, true
	case rowID == "recommended_for_you":
		rows := s.recommendationRowsContext(ctx, user)
		if len(rows) == 0 {
			return HomeRow{ID: rowID, Kind: "personalized", Title: "Recommended For You", Type: "poster", Items: []MediaItem{}}, nil, true
		}
		rows[0].Kind = "personalized"
		rows[0].Explanation = "Suggestions based on your own library activity and saved media."
		return paginateMaterializedHomeRow(rows[0], limit, offset), nil, true
	case strings.HasPrefix(rowID, "recent_"):
		libraryID = strings.TrimPrefix(rowID, "recent_")
		if !s.canAccessLibrary(user, libraryID) {
			return HomeRow{}, nil, false
		}
		library, err := s.getLibrary(libraryID)
		if err != nil || libraryHiddenFrom(library, "home") {
			return HomeRow{}, err, false
		}
		title = "Recently Added in " + library.Name
		rowType = "poster"
		where = "WHERE m.library_id = ? AND m.parent_id IS NULL"
		order = "ORDER BY m.added_at DESC"
		args = append(args, library.ID)
	default:
		return HomeRow{}, nil, false
	}
	where, args = s.applyMediaVisibilityRestrictionSQL(viewerProfileID(user), where, args)
	pagedArgs := append([]any{}, args...)
	pagedArgs = append(pagedArgs, limit+1, offset)
	items, err := s.queryMediaListItemsContext(ctx, viewerProfileID(user), where+" "+order+" LIMIT ? OFFSET ?", pagedArgs)
	if err != nil {
		return HomeRow{}, err, true
	}
	hasMore := len(items) > limit
	if hasMore {
		items = items[:limit]
	}
	if resolveContinue {
		items = s.resolveContinueWatchingItems(viewerProfileID(user), items)
		items = s.filterItemsByLibraryVisibility(items, "continue")
	} else {
		items = s.filterItemsByLibraryVisibility(items, "home")
	}
	return HomeRow{ID: rowID, Title: title, Type: rowType, LibraryID: libraryID, Items: items, Total: offset + len(items) + boolInt(hasMore), Limit: limit, Offset: offset, HasMore: hasMore}, nil, true
}

func (s *Server) onDeckHomeItems(userID string, limit, offset int) ([]MediaItem, error) {
	return s.onDeckHomeItemsContext(context.Background(), userID, limit, offset)
}

func (s *Server) onDeckHomeItemsContext(ctx context.Context, userID string, limit, offset int) ([]MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	overfetch := max(limit+1, homeRowItemLimit)
	if offset > 0 {
		where := "WHERE m.type = 'episode'"
		args := []any{}
		where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
		args = append(args, limit+1, offset)
		items, err := s.queryMediaListItemsContext(ctx, userID, `
			`+where+`
			ORDER BY m.added_at DESC
			LIMIT ? OFFSET ?`, args)
		if err != nil {
			return nil, err
		}
		return items, nil
	}
	inProgressWhere := `
		WHERE m.type = 'episode'
			AND ums.progress_seconds > 0
			AND ums.watched = 0`
	inProgressArgs := []any{}
	inProgressWhere, inProgressArgs = s.applyMediaVisibilityRestrictionSQL(userID, inProgressWhere, inProgressArgs)
	inProgressArgs = append(inProgressArgs, overfetch)
	inProgress, err := s.queryMediaListItemsContext(ctx, userID, `
		`+inProgressWhere+`
		ORDER BY COALESCE(ums.last_played_at, ums.updated_at) DESC
		LIMIT ?`, inProgressArgs)
	if err != nil {
		return nil, err
	}
	newestWhere := "WHERE m.type = 'episode'"
	newestArgs := []any{}
	newestWhere, newestArgs = s.applyMediaVisibilityRestrictionSQL(userID, newestWhere, newestArgs)
	newestArgs = append(newestArgs, overfetch)
	newest, err := s.queryMediaListItemsContext(ctx, userID, `
		`+newestWhere+`
		ORDER BY m.added_at DESC
		LIMIT ?`, newestArgs)
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	merged := make([]MediaItem, 0, limit+1)
	for _, item := range append(inProgress, newest...) {
		if seen[item.ID] {
			continue
		}
		seen[item.ID] = true
		merged = append(merged, item)
		if len(merged) >= limit+1 {
			break
		}
	}
	return merged, nil
}

func removeListeningMediaFromMixedHomeRows(rows []HomeRow) []HomeRow {
	filtered := make([]HomeRow, 0, len(rows))
	for _, row := range rows {
		if row.ID != "continue_listening" {
			items := row.Items[:0]
			for _, item := range row.Items {
				if !homeListeningMedia(item) {
					items = append(items, item)
				}
			}
			row.Items = items
		}
		if len(row.Items) > 0 {
			filtered = append(filtered, row)
		}
	}
	return filtered
}

func homeListeningMedia(item MediaItem) bool {
	return item.Type == "track" || item.Type == "album" || item.Type == "artist" || item.Type == "audiobook"
}

func (s *Server) resolveContinueWatchingItems(userID string, items []MediaItem) []MediaItem {
	resolved := make([]MediaItem, 0, len(items))
	seen := map[string]bool{}
	groupIndex := map[string]int{}
	groupFromContainer := map[string]bool{}
	for _, item := range items {
		candidate := item
		directPlayable := continueWatchingPlayable(candidate)
		fromContainer := false
		if !directPlayable {
			if candidate.State.ProgressSeconds <= 0 {
				continue
			}
			next, ok := s.continueWatchingPlayableForContainer(userID, candidate)
			if !ok {
				continue
			}
			candidate = next
			fromContainer = true
		}
		if !continueWatchingPlayable(candidate) || !continueRowItemStarted(candidate, fromContainer) || seen[candidate.ID] {
			continue
		}
		if key := s.continueWatchingGroupKey(candidate); key != "" {
			if index, ok := groupIndex[key]; ok {
				if groupFromContainer[key] && directPlayable {
					resolved[index] = candidate
					groupFromContainer[key] = false
					seen[candidate.ID] = true
				}
				continue
			}
			groupIndex[key] = len(resolved)
			groupFromContainer[key] = !directPlayable
			seen[key] = true
		}
		seen[candidate.ID] = true
		resolved = append(resolved, candidate)
	}
	return resolved
}

func continueRowItemStarted(item MediaItem, fromContainer bool) bool {
	if fromContainer {
		return true
	}
	if item.Type == "track" {
		return strings.TrimSpace(item.State.LastPlayedAt) != ""
	}
	return item.State.ProgressSeconds > 0
}

func (s *Server) continueWatchingGroupKey(item MediaItem) string {
	if item.Type == "episode" {
		if item.GrandparentID != "" {
			return "show:" + item.GrandparentID
		}
		if title := strings.ToLower(strings.TrimSpace(item.GrandparentTitle)); title != "" {
			return "show-title:" + title
		}
	}
	if item.Type == "track" {
		albumTitle := strings.ToLower(strings.TrimSpace(firstNonEmpty(item.TypedMetadata["albumTitle"], item.ParentTitle)))
		artist := strings.ToLower(strings.TrimSpace(firstNonEmpty(item.TypedMetadata["albumArtist"], item.TypedMetadata["artist"], item.GrandparentTitle, item.Studio)))
		if item.ParentID != "" && (albumTitle == "" || artist == "") {
			var parentTitle, grandparentTitle, studio string
			_ = s.queryUserRow(context.Background(), `
				SELECT album.title, COALESCE(artist.title, ''), COALESCE(album.studio, '')
				FROM media_items album
				LEFT JOIN media_items artist ON artist.id = album.parent_id
				WHERE album.id = ?`, item.ParentID).Scan(&parentTitle, &grandparentTitle, &studio)
			albumTitle = strings.ToLower(strings.TrimSpace(firstNonEmpty(albumTitle, parentTitle)))
			artist = strings.ToLower(strings.TrimSpace(firstNonEmpty(artist, grandparentTitle, studio)))
		}
		if albumTitle == "" {
			var raw string
			if err := s.queryUserRow(context.Background(), `SELECT COALESCE(typed_metadata_json, '{}') FROM media_items WHERE id = ?`, item.ID).Scan(&raw); err == nil {
				var metadata map[string]string
				if json.Unmarshal([]byte(raw), &metadata) == nil {
					albumTitle = strings.ToLower(strings.TrimSpace(metadata["albumTitle"]))
					if artist == "" {
						artist = strings.ToLower(strings.TrimSpace(firstNonEmpty(metadata["albumArtist"], metadata["artist"])))
					}
				}
			}
		}
		if albumTitle != "" {
			return "album-title:" + albumTitle
		}
		if item.ParentID != "" {
			return "album:" + item.ParentID
		}
	}
	return ""
}

func (s *Server) continueWatchingPlayableForContainer(userID string, item MediaItem) (MediaItem, bool) {
	children, err := s.childrenFor(userID, item)
	if err != nil {
		return MediaItem{}, false
	}
	item.Children = children
	playable := flattenPlayableDescendants(item)
	for _, child := range playable {
		if child.State.ProgressSeconds > 0 && !child.State.Watched && !child.Missing {
			return child, true
		}
	}
	for _, child := range playable {
		if !child.State.Watched && !child.Missing {
			return child, true
		}
	}
	return MediaItem{}, false
}

func continueWatchingPlayable(item MediaItem) bool {
	return !item.Missing && (item.Type == "movie" || item.Type == "episode" || item.Type == "track" || item.Type == "audiobook" || item.Type == "extra")
}

func (s *Server) cachedHomeResponse(key, targetProfile string) (HomeResponse, bool) {
	if key == "" {
		return HomeResponse{}, false
	}
	now := time.Now()
	s.homeCacheMu.Lock()
	defer s.homeCacheMu.Unlock()
	if s.homeCache == nil {
		s.homeCache = map[string]homeCacheEntry{}
		return HomeResponse{}, false
	}
	entry, ok := s.homeCache[key]
	if !ok {
		return HomeResponse{}, false
	}
	if now.After(entry.expiresAt) {
		delete(s.homeCache, key)
		return HomeResponse{}, false
	}
	response, err := s.rebindHomeResponseCursors(entry.response, entry.sourceProfile, targetProfile, now)
	return response, err == nil
}

func (s *Server) storeHomeResponse(key, sourceProfile string, response HomeResponse) {
	if key == "" {
		return
	}
	s.homeCacheMu.Lock()
	defer s.homeCacheMu.Unlock()
	if s.homeCache == nil {
		s.homeCache = map[string]homeCacheEntry{}
	}
	pruneHomeCacheLocked(s.homeCache, time.Now(), 512)
	ttl := homeCacheTTL
	if strings.HasPrefix(key, "empty-state\x00") {
		ttl = 60 * time.Second
	}
	s.homeCache[key] = homeCacheEntry{response: response, sourceProfile: sourceProfile, expiresAt: time.Now().Add(ttl)}
}

func pruneHomeCacheLocked(cache map[string]homeCacheEntry, now time.Time, maximum int) {
	for key, entry := range cache {
		if !now.Before(entry.expiresAt) {
			delete(cache, key)
		}
	}
	for len(cache) >= maximum && len(cache) > 0 {
		oldestKey := ""
		var oldest time.Time
		for key, entry := range cache {
			if oldestKey == "" || entry.expiresAt.Before(oldest) {
				oldestKey, oldest = key, entry.expiresAt
			}
		}
		delete(cache, oldestKey)
	}
}

func (s *Server) beginHomeResponseBuild(key string) (chan struct{}, bool) {
	if key == "" {
		return nil, true
	}
	s.homeCacheMu.Lock()
	defer s.homeCacheMu.Unlock()
	if s.homeInFlight == nil {
		s.homeInFlight = map[string]chan struct{}{}
	}
	if wait, ok := s.homeInFlight[key]; ok {
		return wait, false
	}
	wait := make(chan struct{})
	s.homeInFlight[key] = wait
	return wait, true
}

func (s *Server) finishHomeResponseBuild(key string) {
	if key == "" {
		return
	}
	s.homeCacheMu.Lock()
	defer s.homeCacheMu.Unlock()
	wait, ok := s.homeInFlight[key]
	if !ok {
		return
	}
	delete(s.homeInFlight, key)
	close(wait)
}

func (s *Server) rebindHomeResponseCursors(response HomeResponse, sourceProfile, targetProfile string, now time.Time) (HomeResponse, error) {
	if sourceProfile == targetProfile {
		return response, nil
	}
	rows := append([]HomeRow(nil), response.Rows...)
	for index := range rows {
		if strings.TrimSpace(rows[index].NextCursor) == "" {
			continue
		}
		var cursor materializedPageCursor
		scope := "home:" + rows[index].ID
		if err := s.decodeContractCursor(rows[index].NextCursor, scope, sourceProfile, &cursor, now); err != nil {
			return HomeResponse{}, err
		}
		token, err := s.encodeMaterializedPageCursor(scope, targetProfile, cursor.Offset, now)
		if err != nil {
			return HomeResponse{}, err
		}
		rows[index].NextCursor = token
	}
	response.Rows = rows
	return response, nil
}

func (s *Server) invalidateHomeCache() {
	s.homeCacheMu.Lock()
	if len(s.homeCache) > 0 {
		s.homeCache = map[string]homeCacheEntry{}
	}
	s.homeCacheMu.Unlock()
	s.invalidateMediaDetailCache()
	s.invalidateLibraryItemsCache()
	if _, err := s.execUserWriteTagged(context.Background(), []string{}, `DELETE FROM user_recommendation_cache`); err != nil {
		s.log.Warn("clear recommendation cache failed", "error", err)
	}
	s.invalidateDashboardCache()
	s.invalidateCategoryCache()
	s.invalidateSuggestionsCache()
}

func (s *Server) invalidateHomeCacheForProfile(profileID string) {
	profileID = strings.TrimSpace(profileID)
	if profileID == "" {
		s.invalidateHomeCache()
		return
	}
	prefix := profileID + "\x00"
	s.homeCacheMu.Lock()
	for key := range s.homeCache {
		if strings.HasPrefix(key, prefix) {
			delete(s.homeCache, key)
		}
	}
	s.homeCacheMu.Unlock()
	s.invalidateMediaDetailCacheForProfile(profileID)
	if _, err := s.execUserWriteTagged(context.Background(), []string{}, `DELETE FROM user_recommendation_cache WHERE profile_id = ?`, profileID); err != nil {
		s.log.Warn("clear profile recommendation cache failed", "profileId", profileID, "error", err)
	}
	// These caches include viewer state and are cheap to rebuild; the catalog
	// caches intentionally remain intact for an exact profile mutation.
	s.invalidateSuggestionsCache()
}

func homeCacheKey(user User) string {
	profileID := viewerProfileID(user)
	if strings.TrimSpace(profileID) == "" {
		return ""
	}
	return strings.Join([]string{profileID, effectiveAuthorizationCacheFingerprint(user)}, "\x00")
}

func effectiveAuthorizationCacheFingerprint(user User) string {
	material, _ := json.Marshal(struct {
		Role                 string                 `json:"role"`
		Permissions          map[string]bool        `json:"permissions"`
		LibraryIDs           []string               `json:"libraryIds"`
		AccessSchedule       UserAccessSchedule     `json:"accessSchedule"`
		TagPolicy            UserTagPolicy          `json:"tagPolicy"`
		ChannelPolicy        UserChannelPolicy      `json:"channelPolicy"`
		MaxContentRating     string                 `json:"maxContentRating"`
		MaximumAgeRating     *int                   `json:"maximumAgeRating"`
		AllowUnrated         bool                   `json:"allowUnrated"`
		BlockedProfileLabels []string               `json:"blockedProfileLabels"`
		AllowFeedback        bool                   `json:"allowFeedback"`
		Privacy              UserPrivacyPreferences `json:"privacy"`
	}{
		Role: user.Role, Permissions: user.Permissions, LibraryIDs: sortedUniqueStrings(user.LibraryIDs),
		AccessSchedule: user.AccessSchedule, TagPolicy: user.TagPolicy, ChannelPolicy: user.ChannelPolicy,
		MaxContentRating: user.MaxContentRating, MaximumAgeRating: user.MaximumAgeRating, AllowUnrated: user.AllowUnrated,
		BlockedProfileLabels: sortedUniqueStrings(user.BlockedProfileLabels), AllowFeedback: user.AllowFeedback,
		Privacy: user.Preferences.Privacy,
	})
	digest := sha256.Sum256(material)
	return "authz_effective_" + hex.EncodeToString(digest[:16])
}

func sortedUniqueStrings(values []string) []string {
	result := uniqueStrings(append([]string(nil), values...))
	sort.Strings(result)
	return result
}

func (s *Server) handleDashboard(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view the server dashboard.")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
	defer cancel()
	dashboard, err := s.cachedDashboard(ctx, user, dashboardFiltersFromRequest(r))
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, "dashboard_timeout", "Dashboard exceeded the foreground request budget. Try again shortly.")
			return
		}
		writeError(w, http.StatusInternalServerError, "dashboard_failed", "Unable to load dashboard.")
		return
	}
	writeJSON(w, http.StatusOK, dashboard)
}

