func (s *Server) handleMediaLyricsApply(w http.ResponseWriter, r *http.Request, user User, mediaID string) {
	if !canManageLyrics(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage lyrics.")
		return
	}
	var req struct {
		Provider   string `json:"provider"`
		ExternalID string `json:"externalId"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Provider) != "" && strings.TrimSpace(req.Provider) != "lrclib" {
		writeError(w, http.StatusBadRequest, "lyrics_apply_failed", "Only LRCLIB lyric candidates can be applied.")
		return
	}
	item, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID)
	if err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	if item.Type != "track" {
		writeError(w, http.StatusBadRequest, "lyrics_apply_failed", "Remote lyrics can only be applied to music tracks.")
		return
	}
	lyric, err := s.fetchLRCLibLyricsByID(r.Context(), strings.TrimSpace(req.ExternalID))
	if err != nil {
		writeError(w, http.StatusBadGateway, "lyrics_apply_failed", err.Error())
		return
	}
	if err := s.saveLRCLibLyrics(mediaID, lyric); err != nil {
		writeError(w, http.StatusInternalServerError, "lyrics_apply_failed", "Unable to save provider lyrics.")
		return
	}
	s.recordAudit(r, user, "media.lyrics_applied", "media", mediaID, "info", map[string]string{"title": item.Title, "provider": "lrclib", "externalId": strings.TrimSpace(req.ExternalID), "format": lyric.Format})
	s.invalidateMediaDetailCache()
	writeJSON(w, http.StatusCreated, s.mediaMutationResponseContext(r.Context(), viewerProfileID(user), mediaID, item))
}

func (s *Server) saveLRCLibLyrics(mediaID string, lyric fetchedLyric) error {
	now := time.Now().UTC().Format(time.RFC3339)
	return s.withUserTxTagged(context.Background(), []string{"media", "metadata", "library-items"}, func(tx *sql.Tx) error {
		if _, err := tx.Exec(`DELETE FROM media_lyrics WHERE media_id = ? AND source = 'provider' AND provider = 'lrclib'`, mediaID); err != nil {
			return err
		}
		_, err := tx.Exec(`
			INSERT INTO media_lyrics (id, media_id, source, provider, format, language, path, text, synced, created_at)
			VALUES (?, ?, 'provider', 'lrclib', ?, 'und', ?, ?, ?, ?)`,
			randomOpaquePublicID(), mediaID, lyric.Format, lyric.Path, lyric.Text, boolInt(lyric.Synced), now)
		return err
	})
}

type fetchedLyric struct {
	Format string
	Path   string
	Text   string
	Synced bool
}

type lrclibLyricsResponse struct {
	ID           int     `json:"id"`
	TrackName    string  `json:"trackName"`
	ArtistName   string  `json:"artistName"`
	AlbumName    string  `json:"albumName"`
	Duration     float64 `json:"duration"`
	Instrumental bool    `json:"instrumental"`
	PlainLyrics  string  `json:"plainLyrics"`
	SyncedLyrics string  `json:"syncedLyrics"`
}

func (s *Server) fetchLRCLibLyrics(ctx context.Context, item MediaItem) (fetchedLyric, error) {
	baseURL := strings.TrimRight(firstNonEmpty(s.cfg.LRCLibBaseURL, "https://lrclib.net"), "/")
	if baseURL == "" {
		return fetchedLyric{}, errors.New("LRCLIB provider is not configured.")
	}
	artist := firstNonEmpty(item.TypedMetadata["trackArtist"], item.TypedMetadata["albumArtist"], item.GrandparentTitle, item.Studio)
	album := firstNonEmpty(item.TypedMetadata["albumTitle"], item.ParentTitle)
	query := url.Values{}
	query.Set("track_name", item.Title)
	if artist != "" {
		query.Set("artist_name", artist)
	}
	if album != "" {
		query.Set("album_name", album)
	}
	if item.DurationSeconds > 0 {
		query.Set("duration", strconv.Itoa(item.DurationSeconds))
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL+"/api/get?"+query.Encode(), nil)
	if err != nil {
		return fetchedLyric{}, err
	}
	req.Header.Set("User-Agent", "Portico/0.1 (+https://getportico.tv)")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fetchedLyric{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		return fetchedLyric{}, errors.New("No LRCLIB lyrics were found for this track.")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fetchedLyric{}, fmt.Errorf("LRCLIB returned HTTP %d", resp.StatusCode)
	}
	var payload lrclibLyricsResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&payload); err != nil {
		return fetchedLyric{}, errors.New("LRCLIB returned an invalid lyric response.")
	}
	return fetchedLyricFromLRCLib(payload)
}

func (s *Server) searchLRCLibLyrics(ctx context.Context, item MediaItem, queryText string) ([]LyricSearchCandidate, error) {
	baseURL := strings.TrimRight(firstNonEmpty(s.cfg.LRCLibBaseURL, "https://lrclib.net"), "/")
	if baseURL == "" {
		return nil, errors.New("LRCLIB provider is not configured.")
	}
	artist := firstNonEmpty(item.TypedMetadata["trackArtist"], item.TypedMetadata["albumArtist"], item.GrandparentTitle, item.Studio)
	album := firstNonEmpty(item.TypedMetadata["albumTitle"], item.ParentTitle)
	searchText := strings.TrimSpace(queryText)
	if searchText == "" {
		searchText = strings.TrimSpace(strings.Join([]string{artist, item.Title, album}, " "))
	}
	if searchText == "" {
		return nil, errors.New("A lyric search query is required.")
	}
	query := url.Values{}
	query.Set("q", searchText)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL+"/api/search?"+query.Encode(), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "Portico/0.1 (+https://getportico.tv)")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, fmt.Errorf("LRCLIB returned HTTP %d", resp.StatusCode)
	}
	var payload []lrclibLyricsResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&payload); err != nil {
		return nil, errors.New("LRCLIB returned an invalid lyric search response.")
	}
	candidates := make([]LyricSearchCandidate, 0, min(len(payload), 20))
	for _, result := range payload {
		if result.ID == 0 {
			continue
		}
		format := "txt"
		synced := false
		if strings.TrimSpace(result.SyncedLyrics) != "" {
			format = "lrc"
			synced = true
		}
		candidates = append(candidates, LyricSearchCandidate{
			Provider:        "lrclib",
			ExternalID:      strconv.Itoa(result.ID),
			TrackName:       strings.TrimSpace(result.TrackName),
			ArtistName:      strings.TrimSpace(result.ArtistName),
			AlbumName:       strings.TrimSpace(result.AlbumName),
			DurationSeconds: int(math.Round(result.Duration)),
			Format:          format,
			Synced:          synced,
			Instrumental:    result.Instrumental,
		})
		if len(candidates) >= 20 {
			break
		}
	}
	return candidates, nil
}

func (s *Server) fetchLRCLibLyricsByID(ctx context.Context, externalID string) (fetchedLyric, error) {
	externalID = strings.TrimSpace(externalID)
	if externalID == "" {
		return fetchedLyric{}, errors.New("Choose an LRCLIB lyric candidate.")
	}
	baseURL := strings.TrimRight(firstNonEmpty(s.cfg.LRCLibBaseURL, "https://lrclib.net"), "/")
	if baseURL == "" {
		return fetchedLyric{}, errors.New("LRCLIB provider is not configured.")
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL+"/api/get/"+url.PathEscape(externalID), nil)
	if err != nil {
		return fetchedLyric{}, err
	}
	req.Header.Set("User-Agent", "Portico/0.1 (+https://getportico.tv)")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fetchedLyric{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		return fetchedLyric{}, errors.New("No LRCLIB lyrics were found for this candidate.")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fetchedLyric{}, fmt.Errorf("LRCLIB returned HTTP %d", resp.StatusCode)
	}
	var payload lrclibLyricsResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&payload); err != nil {
		return fetchedLyric{}, errors.New("LRCLIB returned an invalid lyric response.")
	}
	if payload.ID == 0 {
		if parsed, err := strconv.Atoi(externalID); err == nil {
			payload.ID = parsed
		}
	}
	return fetchedLyricFromLRCLib(payload)
}

func fetchedLyricFromLRCLib(payload lrclibLyricsResponse) (fetchedLyric, error) {
	if text := strings.TrimSpace(payload.SyncedLyrics); text != "" {
		return fetchedLyric{Format: "lrc", Path: lrclibLyricPath(payload), Text: text, Synced: true}, nil
	}
	if text := strings.TrimSpace(payload.PlainLyrics); text != "" {
		return fetchedLyric{Format: "txt", Path: lrclibLyricPath(payload), Text: text, Synced: false}, nil
	}
	return fetchedLyric{}, errors.New("LRCLIB did not return lyric text for this track.")
}

func lrclibLyricPath(payload lrclibLyricsResponse) string {
	if payload.ID > 0 {
		return "lrclib:" + strconv.Itoa(payload.ID)
	}
	return "lrclib:" + strings.TrimSpace(strings.Join([]string{payload.ArtistName, payload.TrackName}, ":"))
}

func (s *Server) handleMediaImageUpload(w http.ResponseWriter, r *http.Request, user User, mediaID string) {
	if !user.Permissions["editMetadata"] {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage artwork.")
		return
	}
	item, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID)
	if err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	if err := r.ParseMultipartForm(5 << 20); err != nil {
		writeError(w, http.StatusBadRequest, "image_upload_failed", "Artwork upload must be a multipart image file under 5 MB.")
		return
	}
	expectedRevision, ok := parseRequiredMetadataRevision(w, r.FormValue("expectedRevision"))
	if !ok {
		return
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, http.StatusBadRequest, "image_upload_failed", "Artwork file is required.")
		return
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, (5<<20)+1))
	if err != nil {
		writeError(w, http.StatusBadRequest, "image_upload_failed", "Unable to read artwork file.")
		return
	}
	if len(data) == 0 || len(data) > 5<<20 {
		writeError(w, http.StatusBadRequest, "image_upload_failed", "Artwork upload must be under 5 MB.")
		return
	}
	imageType := normalizeMediaImageType(r.FormValue("type"), item.Type)
	if imageType == "" {
		writeError(w, http.StatusBadRequest, "image_upload_failed", "Artwork type is not valid for this media item.")
		return
	}
	extension, width, height, err := validateUploadedArtwork(data, header.Filename)
	if err != nil {
		writeError(w, http.StatusBadRequest, "image_upload_failed", err.Error())
		return
	}
	imageID := randomOpaquePublicID()
	dir := filepath.Join(s.cfg.AppDataDir, "artwork", safePathComponent(mediaID))
	if err := os.MkdirAll(dir, 0o700); err != nil {
		writeError(w, http.StatusInternalServerError, "image_upload_failed", "Unable to store artwork file.")
		return
	}
	path := filepath.Join(dir, safePathComponent(imageID)+"."+extension)
	if err := publishPrivateArtifact(filepath.Join(s.cfg.AppDataDir, "artwork"), path, data); err != nil {
		writeError(w, http.StatusInternalServerError, "image_upload_failed", "Unable to store artwork file.")
		return
	}
	_, err = s.applyMetadata(r.Context(), metadataApplyRequest{
		MediaID: mediaID, ExpectedRevision: expectedRevision, Origin: metadataSourceManual,
		Source: "manual", Provider: "upload", ActorUserID: user.ID,
		OperationID: "manual-artwork-upload-" + imageID,
		ArtworkMutation: func(tx *sql.Tx, revision int, now string) error {
			if _, err := tx.Exec(`UPDATE media_images SET preferred = 0 WHERE media_id = ? AND image_type = ?`, mediaID, imageType); err != nil {
				return err
			}
			_, err := tx.Exec(`
			INSERT INTO media_images (id, media_id, image_type, source, provider, path, remote_url, width, height, language, rating, sort_order, preferred, created_at, metadata_revision)
			VALUES (?, ?, ?, 'manual', 'upload', ?, '', ?, ?, '', 100, 0, 1, ?, ?)`,
				imageID, mediaID, imageType, path, width, height, now, revision)
			return err
		}})
	if err != nil {
		_ = os.Remove(path)
		if errors.Is(err, errMetadataRevisionConflict) {
			writeError(w, http.StatusConflict, "metadata_revision_conflict", "Metadata changed on another client. Reload it before uploading artwork.")
			return
		}
		writeError(w, http.StatusInternalServerError, "image_upload_failed", "Unable to save artwork.")
		return
	}
	s.recordAudit(r, user, "media.image_uploaded", "media", mediaID, "info", map[string]string{"title": item.Title, "type": imageType, "revision": strconv.Itoa(expectedRevision + 1)})
	s.invalidateMediaDetailCache()
	writeJSON(w, http.StatusCreated, s.mediaMutationResponseContext(r.Context(), viewerProfileID(user), mediaID, item))
}

func normalizeMediaImageType(input, mediaType string) string {
	imageType := strings.ToLower(strings.TrimSpace(input))
	if imageType == "" {
		imageType = "poster"
	}
	switch imageType {
	case "cover":
		imageType = "poster"
	case "still":
		imageType = "thumb"
	}
	allowed := map[string]bool{"poster": true, "backdrop": true, "thumb": true, "logo": true, "banner": true, "disc": true, "clearart": true}
	if !allowed[imageType] {
		return ""
	}
	if mediaType == "episode" && imageType == "poster" {
		return "thumb"
	}
	return imageType
}

func validateUploadedArtwork(data []byte, filename string) (string, int, int, error) {
	contentType := http.DetectContentType(data)
	extension := ""
	switch contentType {
	case "image/jpeg":
		extension = "jpg"
	case "image/png":
		extension = "png"
	case "image/gif":
		extension = "gif"
	case "image/webp":
		extension = "webp"
	default:
		return "", 0, 0, errors.New("Only JPEG, PNG, GIF, and WebP artwork files are supported.")
	}
	ext := strings.ToLower(strings.TrimPrefix(filepath.Ext(filename), "."))
	if ext != "" && ext != "jpg" && ext != "jpeg" && ext != "png" && ext != "gif" && ext != "webp" {
		return "", 0, 0, errors.New("Artwork filename must use .jpg, .jpeg, .png, .gif, or .webp.")
	}
	config, _, err := image.DecodeConfig(bytes.NewReader(data))
	if err != nil || config.Width <= 0 || config.Height <= 0 {
		return "", 0, 0, errors.New("Artwork file could not be decoded.")
	}
	if config.Width > 10000 || config.Height > 10000 {
		return "", 0, 0, errors.New("Artwork dimensions are too large.")
	}
	return extension, config.Width, config.Height, nil
}

func (s *Server) handleMediaImageDelete(w http.ResponseWriter, r *http.Request, user User, mediaID string, imageID string) {
	if !user.Permissions["editMetadata"] {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage artwork.")
		return
	}
	if _, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID); err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	expectedRevision, ok := parseRequiredMetadataRevision(w, r.URL.Query().Get("expectedRevision"))
	if !ok {
		return
	}
	var path string
	if err := s.queryUserRow(context.Background(), `SELECT path FROM media_images WHERE id = ? AND media_id = ? AND source = 'manual' AND provider = 'upload'`, imageID, mediaID).Scan(&path); err != nil {
		writeError(w, http.StatusNotFound, "image_not_found", "Uploaded artwork was not found.")
		return
	}
	root := filepath.Join(s.cfg.AppDataDir, "artwork")
	if !pathInsideRoot(path, root) {
		writeError(w, http.StatusBadRequest, "image_delete_failed", "Artwork path is invalid.")
		return
	}
	_, err := s.applyMetadata(r.Context(), metadataApplyRequest{
		MediaID: mediaID, ExpectedRevision: expectedRevision, Origin: metadataSourceManual,
		Source: "manual", Provider: "upload", ActorUserID: user.ID,
		OperationID: "manual-artwork-delete-" + imageID,
		ArtworkMutation: func(tx *sql.Tx, _ int, _ string) error {
			result, err := tx.Exec(`DELETE FROM media_images WHERE id = ? AND media_id = ? AND source = 'manual' AND provider = 'upload'`, imageID, mediaID)
			if err == nil && rowsAffected(result) == 0 {
				return sql.ErrNoRows
			}
			return err
		},
	})
	if errors.Is(err, errMetadataRevisionConflict) {
		writeError(w, http.StatusConflict, "metadata_revision_conflict", "Metadata changed on another client. Reload it before deleting artwork.")
		return
	}
	if errors.Is(err, sql.ErrNoRows) {
		writeError(w, http.StatusNotFound, "image_not_found", "Uploaded artwork was not found.")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "image_delete_failed", "Unable to delete artwork.")
		return
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		s.recordAudit(r, user, "media.image_file_cleanup_failed", "media", mediaID, "warning", map[string]string{"imageId": imageID})
	}
	s.recordAudit(r, user, "media.image_deleted", "media", mediaID, "info", map[string]string{"imageId": imageID, "revision": strconv.Itoa(expectedRevision + 1)})
	s.invalidateMediaDetailCache()
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

func (s *Server) handleMediaImageInfo(w http.ResponseWriter, r *http.Request, user User, mediaID string, imageID string) {
	if _, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID); err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	image, err := s.mediaImageFor(mediaID, imageID)
	if err != nil {
		writeError(w, http.StatusNotFound, "image_not_found", "Artwork was not found.")
		return
	}
	if !canInteractivelyManageServer(user) {
		image.Path = ""
	}
	writeJSON(w, http.StatusOK, image)
}

func (s *Server) handleMediaImageOrder(w http.ResponseWriter, r *http.Request, user User, mediaID string) {
	if !user.Permissions["editMetadata"] {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage artwork.")
		return
	}
	item, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID)
	if err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	var req struct {
		ImageIDs         []string `json:"imageIds"`
		ExpectedRevision *int     `json:"expectedRevision"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	if len(req.ImageIDs) == 0 || len(req.ImageIDs) > 100 {
		writeError(w, http.StatusBadRequest, "image_order_failed", "Artwork order must include 1 to 100 image IDs.")
		return
	}
	if req.ExpectedRevision == nil || *req.ExpectedRevision < 0 {
		writeError(w, http.StatusBadRequest, "metadata_revision_required", "expectedRevision is required and must be zero or greater.")
		return
	}
	seen := map[string]bool{}
	var txStatus int
	var txCode string
	var txMessage string
	_, err = s.applyMetadata(r.Context(), metadataApplyRequest{
		MediaID: mediaID, ExpectedRevision: *req.ExpectedRevision, Origin: metadataSourceManual,
		Source: "manual", Provider: "upload", ActorUserID: user.ID, OperationID: "manual-artwork-order",
		ArtworkMutation: func(tx *sql.Tx, revision int, _ string) error {
			for index, imageID := range req.ImageIDs {
				imageID = strings.TrimSpace(imageID)
				if imageID == "" || seen[imageID] {
					txStatus = http.StatusBadRequest
					txCode = "image_order_failed"
					txMessage = "Artwork order contains duplicate or empty IDs."
					return errors.New(txMessage)
				}
				seen[imageID] = true
				result, err := tx.Exec(`UPDATE media_images SET sort_order = ?, metadata_revision = ? WHERE media_id = ? AND id = ?`, index, revision, mediaID, imageID)
				if err != nil {
					return err
				}
				if rowsAffected(result) == 0 {
					txStatus = http.StatusNotFound
					txCode = "image_not_found"
					txMessage = "Artwork was not found."
					return sql.ErrNoRows
				}
			}
			return nil
		}})
	if err != nil {
		if errors.Is(err, errMetadataRevisionConflict) {
			writeError(w, http.StatusConflict, "metadata_revision_conflict", "Metadata changed on another client. Reload it before reordering artwork.")
			return
		}
		if txStatus != 0 {
			writeError(w, txStatus, txCode, txMessage)
			return
		}
		writeError(w, http.StatusInternalServerError, "image_order_failed", "Unable to update artwork order.")
		return
	}
	s.recordAudit(r, user, "media.images_reordered", "media", mediaID, "info", map[string]string{"revision": strconv.Itoa(*req.ExpectedRevision + 1)})
	s.invalidateMediaDetailCache()
	writeJSON(w, http.StatusOK, s.mediaMutationResponseContext(r.Context(), viewerProfileID(user), mediaID, item))
}

func (s *Server) handleMediaImagePreferred(w http.ResponseWriter, r *http.Request, user User, mediaID string, imageID string) {
	if !user.Permissions["editMetadata"] {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage artwork.")
		return
	}
	item, err := s.getMediaAccessSummaryContext(r.Context(), viewerProfileID(user), mediaID)
	if err != nil {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	var req struct {
		ExpectedRevision *int `json:"expectedRevision"`
	}
	if !decodeJSON(w, r, &req) {
		return
	}
	if req.ExpectedRevision == nil || *req.ExpectedRevision < 0 {
		writeError(w, http.StatusBadRequest, "metadata_revision_required", "expectedRevision is required and must be zero or greater.")
		return
	}
	_, err = s.applyMetadata(r.Context(), metadataApplyRequest{
		MediaID: mediaID, ExpectedRevision: *req.ExpectedRevision, Origin: metadataSourceManual,
		Source: "manual", Provider: "upload", ActorUserID: user.ID,
		OperationID: "manual-artwork-preferred-" + imageID,
		ArtworkMutation: func(tx *sql.Tx, revision int, _ string) error {
			var imageType string
			if err := tx.QueryRow(`SELECT image_type FROM media_images WHERE id = ? AND media_id = ?`, imageID, mediaID).Scan(&imageType); err != nil {
				return err
			}
			if _, err := tx.Exec(`UPDATE media_images SET preferred = 0 WHERE media_id = ? AND image_type = ?`, mediaID, imageType); err != nil {
				return err
			}
			result, err := tx.Exec(`UPDATE media_images SET preferred = 1, metadata_revision = ? WHERE id = ? AND media_id = ?`, revision, imageID, mediaID)
			if err != nil {
				return err
			}
			if rowsAffected(result) == 0 {
				return sql.ErrNoRows
			}
			return nil
		}})
	if errors.Is(err, errMetadataRevisionConflict) {
		writeError(w, http.StatusConflict, "metadata_revision_conflict", "Metadata changed on another client. Reload it before selecting artwork.")
		return
	}
	if errors.Is(err, sql.ErrNoRows) {
		writeError(w, http.StatusNotFound, "image_not_found", "Artwork was not found.")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "image_preference_failed", "Unable to update preferred artwork.")
		return
	}
	s.recordAudit(r, user, "media.image_preferred", "media", mediaID, "info", map[string]string{"imageId": imageID, "revision": strconv.Itoa(*req.ExpectedRevision + 1)})
	s.invalidateMediaDetailCache()
	writeJSON(w, http.StatusOK, s.mediaMutationResponseContext(r.Context(), viewerProfileID(user), mediaID, item))
}

func parseRequiredMetadataRevision(w http.ResponseWriter, raw string) (int, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		writeError(w, http.StatusBadRequest, "metadata_revision_required", "expectedRevision is required and must be zero or greater.")
		return 0, false
	}
	revision, err := strconv.Atoi(raw)
	if err != nil || revision < 0 {
		writeError(w, http.StatusBadRequest, "metadata_revision_required", "expectedRevision is required and must be zero or greater.")
		return 0, false
	}
	return revision, true
}

func (s *Server) subtitleStreamPath(mediaID string, streamID string) (string, error) {
	path, _, err := s.subtitleStreamPathAndOffset(mediaID, streamID)
	return path, err
}

func (s *Server) subtitleStreamPathAndOffset(mediaID string, streamID string) (string, int, error) {
	streamID = s.resolveMediaStreamIDContext(context.Background(), mediaID, streamID)
	var raw, storageKey string
	var offsetMs int
	if err := s.queryUserRow(context.Background(), `SELECT source_url, COALESCE(NULLIF(storage_key, ''), id), COALESCE(subtitle_offset_ms, 0) FROM media_streams WHERE id = ? AND media_id = ? AND kind = 'subtitle' AND source_url <> ''`, streamID, mediaID).Scan(&raw, &storageKey, &offsetMs); err != nil {
		return "", 0, err
	}
	path := filepath.Join(s.cfg.AppDataDir, "subtitles", safePathComponent(mediaID), safePathComponent(storageKey)+".vtt")
	root := filepath.Join(s.cfg.AppDataDir, "subtitles")
	if !pathInsideRoot(path, root) {
		return "", 0, errors.New("subtitle path escaped app data")
	}
	return path, offsetMs, nil
}

func (s *Server) subtitleStreamPathForBurnIn(mediaID string, streamID string) (string, error) {
	path, offsetMs, err := s.subtitleStreamPathAndOffset(mediaID, streamID)
	if err != nil || offsetMs == 0 {
		return path, err
	}
	data, err := s.readPlaybackSubtitleFile(context.Background(), path)
	if err != nil {
		return "", err
	}
	dir := filepath.Dir(path)
	adjustedPath := filepath.Join(dir, safePathComponent(streamID)+"_offset_"+strconv.Itoa(offsetMs)+".vtt")
	root := filepath.Join(s.cfg.AppDataDir, "subtitles")
	if !pathInsideRoot(adjustedPath, root) {
		return "", errors.New("subtitle offset path escaped app data")
	}
	if err := os.WriteFile(adjustedPath, shiftWebVTTCues(data, offsetMs), 0o600); err != nil {
		return "", err
	}
	return adjustedPath, nil
}

var webVTTCueTimingPattern = regexp.MustCompile(`((?:\d{2,}:)?\d{2}:\d{2}\.\d{3})[ \t]+-->[ \t]+((?:\d{2,}:)?\d{2}:\d{2}\.\d{3})([^\r\n]*)`)

func shiftWebVTTCues(data []byte, offsetMs int) []byte {
	if offsetMs == 0 {
		return data
	}
	return webVTTCueTimingPattern.ReplaceAllFunc(data, func(match []byte) []byte {
		parts := webVTTCueTimingPattern.FindSubmatch(match)
		if len(parts) != 4 {
			return match
		}
		startMs, startOK := flexibleTimeMillis(string(parts[1]))
		endMs, endOK := flexibleTimeMillis(string(parts[2]))
		if !startOK || !endOK {
			return match
		}
		startMs = maxInt64(0, startMs+int64(offsetMs))
		endMs = maxInt64(0, endMs+int64(offsetMs))
		if endMs <= startMs {
			endMs = startMs + 1
		}
		return []byte(millisToVTT(startMs) + " --> " + millisToVTT(endMs) + string(parts[3]))
	})
}

func buildHLSWebVTTMediaSegment(data []byte, offsetMs int, segmentStartSeconds int, segmentDurationSeconds int) []byte {
	segmentStartMs := int64(max(0, segmentStartSeconds)) * 1000
	segmentDurationMs := int64(max(1, segmentDurationSeconds)) * 1000
	segmentEndMs := segmentStartMs + segmentDurationMs
	const mpegTSTimestampWrap = int64(1) << 33
	mpegTSTimestamp := (segmentStartMs * 90) % mpegTSTimestampWrap
	var out strings.Builder
	out.WriteString("WEBVTT\n")
	out.WriteString("X-TIMESTAMP-MAP=LOCAL:00:00:00.000,MPEGTS:")
	out.WriteString(strconv.FormatInt(mpegTSTimestamp, 10))
	out.WriteString("\n\n")
	blocks := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n\n")
	for _, block := range blocks {
		block = strings.Trim(block, "\n")
		if block == "" || strings.HasPrefix(block, "WEBVTT") {
			continue
		}
		lines := strings.Split(block, "\n")
		timingLine := -1
		var parts [][]byte
		for index, line := range lines {
			match := webVTTCueTimingPattern.FindSubmatch([]byte(line))
			if len(match) == 4 {
				timingLine = index
				parts = match
				break
			}
		}
		if timingLine < 0 {
			continue
		}
		startMs, startOK := flexibleTimeMillis(string(parts[1]))
		endMs, endOK := flexibleTimeMillis(string(parts[2]))
		if !startOK || !endOK {
			continue
		}
		startMs = maxInt64(0, startMs+int64(offsetMs))
		endMs = maxInt64(0, endMs+int64(offsetMs))
		if endMs <= segmentStartMs || startMs >= segmentEndMs {
			continue
		}
		localStartMs := maxInt64(0, startMs-segmentStartMs)
		localEndMs := minInt64(segmentDurationMs, endMs-segmentStartMs)
		if localEndMs <= localStartMs {
			localEndMs = localStartMs + 1
		}
		for index := 0; index < timingLine; index++ {
			if strings.TrimSpace(lines[index]) != "" {
				out.WriteString(strings.TrimRight(lines[index], " \t"))
				out.WriteByte('\n')
			}
		}
		out.WriteString(millisToVTT(localStartMs))
		out.WriteString(" --> ")
		out.WriteString(millisToVTT(localEndMs))
		out.WriteString(string(parts[3]))
		out.WriteByte('\n')
		for _, line := range lines[timingLine+1:] {
			out.WriteString(strings.TrimRight(line, " \t"))
			out.WriteByte('\n')
		}
		out.WriteByte('\n')
	}
	return []byte(out.String())
}

func removeSubtitleOffsetCopies(appDataDir, mediaID, streamID string) {
	pattern := filepath.Join(appDataDir, "subtitles", safePathComponent(mediaID), safePathComponent(streamID)+"_offset_*.vtt")
	for _, path := range globQuiet(pattern) {
		_ = os.Remove(path)
	}
}

func maxInt64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func minInt64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func globQuiet(pattern string) []string {
	matches, err := filepath.Glob(pattern)
	if err != nil {
		return nil
	}
	return matches
}

func (s *Server) searchMedia(userID string, q string, limit int) ([]MediaItem, error) {
	return s.searchMediaContext(context.Background(), userID, q, limit)
}

// Foreground budgets are intentionally bounded, but must leave enough room for
// a cold SQLite page cache and a normal multi-user burst. The previous 250 ms
// ceiling routinely canceled healthy indexed reads before workload admission
// or SQLite's busy handling could do their jobs, turning harmless bursts into
// intermittent 503/504 responses. These remain well below the lane-level
// request budgets and the UI's two-second navigation latency guardrail.
const searchRequestTimeout = 1500 * time.Millisecond
const mediaSearchBranchTimeout = 1 * time.Second
const liveTVSearchBranchTimeout = 300 * time.Millisecond
const navigationRequestTimeout = 1500 * time.Millisecond
const browseRequestTimeout = 2 * time.Second
const maxPlaybackHistoryOffset = 20000
const maxPlaybackHistoryExportRows = 5000
const maxHomeRowOffset = 5000
const maxDVROffset = 10000
const maxSearchTerms = 6
const maxSearchQueryRunes = 120

func (s *Server) searchMediaContext(ctx context.Context, userID string, q string, limit int) ([]MediaItem, error) {
	q = strings.TrimSpace(q)
	if q == "" {
		return []MediaItem{}, nil
	}
	if limit <= 0 || limit > 100 {
		limit = 50
	}
	match := mediaSearchQuery(q)
	if match == "" {
		return []MediaItem{}, nil
	}
	key := searchInFlightKey(userID, match, limit)
	call, owner := s.beginSearchInFlight(key)
	if !owner {
		select {
		case <-call.done:
			return append([]MediaItem(nil), call.items...), call.err
		case <-ctx.Done():
			return nil, ctx.Err()
		}
	}
	queryArgs := []any{match, limit}
	items, err := s.queryMediaListItemsContext(ctx, userID, `
		JOIN media_search ON media_search.media_id = m.id
		WHERE media_search MATCH ?
		ORDER BY bm25(media_search), m.sort_title ASC
		LIMIT ?`, queryArgs)
	if err != nil {
		s.finishSearchInFlight(key, call, nil, err)
		return nil, err
	}
	items = s.filterItemsByLibraryVisibility(items, "search")
	s.finishSearchInFlight(key, call, items, nil)
	return items, nil
}

func searchInFlightKey(userID, match string, limit int) string {
	return strings.TrimSpace(userID) + "\x00" + match + "\x00" + strconv.Itoa(limit)
}

func (s *Server) beginSearchInFlight(key string) (*searchInFlightCall, bool) {
	s.searchInFlightMu.Lock()
	defer s.searchInFlightMu.Unlock()
	if s.searchInFlight == nil {
		s.searchInFlight = map[string]*searchInFlightCall{}
	}
	if call, ok := s.searchInFlight[key]; ok {
		return call, false
	}
	call := &searchInFlightCall{done: make(chan struct{})}
	s.searchInFlight[key] = call
	return call, true
}

func (s *Server) finishSearchInFlight(key string, call *searchInFlightCall, items []MediaItem, err error) {
	s.searchInFlightMu.Lock()
	if current := s.searchInFlight[key]; current == call {
		delete(s.searchInFlight, key)
	}
	call.items = append([]MediaItem(nil), items...)
	call.err = err
	close(call.done)
	s.searchInFlightMu.Unlock()
}

func (s *Server) personMedia(userID string, name string, limit int) ([]MediaItem, error) {
	return s.personMediaContext(context.Background(), userID, name, limit)
}

func (s *Server) personMediaContext(ctx context.Context, userID string, name string, limit int) ([]MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	name = strings.TrimSpace(name)
	if name == "" {
		return []MediaItem{}, nil
	}
	return s.personMediaForIdentityContext(ctx, userID, personIdentitySelector{Kind: "name", Name: name}, limit)
}

func (s *Server) personMediaIdentityContext(ctx context.Context, userID, personID string, limit int) ([]MediaItem, error) {
	identity, _, ok := s.personIdentityForPublicID(ctx, personID)
	if !ok {
		return []MediaItem{}, nil
	}
	resolved, _, _, _, found, err := s.personIdentityContext(ctx, userID, identity)
	if err != nil {
		return nil, err
	}
	if !found {
		return []MediaItem{}, nil
	}
	return s.personMediaForIdentityContext(ctx, userID, resolved, limit)
}

func (s *Server) personMediaForIdentityContext(ctx context.Context, userID string, identity personIdentitySelector, limit int) ([]MediaItem, error) {
	identitySQL, identityArgs := personIdentityPredicateSQL(identity, "p")
	return s.personMediaForCreditPredicateContext(ctx, userID, identitySQL, identityArgs, limit)
}

func (s *Server) personMediaRecommendationContext(ctx context.Context, userID, name, role string, limit int) ([]MediaItem, error) {
	name = strings.Join(strings.Fields(strings.TrimSpace(name)), " ")
	role = strings.Join(strings.Fields(strings.TrimSpace(role)), " ")
	if name == "" || role == "" {
		return []MediaItem{}, nil
	}
	return s.personMediaForCreditPredicateContext(ctx, userID,
		"lower(trim(p.name)) = lower(trim(?)) AND lower(trim(p.role)) = lower(trim(?))",
		[]any{name, role}, limit)
}

func (s *Server) personMediaForCreditPredicateContext(ctx context.Context, userID, creditPredicate string, creditArgs []any, limit int) ([]MediaItem, error) {
	items, err := s.queryMediaListItemsContext(ctx, userID, `
		JOIN (
			SELECT
				root_id AS media_id,
				MIN(role_rank) AS role_rank,
				MIN(sort_order) AS person_sort_order
			FROM (
				SELECT
					CASE
						WHEN credited.type IN ('movie', 'show', 'anime') THEN credited.id
						WHEN parent.type IN ('show', 'anime') THEN parent.id
						WHEN grandparent.type IN ('show', 'anime') THEN grandparent.id
						ELSE credited.id
					END AS root_id,
					CASE
						WHEN LOWER(p.role) IN ('actor', 'cast', 'voice') THEN 0
						WHEN LOWER(p.role) = 'director' THEN 1
						WHEN LOWER(p.role) IN ('writer', 'screenplay', 'teleplay') THEN 2
						WHEN LOWER(p.role) IN ('creator', 'showrunner') THEN 3
						WHEN LOWER(p.role) LIKE '%producer%' THEN 4
						ELSE 5
					END AS role_rank,
					p.sort_order
				FROM media_people p
				JOIN media_items credited ON credited.id = p.media_id
				LEFT JOIN media_items parent ON parent.id = credited.parent_id
				LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
				WHERE `+creditPredicate+`
			)
			WHERE root_id <> ''
			GROUP BY root_id
		) person_match ON person_match.media_id = m.id
		WHERE m.type IN ('movie', 'show', 'anime')
		ORDER BY person_match.role_rank ASC, person_match.person_sort_order ASC, m.year DESC, m.sort_title ASC`+optionalLimitClause(limit), append(creditArgs, optionalLimitArgs(limit)...))
	if err != nil {
		return nil, err
	}
	return s.filterItemsByLibraryVisibility(items, "person-media"), nil
}

func (s *Server) searchLiveTVChannels(user User, q string, limit int) ([]MediaItem, error) {
	return s.searchLiveTVChannelsContext(context.Background(), user, q, limit)
}

func (s *Server) searchLiveTVChannelsContext(ctx context.Context, user User, q string, limit int) ([]MediaItem, error) {
	return s.searchLiveTVChannelsPageContext(ctx, user, q, limit, searchResultCursor{})
}

func (s *Server) searchLiveTVChannelsPageContext(ctx context.Context, user User, q string, limit int, cursor searchResultCursor) ([]MediaItem, error) {
	q = strings.TrimSpace(q)
	if q == "" || !canViewLiveTV(user) {
		return []MediaItem{}, nil
	}
	if limit <= 0 || limit > 100 {
		limit = 50
	}
	match := mediaSearchQuery(q)
	if match == "" {
		return []MediaItem{}, nil
	}
	policy := normalizeUserChannelPolicy(user.ChannelPolicy)
	if user.Role == "owner" {
		policy = UserChannelPolicy{}
	} else {
		policy = combineUserChannelPolicies(s.userLiveTVChannelPolicy(accountIDForUser(user)), policy)
	}
	policySQL := ""
	policyArgs := []any{}
	if len(policy.AllowedChannelIDs) > 0 {
		policySQL += " AND c.id IN (" + sqlPlaceholders(len(policy.AllowedChannelIDs)) + ")"
		for _, channelID := range policy.AllowedChannelIDs {
			policyArgs = append(policyArgs, channelID)
		}
	}
	if len(policy.BlockedChannelIDs) > 0 {
		policySQL += " AND c.id NOT IN (" + sqlPlaceholders(len(policy.BlockedChannelIDs)) + ")"
		for _, channelID := range policy.BlockedChannelIDs {
			policyArgs = append(policyArgs, channelID)
		}
	}
	cursorSQL := ""
	args := []any{viewerProfileID(user), match}
	args = append(args, policyArgs...)
	if cursor.Mode != "" {
		cursorSQL = `WHERE
			match_bucket > ? OR
			(match_bucket = ? AND (relevance > ? OR
			(relevance = ? AND (sort_order > ? OR
			(sort_order = ? AND (name COLLATE NOCASE > ? OR
			(name COLLATE NOCASE = ? AND id > ?)))))))`
		args = append(args, cursor.Bucket, cursor.Bucket, cursor.Rank, cursor.Rank, cursor.Year, cursor.Year, cursor.SortTitle, cursor.SortTitle, cursor.ID)
	}
	args = append(args, limit)
	rows, err := s.queryUserRead(ctx, `
		WITH ranked_channels AS (
			SELECT
				c.id, c.source_id, c.number, c.name, c.logo_url, c.tvg_id, c.group_title, c.country,
				COALESCE(cps.favorite, 0) AS favorite, c.sort_order, s.name AS source_name, s.type AS source_type,
				CASE
					WHEN LOWER(c.name) = LOWER(?) THEN 0
					WHEN LOWER(c.number) = LOWER(?) THEN 1
					WHEN LOWER(c.name) LIKE LOWER(?) THEN 2
					ELSE 3
				END AS match_bucket,
				bm25(live_tv_channel_search) AS relevance
			FROM live_tv_channel_search
			JOIN live_tv_channels c ON c.id = live_tv_channel_search.channel_id
			JOIN live_tv_sources s ON s.id = c.source_id
			LEFT JOIN live_tv_channel_profile_state cps ON cps.channel_id = c.id AND cps.profile_id = ?
			WHERE live_tv_channel_search MATCH ?
			  AND c.enabled = 1
			  AND COALESCE(cps.hidden, 0) = 0
			  AND s.enabled = 1`+policySQL+`
		)
		SELECT id, source_id, number, name, logo_url, tvg_id, group_title, country,
		       favorite, sort_order, source_name, source_type, match_bucket, relevance
		FROM ranked_channels `+cursorSQL+`
		ORDER BY match_bucket ASC, relevance ASC, sort_order ASC, name COLLATE NOCASE ASC, id ASC
		LIMIT ?`, append([]any{q, q, q + "%"}, args...)...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MediaItem{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var id, sourceID, number, name, rawLogoURL, tvgID, groupTitle, country, sourceName, sourceType string
		var favorite, sortOrder, searchBucket int
		var searchRank float64
		if err := rows.Scan(&id, &sourceID, &number, &name, &rawLogoURL, &tvgID, &groupTitle, &country, &favorite, &sortOrder, &sourceName, &sourceType, &searchBucket, &searchRank); err != nil {
			return nil, err
		}
		images := imageSetFor(id, groupTitle, name, nil)
		if rawLogoURL != "" {
			images.Thumb = liveTVLogoProxyURL(id, rawLogoURL)
			images.Poster = images.Thumb
		}
		item := MediaItem{
			ID:           id,
			LibraryID:    sourceID,
			Type:         "live_channel",
			Title:        name,
			SortTitle:    firstNonEmpty(number+" "+name, name),
			Summary:      strings.TrimSpace(strings.Join(nonEmptySearchParts([]string{number, groupTitle, sourceName}), " · ")),
			Network:      sourceName,
			Country:      country,
			Genres:       []string{"Live TV"},
			Tags:         nonEmptySearchParts([]string{sourceName, tvgID}),
			Labels:       nonEmptySearchParts([]string{sourceType, groupTitle}),
			AddedAt:      time.Now().UTC().Format(time.RFC3339),
			IndexNumber:  sortOrder,
			SearchBucket: searchBucket,
			SearchRank:   searchRank,
			Images:       images,
			State:        MediaState{Favorite: favorite == 1},
			TypedMetadata: map[string]string{
				"channelNumber": number,
				"source":        sourceName,
				"group":         groupTitle,
			},
			SourceURL: liveTVHLSPlaylistRoute(id, ""),
		}
		applyMediaActionsToItem(&item, user)
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const (
	maxConcurrentSearchesPerUser = 2
	maxConcurrentSearchesGlobal  = 100
)

func (s *Server) acquireUserSearchSlot(userID string) bool {
	key := strings.TrimSpace(userID)
	if key == "" {
		key = "anonymous"
	}
	s.searchMu.Lock()
	defer s.searchMu.Unlock()
	if s.searchActive == nil {
		s.searchActive = map[string]int{}
	}
	totalActive := 0
	for _, active := range s.searchActive {
		totalActive += active
	}
	if totalActive >= maxConcurrentSearchesGlobal {
		return false
	}
	if s.searchActive[key] >= maxConcurrentSearchesPerUser {
		return false
	}
	s.searchActive[key]++
	return true
}

func (s *Server) releaseUserSearchSlot(userID string) {
	key := strings.TrimSpace(userID)
	if key == "" {
		key = "anonymous"
	}
	s.searchMu.Lock()
	defer s.searchMu.Unlock()
	if s.searchActive == nil || s.searchActive[key] <= 0 {
		return
	}
	s.searchActive[key]--
	if s.searchActive[key] == 0 {
		delete(s.searchActive, key)
	}
}

func (s *Server) handleSettings(w http.ResponseWriter, r *http.Request, user User) {
	if !canViewServerSettings(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage server settings.")
		return
	}
	switch r.Method {
	case http.MethodGet:
		document, err := s.settingsDocumentForUser(r.Context(), user, SettingsApplyImpact{})
		if err != nil {
			writeError(w, http.StatusInternalServerError, "settings_failed", "Unable to load settings.")
			return
		}
		writeSettingsDocument(w, http.StatusOK, document)
	case http.MethodPatch:
		var req struct {
			ExpectedRevision string                     `json:"expectedRevision"`
			IdempotencyKey   string                     `json:"idempotencyKey"`
			Groups           map[string]json.RawMessage `json:"groups"`
		}
		if !decodeJSON(w, r, &req) {
			return
		}
		req.ExpectedRevision = normalizeSettingsRevision(req.ExpectedRevision)
		if req.ExpectedRevision == "" {
			writeError(w, http.StatusBadRequest, "settings_revision_required", "expectedRevision is required. Reload settings before saving changes.")
			return
		}
		if len(req.Groups) == 0 {
			writeError(w, http.StatusBadRequest, "settings_groups_required", "At least one settings group is required.")
			return
		}
		idempotencyKey, idempotencyErr := validateSettingsIdempotencyKey(req.IdempotencyKey)
		if idempotencyErr != nil {
			writeError(w, http.StatusBadRequest, "settings_idempotency_key_invalid", idempotencyErr.Error())
			return
		}
		if idempotencyKey == "" {
			writeError(w, http.StatusBadRequest, "settings_idempotency_key_required", "idempotencyKey is required for settings mutations.")
			return
		}
		fingerprint := ""
		if idempotencyKey != "" {
			fingerprint, idempotencyErr = settingsMutationFingerprint(req.ExpectedRevision, req.Groups)
			if idempotencyErr != nil {
				writeError(w, http.StatusBadRequest, "settings_idempotency_key_invalid", "Settings request could not be fingerprinted.")
				return
			}
		}
		now := time.Now().UTC().Format(time.RFC3339Nano)
		var txStatus int
		var txCode string
		var txMessage string
		var txDetails map[string]any
		changedFields := []string{}
		currentRevision := ""
		replayed := false
		scanProfileRunningJobIDs := []string{}
		scanProfileFollowups := []scanProfileFollowup{}
		var scanProfileBefore, scanProfileAfter map[string]any
		receiptKey := ""
		var replayDocument *SettingsDocument
		err := s.withUserTxTagged(r.Context(), []string{"settings"}, func(tx *sql.Tx) error {
			currentSettings, revision, _, err := loadSettingsSnapshotFromQuery(tx.Query(`SELECT key, value_json, updated_at FROM settings ORDER BY key ASC`))
			if err != nil {
				return err
			}
			currentRevision = revision
			if idempotencyKey != "" {
				receiptKey = settingsMutationReceiptKey(user, idempotencyKey)
				receipt, found, receiptErr := loadSettingsMutationReceipt(tx, receiptKey)
				if receiptErr != nil {
					return receiptErr
				}
				if found {
					if receipt.Fingerprint != fingerprint {
						txStatus = http.StatusConflict
						txCode = "settings_idempotency_conflict"
						txMessage = "This idempotency key was already used for a different settings request."
						return errors.New(txMessage)
					}
					// A retry after a lost response is already committed.  Return the
					// authoritative document without comparing its old expected revision
					// or applying the patch a second time.
					currentRevision = receipt.Revision
					replayed = true
					if len(receipt.Response) > 0 {
						var document SettingsDocument
						if decodeErr := json.Unmarshal(receipt.Response, &document); decodeErr == nil && document.Revision != "" {
							replayDocument = &document
						}
					}
					return nil
				}
			}
			if req.ExpectedRevision != currentRevision {
				txStatus = http.StatusConflict
				txCode = "settings_revision_conflict"
				txMessage = "Settings changed after this document was loaded. Reload settings and reapply the change."
				return errors.New(txMessage)
			}
			for key, value := range req.Groups {
				if !canWriteSettingGroup(user, key) {
					txStatus = http.StatusForbidden
					txCode = "forbidden"
					txMessage = "You do not have permission to change this settings group."
					return errors.New(txMessage)
				}
				if !isWritableSettingGroup(key) {
					txStatus = http.StatusBadRequest
					txCode = "setting_group_not_writable"
					txMessage = "This settings group is read-only."
					return errors.New(txMessage)
				}
				if !json.Valid(value) {
					txStatus = http.StatusBadRequest
					txCode = "invalid_setting_value"
					txMessage = "Settings value must be valid JSON."
					return errors.New(txMessage)
				}
				var requestedFields map[string]any
				if err := json.Unmarshal(value, &requestedFields); err != nil {
					txStatus = http.StatusBadRequest
					txCode = "invalid_setting_value"
					txMessage = key + " settings must be a JSON object."
					txDetails = map[string]any{"fieldPath": key}
					return err
				}
				if requestedFields == nil {
					txStatus = http.StatusBadRequest
					txCode = "invalid_setting_value"
					txMessage = key + " settings must be a JSON object."
					txDetails = map[string]any{"fieldPath": key}
					return errors.New(txMessage)
				}
				if key == "metadataAgents" {
					sanitized, err := s.applyMetadataAgentSecrets(tx, value, now)
					if err != nil {
						txStatus = http.StatusBadRequest
						txCode = "invalid_setting_value"
						txMessage = err.Error()
						txDetails = map[string]any{"fieldPath": settingsValidationFieldPath(key, err)}
						return err
					}
					value = sanitized
				}
				normalized, err := mergeAndNormalizeWritableSettingGroup(key, currentSettings[key], value)
				if err != nil {
					txStatus = http.StatusBadRequest
					txCode = "invalid_setting_value"
					txMessage = err.Error()
					txDetails = map[string]any{"fieldPath": settingsValidationFieldPath(key, err)}
					return err
				}
				if key == "library" {
					scanProfileBefore = decodeScanProfileSettings(currentSettings[key])
					scanProfileAfter = decodeScanProfileSettings(normalized)
				}
				if !settingJSONEqual(currentSettings[key], normalized) {
					if _, err := tx.Exec(`INSERT INTO settings (key, value_json, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, updated_at = excluded.updated_at`, key, string(normalized), now); err != nil {
						return err
					}
				}
				for field := range requestedFields {
					changedFields = append(changedFields, key+"."+field)
				}
			}
			if scanProfileBefore != nil && scanProfileAfter != nil {
				scanProfileRunningJobIDs, scanProfileFollowups, err = s.fenceGlobalScanProfileChangeTx(tx, scanProfileBefore, scanProfileAfter)
				if err != nil {
					return err
				}
			}
			if idempotencyKey != "" {
				// Include the post-write revision in the receipt while still inside
				// the same transaction as the settings mutation.
				_, nextRevision, _, revisionErr := loadSettingsSnapshotFromQuery(tx.Query(`SELECT key, value_json, updated_at FROM settings ORDER BY key ASC`))
				if revisionErr != nil {
					return revisionErr
				}
				currentRevision = nextRevision
				if err := saveSettingsMutationReceipt(tx, receiptKey, settingsMutationReceipt{Fingerprint: fingerprint, Revision: nextRevision, CreatedAt: now, ExpiresAt: time.Now().UTC().Add(7 * 24 * time.Hour).Format(time.RFC3339Nano)}); err != nil {
					return err
				}
			}
			return nil
		})
		if err != nil {
			if txStatus != 0 {
				if currentRevision != "" {
					w.Header().Set("ETag", settingsETag(currentRevision))
					w.Header().Set("X-Portico-Settings-Revision", currentRevision)
				}
				writeProductErrorWithDetails(w, txStatus, txCode, txMessage, txDetails)
				return
			}
			writeError(w, http.StatusInternalServerError, "settings_failed", "Unable to save settings.")
			return
		}
		s.cancelRunningJobContexts(scanProfileRunningJobIDs)
		s.enqueueScanProfileFollowups(scanProfileFollowups)
		s.invalidateSessionCookieCache()
		if !replayed {
			s.recordLog("info", "Server settings saved", map[string]string{"actorId": strings.TrimSpace(user.ID)})
			s.recordAudit(r, user, "settings.updated", "settings", "", "info", map[string]string{
				"groups": strings.Join(mapKeysRaw(req.Groups), ","), "previousRevision": req.ExpectedRevision,
				"resultRevision": currentRevision, "idempotency": strconv.FormatBool(idempotencyKey != ""),
			})
		}
		changedFields = uniqueStrings(changedFields)
		sort.Strings(changedFields)
		restartFields := changedRestartRequiredSettingFields(changedFields)
		document, err := s.settingsDocumentForUser(r.Context(), user, SettingsApplyImpact{
			ChangedFields:         changedFields,
			RestartRequired:       len(restartFields) > 0,
			RestartRequiredFields: restartFields,
		})
		if err != nil {
			writeError(w, http.StatusInternalServerError, "settings_failed", "Settings were saved but the updated document could not be loaded.")
			return
		}
		if replayDocument != nil {
			writeSettingsDocument(w, http.StatusOK, *replayDocument)
			return
		}
		if idempotencyKey != "" {
			if receiptErr := s.withUserTxTagged(r.Context(), []string{"settings"}, func(tx *sql.Tx) error {
				return updateSettingsMutationReceiptResponse(tx, receiptKey, document)
			}); receiptErr != nil {
				// The durable settings commit is already complete. Do not turn a
				// successful save into a false failure; retries still reconcile by
				// the committed revision when a response receipt cannot be extended.
				s.recordLog("warn", "Settings idempotency response receipt was not persisted", map[string]string{"error": s.sanitizeDiagnosticText(receiptErr.Error(), 240)})
			}
		}
		writeSettingsDocument(w, http.StatusOK, document)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or PATCH for this endpoint.")
	}
}

func settingsValidationFieldPath(group string, err error) string {
	fallback := strings.TrimSpace(group)
	if err == nil {
		return fallback
	}
	message := strings.TrimSpace(err.Error())
	if message == "" {
		return fallback
	}
	field := strings.Trim(strings.Fields(message)[0], ":,.;")
	if field == fallback || strings.HasPrefix(field, fallback+".") {
		return field
	}
	return fallback
}

func (s *Server) handleSettingsSummary(w http.ResponseWriter, r *http.Request, user User) {
	if !canViewServerSettings(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view server settings.")
		return
	}
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	settings, _, _, err := s.loadSettingsSnapshotContext(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "settings_summary_failed", "Unable to load settings summary.")
		return
	}
	writeJSON(w, http.StatusOK, s.settingsSummaryForUser(user, settings))
}

func (s *Server) handleLogs(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view server logs.")
		return
	}
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
	cursorTime, cursorID, err := decodeTimeIDCursor(strings.TrimSpace(r.URL.Query().Get("cursor")))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_cursor", "Log cursor is invalid.")
		return
	}
	events, nextCursor := s.listLogEventsPage(limit, cursorTime, cursorID)
	responseLimit := normalizedLogLimit(limit)
	writeJSON(w, http.StatusOK, ListResponse[LogEvent]{Items: events, Total: len(events), Limit: responseLimit, HasMore: nextCursor != "", NextCursor: nextCursor})
}

func (s *Server) handleLogStream(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view server logs.")
		return
	}
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, http.StatusInternalServerError, "stream_unavailable", "Streaming is not supported by this server.")
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.Header().Set("X-Portico-Stream-Resume", "none")
	if streamResumeResetRequested(r, w, flusher) {
		return
	}

	events := s.subscribeLogs()
	defer s.unsubscribeLogs(events)
	s.recordLog("debug", "Console stream connected", map[string]string{"user": user.Email})
	prepareStreamWrite(w)
	if _, err := fmt.Fprint(w, ": connected\n\n"); err != nil {
		return
	}
	flusher.Flush()

	heartbeat := time.NewTicker(25 * time.Second)
	defer heartbeat.Stop()
	authorization := time.NewTicker(eventStreamAuthorizationCheck)
	defer authorization.Stop()
	shutdownDone := s.shutdownDone()
	for {
		select {
		case event, ok := <-events:
			if !ok {
				prepareStreamWrite(w)
				_, _ = fmt.Fprint(w, "event: stream-reset\ndata: {\"resetRequired\":true,\"reason\":\"gap\"}\n\n")
				flusher.Flush()
				return
			}
			bytes, err := json.Marshal(event)
			if err != nil {
				continue
			}
			prepareStreamWrite(w)
			if _, err := fmt.Fprintf(w, "data: %s\n\n", bytes); err != nil {
				return
			}
			flusher.Flush()
		case <-heartbeat.C:
			prepareStreamWrite(w)
			if _, err := fmt.Fprint(w, ": heartbeat\n\n"); err != nil {
				return
			}
			flusher.Flush()
		case <-authorization.C:
			if !s.longPollUserAuthorizationCurrent(r, user) {
				return
			}
		case <-r.Context().Done():
			return
		case <-shutdownDone:
			return
		}
	}
}

// Event publication is signal-driven. The timer is a fallback for credentials
// that expire or are revoked outside the server's normal mutation pipeline.
var eventStreamAuthorizationCheck = 15 * time.Second

func (s *Server) handleAppEvents(w http.ResponseWriter, r *http.Request, user User) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, http.StatusInternalServerError, "stream_unavailable", "Streaming is not supported by this server.")
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.Header().Set("X-Portico-Stream-Resume", "none")
	if streamResumeResetRequested(r, w, flusher) {
		return
	}

	events := s.subscribeAppEventsForUser(user)
	defer s.unsubscribeAppEvents(events)
	prepareStreamWrite(w)
	if _, err := fmt.Fprint(w, ": connected\n\n"); err != nil {
		return
	}
	flusher.Flush()

	heartbeat := time.NewTicker(25 * time.Second)
	defer heartbeat.Stop()
	authorization := time.NewTicker(eventStreamAuthorizationCheck)
	defer authorization.Stop()
	shutdownDone := s.shutdownDone()
	for {
		select {
		case event, ok := <-events:
			if !ok {
				prepareStreamWrite(w)
				_, _ = fmt.Fprint(w, "event: stream-reset\ndata: {\"resetRequired\":true,\"reason\":\"gap\"}\n\n")
				flusher.Flush()
				return
			}
			projected, visible := s.projectAppEventForUserContext(r.Context(), user, event)
			if !visible {
				continue
			}
			bytes, err := json.Marshal(projected)
			if err != nil {
				continue
			}
			prepareStreamWrite(w)
			if _, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", projected.ID, projected.Type, bytes); err != nil {
				return
			}
			flusher.Flush()
		case <-heartbeat.C:
			prepareStreamWrite(w)
			if _, err := fmt.Fprint(w, ": heartbeat\n\n"); err != nil {
				return
			}
			flusher.Flush()
		case <-authorization.C:
			// Long-lived native streams must not outlive an expired/revoked
			// credential or a profile/permission revision. Closing here lets
			// Client Core refresh and reconnect through the normal lifecycle.
			if !s.longPollUserAuthorizationCurrent(r, user) {
				return
			}
		case <-r.Context().Done():
			return
		case <-shutdownDone:
			return
		}
	}
}

func (s *Server) handleUsers(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "owner_required", "Only the server owner can manage server users.")
		return
	}
	switch r.Method {
	case http.MethodGet:
		if settings, err := s.remoteAccessSettings(); err == nil {
			s.syncRemoteAccessMembersIfClaimed(r.Context(), settings)
		} else {
			s.recordLog("warn", "Portico account member sync skipped from Users screen", map[string]string{"error": err.Error()})
		}
		users, err := s.listUsers()
		if err != nil {
			writeError(w, http.StatusInternalServerError, "users_failed", "Unable to load users.")
			return
		}
		writeJSON(w, http.StatusOK, ListResponse[User]{Items: users, Total: len(users)})
	case http.MethodPost:
		if !s.localUserManagementAllowed() {
			writeError(w, http.StatusConflict, "portico_account_mode", "Local user management is disabled while this server uses Portico accounts.")
			return
		}
		var req UserCreateRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		created, err := s.createUserContext(r.Context(), req.internalRequest())
		if err != nil {
			if writeKDFUnavailable(w, err) {
				return
			}
			writeError(w, http.StatusBadRequest, "user_create_failed", err.Error())
			return
		}
		s.recordLog("info", "User created", map[string]string{"actor": user.Email, "user": created.Email, "role": created.Role})
		s.recordAudit(r, user, "user.created", "user", created.ID, "info", map[string]string{"email": created.Email, "role": created.Role})
		writeJSON(w, http.StatusCreated, created)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET or POST for this endpoint.")
		return
	}
}

func (s *Server) handleUserRoute(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "owner_required", "Only the server owner can manage server users.")
		return
	}
	userID := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/users/"), "/")
	if userID == "" {
		writeError(w, http.StatusNotFound, "not_found", "User route was not found.")
		return
	}
	var targetRole string
	if err := s.queryUserRow(r.Context(), `SELECT role FROM users WHERE id = ?`, userID).Scan(&targetRole); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "user_not_found", "User was not found.")
			return
		}
		writeDatabaseAccessError(w, err, http.StatusInternalServerError, "users_failed", "Unable to load the target user.")
		return
	}
	if targetRole == "owner" {
		writeError(w, http.StatusForbidden, "owner_target_forbidden", "The server owner must use owner self-service or recovery flows.")
		return
	}
	switch r.Method {
	case http.MethodPatch:
		if !s.localUserManagementAllowed() {
			writeError(w, http.StatusConflict, "portico_account_mode", "Local user management is disabled while this server uses Portico accounts.")
			return
		}
		var req UserPatchRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		updated, err := s.updateUserContext(r.Context(), userID, req)
		if err != nil {
			if writeKDFUnavailable(w, err) {
				return
			}
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "user_not_found", "User was not found.")
				return
			}
			var fieldErr *requestFieldValidationError
			if errors.As(err, &fieldErr) {
				writeProductErrorWithDetails(w, http.StatusBadRequest, "invalid_user_field", fieldErr.Detail, map[string]any{"fieldPath": fieldErr.FieldPath})
				return
			}
			writeError(w, http.StatusBadRequest, "user_update_failed", err.Error())
			return
		}
		s.recordLog("info", "User updated", map[string]string{"actor": user.Email, "user": updated.Email, "role": updated.Role})
		s.recordAudit(r, user, "user.updated", "user", updated.ID, "info", map[string]string{"email": updated.Email, "role": updated.Role})
		writeJSON(w, http.StatusOK, updated)
	case http.MethodDelete:
		if !s.localUserManagementAllowed() {
			writeError(w, http.StatusConflict, "portico_account_mode", "Local user management is disabled while this server uses Portico accounts.")
			return
		}
		deleted, err := s.deleteUserContext(r.Context(), userID)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "user_not_found", "User was not found.")
				return
			}
			if errors.Is(err, errProfileErasureDrainTimeout) || errors.Is(err, errProfileErasureInProgress) {
				w.Header().Set("Retry-After", "2")
				writeError(w, http.StatusServiceUnavailable, "user_authority_drain_pending", "Active work for this user did not stop safely. Try again shortly.")
				return
			}
			writeError(w, http.StatusBadRequest, "user_delete_failed", err.Error())
			return
		}
		s.recordLog("warn", "User deleted", map[string]string{"actor": user.Email, "user": deleted.Email})
		s.recordAudit(r, user, "user.deleted", "user", deleted.ID, "warn", map[string]string{"email": deleted.Email})
		writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
	default:
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use PATCH or DELETE for this endpoint.")
	}
}

func (s *Server) localUserManagementAllowed() bool {
	return !s.porticoAccountMode()
}

func (s *Server) porticoAccountMode() bool {
	settings, err := s.remoteAccessSettings()
	if err != nil {
		return false
	}
	if strings.TrimSpace(settings.ServerID) == "" || settings.ClaimStatus != "claimed" {
		return false
	}
	return settings.PreferredRemoteAuthMode == "portico"
}

func isPorticoPrincipal(user User) bool {
	return strings.TrimSpace(user.PorticoUserID) != "" || user.AuthOrigin == "portico"
}

func (s *Server) handleActivity(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to view activity.")
		return
	}
	path := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/activity"), "/")
	if path != "" {
		if path == "cancel" {
			if r.Method != http.MethodPost {
				writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
				return
			}
			var req struct {
				Type string `json:"type"`
			}
			if !decodeJSON(w, r, &req) {
				return
			}
			response, err := s.cancelJobsByType(req.Type)
			if err != nil {
				writeError(w, http.StatusBadRequest, "job_cancel_failed", err.Error())
				return
			}
			writeJSON(w, http.StatusOK, response)
			return
		}
		parts := strings.Split(path, "/")
		if len(parts) == 2 && parts[1] == "cancel" {
			if r.Method != http.MethodPost {
				writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
				return
			}
			job, err := s.cancelJob(parts[0])
			if err != nil {
				if errors.Is(err, sql.ErrNoRows) {
					writeError(w, http.StatusNotFound, "job_not_found", "Job was not found.")
					return
				}
				writeError(w, http.StatusConflict, "job_not_cancellable", err.Error())
				return
			}
			writeJSON(w, http.StatusOK, job)
			return
		}
		writeError(w, http.StatusNotFound, "not_found", "Activity route was not found.")
		return
	}
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
		return
	}
	limit := max(1, min(250, queryInt(r, "limit", 80)))
	cursorCreatedAt, cursorID, err := decodeTimeIDCursor(strings.TrimSpace(r.URL.Query().Get("cursor")))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_cursor", "Activity cursor is invalid.")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), navigationRequestTimeout)
	defer cancel()
	jobs, nextCursor, err := s.listJobsPageContext(ctx, limit, cursorCreatedAt, cursorID)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, "activity_timeout", "Activity exceeded the foreground request budget. Try again shortly.")
			return
		}
		writeError(w, http.StatusInternalServerError, "activity_failed", "Unable to load activity.")
		return
	}
	writeJSON(w, http.StatusOK, ListResponse[Job]{Items: jobs, Total: len(jobs), Limit: limit, HasMore: nextCursor != "", NextCursor: nextCursor})
}

func (s *Server) handleScheduledTasks(w http.ResponseWriter, r *http.Request, user User) {
	if !canInteractivelyManageServer(user) {
		writeError(w, http.StatusForbidden, "forbidden", "You do not have permission to manage scheduled tasks.")
		return
	}
	path := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/tasks"), "/")
	if path == "" {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use GET for this endpoint.")
			return
		}
		tasks, err := s.listScheduledTasks()
		if err != nil {
			writeError(w, http.StatusInternalServerError, "tasks_failed", "Unable to load scheduled tasks.")
			return
		}
		writeJSON(w, http.StatusOK, ListResponse[ScheduledTask]{Items: tasks, Total: len(tasks)})
		return
	}
	parts := strings.Split(path, "/")
	if len(parts) == 1 && r.Method == http.MethodPatch {
		var req ScheduledTaskUpdateRequest
		if !decodeJSON(w, r, &req) {
			return
		}
		task, err := s.updateScheduledTaskTrigger(parts[0], req)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "task_not_found", "Scheduled task was not found.")
				return
			}
			writeError(w, http.StatusBadRequest, "task_update_failed", err.Error())
			return
		}
		s.recordAudit(r, user, "scheduled_task.updated", "scheduled_task", task.ID, "info", map[string]string{"enabled": strconv.FormatBool(task.Trigger.Enabled), "intervalHours": strconv.Itoa(task.Trigger.IntervalHours)})
		writeJSON(w, http.StatusOK, task)
		return
	}
	if len(parts) == 2 && parts[1] == "run" {
		if r.Method != http.MethodPost {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "Use POST for this endpoint.")
			return
		}
		jobs, err := s.runScheduledTask(parts[0])
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "task_not_found", "Scheduled task was not found.")
				return
			}
			writeError(w, http.StatusBadRequest, "task_run_failed", err.Error())
			return
		}
		writeJSON(w, http.StatusAccepted, ScheduledTaskRunResponse{TaskID: parts[0], Jobs: jobs})
		return
	}
	writeError(w, http.StatusNotFound, "not_found", "Scheduled task route was not found.")
}

func (s *Server) listScheduledTasks() ([]ScheduledTask, error) {
	settings := s.scheduledTaskSettings()
	jobs, err := s.listJobs()
	if err != nil {
		return nil, err
	}
	lastByType := map[string]*Job{}
	runningByType := map[string]bool{}
	for _, job := range jobs {
		jobCopy := job
		if _, ok := lastByType[job.Type]; !ok {
			lastByType[job.Type] = &jobCopy
		}
		if job.Status == "queued" || job.Status == "running" {
			runningByType[job.Type] = true
		}
	}
	window := scheduledWindowLabelInTimezone(settings.MaintenanceWindow, settings.MaintenanceTimezone, settings.StartHour, settings.EndHour)
	days := scheduledDaysLabel(settings.MaintenanceDays)
	backupInterval := settings.taskIntervalHours("database-backup", settings.BackupCadence, 24)
	libraryInterval := settings.taskIntervalHours("library-scan", settings.LibraryScanCadence, settings.LibraryScanIntervalHours)
	metadataInterval := settings.taskIntervalHours("metadata-refresh", settings.MetadataRefreshCadence, 24)
	analysisInterval := settings.taskIntervalHours("media-analysis", settings.AnalysisCadence, 24)
	tasks := []ScheduledTask{
		{ID: "database-backup", Title: "Database Backup", Category: "Backups", Description: "Create and retain SQLite database backups.", Enabled: settings.Enabled && settings.taskEnabled("database-backup", settings.BackupDatabase), JobType: "database_backup", Schedule: fmt.Sprintf("%s during %s, %s", scheduledCadenceLabel(settings.BackupCadence, backupInterval), window, days), Trigger: ScheduledTaskTrigger{Enabled: settings.taskEnabled("database-backup", settings.BackupDatabase), IntervalHours: backupInterval}},
		{ID: "library-scan", Title: "Library Scan", Category: "Libraries", Description: "Queue scans for libraries that allow automatic scanning.", Enabled: settings.Enabled && settings.globallyEnabledTask("library-scan", settings.ScanLibraries), JobType: "library_scan", Schedule: fmt.Sprintf("%s during %s, %s", scheduledCadenceLabel(settings.LibraryScanCadence, libraryInterval), window, days), Trigger: ScheduledTaskTrigger{Enabled: settings.globallyEnabledTask("library-scan", settings.ScanLibraries), IntervalHours: libraryInterval}},
		{ID: "metadata-refresh", Title: "Metadata Refresh", Category: "Metadata", Description: "Refresh stale movie, show, anime, and episode metadata.", Enabled: settings.Enabled && settings.taskEnabled("metadata-refresh", settings.RefreshMetadata), JobType: "metadata_refresh_library", Schedule: fmt.Sprintf("%s during %s, %s; refresh items older than %d days", scheduledCadenceLabel(settings.MetadataRefreshCadence, metadataInterval), window, days, settings.MetadataRefreshDays), Trigger: ScheduledTaskTrigger{Enabled: settings.taskEnabled("metadata-refresh", settings.RefreshMetadata), IntervalHours: metadataInterval}},
		{ID: "media-analysis", Title: "Media Analysis", Category: "Analysis", Description: "Analyze media streams where enabled.", Enabled: settings.Enabled && settings.globallyEnabledTask("media-analysis", settings.AnalyzeMedia), JobType: "media_analyze", Schedule: fmt.Sprintf("%s during %s, %s", scheduledCadenceLabel(settings.AnalysisCadence, analysisInterval), window, days), Trigger: ScheduledTaskTrigger{Enabled: settings.globallyEnabledTask("media-analysis", settings.AnalyzeMedia), IntervalHours: analysisInterval}},
	}
	for index := range tasks {
		tasks[index].Timezone = settings.MaintenanceTimezone
		tasks[index].LastJob = lastByType[tasks[index].JobType]
		tasks[index].Running = runningByType[tasks[index].JobType]
	}
	return tasks, nil
}

func (s *Server) updateScheduledTaskTrigger(taskID string, req ScheduledTaskUpdateRequest) (ScheduledTask, error) {
	taskID = strings.TrimSpace(taskID)
	if !knownScheduledTaskID(taskID) {
		return ScheduledTask{}, sql.ErrNoRows
	}
	settings, err := s.loadSettings()
	if err != nil {
		return ScheduledTask{}, err
	}
	group, _ := settings["scheduledTasks"].(map[string]any)
	if group == nil {
		group = map[string]any{}
	}
	rawTriggers, _ := group["taskTriggers"].(map[string]any)
	if rawTriggers == nil {
		rawTriggers = map[string]any{}
	}
	trigger, _ := rawTriggers[taskID].(map[string]any)
	if trigger == nil {
		trigger = map[string]any{}
	}
	if req.Enabled != nil {
		trigger["enabled"] = *req.Enabled
		if enabledKey := scheduledTaskEnabledSettingKey(taskID); enabledKey != "" {
			group[enabledKey] = *req.Enabled
		}
	}
	if req.IntervalHours != nil {
		trigger["intervalHours"] = max(1, min(24*365, *req.IntervalHours))
		if cadenceKey := scheduledTaskCadenceSettingKey(taskID); cadenceKey != "" {
			group[cadenceKey] = "custom"
		}
	}
	rawTriggers[taskID] = trigger
	group["taskTriggers"] = rawTriggers
	bytes, err := json.Marshal(group)
	if err != nil {
		return ScheduledTask{}, err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if _, err := s.execUserWrite(context.Background(), `INSERT INTO settings (key, value_json, updated_at) VALUES ('scheduledTasks', ?, ?) ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, updated_at = excluded.updated_at`, string(bytes), now); err != nil {
		return ScheduledTask{}, err
	}
	tasks, err := s.listScheduledTasks()
	if err != nil {
		return ScheduledTask{}, err
	}
	for _, task := range tasks {
		if task.ID == taskID {
			return task, nil
		}
	}
	return ScheduledTask{}, sql.ErrNoRows
}

func scheduledTaskCadenceSettingKey(taskID string) string {
	switch strings.TrimSpace(taskID) {
	case "database-backup":
		return "backupCadence"
	case "library-scan":
		return "libraryScanCadence"
	case "metadata-refresh":
		return "metadataRefreshCadence"
	case "media-analysis":
		return "analysisCadence"
	default:
		return ""
	}
}

func scheduledTaskEnabledSettingKey(taskID string) string {
	switch strings.TrimSpace(taskID) {
	case "database-backup":
		return "backupDatabase"
	case "library-scan":
		return "scanLibraries"
	case "metadata-refresh":
		return "refreshMetadata"
	case "media-analysis":
		return "analyzeMedia"
	default:
		return ""
	}
}

func knownScheduledTaskID(taskID string) bool {
	switch strings.TrimSpace(taskID) {
	case "database-backup", "library-scan", "metadata-refresh", "media-analysis":
		return true
	default:
		return false
	}
}

func (s *Server) runScheduledTask(taskID string) ([]Job, error) {
	settings := s.scheduledTaskSettings()
	switch strings.TrimSpace(taskID) {
	case "database-backup":
		job, err := s.createJobFor("database_backup", "Manual database backup queued.", "database", time.Now().UTC().Format("2006-01-02-150405"))
		if err != nil {
			return nil, err
		}
		return []Job{job}, nil
	case "library-scan":
		libraries, err := s.listLibraries()
		if err != nil {
			return nil, err
		}
		jobs := []Job{}
		for _, library := range libraries {
			if settingBool(library.Settings, "scannerEnabled", true) == false {
				continue
			}
			job, err := s.queueLibraryScan(library, "reconcile", "scheduled-task-api", fmt.Sprintf("Manual scan queued for %s.", library.Name))
			if err != nil {
				return jobs, err
			}
			jobs = append(jobs, job)
		}
		return jobs, nil
	case "metadata-refresh":
		libraries, err := s.listLibraries()
		if err != nil {
			return nil, err
		}
		jobs := []Job{}
		for _, library := range libraries {
			refreshDays, enabled := libraryScheduledMetadataRefreshDays(library, settings.MetadataRefreshDays)
			if !enabled {
				continue
			}
			metadata := map[string]string{
				"libraryId":     library.ID,
				"libraryName":   library.Name,
				"refreshDays":   strconv.Itoa(refreshDays),
				"subtaskScope":  "library",
				"refreshIntent": string(metadataRefreshUnlocked),
			}
			job, err := s.createJobForWithMetadata("metadata_refresh_library", fmt.Sprintf("Manual metadata refresh queued for %s.", library.Name), "library", library.ID, metadata)
			if err != nil {
				return jobs, err
			}
			jobs = append(jobs, job)
		}
		return jobs, nil
	case "media-analysis":
		items, err := s.scheduledAnalysisItems(100)
		if err != nil {
			return nil, err
		}
		jobs := []Job{}
		for _, item := range items {
			if !s.mediaAnalysisQueueEnabled(item) {
				continue
			}
			job, err := s.createJobForWithMetadata("media_analyze", fmt.Sprintf("Manual media stream analysis queued for %s.", item.Title), "media", item.ID, s.mediaAnalysisMetadataForItem(context.Background(), item, mediaAnalysisModeProbe))
			if err != nil {
				return jobs, err
			}
			jobs = append(jobs, job)
		}
		return jobs, nil
	default:
		return nil, sql.ErrNoRows
	}
}

func (s *Server) handleArtwork(w http.ResponseWriter, r *http.Request, user User) {
	path := strings.TrimPrefix(r.URL.Path, "/api/artwork/")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) != 2 {
		writeError(w, http.StatusNotFound, "not_found", "Artwork route was not found.")
		return
	}
	if parts[0] == "person" {
		s.handlePersonArtwork(w, r, user, parts[1])
		return
	}
	mediaID := parts[0]
	kind := strings.TrimSuffix(strings.TrimSuffix(parts[1], ".svg"), ".jpg")
	resolution, err := s.resolveArtworkRequest(r.Context(), viewerProfileID(user), user.ID, mediaID, kind, r.URL.Query().Get("v"))
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) || r.Context().Err() != nil {
			w.Header().Set("Retry-After", "1")
			writeError(w, http.StatusServiceUnavailable, "artwork_timeout", "Artwork lookup timed out. Please retry shortly.")
			return
		}
	}
	if !resolution.mediaFound {
		writeError(w, http.StatusNotFound, "media_not_found", "Media item was not found.")
		return
	}
	if resolution.path != "" {
		s.serveArtworkFile(w, r, resolution.path)
		return
	}
	// A missing artwork slot remains missing. Do not turn a presentation
	// fallback into metadata, and do not synthesize branded initials artwork.
	// Clients can consequently use their intentional page-glow/card/player
	// empty states while scanners remain free to fill the slot later.
	writeOptionalArtworkMiss(w)
}

const (
	artworkNegativeCacheTTL = 5 * time.Minute
	artworkNegativeCacheMax = 4096
)

// resolveArtworkRequest coalesces the comparatively expensive catalog and
// filesystem walk needed to prove that an optional artwork slot is empty. Only
// negative results are retained: a cached positive path could outlive a
// profile's library authorization, while a profile-keyed negative can at worst
// delay newly-added artwork until the versioned URL or short TTL changes.
func (s *Server) resolveArtworkRequest(ctx context.Context, profileID, accountID, mediaID, kind, version string) (artworkResolution, error) {
	key := strings.Join([]string{strings.TrimSpace(profileID), strings.TrimSpace(accountID), strings.TrimSpace(mediaID), strings.TrimSpace(kind), strings.TrimSpace(version)}, "\x00")
	now := time.Now()
	s.artworkResolutionMu.Lock()
	if expiresAt, ok := s.artworkNegativeCache[key]; ok {
		if now.Before(expiresAt) {
			s.artworkResolutionMu.Unlock()
			return artworkResolution{mediaFound: true}, nil
		}
		delete(s.artworkNegativeCache, key)
	}
	if call := s.artworkResolutionInFlight[key]; call != nil {
		done := call.done
		s.artworkResolutionMu.Unlock()
		select {
		case <-done:
			return call.result, call.err
		case <-ctx.Done():
			return artworkResolution{}, ctx.Err()
		}
	}
	call := &artworkResolutionCall{done: make(chan struct{})}
	if s.artworkResolutionInFlight == nil {
		s.artworkResolutionInFlight = map[string]*artworkResolutionCall{}
	}
	s.artworkResolutionInFlight[key] = call
	hook := s.artworkResolutionHook
	s.artworkResolutionMu.Unlock()

	if hook != nil {
		hook()
	}
	result, err := s.resolveArtworkRequestUncached(ctx, profileID, accountID, mediaID, kind)

	s.artworkResolutionMu.Lock()
	call.result = result
	call.err = err
	delete(s.artworkResolutionInFlight, key)
	if err == nil && result.mediaFound && result.path == "" {
		if s.artworkNegativeCache == nil {
			s.artworkNegativeCache = map[string]time.Time{}
		}
		if len(s.artworkNegativeCache) >= artworkNegativeCacheMax {
			for cachedKey, expiresAt := range s.artworkNegativeCache {
				if !now.Before(expiresAt) || len(s.artworkNegativeCache) >= artworkNegativeCacheMax {
					delete(s.artworkNegativeCache, cachedKey)
				}
				if len(s.artworkNegativeCache) < artworkNegativeCacheMax {
					break
				}
			}
		}
		s.artworkNegativeCache[key] = time.Now().Add(artworkNegativeCacheTTL)
	}
	close(call.done)
	s.artworkResolutionMu.Unlock()
	return result, err
}

func (s *Server) resolveArtworkRequestUncached(ctx context.Context, profileID, accountID, mediaID, kind string) (artworkResolution, error) {
	item, err := s.getMediaArtworkSeedContext(ctx, profileID, mediaID)
	if err != nil {
		return artworkResolution{}, err
	}
	result := artworkResolution{mediaFound: true}
	if path, ok := s.resolvedArtworkPath(ctx, item, kind); ok {
		result.path = path
		return result, nil
	}
	if item.Type == "track" {
		if inherited, inheritedKind, ok := s.inheritedArtworkItemContext(ctx, profileID, item, kind); ok {
			if path, ok := s.resolvedArtworkPath(ctx, inherited, inheritedKind); ok {
				result.path = path
				return result, nil
			}
		}
	}
	if kind == "poster" || kind == "thumb" {
		for _, candidate := range s.frameArtworkFallbackCandidates(accountID, item) {
			if path, ok := s.resolvedArtworkPath(ctx, candidate, "thumb"); ok {
				result.path = path
				return result, nil
			}
		}
	}
	return result, nil
}

func writeOptionalArtworkMiss(w http.ResponseWriter) {
	// This is an expected optional-resource miss, not a broken application
	// route. A cacheable empty response prevents remounted cards and rows from
	// producing a burst of identical 404s while still allowing later metadata
	// refreshes to replace the miss after the short negative-cache window.
	w.Header().Set("Cache-Control", "private, max-age=300")
	w.Header().Set("X-Portico-Optional-Resource", "artwork-unavailable")
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) handlePersonArtwork(w http.ResponseWriter, r *http.Request, user User, publicID string) {
	publicID = strings.TrimSpace(strings.TrimSuffix(strings.TrimSuffix(publicID, ".jpg"), ".svg"))
	identity, _, ok := s.personIdentityForPublicID(r.Context(), publicID)
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "Artwork route was not found.")
		return
	}
	identitySQL, args := personIdentityPredicateSQL(identity, "p")
	restrictionSQL, restrictionArgs := s.mediaVisibilityRestrictionSQL(viewerProfileID(user))
	args = append(args, restrictionArgs...)
	curationSQL, curationArgs := s.libraryCurationRestrictionSQL(r.Context(), viewerProfileID(user))
	args = append(args, curationArgs...)
	rows, err := s.queryUserRead(r.Context(), `
		SELECT COALESCE(p.image_url, '')
		FROM media_people p
		JOIN media_items m ON m.id = p.media_id
		WHERE `+identitySQL+restrictionSQL+curationSQL+`
		ORDER BY CASE WHEN trim(p.image_url) <> '' THEN 0 ELSE 1 END, p.sort_order
		LIMIT 8`, args...)
	if err != nil {
		writeError(w, http.StatusNotFound, "artwork_not_found", "Person artwork was not found.")
		return
	}
	defer rows.Close()
	imagePath := ""
	for rows.Next() {
		var candidate string
		if rows.Scan(&candidate) == nil && localArtworkFileExists(candidate) {
			imagePath = candidate
			break
		}
	}
	if imagePath == "" {
		writeError(w, http.StatusNotFound, "artwork_not_found", "Person artwork was not found.")
		return
	}
	s.serveArtworkFile(w, r, imagePath)
}

func (s *Server) getMediaArtworkSeedContext(ctx context.Context, userID, id string) (MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	id = strings.TrimSpace(id)
	if id == "" {
		return MediaItem{}, sql.ErrNoRows
	}
	where, args := s.applyMediaVisibilityRestrictionSQL(userID, "m.id = ?", []any{id})
	where, args = s.applyLibraryCurationRestrictionSQL(ctx, userID, where, args)
	var item MediaItem
	var genresJSON string
	var tagsJSON string
	var labelsJSON string
	var artworkJSON string
	err := s.queryUserRow(ctx, `
		SELECT
			m.id, COALESCE(m.metadata_revision, 0), COALESCE(m.metadata_etag, ''), COALESCE(m.library_id, ''), COALESCE(m.parent_id, ''), m.type, m.title, m.sort_title,
			COALESCE(m.content_rating, ''), COALESCE(m.duration_seconds, 0), m.art_seed,
			COALESCE(m.artwork_json, '{}'), COALESCE(m.source_url, ''),
			COALESCE(m.genres_json, '[]'), COALESCE(m.tags_json, '[]'), COALESCE(m.labels_json, '[]'),
			COALESCE(parent.title, ''), COALESCE(grandparent.id, ''), COALESCE(grandparent.title, '')
		FROM media_items m
		LEFT JOIN media_items parent ON parent.id = m.parent_id
		LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
		WHERE `+where+`
		LIMIT 1`, args...).Scan(
		&item.ID, &item.MetadataRevision, &item.MetadataETag, &item.LibraryID, &item.ParentID, &item.Type, &item.Title, &item.SortTitle,
		&item.ContentRating, &item.DurationSeconds, &item.ArtSeed, &artworkJSON, &item.SourceURL,
		&genresJSON, &tagsJSON, &labelsJSON, &item.ParentTitle, &item.GrandparentID, &item.GrandparentTitle,
	)
	if err != nil {
		return MediaItem{}, err
	}
	_ = json.Unmarshal([]byte(genresJSON), &item.Genres)
	_ = json.Unmarshal([]byte(tagsJSON), &item.Tags)
	_ = json.Unmarshal([]byte(labelsJSON), &item.Labels)
	_ = json.Unmarshal([]byte(artworkJSON), &item.Artwork)
	item.Images = imageSetFor(item.ID, item.ArtSeed, item.Title, item.Artwork)
	return item, nil
}

func (s *Server) serveResolvedArtwork(w http.ResponseWriter, r *http.Request, item MediaItem, kind string) bool {
	path, ok := s.resolvedArtworkPath(r.Context(), item, kind)
	if ok {
		s.serveArtworkFile(w, r, path)
	}
	return ok
}

func (s *Server) resolvedArtworkPath(ctx context.Context, item MediaItem, kind string) (string, bool) {
	// Keep the ordered image projection for the whole resolution attempt. This
	// request used to read media_images once for the preferred row and again for
	// the provider fallback; serveArtworkFile remains the path authorization
	// boundary.
	images := s.mediaImagesForContext(ctx, item.ID)
	for _, image := range images {
		if image.Type == kind && image.Preferred && strings.TrimSpace(image.Path) != "" {
			return image.Path, true
		}
	}
	for _, source := range artworkSourceOrder(s.artworkPolicyForItem(item)) {
		switch source {
		case "local":
			if localPath, ok := s.localArtworkPath(item, kind); ok {
				return localPath, true
			}
		case "provider":
			for _, image := range images {
				if image.Type == kind && strings.TrimSpace(image.Path) != "" {
					return image.Path, true
				}
			}
		}
	}
	if generatedPath, ok := s.generatedArtworkPath(item.ID, kind); ok {
		return generatedPath, true
	}
	return "", false
}

func (s *Server) serveFrameArtworkFallback(w http.ResponseWriter, r *http.Request, userID string, item MediaItem, kind string) bool {
	if kind != "poster" && kind != "thumb" {
		return false
	}
	for _, candidate := range s.frameArtworkFallbackCandidates(userID, item) {
		if s.serveResolvedArtwork(w, r, candidate, "thumb") {
			return true
		}
		// Missing-art generation belongs to bounded background analysis. Never
		// launch FFmpeg from an interactive image request.
	}
	return false
}

func (s *Server) frameArtworkFallbackCandidates(userID string, item MediaItem) []MediaItem {
	if isPlayableFrameArtworkType(item.Type) && strings.TrimSpace(item.SourceURL) != "" {
		return []MediaItem{item}
	}
	var items []MediaItem
	var err error
	switch item.Type {
	case "show", "anime":
		items, err = s.queryMedia(userID, `
			WHERE m.type = 'episode'
				AND m.parent_id IN (SELECT id FROM media_items WHERE parent_id = ? AND type = 'season')
			ORDER BY m.season_number ASC, m.episode_number ASC, m.index_number ASC
			LIMIT 24`, []any{item.ID})
	case "season":
		items, err = s.queryMedia(userID, `
			WHERE m.type = 'episode' AND m.parent_id = ?
			ORDER BY m.episode_number ASC, m.index_number ASC
			LIMIT 24`, []any{item.ID})
	case "collection", "playlist":
		items = nil
	}
	if err != nil {
		s.log.Warn("frame artwork fallback candidates failed", "media", item.ID, "error", err)
		return nil
	}
	candidates := make([]MediaItem, 0, len(items))
	for _, candidate := range items {
		if isPlayableFrameArtworkType(candidate.Type) && strings.TrimSpace(candidate.SourceURL) != "" {
			candidates = append(candidates, candidate)
		}
	}
	return candidates
}

func isPlayableFrameArtworkType(mediaType string) bool {
	switch mediaType {
	case "movie", "episode", "extra", "trailer", "featurette", "deleted_scene", "behind_the_scenes":
		return true
	default:
		return false
	}
}

func (s *Server) inheritedArtworkItem(userID string, item MediaItem, kind string) (MediaItem, string, bool) {
	return s.inheritedArtworkItemContext(context.Background(), userID, item, kind)
}

func (s *Server) inheritedArtworkItemContext(ctx context.Context, userID string, item MediaItem, kind string) (MediaItem, string, bool) {
	switch item.Type {
	case "track":
		if item.ParentID == "" || (kind != "poster" && kind != "thumb" && kind != "backdrop") {
			return MediaItem{}, "", false
		}
		album, err := s.getMediaArtworkSeedContext(ctx, userID, item.ParentID)
		if err != nil || album.Type != "album" {
			return MediaItem{}, "", false
		}
		return album, "poster", true
	case "season":
		if item.ParentID == "" || (kind != "poster" && kind != "backdrop") {
			return MediaItem{}, "", false
		}
		show, err := s.getMediaArtworkSeedContext(ctx, userID, item.ParentID)
		if err != nil || (show.Type != "show" && show.Type != "anime") {
			return MediaItem{}, "", false
		}
		return show, kind, true
	case "episode":
		if kind != "poster" && kind != "backdrop" {
			return MediaItem{}, "", false
		}
		showID := strings.TrimSpace(item.GrandparentID)
		if showID == "" && item.ParentID != "" {
			if season, err := s.getMediaArtworkSeedContext(ctx, userID, item.ParentID); err == nil {
				showID = strings.TrimSpace(season.ParentID)
			}
		}
		if showID == "" {
			return MediaItem{}, "", false
		}
		show, err := s.getMediaArtworkSeedContext(ctx, userID, showID)
		if err != nil || (show.Type != "show" && show.Type != "anime") {
			return MediaItem{}, "", false
		}
		return show, kind, true
	}
	return MediaItem{}, "", false
}

func (s *Server) serveArtworkFile(w http.ResponseWriter, r *http.Request, path string) {
	validatedPath, ok := s.validatedLocalContentPath(r.Context(), path)
	if !ok {
		writeError(w, http.StatusNotFound, "artwork_not_found", "Artwork was not found.")
		return
	}
	path = validatedPath
	width, height, resizeRequested, err := artworkResizeParams(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_artwork_size", err.Error())
		return
	}
	w.Header().Set("Cache-Control", "private, max-age=3600")
	if !resizeRequested {
		http.ServeFile(w, r, path)
		return
	}
	if cachePath, ok := s.resizedImageCachePath("artwork", path, width, height); ok {
		if _, err := os.Stat(cachePath); err == nil {
			w.Header().Set("X-Portico-Artwork-Variant", "resized")
			http.ServeFile(w, r, cachePath)
			return
		}
		if r.Method != http.MethodHead {
			if err := s.ensureResizedImageCache(r.Context(), path, cachePath, width, height); err == nil {
				w.Header().Set("X-Portico-Artwork-Variant", "resized")
				http.ServeFile(w, r, cachePath)
				return
			} else if !errors.Is(err, errArtworkTransformBusy) {
				s.log.Warn("cache resized artwork failed", "path", path, "cachePath", cachePath, "error", err)
			}
		}
	}
	// If a bounded transform cannot be produced, serve the validated original
	// instead of decoding/encoding again on the interactive request goroutine.
	// Keep this requested-size URL's fallback cache short so a later request can
	// pick up the exact resized variant once background capacity is available.
	w.Header().Set("Cache-Control", "private, max-age=60")
	w.Header().Set("X-Portico-Artwork-Variant", "original-fallback")
	http.ServeFile(w, r, path)
}

// validatedLocalContentPath is the final authorization boundary for files that
// were discovered on disk and later persisted in the catalog. It resolves the
// target and every admitted root at request time so a symlink introduced after
// a scan cannot turn an artwork route into an arbitrary local-file reader.
func (s *Server) validatedLocalContentPath(ctx context.Context, path string) (string, bool) {
	path = strings.TrimSpace(path)
	if path == "" {
		return "", false
	}
	resolvedPath, err := filepath.EvalSymlinks(path)
	if err != nil {
		return "", false
	}
	info, err := os.Stat(resolvedPath)
	if err != nil || !info.Mode().IsRegular() {
		return "", false
	}
	// Provider, generated, uploaded, and resized artwork live below app data.
	// Admit that common case without querying and walking every library root.
	// Both sides are still resolved for each request, so a later symlink swap
	// cannot widen access.
	if resolvedAppData, err := filepath.EvalSymlinks(s.cfg.AppDataDir); err == nil && pathInsideRoot(resolvedPath, resolvedAppData) {
		return resolvedPath, true
	}
	roots, ok := s.cachedLocalContentRoots(ctx)
	if !ok {
		return "", false
	}
	for _, root := range roots {
		resolvedRoot, err := filepath.EvalSymlinks(root)
		if err != nil {
			continue
		}
		if pathInsideRoot(resolvedPath, resolvedRoot) {
			return resolvedPath, true
		}
	}
	return "", false
}

func (s *Server) cachedLocalContentRoots(ctx context.Context) ([]string, bool) {
	s.localContentRootsMu.Lock()
	if s.localContentRootsLoaded {
		roots := append([]string(nil), s.localContentRoots...)
		s.localContentRootsMu.Unlock()
		return roots, true
	}
	generation := s.localContentRootsGeneration
	s.localContentRootsMu.Unlock()

	rows, err := s.queryUserRead(ctx, `
		SELECT path FROM library_paths WHERE trim(path) <> ''
		UNION
		SELECT path FROM libraries WHERE trim(COALESCE(path, '')) <> ''`)
	if err != nil {
		return nil, false
	}
	defer rows.Close()
	var roots []string
	for rows.Next() {
		var root string
		if rows.Scan(&root) == nil && strings.TrimSpace(root) != "" {
			roots = append(roots, strings.TrimSpace(root))
		}
	}
	if err := rows.Err(); err != nil {
		return nil, false
	}
	s.localContentRootsMu.Lock()
	if generation == s.localContentRootsGeneration {
		s.localContentRoots = append([]string(nil), roots...)
		s.localContentRootsLoaded = true
	}
	s.localContentRootsMu.Unlock()
	return roots, true
}

func (s *Server) invalidateLocalContentRoots() {
	s.localContentRootsMu.Lock()
	s.localContentRootsGeneration++
	s.localContentRoots = nil
	s.localContentRootsLoaded = false
	s.localContentRootsMu.Unlock()
}

func (s *Server) ensureResizedImageCache(ctx context.Context, sourcePath, cachePath string, width, height int) error {
	if ctx == nil {
		ctx = context.Background()
	}
	s.artworkWorkMu.Lock()
	s.ensureArtworkWorkerStateLocked()
	if existing := s.artworkTransformInFlight[cachePath]; existing != nil {
		s.artworkWorkMu.Unlock()
		select {
		case <-existing.done:
			return existing.err
		default:
			return errArtworkTransformBusy
		}
	}
	call := &artworkTransformCall{done: make(chan struct{})}
	s.artworkTransformInFlight[cachePath] = call
	s.artworkWorkMu.Unlock()
	defer func() {
		s.artworkWorkMu.Lock()
		delete(s.artworkTransformInFlight, cachePath)
		close(call.done)
		s.artworkWorkMu.Unlock()
	}()
	select {
	case s.artworkWorkSlots <- struct{}{}:
		defer func() { <-s.artworkWorkSlots }()
	case <-ctx.Done():
		call.err = ctx.Err()
		return call.err
	default:
		call.err = errArtworkTransformBusy
		return call.err
	}
	call.err = s.writeResizedImageCache(sourcePath, cachePath, width, height)
	return call.err
}

func (s *Server) ensureArtworkWorkerStateLocked() {
	if s.artworkIngestInFlight == nil {
		s.artworkIngestInFlight = map[string]*artworkIngestCall{}
	}
	if s.artworkTransformInFlight == nil {
		s.artworkTransformInFlight = map[string]*artworkTransformCall{}
	}
	if s.artworkWorkSlots == nil {
		s.artworkWorkSlots = make(chan struct{}, artworkTransformConcurrency())
	}
}

func artworkTransformConcurrency() int {
	if concurrency := runtime.GOMAXPROCS(0); concurrency < 2 {
		return 1
	}
	return 2
}

func (s *Server) resizedImageCachePath(namespace string, sourcePath string, width int, height int) (string, bool) {
	info, err := os.Stat(sourcePath)
	if err != nil || info.IsDir() {
		return "", false
	}
	namespace = safePathComponent(namespace)
	seed := strings.Join([]string{
		namespace,
		filepath.Clean(sourcePath),
		strconv.FormatInt(info.ModTime().UnixNano(), 10),
		strconv.FormatInt(info.Size(), 10),
		strconv.Itoa(width),
		strconv.Itoa(height),
	}, "\x00")
	sum := sha256.Sum256([]byte(seed))
	return filepath.Join(s.cfg.AppDataDir, "image-cache", namespace, hex.EncodeToString(sum[:])+".jpg"), true
}

func (s *Server) writeResizedImageCache(sourcePath string, cachePath string, width int, height int) error {
	file, err := os.Open(sourcePath)
	if err != nil {
		return err
	}
	defer file.Close()
	source, _, err := image.Decode(file)
	if err != nil {
		return err
	}
	resized := resizeImageNearest(source, width, height)
	if err := os.MkdirAll(filepath.Dir(cachePath), 0o700); err != nil {
		return err
	}
	temp, err := os.CreateTemp(filepath.Dir(cachePath), ".artwork-*.jpg")
	if err != nil {
		return err
	}
	tempPath := temp.Name()
	if err := jpeg.Encode(temp, resized, &jpeg.Options{Quality: 88}); err != nil {
		_ = temp.Close()
		_ = os.Remove(tempPath)
		return err
	}
	if err := temp.Close(); err != nil {
		_ = os.Remove(tempPath)
		return err
	}
	if err := os.Chmod(tempPath, 0o600); err != nil {
		_ = os.Remove(tempPath)
		return err
	}
	if err := os.Rename(tempPath, cachePath); err != nil {
		_ = os.Remove(tempPath)
		return err
	}
	return nil
}

func artworkResizeParams(r *http.Request) (int, int, bool, error) {
	query := r.URL.Query()
	rawWidth := strings.TrimSpace(query.Get("width"))
	rawHeight := strings.TrimSpace(query.Get("height"))
	if rawWidth == "" && rawHeight == "" {
		return 0, 0, false, nil
	}
	parse := func(label, value string) (int, error) {
		if value == "" {
			return 0, nil
		}
		parsed, err := strconv.Atoi(value)
		if err != nil || parsed < 32 || parsed > 2000 {
			return 0, fmt.Errorf("%s must be between 32 and 2000 pixels", label)
		}
		return parsed, nil
	}
	width, err := parse("width", rawWidth)
	if err != nil {
		return 0, 0, true, err
	}
	height, err := parse("height", rawHeight)
	if err != nil {
		return 0, 0, true, err
	}
	width, height, ok := canonicalArtworkResize(width, height)
	if !ok {
		return 0, 0, true, errors.New("choose a supported square, poster, or widescreen artwork size")
	}
	return width, height, true, nil
}

var canonicalArtworkResizePairs = [][2]int{
	// Profile, person, and compact icon surfaces.
	{64, 64}, {96, 96}, {192, 192}, {384, 384},
	// Poster cards used across Web and native clients.
	{160, 240}, {320, 480}, {480, 720},
	// Backdrops and thumbnail rails.
	{320, 180}, {640, 360}, {960, 540}, {1280, 720},
}

var canonicalArtworkSingleDimensions = []int{64, 96, 160, 192, 320, 384, 480, 640, 960, 1280}

func canonicalArtworkResize(width, height int) (int, int, bool) {
	if width == 0 || height == 0 {
		value := width
		if value == 0 {
			value = height
		}
		nearest := nearestCanonicalDimension(value, canonicalArtworkSingleDimensions)
		if nearest == 0 {
			return 0, 0, false
		}
		if width == 0 {
			return 0, nearest, true
		}
		return nearest, 0, true
	}
	ratio := float64(width) / float64(height)
	bestDistance := math.MaxFloat64
	bestWidth, bestHeight := 0, 0
	for _, pair := range canonicalArtworkResizePairs {
		pairRatio := float64(pair[0]) / float64(pair[1])
		ratioDistance := math.Abs(ratio - pairRatio)
		if ratioDistance > 0.08 {
			continue
		}
		sizeDistance := math.Abs(float64(width-pair[0])) + math.Abs(float64(height-pair[1]))
		if sizeDistance < bestDistance {
			bestDistance, bestWidth, bestHeight = sizeDistance, pair[0], pair[1]
		}
	}
	return bestWidth, bestHeight, bestWidth > 0
}

func nearestCanonicalDimension(value int, choices []int) int {
	if value <= 0 || len(choices) == 0 {
		return 0
	}
	best := choices[0]
	bestDistance := absInt(value - best)
	for _, candidate := range choices[1:] {
		if distance := absInt(value - candidate); distance < bestDistance {
			best, bestDistance = candidate, distance
		}
	}
	return best
}

func resizeImageNearest(source image.Image, width, height int) image.Image {
	bounds := source.Bounds()
	sourceWidth := bounds.Dx()
	sourceHeight := bounds.Dy()
	if sourceWidth <= 0 || sourceHeight <= 0 {
		return source
	}
	if width <= 0 && height <= 0 {
		return source
	}
	if width <= 0 {
		width = max(1, int(math.Round(float64(sourceWidth)*float64(height)/float64(sourceHeight))))
	}
	if height <= 0 {
		height = max(1, int(math.Round(float64(sourceHeight)*float64(width)/float64(sourceWidth))))
	}
	width = max(1, width)
	height = max(1, height)
	target := image.NewRGBA(image.Rect(0, 0, width, height))
	for y := 0; y < height; y++ {
		sourceY := bounds.Min.Y + min(sourceHeight-1, y*sourceHeight/height)
		for x := 0; x < width; x++ {
			sourceX := bounds.Min.X + min(sourceWidth-1, x*sourceWidth/width)
			target.Set(x, y, source.At(sourceX, sourceY))
		}
	}
	return target
}

func providerArtworkURL(artwork map[string]string, kind string) (string, bool) {
	switch artwork["source"] {
	case "tmdb":
		path := ""
		switch kind {
		case "poster":
			path = artwork["posterPath"]
		case "backdrop":
			path = artwork["backdropPath"]
		case "thumb":
			path = firstNonEmpty(artwork["thumbPath"], artwork["backdropPath"], artwork["posterPath"])
		}
		path = strings.TrimSpace(path)
		if path == "" || !strings.HasPrefix(path, "/") || strings.Contains(path, "..") {
			return "", false
		}
		size := "w780"
		if kind == "backdrop" || kind == "thumb" {
			size = "w1280"
		}
		return "https://image.tmdb.org/t/p/" + size + path, true
	case "tvdb":
		raw := strings.TrimSpace(artwork["posterURL"])
		parsed, err := url.Parse(raw)
		if err != nil || parsed.Scheme != "https" || !strings.EqualFold(parsed.Hostname(), "artworks.thetvdb.com") || parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" {
			return "", false
		}
		return parsed.String(), true
	case "musicbrainz":
		if id := strings.TrimSpace(artwork["releaseID"]); id != "" {
			if strings.ContainsAny(id, `/\?&#`) {
				return "", false
			}
			return "https://coverartarchive.org/release/" + url.PathEscape(id) + "/front", true
		}
		if id := strings.TrimSpace(artwork["releaseGroupID"]); id != "" {
			if strings.ContainsAny(id, `/\?&#`) {
				return "", false
			}
			return "https://coverartarchive.org/release-group/" + url.PathEscape(id) + "/front", true
		}
		return "", false
	case "anilist":
		remoteURL := ""
		switch kind {
		case "poster":
			remoteURL = artwork["posterURL"]
		case "backdrop", "thumb":
			remoteURL = firstNonEmpty(artwork["backdropURL"], artwork["posterURL"])
		}
		parsed, err := url.Parse(strings.TrimSpace(remoteURL))
		if err != nil || parsed.Scheme != "https" || parsed.Host == "" {
			return "", false
		}
		return parsed.String(), true
	default:
		return "", false
	}
}

func (s *Server) proxyProviderArtwork(w http.ResponseWriter, r *http.Request, remoteURL string) {
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, remoteURL, nil)
	if err != nil {
		writeError(w, http.StatusBadGateway, "artwork_provider_failed", "Provider artwork could not be requested.")
		return
	}
	req.Header.Set("Accept", "image/avif,image/webp,image/apng,image/*,*/*;q=0.8")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		writeError(w, http.StatusBadGateway, "artwork_provider_failed", "Provider artwork could not be loaded.")
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		writeError(w, http.StatusBadGateway, "artwork_provider_failed", "Provider artwork was unavailable.")
		return
	}
	contentType := resp.Header.Get("Content-Type")
	if contentType != "" && !strings.HasPrefix(contentType, "image/") {
		writeError(w, http.StatusBadGateway, "artwork_provider_failed", "Provider artwork was not an image.")
		return
	}
	if contentType != "" {
		w.Header().Set("Content-Type", contentType)
	}
	w.Header().Set("Cache-Control", "private, max-age=86400")
	_, _ = io.Copy(w, io.LimitReader(resp.Body, 20<<20))
}

func (s *Server) handleStatic(w http.ResponseWriter, r *http.Request) {
	if isMaintenanceAPIPath(r.URL.Path) {
		writeError(w, http.StatusNotFound, "not_found", "API route was not found.")
		return
	}
	if r.URL.Path == "/portico-config.js" {
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write([]byte(`window.__PORTICO_CONFIG__ = {
  mode: "bundled",
  apiBaseUrl: "",
  hostedApiBaseUrl: "https://api.getportico.tv"
};
`))
		return
	}
	target, targetOK := webDistTarget(s.cfg.WebDistDir, r.URL.Path)
	if targetOK {
		if info, err := os.Stat(target); err == nil && !info.IsDir() {
			if filepath.Base(target) == "index.html" {
				w.Header().Set("Cache-Control", "no-cache")
			}
			http.ServeFile(w, r, target)
			return
		}
	}
	if isWebAssetRequest(r.URL.Path) {
		w.Header().Set("Cache-Control", "no-store")
		writeError(w, http.StatusNotFound, "asset_not_found", "Static asset was not found.")
		return
	}

	indexPath, indexOK := webDistTarget(s.cfg.WebDistDir, "/index.html")
	if indexOK {
		if _, err := os.Stat(indexPath); err == nil {
			w.Header().Set("Cache-Control", "no-cache")
			http.ServeFile(w, r, indexPath)
			return
		}
	}

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("Portico API is running. Start the web client with `cd web && npm run dev`."))
}

// webDistTarget converts a URL path into a path below the packaged web
// directory. It rejects traversal before joining, including platform-native
// separators, so the DB-independent maintenance responder cannot become a
// file disclosure primitive.
func webDistTarget(webDir, requestPath string) (string, bool) {
	webDir = strings.TrimSpace(webDir)
	if webDir == "" || strings.ContainsRune(requestPath, '\x00') {
		return "", false
	}
	clean := path.Clean("/" + strings.TrimPrefix(requestPath, "/"))
	relative := strings.TrimPrefix(clean, "/")
	if relative == "" || relative == "." {
		relative = "index.html"
	}
	if strings.ContainsRune(relative, '\\') || filepath.IsAbs(relative) {
		return "", false
	}
	for _, component := range strings.Split(relative, "/") {
		if component == ".." || component == "" {
			return "", false
		}
	}
	root, err := filepath.Abs(webDir)
	if err != nil {
		return "", false
	}
	target := filepath.Join(root, filepath.FromSlash(relative))
	rel, err := filepath.Rel(root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", false
	}
	return target, true
}

func isWebAssetRequest(requestPath string) bool {
	cleanPath := path.Clean("/" + strings.TrimPrefix(requestPath, "/"))
	if strings.HasPrefix(cleanPath, "/assets/") || strings.HasPrefix(cleanPath, "/brand/") {
		return true
	}
	switch strings.ToLower(filepath.Ext(cleanPath)) {
	case ".css", ".gif", ".html", ".ico", ".jpeg", ".jpg", ".js", ".json", ".map", ".mjs", ".png", ".svg", ".ttf", ".wasm", ".webp", ".woff", ".woff2":
		return true
	default:
		return false
	}
}

func (s *Server) createSession(w http.ResponseWriter, r *http.Request, userID string) (string, error) {
	return s.createSessionForProvider(w, r, userID, "local")
}

func (s *Server) createSessionForProvider(w http.ResponseWriter, r *http.Request, userID string, provider string) (string, error) {
	return s.createSessionForProviderWithOptions(w, r, userID, provider, false)
}

func (s *Server) createSessionForProviderWithOptions(w http.ResponseWriter, r *http.Request, userID string, provider string, trustDevice bool) (string, error) {
	return s.createSessionForProviderWithSessionOptions(w, r, userID, provider, sessionCreateOptions{TrustDevice: trustDevice})
}

func (s *Server) createSessionForProviderWithSessionOptions(w http.ResponseWriter, r *http.Request, userID string, provider string, options sessionCreateOptions) (string, error) {
	ctx := context.Background()
	if r != nil {
		ctx = r.Context()
	}
	provider = normalizeAuthProvider(provider)
	var disabledAt string
	if err := s.queryUserRow(ctx, `SELECT COALESCE(disabled_at, '') FROM users WHERE id = ?`, userID).Scan(&disabledAt); err != nil {
		return "", err
	}
	if disabledAt != "" {
		return "", errBrowserAccountDisabled
	}
	requestedProfileID := strings.TrimSpace(options.ProfileID)
	if requestedProfileID == "" {
		requestedProfileID = userID
	}
	token := randomToken()
	hash := hashToken(token)
	now := time.Now().UTC()
	expires := now.Add(s.browserSessionTTLContext(ctx))
	deviceID := strings.TrimSpace(options.BoundDeviceID)
	if deviceID == "" {
		var err error
		deviceID, err = s.upsertDeviceForRequest(r, userID)
		if err != nil {
			return "", err
		}
	} else {
		var count int
		if err := s.queryUserRow(ctx, `
			SELECT COUNT(*) FROM devices
			WHERE id = ? AND user_id = ? AND COALESCE(revoked_at, '') = ''`,
			deviceID, userID).Scan(&count); err != nil || count != 1 {
			return "", errInvalidProfileSelectionGrant
		}
	}
	if options.TrustDevice {
		_, _ = s.execUserWrite(ctx, `UPDATE devices SET trusted = 1, last_seen_at = ? WHERE id = ? AND revoked_at = ''`, now.Format(time.RFC3339), deviceID)
	}
	if s.requireTrustedDevicesContext(ctx) && !s.deviceTrustedContext(ctx, deviceID) {
		return "", errDeviceNotTrusted
	}
	if !s.userDevicePolicyAllowsContext(ctx, userID, deviceID) {
		return "", errDeviceNotAllowed
	}
	if !s.userAccessScheduleAllowsNowContext(ctx, userID, now) {
		return "", errAccessSchedule
	}
	var installationID string
	_ = s.queryUserRow(ctx, `SELECT COALESCE(installation_id, '') FROM devices WHERE id = ? AND user_id = ?`, deviceID, userID).Scan(&installationID)
	err := s.withUserTxTagged(ctx, []string{"sessions", "profile_selection_grants"}, func(tx *sql.Tx) error {
		if expected := strings.TrimSpace(options.ExpectedLocalPasswordHash); expected != "" {
			var currentPasswordHash string
			if err := tx.QueryRow(`SELECT COALESCE(password_hash, '') FROM users WHERE id = ? AND COALESCE(disabled_at, '') = ''`, userID).Scan(&currentPasswordHash); err != nil || currentPasswordHash != expected {
				return errPasswordCredentialChanged
			}
		}
		profileID := requestedProfileID
		if grant := strings.TrimSpace(options.ProfileSelectionGrant); grant != "" {
			principal, err := s.consumeProfileSelectionGrantForPurposeTx(tx, grant, userID, provider, options.ProfileSelectionPurpose, deviceID, installationID, now)
			if err != nil {
				return err
			}
			if requestedProfileID != userID && requestedProfileID != principal.ProfileID {
				return errInvalidProfileSelectionGrant
			}
			profileID = principal.ProfileID
		} else {
			if profileID != userID {
				return errInvalidProfileSelectionGrant
			}
			required, err := profileRequiresSelectionGrantTx(tx, userID, profileID)
			if err != nil {
				return err
			}
			if required {
				return errInvalidProfileSelectionGrant
			}
			if _, err := resolveRequestPrincipalTx(tx, userID, profileID); err != nil {
				return err
			}
		}
		if err := enforceActiveSessionLimitTx(tx, userID, now); err != nil {
			return err
		}
		profileIdentityID := ""
		_ = tx.QueryRow(`SELECT id FROM profile_identities WHERE profile_id = ? AND provider = ? ORDER BY created_at LIMIT 1`, userID, provider).Scan(&profileIdentityID)
		_, err := tx.Exec(`INSERT INTO sessions (id, user_id, profile_id, profile_identity_id, auth_provider, device_id, token_hash, expires_at, created_at, last_seen_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			randomID("sess"), userID, profileID, profileIdentityID, provider, deviceID, hash, expires.Format(time.RFC3339), now.Format(time.RFC3339), now.Format(time.RFC3339))
		return err
	})
	if err != nil {
		return "", err
	}
	s.setSessionCookie(ctx, w, s.sessionCookieNameContext(ctx), token, expires)
	return token, nil
}

func normalizeAuthProvider(provider string) string {
	switch strings.ToLower(strings.TrimSpace(provider)) {
	case "portico":
		return "portico"
	case "local":
		return "local"
	default:
		return ""
	}
}

func (s *Server) createQuickConnectRequest(secret string, installationID string, device string, app string, platform string, userAgent string, clientIP string, now time.Time, expires time.Time) (string, error) {
	for attempt := 0; attempt < quickConnectCodeAttempts; attempt++ {
		code, err := randomQuickConnectCode(s.quickConnectEntropyReader())
		if err != nil {
			return "", fmt.Errorf("%w: %v", errQuickConnectEntropyUnavailable, err)
		}
		requestID, err := randomQuickConnectRequestID(s.quickConnectEntropyReader())
		if err != nil {
			return "", fmt.Errorf("%w: %v", errQuickConnectEntropyUnavailable, err)
		}
		nowValue := now.Format(time.RFC3339)
		err = s.withUserTxTagged(context.Background(), []string{"quick-connect"}, func(tx *sql.Tx) error {
			if _, err := tx.Exec(`
				UPDATE quick_connect_requests
				SET status = 'expired', updated_at = ?
				WHERE code = ? AND status IN ('pending', 'approved') AND expires_at <= ?`,
				nowValue, code, nowValue); err != nil {
				return err
			}
			_, err := tx.Exec(`
				INSERT INTO quick_connect_requests (id, code, secret_hash, status, installation_id, device_name, app, platform, user_agent, client_ip, expires_at, created_at, updated_at)
				VALUES (?, ?, ?, 'pending', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
				requestID, code, hashToken(secret), installationID, device, app, platform, strings.TrimSpace(userAgent), clientIP,
				expires.Format(time.RFC3339), nowValue, nowValue)
			return err
		})
		if err == nil {
			return code, nil
		}
		if !isQuickConnectCodeConflict(err) {
			return "", err
		}
	}
	return "", errQuickConnectCodeSpaceBusy
}

func (s *Server) quickConnectStatus(secret string) (QuickConnectStatusResponse, error) {
	hash := hashToken(strings.TrimSpace(secret))
	var response QuickConnectStatusResponse
	if hash == hashToken("") {
		return response, sql.ErrNoRows
	}
	var status string
	var expiresAt string
	if err := s.queryUserRow(context.Background(), `
		SELECT status, device_name, app, platform, expires_at
		FROM quick_connect_requests
		WHERE secret_hash = ?`, hash).Scan(&status, &response.Device, &response.App, &response.Platform, &expiresAt); err != nil {
		return response, err
	}
	if quickConnectExpired(expiresAt) && status == "pending" {
		status = "expired"
	}
	response.Status = status
	response.ExpiresAt = expiresAt
	return response, nil
}

func (s *Server) pendingQuickConnectRequests() ([]QuickConnectRequest, error) {
	now := time.Now().UTC().Format(time.RFC3339)
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id, code, device_name, app, platform, client_ip, expires_at, created_at
		FROM quick_connect_requests
		WHERE status = 'pending' AND expires_at > ?
		ORDER BY created_at ASC`, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	requests := []QuickConnectRequest{}
	for rows.Next() {
		var request QuickConnectRequest
		if err := rows.Scan(&request.ID, &request.Code, &request.Device, &request.App, &request.Platform, &request.ClientIP, &request.ExpiresAt, &request.CreatedAt); err != nil {
			return nil, err
		}
		request.ProtocolVersion = quickConnectProtocolForCode(request.Code)
		requests = append(requests, request)
	}
	return requests, rows.Err()
}

func (s *Server) updateQuickConnectStatus(code string, userID string, status string) (QuickConnectRequest, error) {
	code = quickConnectCodeForLookup(code)
	if code == "" || (status != "approved" && status != "denied") {
		return QuickConnectRequest{}, sql.ErrNoRows
	}
	now := time.Now().UTC().Format(time.RFC3339)
	result, err := s.execUserWrite(context.Background(), `
		UPDATE quick_connect_requests
		SET status = ?, user_id = CASE WHEN ? = 'approved' THEN ? ELSE user_id END, updated_at = ?
		WHERE code = ? AND status = 'pending' AND expires_at > ?`,
		status, status, userID, now, code, now)
	if err != nil {
		return QuickConnectRequest{}, err
	}
	if affected, err := result.RowsAffected(); err == nil && affected == 0 {
		return QuickConnectRequest{}, sql.ErrNoRows
	}
	var request QuickConnectRequest
	err = s.queryUserRow(context.Background(), `
		SELECT id, code, device_name, app, platform, client_ip, expires_at, created_at
		FROM quick_connect_requests
		WHERE code = ?
		ORDER BY updated_at DESC
		LIMIT 1`, code).Scan(&request.ID, &request.Code, &request.Device, &request.App, &request.Platform, &request.ClientIP, &request.ExpiresAt, &request.CreatedAt)
	request.ProtocolVersion = quickConnectProtocolForCode(request.Code)
	return request, err
}

type quickConnectConsumeResult struct {
	RequestID      string
	UserID         string
	InstallationID string
	Device         string
	App            string
	Platform       string
	Status         string
	ExpiresAt      string
	ConsumedAt     string
	ReceiptID      string
}

func (s *Server) quickConnectExchangeState(ctx context.Context, secretHash string) (quickConnectConsumeResult, error) {
	var result quickConnectConsumeResult
	err := s.queryUserRow(ctx, `
		SELECT id, user_id, installation_id, device_name, app, platform, status, expires_at, consumed_at, native_refresh_token_id
		FROM quick_connect_requests WHERE secret_hash = ?`, secretHash).Scan(
		&result.RequestID, &result.UserID, &result.InstallationID, &result.Device, &result.App, &result.Platform,
		&result.Status, &result.ExpiresAt, &result.ConsumedAt, &result.ReceiptID,
	)
	if errors.Is(err, sql.ErrNoRows) {
		return result, errQuickConnectNotFound
	}
	return result, err
}

func validateQuickConnectExchangeState(result quickConnectConsumeResult, now time.Time) error {
	if result.Status == "consumed" {
		if result.ReceiptID != "" && nativeExchangeReceiptRecoverable(result.ConsumedAt, now) {
			return nil
		}
		return errQuickConnectAlreadyUsed
	}
	expiresAt, err := parseCredentialTime(result.ExpiresAt)
	if err != nil || !expiresAt.After(now) {
		return errQuickConnectExpired
	}
	if result.Status != "approved" || strings.TrimSpace(result.UserID) == "" {
		return errQuickConnectNotApproved
	}
	return nil
}

func (s *Server) exchangeQuickConnectCredentials(r *http.Request, secret string) (quickConnectConsumeResult, NativeSessionCredentials, error) {
	hash := hashToken(strings.TrimSpace(secret))
	if hash == hashToken("") {
		return quickConnectConsumeResult{}, NativeSessionCredentials{}, errQuickConnectNotFound
	}
	ctx := r.Context()
	now := time.Now().UTC()
	result, err := s.quickConnectExchangeState(ctx, hash)
	if err != nil {
		return result, NativeSessionCredentials{}, err
	}
	if err := validateQuickConnectExchangeState(result, now); err != nil {
		return result, NativeSessionCredentials{}, err
	}
	if result.Status == "consumed" {
		record, err := s.nativeRefreshByIDContext(ctx, result.ReceiptID)
		if err != nil {
			return result, NativeSessionCredentials{}, errInvalidNativeRefreshToken
		}
		credentials, err := s.nativeCredentialReceiptResponse(ctx, result.UserID, record)
		return result, credentials, err
	}
	user, err := s.getUser(result.UserID)
	if err != nil {
		return result, NativeSessionCredentials{}, err
	}
	var draft nativeCredentialDraft
	created := false
	err = s.withUserTxTagged(ctx, []string{"quick-connect", "sessions", "devices"}, func(tx *sql.Tx) error {
		var current quickConnectConsumeResult
		if err := tx.QueryRow(`
			SELECT id, user_id, installation_id, device_name, app, platform, status, expires_at, consumed_at, native_refresh_token_id
			FROM quick_connect_requests WHERE secret_hash = ?`, hash).Scan(
			&current.RequestID, &current.UserID, &current.InstallationID, &current.Device, &current.App, &current.Platform,
			&current.Status, &current.ExpiresAt, &current.ConsumedAt, &current.ReceiptID,
		); err != nil {
			return errQuickConnectNotFound
		}
		if err := validateQuickConnectExchangeState(current, now); err != nil {
			return err
		}
		result = current
		if current.Status == "consumed" {
			if err := localNativeUserActiveTx(tx, current.UserID); err != nil {
				return err
			}
			draft.Record, err = nativeRefreshByIDTx(tx, current.ReceiptID)
			return err
		}
		draft, err = s.prepareNativeExchangeCredentialTx(tx, r, user, "local", nativeDeviceDescriptor{
			InstallationID: current.InstallationID, Name: current.Device, App: current.App, Platform: current.Platform, Trust: true,
		}, now)
		if err != nil {
			return err
		}
		terminalAt := now.Format(time.RFC3339Nano)
		update, err := tx.Exec(`
			UPDATE quick_connect_requests
			SET status = 'consumed', consumed_at = ?, updated_at = ?, native_refresh_token_id = ?
			WHERE id = ? AND status = 'approved' AND native_refresh_token_id = '' AND expires_at > ?`,
			terminalAt, terminalAt, draft.Record.ID, current.RequestID, terminalAt)
		if err != nil {
			return err
		}
		if affected, err := update.RowsAffected(); err != nil || affected != 1 {
			return errQuickConnectAlreadyUsed
		}
		if err := insertNativeCredentialTx(tx, draft); err != nil {
			return err
		}
		result.Status, result.ConsumedAt, result.ReceiptID = "consumed", terminalAt, draft.Record.ID
		created = true
		return nil
	})
	if err != nil {
		return result, NativeSessionCredentials{}, err
	}
	if created {
		if err := s.runNativeExchangeAfterCommit(); err != nil {
			return result, NativeSessionCredentials{}, err
		}
	}
	credentials, err := s.nativeCredentialReceiptResponse(ctx, result.UserID, draft.Record)
	return result, credentials, err
}

func (s *Server) quickConnectApprovalLinks(r *http.Request) (string, string) {
	origin := s.requestPublicOrigin(r)
	if origin == "" {
		return "", ""
	}
	approvalURL := origin + "/#/settings/devices"
	deepLinkURL := "portico://quick-connect?server=" + url.QueryEscape(origin)
	return approvalURL, deepLinkURL
}

func (s *Server) requestPublicOrigin(r *http.Request) string {
	if r == nil {
		return ""
	}
	host := strings.TrimSpace(r.Host)
	if s.requestFromTrustedProxy(r) {
		if forwardedHost := strings.TrimSpace(strings.Split(r.Header.Get("X-Forwarded-Host"), ",")[0]); forwardedHost != "" {
			host = forwardedHost
		}
	}
	if host == "" || strings.ContainsAny(host, "\r\n\t /\\") {
		return ""
	}
	return s.requestScheme(r) + "://" + host
}

type requestTransportSecureKey struct{}

func (s *Server) requestTransport(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		secure := r.TLS != nil
		if !secure && s.requestFromTrustedProxy(r) {
			secure = strings.EqualFold(strings.TrimSpace(strings.Split(r.Header.Get("X-Forwarded-Proto"), ",")[0]), "https")
		}
		ctx := context.WithValue(r.Context(), requestTransportSecureKey{}, secure)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func (s *Server) secureCookieForContext(ctx context.Context) bool {
	if s.cfg.CookieSecure {
		return true
	}
	if ctx == nil {
		return true
	}
	if secure, ok := ctx.Value(requestTransportSecureKey{}).(bool); ok {
		return secure
	}
	// Cookie issuance outside the request middleware must fail closed. The
	// normal HTTP path carries an explicit false value; an absent value is
	// background/setup work and must never downgrade a browser credential.
	return true
}

func (s *Server) requestScheme(r *http.Request) string {
	if r != nil && s.requestFromTrustedProxy(r) {
		if forwarded := strings.TrimSpace(strings.Split(r.Header.Get("X-Forwarded-Proto"), ",")[0]); forwarded == "http" || forwarded == "https" {
			return forwarded
		}
	}
	if r != nil && r.TLS != nil {
		return "https"
	}
	return "http"
}

func (s *Server) requestFromTrustedProxy(r *http.Request) bool {
	if r == nil || len(s.cfg.TrustedProxyCIDRs) == 0 {
		return false
	}
	host, _, err := net.SplitHostPort(strings.TrimSpace(r.RemoteAddr))
	if err != nil {
		host = strings.TrimSpace(r.RemoteAddr)
	}
	addr, err := netip.ParseAddr(strings.Trim(host, "[]"))
	if err != nil {
		return false
	}
	for _, prefix := range s.cfg.TrustedProxyCIDRs {
		if prefix.Contains(addr) {
			return true
		}
	}
	return false
}

func quickConnectExpired(expiresAt string) bool {
	expires, err := time.Parse(time.RFC3339, expiresAt)
	return err != nil || !time.Now().UTC().Before(expires)
}

func cleanQuickConnectLabel(value string, fallback string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		value = strings.TrimSpace(fallback)
	}
	if value == "" {
		return "Unknown device"
	}
	if len(value) > 80 {
		value = value[:80]
	}
	return value
}

func (s *Server) profileIdentityIDForProvider(profileID string, provider string) string {
	return s.profileIdentityIDForProviderContext(context.Background(), profileID, provider)
}

func (s *Server) profileIdentityIDForProviderContext(ctx context.Context, profileID string, provider string) string {
	if ctx == nil {
		ctx = context.Background()
	}
	provider = normalizeAuthProvider(provider)
	var identityID string
	if err := s.queryUserRow(ctx, `SELECT id FROM profile_identities WHERE profile_id = ? AND provider = ? LIMIT 1`, profileID, provider).Scan(&identityID); err == nil {
		return identityID
	}
	if err := s.queryUserRow(ctx, `SELECT id FROM profile_identities WHERE profile_id = ? ORDER BY CASE provider WHEN ? THEN 0 WHEN 'local' THEN 1 ELSE 2 END LIMIT 1`, profileID, provider).Scan(&identityID); err == nil {
		return identityID
	}
	return ""
}

func (s *Server) enrichUserAuthContext(user *User, provider string) {
	s.enrichUserAuthContextContext(context.Background(), user, provider)
}

func (s *Server) enrichUserAuthContextContext(ctx context.Context, user *User, provider string) {
	if user == nil {
		return
	}
	if ctx == nil {
		ctx = context.Background()
	}
	user.AccountID = user.ID
	if strings.TrimSpace(user.ProfileID) == "" {
		user.ProfileID = user.ID
	}
	if strings.TrimSpace(provider) == "" {
		user.AuthProvider = defaultAuthProviderForUser(*user)
	} else {
		user.AuthProvider = normalizeAuthProvider(provider)
	}
	user.ProfileIdentityID = s.profileIdentityIDForProviderContext(ctx, user.ProfileID, user.AuthProvider)
	s.enrichUserSignInMethodsContext(ctx, user)
}

func defaultAuthProviderForUser(user User) string {
	if user.PorticoUserID != "" || user.AuthOrigin == "portico" {
		return "portico"
	}
	return "local"
}

func (s *Server) enrichUserSignInMethods(user *User) {
	s.enrichUserSignInMethodsContext(context.Background(), user)
}

func (s *Server) enrichUserSignInMethodsContext(ctx context.Context, user *User) {
	if user == nil {
		return
	}
	if ctx == nil {
		ctx = context.Background()
	}
	profileID := strings.TrimSpace(user.ProfileID)
	if profileID == "" {
		profileID = user.ID
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT DISTINCT pi.provider
		FROM profile_identities pi
		LEFT JOIN local_credentials lc ON lc.profile_identity_id = pi.id AND lc.revoked_at = ''
		WHERE pi.profile_id = ?
			AND (pi.provider <> 'local' OR lc.id IS NOT NULL)
		ORDER BY CASE pi.provider WHEN 'portico' THEN 0 WHEN 'local' THEN 1 ELSE 2 END`, profileID)
	if err != nil {
		user.SignInMethods = fallbackSignInMethods(*user)
		return
	}
	defer rows.Close()
	methods := []SignInMethod{}
	for rows.Next() {
		var provider string
		if err := rows.Scan(&provider); err != nil {
			continue
		}
		methods = append(methods, SignInMethod{Provider: provider, Label: authProviderLabel(provider)})
	}
	if len(methods) == 0 {
		methods = fallbackSignInMethods(*user)
	}
	if user.PorticoUserID != "" || user.AuthOrigin == "portico" {
		filtered := []SignInMethod{}
		for _, method := range methods {
			if method.Provider == "portico" {
				filtered = append(filtered, method)
			}
		}
		if len(filtered) > 0 {
			methods = filtered
		}
	}
	user.SignInMethods = methods
}

func fallbackSignInMethods(user User) []SignInMethod {
	methods := []SignInMethod{}
	if user.PorticoUserID != "" || user.AuthOrigin == "portico" {
		methods = append(methods, SignInMethod{Provider: "portico", Label: authProviderLabel("portico")})
	}
	if user.PorticoUserID == "" && (user.HasLocalPassword || user.AuthOrigin == "local") {
		methods = append(methods, SignInMethod{Provider: "local", Label: authProviderLabel("local")})
	}
	if len(methods) == 0 {
		methods = append(methods, SignInMethod{Provider: "local", Label: authProviderLabel("local")})
	}
	return methods
}

func authProviderLabel(provider string) string {
	switch normalizeAuthProvider(provider) {
	case "portico":
		return "Portico account"
	default:
		return "This Server"
	}
}

func (s *Server) sessionCookieName() string {
	return s.sessionCookieNameContext(context.Background())
}

func (s *Server) browserSessionTTLContext(ctx context.Context) time.Duration {
	// Authentication lifetime belongs to the device/account, not the route.
	// A move between a verified LAN address and the public address must not
	// shorten the session or force another sign-in.
	return browserSessionTTL
}

func (s *Server) browserSessionMayRoll(ctx context.Context) bool {
	return true
}

func (s *Server) sessionCookieTransportSuffix(ctx context.Context) string {
	if !s.secureCookieForContext(ctx) {
		return "lan"
	}
	return "remote"
}

func (s *Server) sessionCookieNameContext(ctx context.Context) string {
	names := s.sessionCookieNamesContext(ctx)
	if len(names) == 0 {
		return sessionCookieName + "_" + s.sessionCookieTransportSuffix(ctx)
	}
	return names[0]
}

func (s *Server) sessionCookieNames() []string {
	return s.sessionCookieNamesContext(context.Background())
}

func (s *Server) sessionCookieNamesContext(ctx context.Context) []string {
	if ctx == nil {
		ctx = context.Background()
	}
	now := time.Now()
	s.sessionCookieMu.Lock()
	if len(s.sessionCookieNamesCache) > 0 && now.Before(s.sessionCookieCacheUntil) {
		baseName := s.sessionCookieNamesCache[0]
		s.sessionCookieMu.Unlock()
		return []string{baseName + "_" + s.sessionCookieTransportSuffix(ctx)}
	}
	s.sessionCookieMu.Unlock()

	baseName := sessionCookieName
	identity, err := s.systemIdentityContext(ctx)
	if err == nil {
		if suffix := cookieNameSuffix(identity.ServerID); suffix != "" {
			baseName += "_" + suffix
		}
	}
	name := baseName + "_" + s.sessionCookieTransportSuffix(ctx)
	if err == nil {
		s.sessionCookieMu.Lock()
		// Cache only the installation-scoped base. The transport suffix is
		// request-specific and must never be shared between HTTP and HTTPS.
		s.sessionCookieNamesCache = []string{baseName}
		s.sessionCookieCacheUntil = now.Add(5 * time.Minute)
		s.sessionCookieMu.Unlock()
	}
	return []string{name}
}

func (s *Server) requestSessionCookies(r *http.Request) []*http.Cookie {
	if r == nil {
		return nil
	}
	var cookies []*http.Cookie
	for _, name := range s.sessionCookieNamesContext(r.Context()) {
		cookie, err := r.Cookie(name)
		if err == nil && cookie.Value != "" {
			cookies = append(cookies, cookie)
		}
	}
	return cookies
}

func (s *Server) invalidateSessionCookieCache() {
	s.sessionCookieMu.Lock()
	s.sessionCookieNamesCache = nil
	s.sessionCookieCacheUntil = time.Time{}
	s.sessionCookieMu.Unlock()
}

func (s *Server) setSessionCookie(ctx context.Context, w http.ResponseWriter, name, token string, expires time.Time) {
	http.SetCookie(w, &http.Cookie{
		Name:     name,
		Value:    token,
		Path:     "/",
		Expires:  expires,
		HttpOnly: true,
		Secure:   s.secureCookieForContext(ctx),
		SameSite: http.SameSiteLaxMode,
	})
}

func (s *Server) clearSessionCookies(ctx context.Context, w http.ResponseWriter, names ...string) {
	if len(names) == 0 {
		names = s.sessionCookieNamesContext(ctx)
	}
	seen := map[string]bool{}
	for _, name := range names {
		if name == "" || seen[name] {
			continue
		}
		seen[name] = true
		http.SetCookie(w, &http.Cookie{
			Name:     name,
			Value:    "",
			Path:     "/",
			MaxAge:   -1,
			HttpOnly: true,
			Secure:   s.secureCookieForContext(ctx),
			SameSite: http.SameSiteLaxMode,
		})
	}
}

func cookieNameSuffix(value string) string {
	var builder strings.Builder
	for _, char := range strings.ToLower(value) {
		switch {
		case char >= 'a' && char <= 'z':
			builder.WriteRune(char)
		case char >= '0' && char <= '9':
			builder.WriteRune(char)
		case char == '_' || char == '-':
			builder.WriteRune(char)
		}
	}
	suffix := builder.String()
	if len(suffix) > 32 {
		suffix = suffix[:32]
	}
	return strings.Trim(suffix, "_-")
}

func (s *Server) seedUserMediaState(userID string) error {
	now := time.Now().UTC()
	rows := []struct {
		MediaID         string
		Watchlisted     bool
		Watched         bool
		ProgressSeconds int
		Rating          int
		LastPlayedAgo   time.Duration
	}{
		{"movie_meridian", false, false, 1762, 9, 2 * time.Hour},
		{"episode_northbridge_101", false, false, 880, 0, 7 * time.Hour},
		{"book_atlas", false, false, 6320, 8, 26 * time.Hour},
		{"movie_neon", true, false, 0, 0, 0},
		{"anime_starrail", true, false, 0, 0, 0},
		{"movie_saffron", true, false, 0, 0, 0},
		{"album_mara", false, true, 0, 8, 72 * time.Hour},
	}
	for _, row := range rows {
		var exists int
		if err := s.queryUserRow(context.Background(), `SELECT COUNT(*) FROM media_items WHERE id = ?`, row.MediaID).Scan(&exists); err != nil {
			return err
		}
		if exists == 0 {
			continue
		}
		var lastPlayed any
		if row.LastPlayedAgo > 0 {
			lastPlayed = now.Add(-row.LastPlayedAgo).Format(time.RFC3339)
		}
		_, err := s.execUserWrite(context.Background(), `
			INSERT INTO user_media_state (profile_id, user_id, media_id, watchlisted, watched, progress_seconds, rating, last_played_at, updated_at)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
			ON CONFLICT(profile_id, media_id) DO UPDATE SET
				watchlisted = excluded.watchlisted,
				watched = excluded.watched,
				progress_seconds = excluded.progress_seconds,
				rating = excluded.rating,
				last_played_at = excluded.last_played_at,
				updated_at = excluded.updated_at`,
			userID, userID, row.MediaID, boolInt(row.Watchlisted), boolInt(row.Watched), row.ProgressSeconds, row.Rating, lastPlayed, now.Format(time.RFC3339))
		if err != nil {
			return err
		}
	}
	return nil
}

func validLibraryStorageKind(id string) bool {
	switch strings.ToLower(strings.TrimSpace(id)) {
	case "movie", "show", "anime", "music", "audiobook", "recorded-tv":
		return true
	default:
		return false
	}
}

func (s *Server) listLibrariesContext(ctx context.Context) ([]Library, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT l.id, l.name, l.type, l.sort_order, l.path, l.settings_json, COALESCE(lc.root_item_count, 0)
		FROM libraries l
		LEFT JOIN library_item_counts lc ON lc.library_id = l.id
		ORDER BY l.sort_order ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var libraries []Library
	for rows.Next() {
		var library Library
		var settingsJSON string
		if err := rows.Scan(&library.ID, &library.Name, &library.Type, &library.SortOrder, &library.Path, &settingsJSON, &library.Count); err != nil {
			return nil, err
		}
		library.Settings = decodeSettingsMap(settingsJSON)
		libraries = append(libraries, library)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	libraries, err = s.withLibraryPathsContext(ctx, libraries)
	if err != nil {
		return nil, err
	}
	return s.withLibraryScanSummariesContext(ctx, libraries)
}

func (s *Server) listLibraries() ([]Library, error) {
	return s.listLibrariesContext(context.Background())
}

func (s *Server) listLibrariesForUser(user User) ([]Library, error) {
	return s.listLibrariesForUserContext(context.Background(), user)
}

func (s *Server) listLibrariesForUserContext(ctx context.Context, user User) ([]Library, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	libraries, err := s.listLibrariesContext(ctx)
	if err != nil {
		return nil, err
	}
	if user.Role == "owner" {
		return libraries, nil
	}
	allowed, err := s.userLibraryAccessSetContext(ctx, user.ID)
	if err != nil {
		return nil, err
	}
	filtered := make([]Library, 0, len(libraries))
	for _, library := range libraries {
		if allowed[library.ID] {
			filtered = append(filtered, library)
		}
	}
	return filtered, nil
}

func (s *Server) canAccessLibrary(user User, libraryID string) bool {
	return s.canAccessLibraryContext(context.Background(), user, libraryID)
}

func (s *Server) canAccessLibraryContext(ctx context.Context, user User, libraryID string) bool {
	allowed, err := s.libraryAccessAllowedContext(ctx, user, libraryID)
	if err != nil {
		return false
	}
	return allowed
}

func (s *Server) libraryAccessAllowedContext(ctx context.Context, user User, libraryID string) (bool, error) {
	if user.Role == "owner" {
		return true, nil
	}
	allowed, err := s.userLibraryAccessSetContext(ctx, user.ID)
	if err != nil {
		return false, err
	}
	return allowed[libraryID], nil
}

func (s *Server) userLibraryAccessSet(userID string) (map[string]bool, error) {
	return s.userLibraryAccessSetContext(context.Background(), userID)
}

func (s *Server) userLibraryAccessSetContext(ctx context.Context, userID string) (map[string]bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `SELECT library_id FROM user_library_access WHERE user_id = ?`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	allowed := map[string]bool{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var libraryID string
		if err := rows.Scan(&libraryID); err != nil {
			return nil, err
		}
		allowed[libraryID] = true
	}
	return allowed, rows.Err()
}

func (s *Server) getLibraryContext(ctx context.Context, id string) (Library, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var library Library
	var settingsJSON string
	err := s.queryUserRow(ctx, `
		SELECT l.id, l.name, l.type, l.sort_order, l.path, l.settings_json, COALESCE(lc.root_item_count, 0)
		FROM libraries l
		LEFT JOIN library_item_counts lc ON lc.library_id = l.id
		WHERE l.id = ?
		LIMIT 1`, id).Scan(&library.ID, &library.Name, &library.Type, &library.SortOrder, &library.Path, &settingsJSON, &library.Count)
	if err != nil {
		return Library{}, err
	}
	library.Settings = decodeSettingsMap(settingsJSON)
	libraries, err := s.withLibraryPathsContext(ctx, []Library{library})
	if err != nil {
		return Library{}, err
	}
	libraries, err = s.withLibraryScanSummariesContext(ctx, libraries)
	if err != nil {
		return Library{}, err
	}
	return libraries[0], nil
}

func (s *Server) getLibrary(id string) (Library, error) {
	return s.getLibraryContext(context.Background(), id)
}

func (s *Server) createLibrary(req CreateLibraryRequest) (Library, error) {
	req.Name = strings.TrimSpace(req.Name)
	req.Type = strings.TrimSpace(req.Type)
	req.Path = strings.TrimSpace(req.Path)
	paths, err := normalizePaths(req.Path, req.Paths)
	if err != nil {
		return Library{}, err
	}
	if req.Name == "" {
		return Library{}, errors.New("Library name is required.")
	}
	if !validLibraryStorageKind(req.Type) {
		return Library{}, errors.New("Library type is not recognized.")
	}
	if len(paths) == 0 {
		return Library{}, errors.New("At least one library folder is required.")
	}
	settingsJSON, err := encodeLibrarySettings(req.Settings)
	if err != nil {
		return Library{}, err
	}

	sortOrder := 100
	_ = s.queryUserRow(context.Background(), `SELECT COALESCE(MAX(sort_order), 90) + 1 FROM libraries`).Scan(&sortOrder)
	id := randomID("lib")
	now := time.Now().UTC().Format(time.RFC3339)
	if err := s.withUserTxTagged(context.Background(), []string{"home", "libraries", "library-items"}, func(tx *sql.Tx) error {
		if _, err := tx.Exec(`INSERT INTO libraries (id, name, type, sort_order, path, settings_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)`,
			id, req.Name, req.Type, sortOrder, paths[0], settingsJSON, now); err != nil {
			return err
		}
		if _, err := tx.Exec(`
			INSERT INTO user_library_navigation (profile_id, user_id, library_id, pinned, sort_order, created_at, updated_at)
			SELECT id, id, ?, 1, ?, ?, ? FROM users WHERE role = 'owner'
			ON CONFLICT(profile_id, library_id) DO NOTHING`, id, sortOrder, now, now); err != nil {
			return err
		}
		return replaceLibraryPaths(tx, id, paths, now)
	}); err != nil {
		return Library{}, err
	}
	s.invalidateHomeCache()
	return s.getLibrary(id)
}

func (s *Server) updateLibrary(id string, req UpdateLibraryRequest) (Library, error) {
	current, err := s.getLibrary(id)
	if err != nil {
		return Library{}, err
	}
	req.Name = strings.TrimSpace(req.Name)
	req.Type = strings.TrimSpace(req.Type)
	req.Path = strings.TrimSpace(req.Path)
	if req.Name == "" {
		req.Name = current.Name
	}
	if req.Type == "" {
		req.Type = current.Type
	}
	paths, err := normalizePaths(req.Path, req.Paths)
	if err != nil {
		return Library{}, err
	}
	if len(paths) == 0 {
		paths = current.Paths
	}
	if req.Name == "" {
		return Library{}, errors.New("Library name is required.")
	}
	if !validLibraryStorageKind(req.Type) {
		return Library{}, errors.New("Library type is not recognized.")
	}
	if len(paths) == 0 {
		return Library{}, errors.New("At least one library folder is required.")
	}
	settings := current.Settings
	if req.Settings != nil {
		settings = req.Settings
	}
	settingsJSON, err := encodeLibrarySettings(settings)
	if err != nil {
		return Library{}, err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	scanProfileRunningJobIDs := []string{}
	var scanProfileFollowup scanProfileFollowup
	if err := s.withUserTxTagged(context.Background(), []string{"home", "libraries", "library-items"}, func(tx *sql.Tx) error {
		base := cloneSettingMap(canonicalSettingRegistry["library"].Defaults)
		var globalJSON string
		if loadErr := tx.QueryRow(`SELECT value_json FROM settings WHERE key='library'`).Scan(&globalJSON); loadErr == nil {
			for key, value := range decodeScanProfileSettings(globalJSON) {
				base[key] = value
			}
		} else if loadErr != sql.ErrNoRows {
			return loadErr
		}
		profileChange := compareScanProfiles(mergeScanProfileSettings(base, current.Settings), mergeScanProfileSettings(base, settings))
		result, err := tx.Exec(`UPDATE libraries SET name = ?, type = ?, path = ?, settings_json = ? WHERE id = ?`, req.Name, req.Type, paths[0], settingsJSON, id)
		if err != nil {
			return err
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return err
		}
		if affected == 0 {
			return sql.ErrNoRows
		}
		if err := replaceLibraryPaths(tx, id, paths, now); err != nil {
			return err
		}
		if profileChange.changed() {
			scanProfileRunningJobIDs, err = s.fenceContentWorkForScanProfileTx(tx, id, profileChange)
			scanProfileFollowup = followupForScanProfileChange(id, profileChange)
			return err
		}
		return nil
	}); err != nil {
		return Library{}, err
	}
	s.cancelRunningJobContexts(scanProfileRunningJobIDs)
	s.enqueueScanProfileFollowup(scanProfileFollowup)
	s.invalidateHomeCache()
	return s.getLibrary(id)
}

func (s *Server) deleteLibrary(id string) error {
	artifacts, err := s.remoteStorageArtifactsForLibrary(context.Background(), id)
	if err != nil {
		return err
	}
	if err := s.withUserTxTagged(context.Background(), []string{"home", "libraries", "library-items", "media", "metadata", "search"}, func(tx *sql.Tx) error {
		now := time.Now().UTC().Format(time.RFC3339Nano)
		if _, err := tx.Exec(`
			UPDATE jobs
			SET cancellation_requested_at = ?,
				status = CASE WHEN status IN ('queued', 'deferred') THEN 'cancelled' ELSE status END,
				worker_acknowledged_at = CASE WHEN status IN ('queued', 'deferred') THEN ? ELSE worker_acknowledged_at END,
				updated_at = ?
			WHERE resource_type = 'library' AND resource_id = ? AND status NOT IN ('complete', 'failed', 'cancelled')`, now, now, now, id); err != nil {
			return err
		}
		if _, err := tx.Exec(`DELETE FROM identity_reconciliation_reviews WHERE library_or_source_id = ?`, id); err != nil {
			return err
		}
		for _, artifact := range artifacts {
			if _, err := tx.Exec(`DELETE FROM identity_reconciliation_reviews WHERE library_or_source_id = ?`, artifact.SourceID); err != nil {
				return err
			}
		}
		if _, err := tx.Exec(`DELETE FROM media_search WHERE media_id IN (SELECT id FROM media_items WHERE library_id = ?)`, id); err != nil {
			return err
		}
		if _, err := tx.Exec(`DELETE FROM media_items WHERE library_id = ?`, id); err != nil {
			return err
		}
		if _, err := tx.Exec(`DELETE FROM library_paths WHERE library_id = ?`, id); err != nil {
			return err
		}
		for _, artifact := range artifacts {
			if artifact.InstallationID != "" {
				if _, err := tx.Exec(`DELETE FROM managed_rclone_installations WHERE id=?`, artifact.InstallationID); err != nil {
					return err
				}
			}
		}
		result, err := tx.Exec(`DELETE FROM libraries WHERE id = ?`, id)
		if err != nil {
			return err
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return err
		}
		if affected == 0 {
			return sql.ErrNoRows
		}
		return nil
	}); err != nil {
		return err
	}
	s.cleanupRemoteStorageArtifacts(artifacts)
	s.invalidateHomeCache()
	return nil
}

func (s *Server) deleteMediaItem(id string, req DeleteMediaRequest) (DeleteMediaResponse, error) {
	items, err := s.mediaDeletionItems(id)
	if err != nil {
		return DeleteMediaResponse{}, err
	}
	if len(items) == 0 {
		return DeleteMediaResponse{}, sql.ErrNoRows
	}
	files := []string{}
	if req.DeleteFiles {
		settings := s.librarySettings()
		if !settings.AllowMediaDeletion {
			return DeleteMediaResponse{}, errors.New("media file deletion is disabled in Library settings")
		}
		files, err = s.mediaFileDeletionPathsForMediaTree(id)
		if err != nil {
			return DeleteMediaResponse{}, err
		}
		if len(files) == 0 {
			for _, item := range items {
				path, ok, err := s.localDeletionPath(item)
				if err != nil {
					return DeleteMediaResponse{}, err
				}
				if ok {
					files = append(files, path)
				}
			}
		}
	}
	if s.optimizedVersionSettings().AutoDelete {
		optimizedPaths, err := s.optimizedVersionPathsForMediaTree(id)
		if err != nil {
			return DeleteMediaResponse{}, err
		}
		files = append(files, optimizedPaths...)
	}

	trashedFiles := 0
	trashMoves := make([]durableTrashMove, 0, len(files))
	for _, path := range uniqueStrings(files) {
		move, err := s.stageMediaFileToTrash(path)
		if err != nil {
			for index := len(trashMoves) - 1; index >= 0; index-- {
				_ = trashMoves[index].rollback()
			}
			return DeleteMediaResponse{}, err
		}
		trashMoves = append(trashMoves, move)
		trashedFiles++
	}

	if err := s.withUserTxTagged(context.Background(), []string{"home", "library-items", "media", "metadata", "search"}, func(tx *sql.Tx) error {
		if _, err := tx.Exec(`
			DELETE FROM media_search
			WHERE media_id IN (
				WITH RECURSIVE tree(id) AS (
					SELECT id FROM media_items WHERE id = ?
					UNION ALL
					SELECT child.id FROM media_items child JOIN tree ON child.parent_id = tree.id
				)
				SELECT id FROM tree
			)`, id); err != nil {
			return err
		}
		result, err := tx.Exec(`DELETE FROM media_items WHERE id = ?`, id)
		if err != nil {
			return err
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return err
		}
		if affected == 0 {
			return sql.ErrNoRows
		}
		return nil
	}); err != nil {
		for index := len(trashMoves) - 1; index >= 0; index-- {
			_ = trashMoves[index].rollback()
		}
		return DeleteMediaResponse{}, err
	}
	for _, move := range trashMoves {
		if err := move.commit(); err != nil {
			s.log.Warn("trash move journal cleanup deferred to reconciliation", "error", err)
		}
	}
	s.invalidateHomeCache()
	return DeleteMediaResponse{OK: true, DeletedItems: len(items), TrashedFiles: trashedFiles}, nil
}

func (s *Server) mediaDeletionItems(id string) ([]MediaItem, error) {
	return s.queryMedia("", `
		WHERE m.id IN (
			WITH RECURSIVE tree(id) AS (
				SELECT id FROM media_items WHERE id = ?
				UNION ALL
				SELECT child.id FROM media_items child JOIN tree ON child.parent_id = tree.id
			)
			SELECT id FROM tree
		)
		ORDER BY CASE WHEN m.id = ? THEN 0 ELSE 1 END, m.parent_id, m.title`, []any{id, id})
}

func (s *Server) authorizeMediaTreeDeletionContext(ctx context.Context, userID, id string) error {
	const treePredicate = `m.id IN (
		WITH RECURSIVE tree(id) AS (
			SELECT id FROM media_items WHERE id = ?
			UNION ALL
			SELECT child.id FROM media_items child JOIN tree ON child.parent_id = tree.id
		)
		SELECT id FROM tree
	)`
	var total int
	if err := s.queryUserRow(ctx, `
		SELECT COUNT(*)
		FROM media_items m
		WHERE `+treePredicate, id).Scan(&total); err != nil {
		return err
	}
	if total == 0 {
		return sql.ErrNoRows
	}
	where, args := s.applyMediaVisibilityRestrictionSQL(userID, treePredicate, []any{id})
	where, args = s.applyLibraryCurationRestrictionSQL(ctx, userID, where, args)
	var visible int
	if err := s.queryUserRow(ctx, `SELECT COUNT(*) FROM media_items m WHERE `+where, args...).Scan(&visible); err != nil {
		return err
	}
	if visible != total {
		return errMediaTreeNotFullyVisible
	}
	return nil
}

func (s *Server) optimizedVersionPathsForMediaTree(id string) ([]string, error) {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT path
		FROM optimized_versions
		WHERE media_id IN (
			WITH RECURSIVE tree(id) AS (
				SELECT id FROM media_items WHERE id = ?
				UNION ALL
				SELECT child.id FROM media_items child JOIN tree ON child.parent_id = tree.id
			)
			SELECT id FROM tree
		)`, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	paths := []string{}
	for rows.Next() {
		var path string
		if err := rows.Scan(&path); err != nil {
			return nil, err
		}
		if strings.TrimSpace(path) != "" {
			paths = append(paths, path)
		}
	}
	return paths, rows.Err()
}

func (s *Server) mediaFileDeletionPathsForMediaTree(id string) ([]string, error) {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT mf.path, mf.library_id
		FROM media_files mf
		WHERE mf.available = 1
			AND mf.path <> ''
			AND mf.media_id IN (
				WITH RECURSIVE tree(id) AS (
					SELECT id FROM media_items WHERE id = ?
					UNION ALL
					SELECT child.id FROM media_items child JOIN tree ON child.parent_id = tree.id
				)
				SELECT id FROM tree
			)`, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	paths := []string{}
	for rows.Next() {
		var sourceURL string
		var libraryID string
		if err := rows.Scan(&sourceURL, &libraryID); err != nil {
			return nil, err
		}
		path, ok, err := s.localDeletionPathFromSource(libraryID, sourceURL)
		if err != nil {
			return nil, err
		}
		if ok {
			paths = append(paths, path)
		}
	}
	return paths, rows.Err()
}

func (s *Server) localDeletionPath(item MediaItem) (string, bool, error) {
	return s.localDeletionPathFromSource(item.LibraryID, item.SourceURL)
}

func (s *Server) localDeletionPathFromSource(libraryID string, sourceURL string) (string, bool, error) {
	sourceURL = strings.TrimSpace(sourceURL)
	if sourceURL == "" {
		return "", false, nil
	}
	parsed, err := url.Parse(sourceURL)
	if err == nil && (parsed.Scheme == "http" || parsed.Scheme == "https") {
		return "", false, errors.New("remote media sources cannot be deleted from disk")
	}
	path := sourceURL
	if err == nil && parsed.Scheme == "file" {
		path = parsed.Path
	} else if err == nil && parsed.Scheme != "" {
		return "", false, errUnsupportedPlaybackScheme
	}
	path, err = s.validateLocalMediaPath(libraryID, path)
	if err != nil {
		return "", false, err
	}
	return path, true, nil
}

func uniqueStrings(values []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, value := range values {
		if seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
	}
	return out
}

func (s *Server) withLibraryPaths(libraries []Library) ([]Library, error) {
	return s.withLibraryPathsContext(context.Background(), libraries)
}

func (s *Server) withLibraryPathsContext(ctx context.Context, libraries []Library) ([]Library, error) {
	if len(libraries) == 0 {
		return libraries, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	ids := make([]any, 0, len(libraries))
	placeholders := make([]string, 0, len(libraries))
	indexByID := map[string]int{}
	for i, library := range libraries {
		ids = append(ids, library.ID)
		placeholders = append(placeholders, "?")
		indexByID[library.ID] = i
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT library_id, path
		FROM library_paths
		WHERE library_id IN (`+strings.Join(placeholders, ",")+`)
		ORDER BY sort_order ASC, path ASC`, ids...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var libraryID string
		var path string
		if err := rows.Scan(&libraryID, &path); err != nil {
			return nil, err
		}
		if idx, ok := indexByID[libraryID]; ok {
			libraries[idx].Paths = append(libraries[idx].Paths, path)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	for i := range libraries {
		if len(libraries[i].Paths) == 0 && libraries[i].Path != "" {
			libraries[i].Paths = []string{libraries[i].Path}
		}
		if len(libraries[i].Paths) > 0 {
			libraries[i].Path = libraries[i].Paths[0]
		}
	}
	return libraries, nil
}

func (s *Server) withLibraryScanSummariesContext(ctx context.Context, libraries []Library) ([]Library, error) {
	if len(libraries) == 0 {
		return libraries, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	args := make([]any, 0, len(libraries))
	placeholders := make([]string, 0, len(libraries))
	indexByID := map[string]int{}
	for i, library := range libraries {
		args = append(args, library.ID)
		placeholders = append(placeholders, "?")
		indexByID[library.ID] = i
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT id, status, progress, message, resource_id, created_at, updated_at
		FROM jobs
		WHERE type = 'library_scan'
			AND resource_type = 'library'
			AND resource_id IN (`+strings.Join(placeholders, ",")+`)
		ORDER BY
			CASE status
				WHEN 'running' THEN 0
				WHEN 'queued' THEN 1
				ELSE 2
			END,
			updated_at DESC,
			created_at DESC`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var summary LibraryScanSummary
		var libraryID string
		if err := rows.Scan(&summary.JobID, &summary.Status, &summary.Progress, &summary.Message, &libraryID, &summary.CreatedAt, &summary.UpdatedAt); err != nil {
			return nil, err
		}
		idx, ok := indexByID[libraryID]
		if !ok || libraries[idx].ScanSummary != nil {
			continue
		}
		libraries[idx].ScanSummary = &summary
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return libraries, nil
}

func replaceLibraryPaths(tx *sql.Tx, libraryID string, paths []string, now string) error {
	if _, err := tx.Exec(`DELETE FROM library_paths WHERE library_id = ?`, libraryID); err != nil {
		return err
	}
	for i, path := range paths {
		if _, err := tx.Exec(`INSERT INTO library_paths (id, library_id, path, sort_order, created_at) VALUES (?, ?, ?, ?, ?)`,
			fmt.Sprintf("%s_path_%d", libraryID, i+1), libraryID, path, i, now); err != nil {
			return err
		}
	}
	return nil
}

func normalizePaths(primary string, paths []string) ([]string, error) {
	seen := map[string]bool{}
	var normalized []string
	candidates := append([]string{}, paths...)
	if primary != "" {
		candidates = append([]string{primary}, candidates...)
	}
	for _, path := range candidates {
		path = strings.TrimSpace(path)
		if path == "" {
			continue
		}
		if strings.ContainsRune(path, 0) {
			return nil, errors.New("Library path is invalid.")
		}
		key := strings.ToLower(path)
		if seen[key] {
			continue
		}
		seen[key] = true
		normalized = append(normalized, path)
	}
	return normalized, nil
}

func decodeSettingsMap(raw string) map[string]any {
	settings := map[string]any{}
	if strings.TrimSpace(raw) == "" {
		return settings
	}
	if err := json.Unmarshal([]byte(raw), &settings); err != nil {
		return map[string]any{}
	}
	return settings
}

func encodeLibrarySettings(settings map[string]any) (string, error) {
	if settings == nil {
		settings = map[string]any{}
	}
	allowed := map[string]bool{
		"scannerEnabled":                  true,
		"scanAutomatically":               true,
		"scheduledScanCadence":            true,
		"scheduledScanIntervalHours":      true,
		"scheduledAnalysisEnabled":        true,
		"scheduledAnalysisCadence":        true,
		"scheduledAnalysisIntervalHours":  true,
		"scheduledMetadataRefreshEnabled": true,
		"scheduledMetadataRefreshDays":    true,
		"metadataProvider":                true,
		"localMetadataMode":               true,
		"metadataProviderOrder":           true,
		"disabledMetadataProviders":       true,
		"imagePolicy":                     true,
		"metadataLanguage":                true,
		"visibility":                      true,
		"hideFromHome":                    true,
		"hideFromSearch":                  true,
		"includeInContinueWatching":       true,
		"allowedTags":                     true,
		"blockedTags":                     true,
		"blockedKeywords":                 true,
		"emptyTrashAfterScan":             true,
		"analysisTier":                    true,
		"readLocalMetadata":               true,
		"readExternalSubtitlesAndLyrics":  true,
		"discoverLocalArtwork":            true,
		"fetchDescriptiveMetadata":        true,
		"probeStreams":                    true,
		"readEmbeddedTags":                true,
		"readEmbeddedIndexes":             true,
		"generateRepresentativeThumbnail": true,
		"extractSelectedEmbeddedAssets":   true,
		"validateSeekBehavior":            true,
		"fullFileChecksum":                true,
		"generateTrickplay":               true,
		"generateChapterThumbnails":       true,
		"generateWaveforms":               true,
		"analyzeLoudness":                 true,
		"extractAllEmbeddedAttachments":   true,
		"analyzeSTRMTarget":               true,
		"trickplayStorageLocation":        true,
		"trickplayIntervalSeconds":        true,
		"trickplayTileWidth":              true,
		"trickplayMaxTiles":               true,
		"sonicFingerprinting":             true,
		"detectSegments":                  true,
		"fetchMissingLyricsAfterScan":     true,
		"preferEmbeddedTitles":            true,
		"trashRetentionDays":              true,
		"collectionMode":                  true,
	}
	clean := map[string]any{}
	for key, value := range settings {
		if allowed[key] {
			switch key {
			case "allowedTags", "blockedTags", "blockedKeywords":
				normalized := normalizeLibraryCurationList(value)
				if len(normalized) > 0 {
					clean[key] = normalized
				}
			default:
				clean[key] = value
			}
		}
	}
	bytes, err := json.Marshal(clean)
	if err != nil {
		return "", err
	}
	return string(bytes), nil
}

func normalizeLibraryCurationList(value any) []string {
	candidates := []string{}
	appendValue := func(raw string) {
		for _, part := range strings.FieldsFunc(raw, func(r rune) bool {
			return r == ',' || r == '\n' || r == ';'
		}) {
			if trimmed := strings.TrimSpace(part); trimmed != "" {
				candidates = append(candidates, trimmed)
			}
		}
	}
	switch typed := value.(type) {
	case nil:
	case []string:
		for _, raw := range typed {
			appendValue(raw)
		}
	case []any:
		for _, raw := range typed {
			if text, ok := raw.(string); ok {
				appendValue(text)
			}
		}
	case string:
		appendValue(typed)
	default:
		appendValue(fmt.Sprint(typed))
	}
	return normalizePolicyTagList(candidates)
}

func (s *Server) filterItemsByLibraryVisibility(items []MediaItem, surface string) []MediaItem {
	if len(items) == 0 {
		return items
	}
	libraries, err := s.listLibraries()
	if err != nil {
		return items
	}
	hidden := map[string]bool{}
	for _, library := range libraries {
		if libraryHiddenFrom(library, surface) {
			hidden[library.ID] = true
		}
	}
	if len(hidden) == 0 {
		return items
	}
	filtered := items[:0]
	for _, item := range items {
		if !hidden[item.LibraryID] {
			filtered = append(filtered, item)
		}
	}
	return filtered
}

func libraryHiddenFrom(library Library, surface string) bool {
	switch surface {
	case "home":
		return settingBool(library.Settings, "hideFromHome", false)
	case "continue":
		return settingBool(library.Settings, "hideFromHome", false) || !settingBool(library.Settings, "includeInContinueWatching", true)
	case "search":
		return settingBool(library.Settings, "hideFromSearch", false)
	default:
		return false
	}
}

func librarySurfaceVisibilityRestrictionSQL(surface string) string {
	switch surface {
	case "search":
		return ` AND NOT EXISTS (
			SELECT 1 FROM libraries surface_library
			WHERE surface_library.id = m.library_id
				AND COALESCE(json_extract(surface_library.settings_json, '$.hideFromSearch'), 0) = 1
		)`
	default:
		return ""
	}
}

