func applyTypedMetadataCompatibility(item *MediaItem) {
	if item == nil || len(item.TypedMetadata) == 0 {
		return
	}
	switch item.Type {
	case "album":
		item.Studio = firstNonEmpty(item.TypedMetadata["albumArtist"], item.TypedMetadata["artist"], item.Studio)
	case "track":
		item.Studio = firstNonEmpty(item.TypedMetadata["trackArtist"], item.TypedMetadata["artist"], item.Studio)
	case "audiobook":
		item.Studio = firstNonEmpty(item.TypedMetadata["author"], item.TypedMetadata["narrator"], item.Studio)
	case "show", "anime", "episode", "recording":
		item.Network = firstNonEmpty(item.TypedMetadata["network"], item.Network)
		item.Studio = firstNonEmpty(item.TypedMetadata["studio"], item.Studio)
	}
}

func (s *Server) instantMixItems(userID string, seedID string, limit int) ([]MediaItem, error) {
	return s.instantMixItemsContext(context.Background(), userID, seedID, limit)
}

func (s *Server) instantMixItemsContext(ctx context.Context, userID string, seedID string, limit int) ([]MediaItem, error) {
	if genre, ok := instantMixGenreSeed(seedID); ok {
		return s.instantMixGenreItemsContext(ctx, userID, genre, limit)
	}
	seed, err := s.getMediaListItemContext(ctx, userID, seedID)
	if err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			return nil, err
		}
		user, userErr := s.getUser(userID)
		if userErr != nil {
			return nil, err
		}
		playlist, playlistErr := s.getPlaylist(user, seedID, true)
		if playlistErr != nil {
			return nil, err
		}
		return s.instantMixFromSeedsContext(ctx, userID, playlist.Items, limit)
	}
	if seed.Type != "artist" && seed.Type != "album" && seed.Type != "track" {
		return nil, errors.New("Instant Mix is only available for music artists, albums, tracks, playlists, and genre seeds.")
	}
	return s.instantMixFromSeedsContext(ctx, userID, []MediaItem{seed}, limit)
}

func (s *Server) instantMixGenreItems(userID string, genre string, limit int) ([]MediaItem, error) {
	return s.instantMixGenreItemsContext(context.Background(), userID, genre, limit)
}

func (s *Server) instantMixGenreItemsContext(ctx context.Context, userID string, genre string, limit int) ([]MediaItem, error) {
	if strings.TrimSpace(genre) == "" {
		return nil, errors.New("Instant Mix genre seed is required.")
	}
	seed := MediaItem{Type: "genre", Genres: []string{genre}}
	candidates, err := s.instantMixCandidateTracksContext(ctx, userID, []MediaItem{seed}, limit)
	if err != nil {
		return nil, err
	}
	if len(candidates) == 0 {
		candidates, err = s.instantMixRecentTrackCandidatesContext(ctx, userID, nil, limit)
		if err != nil {
			return nil, err
		}
	}
	return instantMixRankedTracks(candidates, []MediaItem{seed}, limit), nil
}

func (s *Server) instantMixFromSeeds(userID string, seeds []MediaItem, limit int) ([]MediaItem, error) {
	return s.instantMixFromSeedsContext(context.Background(), userID, seeds, limit)
}

func (s *Server) instantMixFromSeedsContext(ctx context.Context, userID string, seeds []MediaItem, limit int) ([]MediaItem, error) {
	musicSeeds := []MediaItem{}
	for _, seed := range seeds {
		switch seed.Type {
		case "artist", "album", "track":
			musicSeeds = append(musicSeeds, seed)
		}
	}
	if len(musicSeeds) == 0 {
		return nil, errors.New("Instant Mix is only available for music artists, albums, tracks, playlists, and genre seeds.")
	}
	candidates, err := s.instantMixCandidateTracksContext(ctx, userID, musicSeeds, limit)
	if err != nil {
		return nil, err
	}
	return instantMixRankedTracks(candidates, musicSeeds, limit), nil
}

func (s *Server) instantMixCandidateTracksContext(ctx context.Context, userID string, seeds []MediaItem, limit int) ([]MediaItem, error) {
	libraryIDs := map[string]bool{}
	seedIDs := map[string]bool{}
	artistIDs := map[string]bool{}
	albumIDs := map[string]bool{}
	artistKeys := map[string]bool{}
	genreKeys := map[string]bool{}
	for _, seed := range seeds {
		if seed.LibraryID != "" {
			libraryIDs[seed.LibraryID] = true
		}
		if seed.ID != "" && seed.Type == "track" {
			seedIDs[seed.ID] = true
		}
		if seed.ID != "" && seed.Type == "artist" {
			artistIDs[seed.ID] = true
		}
		if seed.ID != "" && seed.Type == "album" {
			albumIDs[seed.ID] = true
		}
		if seed.ParentID != "" {
			albumIDs[seed.ParentID] = true
		}
		for artist := range instantMixArtistKeys(seed) {
			artistKeys[artist] = true
		}
		for genre := range stringSet(seed.Genres) {
			genreKeys[genre] = true
		}
	}
	where := []string{"m.type = 'track'"}
	args := []any{}
	if len(libraryIDs) > 0 {
		libraries := sortedRecommendationIDs(libraryIDs)
		where = append(where, "m.library_id IN ("+sqlPlaceholders(len(libraries))+")")
		for _, libraryID := range libraries {
			args = append(args, libraryID)
		}
	} else {
		user, err := s.getUser(userID)
		if err == nil && !strings.EqualFold(strings.TrimSpace(user.Role), "owner") {
			if len(user.LibraryIDs) == 0 {
				return []MediaItem{}, nil
			}
			libraries := append([]string(nil), user.LibraryIDs...)
			sort.Strings(libraries)
			where = append(where, "m.library_id IN ("+sqlPlaceholders(len(libraries))+")")
			for _, libraryID := range libraries {
				args = append(args, libraryID)
			}
		}
	}
	match := []string{}
	if len(seedIDs) > 0 {
		ids := sortedRecommendationIDs(seedIDs)
		match = append(match, "m.id IN ("+sqlPlaceholders(len(ids))+")")
		for _, id := range ids {
			args = append(args, id)
		}
	}
	if len(albumIDs) > 0 {
		ids := sortedRecommendationIDs(albumIDs)
		match = append(match, "m.parent_id IN ("+sqlPlaceholders(len(ids))+")")
		for _, id := range ids {
			args = append(args, id)
		}
	}
	if len(artistIDs) > 0 {
		ids := sortedRecommendationIDs(artistIDs)
		match = append(match, `EXISTS (
			SELECT 1
			FROM media_items instant_mix_album
			WHERE instant_mix_album.id = m.parent_id
				AND instant_mix_album.parent_id IN (`+sqlPlaceholders(len(ids))+`)
		)`)
		for _, id := range ids {
			args = append(args, id)
		}
	}
	appendFacetMatch := func(facetTypes []string, values map[string]bool) {
		if len(values) == 0 {
			return
		}
		orderedValues := sortedRecommendationIDs(values)
		match = append(match, `EXISTS (
			SELECT 1
			FROM media_category_facets instant_mix_facet
			WHERE instant_mix_facet.media_id = m.id
				AND instant_mix_facet.library_id = COALESCE(m.library_id, '')
				AND instant_mix_facet.facet_type IN (`+sqlPlaceholders(len(facetTypes))+`)
				AND instant_mix_facet.sort_value IN (`+sqlPlaceholders(len(orderedValues))+`)
		)`)
		for _, facetType := range facetTypes {
			args = append(args, facetType)
		}
		for _, value := range orderedValues {
			args = append(args, value)
		}
	}
	appendFacetMatch([]string{"artist", "albumArtist"}, artistKeys)
	appendFacetMatch([]string{"genre"}, genreKeys)
	if len(match) == 0 {
		return []MediaItem{}, nil
	}
	where = append(where, "("+strings.Join(match, " OR ")+")")
	candidateLimit := instantMixCandidateBudget(limit)
	args = append(args, candidateLimit)
	return s.queryMediaContext(ctx, userID, `
		WHERE `+strings.Join(where, " AND ")+`
		ORDER BY m.added_at DESC, m.sort_title ASC
		LIMIT ?`, args)
}

func (s *Server) instantMixRecentTrackCandidatesContext(ctx context.Context, userID string, libraryIDs map[string]bool, limit int) ([]MediaItem, error) {
	where := []string{"m.type = 'track'"}
	args := []any{}
	if len(libraryIDs) > 0 {
		libraries := sortedRecommendationIDs(libraryIDs)
		where = append(where, "m.library_id IN ("+sqlPlaceholders(len(libraries))+")")
		for _, libraryID := range libraries {
			args = append(args, libraryID)
		}
	} else {
		user, err := s.getUser(userID)
		if err == nil && !strings.EqualFold(strings.TrimSpace(user.Role), "owner") {
			if len(user.LibraryIDs) == 0 {
				return []MediaItem{}, nil
			}
			libraries := append([]string(nil), user.LibraryIDs...)
			sort.Strings(libraries)
			where = append(where, "m.library_id IN ("+sqlPlaceholders(len(libraries))+")")
			for _, libraryID := range libraries {
				args = append(args, libraryID)
			}
		}
	}
	args = append(args, instantMixCandidateBudget(limit))
	return s.queryMediaContext(ctx, userID, `
		WHERE `+strings.Join(where, " AND ")+`
		ORDER BY m.added_at DESC, m.sort_title ASC
		LIMIT ?`, args)
}

func instantMixCandidateBudget(limit int) int {
	if limit <= 0 {
		limit = 50
	}
	return min(max(limit*20, 200), 1000)
}

func instantMixRankedTracks(candidates []MediaItem, seeds []MediaItem, limit int) []MediaItem {
	type scored struct {
		item  MediaItem
		score int
	}
	scoredItems := []scored{}
	for _, item := range candidates {
		score := 0
		for _, seed := range seeds {
			score += instantMixScore(seed, item)
		}
		if score <= 0 {
			continue
		}
		scoredItems = append(scoredItems, scored{item: item, score: score})
	}
	sort.SliceStable(scoredItems, func(i, j int) bool {
		if scoredItems[i].score != scoredItems[j].score {
			return scoredItems[i].score > scoredItems[j].score
		}
		if scoredItems[i].item.ParentTitle != scoredItems[j].item.ParentTitle {
			return scoredItems[i].item.ParentTitle < scoredItems[j].item.ParentTitle
		}
		return scoredItems[i].item.IndexNumber < scoredItems[j].item.IndexNumber
	})
	if len(scoredItems) > limit {
		scoredItems = scoredItems[:limit]
	}
	items := make([]MediaItem, 0, len(scoredItems))
	for _, scored := range scoredItems {
		items = append(items, scored.item)
	}
	return items
}

func instantMixScore(seed MediaItem, item MediaItem) int {
	score := 0
	if item.ID == seed.ID {
		score += 100
	}
	if seed.Type == "album" && item.ParentID == seed.ID {
		score += 95
	}
	seedArtists := instantMixArtistKeys(seed)
	for artist := range instantMixArtistKeys(item) {
		if seedArtists[artist] {
			score += 60
			break
		}
	}
	seedAlbumTitle := ""
	if seed.Type == "album" {
		seedAlbumTitle = seed.Title
	}
	seedAlbum := strings.ToLower(firstNonEmpty(seed.TypedMetadata["albumTitle"], seed.ParentTitle, seedAlbumTitle))
	itemAlbum := strings.ToLower(firstNonEmpty(item.TypedMetadata["albumTitle"], item.ParentTitle))
	if seedAlbum != "" && itemAlbum == seedAlbum {
		score += 25
	}
	seedGenres := stringSet(seed.Genres)
	for genre := range stringSet(item.Genres) {
		if seedGenres[genre] {
			score += 10
		}
	}
	return score
}

func instantMixGenreSeed(seedID string) (string, bool) {
	genre, ok := strings.CutPrefix(strings.TrimSpace(seedID), "genre:")
	return strings.TrimSpace(genre), ok
}

func instantMixArtistKeys(item MediaItem) map[string]bool {
	return stringSet([]string{
		item.TypedMetadata["trackArtist"],
		item.TypedMetadata["albumArtist"],
		item.TypedMetadata["artist"],
		item.GrandparentTitle,
		item.Studio,
		conditionalString(item.Type == "artist", item.Title),
	})
}

func stringSet(values []string) map[string]bool {
	out := map[string]bool{}
	for _, value := range values {
		key := strings.ToLower(strings.TrimSpace(value))
		if key != "" {
			out[key] = true
		}
	}
	return out
}

func conditionalString(ok bool, value string) string {
	if ok {
		return value
	}
	return ""
}

func paginationFromRequest(r *http.Request, defaultLimit, maxLimit int) (int, int) {
	limit := defaultLimit
	if raw := strings.TrimSpace(r.URL.Query().Get("limit")); raw != "" {
		if parsed, err := strconv.Atoi(raw); err == nil && parsed > 0 {
			limit = parsed
		}
	}
	if limit <= 0 {
		limit = defaultLimit
	}
	if maxLimit > 0 && limit > maxLimit {
		limit = maxLimit
	}
	offset := 0
	if raw := strings.TrimSpace(r.URL.Query().Get("offset")); raw != "" {
		if parsed, err := strconv.Atoi(raw); err == nil && parsed > 0 {
			offset = parsed
		}
	}
	return limit, offset
}

func encodeTimeIDCursor(createdAt, id string) string {
	createdAt = strings.TrimSpace(createdAt)
	id = strings.TrimSpace(id)
	if createdAt == "" || id == "" {
		return ""
	}
	return base64.RawURLEncoding.EncodeToString([]byte(createdAt + "\x00" + id))
}

func decodeTimeIDCursor(cursor string) (string, string, error) {
	cursor = strings.TrimSpace(cursor)
	if cursor == "" {
		return "", "", nil
	}
	bytes, err := base64.RawURLEncoding.DecodeString(cursor)
	if err != nil {
		return "", "", err
	}
	parts := strings.SplitN(string(bytes), "\x00", 2)
	if len(parts) != 2 {
		return "", "", errors.New("invalid cursor")
	}
	createdAt := strings.TrimSpace(parts[0])
	id := strings.TrimSpace(parts[1])
	if createdAt == "" || id == "" {
		return "", "", errors.New("invalid cursor")
	}
	return createdAt, id, nil
}

var errInvalidLibraryCursor = errors.New("invalid library cursor")
var errInvalidLibraryStartAt = errors.New("invalid library title seek")

func normalizeLibraryItemsStartAt(value string) (string, error) {
	normalized := strings.ToUpper(strings.TrimSpace(value))
	if normalized == "" || normalized == "#" || (len(normalized) == 1 && normalized[0] >= 'A' && normalized[0] <= 'Z') {
		return normalized, nil
	}
	return "", fmt.Errorf("%w: startAt must be # or a single letter from A to Z", errInvalidLibraryStartAt)
}

type libraryItemsCursor struct {
	Sort      string `json:"sort"`
	Filter    string `json:"filter"`
	Order     string `json:"order"`
	StartAt   string `json:"startAt,omitempty"`
	Value     string `json:"value"`
	Secondary string `json:"secondary,omitempty"`
	ID        string `json:"id"`
}

func encodeLibraryItemsCursor(sortMode, filterMode, orderMode, startAt, value, secondary, id string) string {
	payload := libraryItemsCursor{
		Sort:      strings.TrimSpace(sortMode),
		Filter:    strings.TrimSpace(filterMode),
		Order:     strings.ToUpper(strings.TrimSpace(orderMode)),
		StartAt:   strings.ToUpper(strings.TrimSpace(startAt)),
		Value:     strings.TrimSpace(value),
		Secondary: strings.TrimSpace(secondary),
		ID:        strings.TrimSpace(id),
	}
	if payload.Value == "" || payload.ID == "" {
		return ""
	}
	raw, err := json.Marshal(payload)
	if err != nil {
		return ""
	}
	return base64.RawURLEncoding.EncodeToString(raw)
}

func decodeLibraryItemsCursor(cursor, sortMode, filterMode, orderMode, startAt string) (string, string, string, error) {
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(cursor))
	if err != nil {
		return "", "", "", fmt.Errorf("%w: malformed cursor", errInvalidLibraryCursor)
	}
	var payload libraryItemsCursor
	if err := json.Unmarshal(raw, &payload); err != nil {
		return "", "", "", fmt.Errorf("%w: malformed cursor", errInvalidLibraryCursor)
	}
	payload.Sort = strings.TrimSpace(payload.Sort)
	payload.Filter = strings.TrimSpace(payload.Filter)
	payload.Order = strings.ToUpper(strings.TrimSpace(payload.Order))
	payload.StartAt = strings.ToUpper(strings.TrimSpace(payload.StartAt))
	payload.Value = strings.TrimSpace(payload.Value)
	payload.Secondary = strings.TrimSpace(payload.Secondary)
	payload.ID = strings.TrimSpace(payload.ID)
	if payload.Value == "" || payload.ID == "" {
		return "", "", "", fmt.Errorf("%w: cursor is incomplete", errInvalidLibraryCursor)
	}
	if payload.Sort != strings.TrimSpace(sortMode) || payload.Filter != strings.TrimSpace(filterMode) || payload.Order != strings.ToUpper(strings.TrimSpace(orderMode)) || payload.StartAt != strings.ToUpper(strings.TrimSpace(startAt)) {
		return "", "", "", fmt.Errorf("%w: cursor does not match this library view", errInvalidLibraryCursor)
	}
	return payload.Value, payload.Secondary, payload.ID, nil
}

type libraryItemsCursorSpec struct {
	PrimaryExpr string
	Direction   string
	Secondary   bool
}

func libraryItemsCursorSpecForSort(sortMode, titleDirection, recentDirection, ratingDirection string) (libraryItemsCursorSpec, bool) {
	switch sortMode {
	case "", "title":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_title COLLATE NOCASE", Direction: titleDirection}, true
	case "added", "dateAdded", "recent", "lastEpisode":
		return libraryItemsCursorSpec{PrimaryExpr: "m.added_at", Direction: recentDirection, Secondary: true}, true
	case "year", "release", "releaseDate":
		return libraryItemsCursorSpec{PrimaryExpr: "m.year", Direction: recentDirection, Secondary: true}, true
	case "critic", "criticRating":
		return libraryItemsCursorSpec{PrimaryExpr: "m.critic_rating", Direction: ratingDirection, Secondary: true}, true
	case "audience", "audienceRating", "rating":
		return libraryItemsCursorSpec{PrimaryExpr: "m.community_rating", Direction: ratingDirection, Secondary: true}, true
	case "duration", "runtime":
		return libraryItemsCursorSpec{PrimaryExpr: "m.duration_seconds", Direction: recentDirection, Secondary: true}, true
	case "progress":
		return libraryItemsCursorSpec{PrimaryExpr: "COALESCE(ums.progress_seconds, 0)", Direction: recentDirection, Secondary: true}, true
	case "contentRating":
		return libraryItemsCursorSpec{PrimaryExpr: "m.content_rating", Direction: titleDirection, Secondary: true}, true
	case "viewed", "lastPlayed":
		return libraryItemsCursorSpec{PrimaryExpr: "COALESCE(ums.last_played_at, '')", Direction: recentDirection, Secondary: true}, true
	case "artist":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_artist_key", Direction: titleDirection, Secondary: true}, true
	case "albumArtist":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_album_artist_key", Direction: titleDirection, Secondary: true}, true
	case "trackArtist":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_track_artist_key", Direction: titleDirection, Secondary: true}, true
	case "author":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_author_key", Direction: titleDirection, Secondary: true}, true
	case "narrator":
		return libraryItemsCursorSpec{PrimaryExpr: "m.sort_narrator_key", Direction: titleDirection, Secondary: true}, true
	case "track":
		return libraryItemsCursorSpec{PrimaryExpr: "m.index_number", Direction: titleDirection, Secondary: true}, true
	case "unwatched":
		return libraryItemsCursorSpec{PrimaryExpr: "COALESCE(ums.watched, 0)", Direction: "ASC", Secondary: true}, true
	case "random":
		return libraryItemsCursorSpec{PrimaryExpr: "m.random_key", Direction: "ASC"}, true
	default:
		return libraryItemsCursorSpec{}, false
	}
}

func appendLibraryItemsCursorPredicate(where string, args []any, spec libraryItemsCursorSpec, value, secondary, id string) (string, []any) {
	operator := ">"
	if strings.EqualFold(spec.Direction, "DESC") {
		operator = "<"
	}
	if spec.Secondary {
		where += " AND (" + spec.PrimaryExpr + " " + operator + " ? OR (" + spec.PrimaryExpr + " = ? AND (m.sort_title > ? OR (m.sort_title = ? AND m.id > ?))))"
		args = append(args, value, value, secondary, secondary, id)
		return where, args
	}
	where += " AND (" + spec.PrimaryExpr + " " + operator + " ? OR (" + spec.PrimaryExpr + " = ? AND m.id > ?))"
	args = append(args, value, value, id)
	return where, args
}

func libraryItemsCursorValues(item MediaItem, sortMode string) (string, string, string) {
	switch sortMode {
	case "", "title":
		return item.SortTitle, "", item.ID
	case "added", "dateAdded", "recent", "lastEpisode":
		return item.AddedAt, item.SortTitle, item.ID
	case "year", "release", "releaseDate":
		return strconv.Itoa(item.Year), item.SortTitle, item.ID
	case "critic", "criticRating":
		return strconv.Itoa(item.CriticRating), item.SortTitle, item.ID
	case "audience", "audienceRating", "rating":
		return strconv.FormatFloat(item.CommunityRating, 'f', -1, 64), item.SortTitle, item.ID
	case "duration", "runtime":
		return strconv.Itoa(item.DurationSeconds), item.SortTitle, item.ID
	case "progress":
		return strconv.Itoa(item.State.ProgressSeconds), item.SortTitle, item.ID
	case "contentRating":
		return item.ContentRating, item.SortTitle, item.ID
	case "viewed", "lastPlayed":
		return item.State.LastPlayedAt, item.SortTitle, item.ID
	case "artist":
		return item.SortArtistKey, item.SortTitle, item.ID
	case "albumArtist":
		return item.SortAlbumArtistKey, item.SortTitle, item.ID
	case "trackArtist":
		return item.SortTrackArtistKey, item.SortTitle, item.ID
	case "author":
		return item.SortAuthorKey, item.SortTitle, item.ID
	case "narrator":
		return item.SortNarratorKey, item.SortTitle, item.ID
	case "track":
		return strconv.Itoa(item.IndexNumber), item.SortTitle, item.ID
	case "unwatched":
		return strconv.Itoa(boolInt(item.State.Watched)), item.SortTitle, item.ID
	case "random":
		return item.RandomKey, "", item.ID
	default:
		return "", "", ""
	}
}

func (s *Server) listLibraryItems(userID, libraryID, sortMode, filterMode, orderMode string, limit, offset int) ([]MediaItem, int, string, string, error) {
	return s.listLibraryItemsContext(context.Background(), userID, libraryID, sortMode, filterMode, orderMode, limit, offset)
}

func (s *Server) listLibraryItemsContext(ctx context.Context, userID, libraryID, sortMode, filterMode, orderMode string, limit, offset int) ([]MediaItem, int, string, string, error) {
	items, total, sortMode, filterMode, _, _, err := s.listLibraryItemsPageContext(ctx, userID, libraryID, sortMode, filterMode, orderMode, "exact", "", limit, offset)
	return items, total, sortMode, filterMode, err
}

func (s *Server) invalidateLibraryItemsCache() {
	s.invalidateCanonicalBrowseCache()
}

func (s *Server) listLibraryItemsPageContext(ctx context.Context, userID, libraryID, sortMode, filterMode, orderMode string, countMode string, cursor string, limit, offset int) ([]MediaItem, int, string, string, bool, string, error) {
	return s.listLibraryItemsPageFromStartContext(ctx, userID, libraryID, sortMode, filterMode, orderMode, "", countMode, cursor, limit, offset)
}

func (s *Server) listLibraryItemsPageFromStartContext(ctx context.Context, userID, libraryID, sortMode, filterMode, orderMode, startAt string, countMode string, cursor string, limit, offset int) ([]MediaItem, int, string, string, bool, string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	sortMode = strings.TrimSpace(sortMode)
	filterMode = strings.TrimSpace(filterMode)
	cursorFilterMode := filterMode
	if cursorFilterMode == "" {
		cursorFilterMode = "all"
	}
	if sortMode == "" {
		sortMode = "title"
	}
	titleDirection := sortDirection(orderMode, "asc")
	startAt, err := normalizeLibraryItemsStartAt(startAt)
	if err != nil {
		return nil, 0, sortMode, filterMode, false, "", err
	}
	if startAt != "" && (sortMode != "title" || titleDirection != "ASC") {
		return nil, 0, sortMode, filterMode, false, "", fmt.Errorf("%w: startAt requires title sorting in ascending order", errInvalidLibraryStartAt)
	}
	recentDirection := sortDirection(orderMode, "desc")
	ratingDirection := sortDirection(orderMode, "desc")
	order := "m.sort_title COLLATE NOCASE " + titleDirection + ", m.id ASC"
	switch sortMode {
	case "added", "dateAdded", "recent":
		order = "m.added_at " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "year", "releaseDate":
		order = "m.year " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "release":
		order = "m.year " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "critic", "criticRating":
		order = "m.critic_rating " + ratingDirection + ", m.sort_title ASC, m.id ASC"
	case "audience", "audienceRating":
		order = "m.community_rating " + ratingDirection + ", m.sort_title ASC, m.id ASC"
	case "rating":
		order = "m.community_rating " + ratingDirection + ", m.sort_title ASC, m.id ASC"
	case "artist":
		order = "m.sort_artist_key " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "albumArtist":
		order = "m.sort_album_artist_key " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "trackArtist":
		order = "m.sort_track_artist_key " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "author":
		order = "m.sort_author_key " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "narrator":
		order = "m.sort_narrator_key " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "track":
		order = "m.index_number " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "duration", "runtime":
		order = "m.duration_seconds " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "progress":
		order = "COALESCE(ums.progress_seconds, 0) " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "contentRating":
		order = "m.content_rating " + titleDirection + ", m.sort_title ASC, m.id ASC"
	case "unwatched":
		order = "COALESCE(ums.watched, 0) ASC, m.sort_title ASC, m.id ASC"
	case "lastEpisode":
		order = "m.added_at " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "viewed", "lastPlayed":
		order = "COALESCE(ums.last_played_at, '') " + recentDirection + ", m.sort_title ASC, m.id ASC"
	case "random":
		order = "m.random_key ASC, m.id ASC"
	}
	where := "WHERE m.library_id = ? AND m.parent_id IS NULL"
	args := []any{libraryID}
	progressPreferences := s.playbackProgressPreferencesForUserContext(ctx, userID)
	appliedTypeFilters := []string{}
	appliedFilters := []string{}
	filterParts := strings.Split(filterMode, ";")
	for _, part := range filterParts {
		part = strings.TrimSpace(part)
		if !strings.HasPrefix(part, "type:") {
			continue
		}
		var applied string
		where, args, applied = appendLibraryItemFilter(where, args, libraryID, part, progressPreferences)
		if applied != "" {
			appliedTypeFilters = append(appliedTypeFilters, applied)
		}
	}
	for _, part := range filterParts {
		part = strings.TrimSpace(part)
		if part == "" || part == "all" || strings.HasPrefix(part, "type:") {
			continue
		}
		var applied string
		where, args, applied = appendLibraryItemFilter(where, args, libraryID, part, progressPreferences)
		if applied != "" {
			appliedFilters = append(appliedFilters, applied)
		}
	}
	if len(appliedFilters) > 0 {
		filterMode = strings.Join(appliedFilters, ";")
	} else if len(appliedTypeFilters) > 0 {
		filterMode = strings.Join(appliedTypeFilters, ";")
	} else {
		filterMode = "all"
	}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	where, args = s.applyLibraryCurationRestrictionSQL(ctx, userID, where, args)
	if startAt != "" && startAt != "#" {
		where += " AND m.sort_title COLLATE NOCASE >= ?"
		args = append(args, startAt)
	}
	cursor = strings.TrimSpace(cursor)
	if cursor != "" {
		cursorValue, cursorSecondary, cursorID, err := decodeLibraryItemsCursor(cursor, sortMode, cursorFilterMode, titleDirection, startAt)
		if err != nil {
			return nil, 0, sortMode, filterMode, false, "", err
		}
		cursorSpec, ok := libraryItemsCursorSpecForSort(sortMode, titleDirection, recentDirection, ratingDirection)
		if !ok {
			return nil, 0, sortMode, filterMode, false, "", fmt.Errorf("%w: cursor pagination is not supported for %s sort", errInvalidLibraryCursor, sortMode)
		}
		where, args = appendLibraryItemsCursorPredicate(where, args, cursorSpec, cursorValue, cursorSecondary, cursorID)
		offset = 0
	}
	exactCount := strings.EqualFold(strings.TrimSpace(countMode), "exact") || strings.TrimSpace(countMode) == ""
	total := 0
	if exactCount {
		var err error
		total, err = s.countMediaForClauseContext(ctx, userID, where, args)
		if err != nil {
			return nil, 0, sortMode, filterMode, false, "", err
		}
	}
	pagedArgs := append([]any{}, args...)
	queryLimit := limit
	if !exactCount {
		queryLimit = limit + 1
	}
	pagedArgs = append(pagedArgs, queryLimit, offset)
	items, err := s.queryMediaListItemsContext(ctx, userID, where+" ORDER BY "+order+" LIMIT ? OFFSET ?", pagedArgs)
	if err != nil {
		return nil, 0, sortMode, filterMode, false, "", err
	}
	hasMore := false
	if exactCount {
		hasMore = offset+len(items) < total
	} else {
		hasMore = len(items) > limit
		if hasMore {
			items = items[:limit]
		}
		total = offset + len(items) + boolInt(hasMore)
	}
	nextCursor := ""
	if hasMore && len(items) > 0 {
		cursorValue, cursorSecondary, cursorID := libraryItemsCursorValues(items[len(items)-1], sortMode)
		nextCursor = encodeLibraryItemsCursor(sortMode, cursorFilterMode, titleDirection, startAt, cursorValue, cursorSecondary, cursorID)
	}
	return items, total, sortMode, filterMode, hasMore, nextCursor, nil
}

type librarySourceGroupAccumulator struct {
	group   LibrarySourceGroup
	itemIDs map[string]bool
}

func (s *Server) listLibrarySourceGroups(libraryID string) ([]LibrarySourceGroup, error) {
	groups, _, err := s.listLibrarySourceGroupsPage(libraryID, 250, 0)
	return groups, err
}

func (s *Server) listLibrarySourceGroupsPage(libraryID string, limit int, offset int) ([]LibrarySourceGroup, int, error) {
	limit = clampInt(limit, 1, 250)
	offset = max(0, offset)
	groups, hasMore, err := s.queryLibrarySourceGroupReadModel(libraryID, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	total := offset + len(groups) + boolInt(hasMore)
	if total > 0 {
		return groups, total, nil
	}
	s.queueLibraryReadModelRepair(libraryID)
	return groups, total, nil
}

func (s *Server) queryLibrarySourceGroupReadModel(libraryID string, limit int, offset int) ([]LibrarySourceGroup, bool, error) {
	limit = clampInt(limit, 1, 250)
	rows, err := s.queryUserRead(context.Background(), `
		SELECT kind, path, label, source_type, filter, item_count, file_count, missing_file_count, size_bytes
		FROM library_source_groups
		WHERE library_id = ?
		ORDER BY item_count DESC, kind ASC, label ASC
		LIMIT ? OFFSET ?`, libraryID, limit+1, max(0, offset))
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	groups := []LibrarySourceGroup{}
	for rows.Next() {
		var group LibrarySourceGroup
		if err := rows.Scan(&group.Kind, &group.Path, &group.Label, &group.SourceType, &group.Filter, &group.ItemCount, &group.FileCount, &group.MissingFileCount, &group.SizeBytes); err != nil {
			return nil, false, err
		}
		group.ID = librarySourceGroupID(group.Kind, group.Path)
		groups = append(groups, group)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	hasMore := len(groups) > limit
	if hasMore {
		groups = groups[:limit]
	}
	return groups, hasMore, nil
}

func (s *Server) rebuildLibrarySourceGroups(libraryID string) error {
	return s.rebuildLibrarySourceGroupsContext(context.Background(), libraryID)
}

func (s *Server) rebuildLibrarySourceGroupsContext(ctx context.Context, libraryID string) error {
	if ctx == nil {
		ctx = context.Background()
	}
	groups, err := s.computeLibrarySourceGroupsContext(ctx, libraryID)
	if err != nil {
		return err
	}
	if !s.waitForForegroundPressureToEase(ctx) {
		return ctx.Err()
	}
	now := time.Now().UTC().Format(time.RFC3339)
	return s.withBackgroundTxTagged(ctx, []string{"libraries", "library-items"}, func(tx *sql.Tx) error {
		if _, err := tx.Exec(`DELETE FROM library_source_groups WHERE library_id = ?`, libraryID); err != nil {
			return err
		}
		for _, group := range groups {
			if _, err := tx.Exec(`
				INSERT INTO library_source_groups (library_id, kind, path, label, source_type, filter, item_count, file_count, missing_file_count, size_bytes, updated_at)
				VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
				libraryID, group.Kind, group.Path, group.Label, group.SourceType, group.Filter, group.ItemCount, group.FileCount, group.MissingFileCount, group.SizeBytes, now); err != nil {
				return err
			}
		}
		return nil
	})
}

func (s *Server) computeLibrarySourceGroups(libraryID string) ([]LibrarySourceGroup, error) {
	return s.computeLibrarySourceGroupsContext(context.Background(), libraryID)
}

func (s *Server) computeLibrarySourceGroupsContext(ctx context.Context, libraryID string) ([]LibrarySourceGroup, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryBackgroundRead(ctx, `
		SELECT m.id, COALESCE(m.source_url, ''), COALESCE(f.path, ''), COALESCE(f.source_type, ''), COALESCE(f.size_bytes, 0), COALESCE(f.available, 1)
		FROM media_items m
		LEFT JOIN media_files f ON f.media_id = m.id
		WHERE m.library_id = ? AND m.parent_id IS NULL
		ORDER BY m.sort_title ASC, f.quality_rank DESC, f.size_bytes DESC`, libraryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	groups := map[string]*librarySourceGroupAccumulator{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var mediaID string
		var sourceURL string
		var filePath string
		var sourceType string
		var sizeBytes int64
		var available int
		if err := rows.Scan(&mediaID, &sourceURL, &filePath, &sourceType, &sizeBytes, &available); err != nil {
			return nil, err
		}
		group := librarySourceGroupFor(filePath, sourceType, sourceURL)
		if group.Path == "" {
			group.Path = "unmapped"
		}
		key := group.Kind + "\x00" + group.Path
		accumulator := groups[key]
		if accumulator == nil {
			group.ID = librarySourceGroupID(group.Kind, group.Path)
			group.Filter = librarySourceGroupFilter(group)
			accumulator = &librarySourceGroupAccumulator{group: group, itemIDs: map[string]bool{}}
			groups[key] = accumulator
		}
		if mediaID != "" && !accumulator.itemIDs[mediaID] {
			accumulator.itemIDs[mediaID] = true
			accumulator.group.ItemCount++
		}
		if filePath != "" {
			accumulator.group.FileCount++
			if available == 0 {
				accumulator.group.MissingFileCount++
			}
			accumulator.group.SizeBytes += sizeBytes
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	out := make([]LibrarySourceGroup, 0, len(groups))
	for _, accumulator := range groups {
		out = append(out, accumulator.group)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].ItemCount != out[j].ItemCount {
			return out[i].ItemCount > out[j].ItemCount
		}
		if out[i].Kind != out[j].Kind {
			return out[i].Kind < out[j].Kind
		}
		return out[i].Label < out[j].Label
	})
	return out, nil
}

func librarySourceGroupFor(filePath, sourceType, sourceURL string) LibrarySourceGroup {
	filePath = strings.TrimSpace(filePath)
	sourceType = strings.ToLower(strings.TrimSpace(sourceType))
	sourceURL = strings.TrimSpace(sourceURL)
	if sourceType == "" {
		sourceType = downloadSourceKind(sourceURL)
	}
	switch sourceType {
	case "remote":
		root := sourceRootForURL(firstNonEmpty(sourceURL, filePath))
		if root == "" {
			root = firstNonEmpty(sourceURL, filePath)
		}
		return LibrarySourceGroup{Kind: "remote", Label: sourceGroupLabel("Remote", root), Path: root, SourceType: "remote"}
	case "local", "":
		path := filePath
		if path == "" {
			path = localPathFromFileSourceURL(sourceURL)
		}
		root := sourceDirectory(path)
		if root == "" {
			root = firstNonEmpty(path, sourceURL, "unmapped")
		}
		return LibrarySourceGroup{Kind: "local", Label: sourceGroupLabel("Local", root), Path: root, SourceType: "local"}
	default:
		root := sourceRootForURL(firstNonEmpty(sourceURL, filePath))
		if root == "" {
			root = firstNonEmpty(filePath, sourceURL, "unmapped")
		}
		return LibrarySourceGroup{Kind: sourceType, Label: sourceGroupLabel(labelFromSourceKind(sourceType), root), Path: root, SourceType: sourceType}
	}
}

func librarySourceGroupID(kind, path string) string {
	sum := sha256.Sum256([]byte(kind + "\x00" + path))
	return "src_" + hex.EncodeToString(sum[:8])
}

func librarySourceGroupFilter(group LibrarySourceGroup) string {
	if group.Path == "" || group.Path == "unmapped" {
		return "source:" + group.Kind
	}
	return "sourcePath:" + group.Path
}

func sourceRootForURL(value string) string {
	parsed, err := url.Parse(strings.TrimSpace(value))
	if err != nil || parsed.Scheme == "" {
		return ""
	}
	if parsed.Scheme == "http" || parsed.Scheme == "https" {
		return parsed.Scheme + "://" + parsed.Host
	}
	if parsed.Scheme == "file" {
		return sourceDirectory(parsed.Path)
	}
	return parsed.Scheme + "://" + parsed.Host
}

func localPathFromFileSourceURL(value string) string {
	parsed, err := url.Parse(strings.TrimSpace(value))
	if err != nil || parsed.Scheme != "file" {
		return ""
	}
	return parsed.Path
}

func sourceDirectory(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	if strings.Contains(value, `\`) && !strings.Contains(value, `/`) {
		if idx := strings.LastIndex(value, `\`); idx > 0 {
			return value[:idx]
		}
		return value
	}
	dir := filepath.Dir(value)
	if dir == "." {
		return value
	}
	return dir
}

func sourceGroupLabel(prefix, root string) string {
	root = strings.TrimSpace(root)
	if root == "" || root == "unmapped" {
		return prefix + " unmapped"
	}
	if parsed, err := url.Parse(root); err == nil && parsed.Scheme != "" {
		if parsed.Host != "" {
			return prefix + " " + parsed.Host
		}
		return prefix + " " + parsed.Scheme
	}
	return prefix + " " + filepath.Base(root)
}

func labelFromSourceKind(kind string) string {
	switch strings.ToLower(strings.TrimSpace(kind)) {
	case "remote":
		return "Remote"
	case "local", "":
		return "Local"
	default:
		return strings.ToUpper(kind[:1]) + kind[1:]
	}
}

func appendLibraryItemFilter(where string, args []any, libraryID, filterMode string, progressPreferences PlaybackProgressPreferences) (string, []any, string) {
	switch filterMode {
	case "watchlisted":
		where += " AND ums.watchlisted = 1"
	case "inProgress", "in-progress", "resume":
		progressPreferences = normalizePlaybackProgressPreferences(progressPreferences)
		where += " AND COALESCE(ums.progress_seconds, 0) > 0 AND COALESCE(ums.watched, 0) = 0 AND (m.duration_seconds <= 0 OR ((COALESCE(ums.progress_seconds, 0) * 100.0 / m.duration_seconds) >= ? AND (COALESCE(ums.progress_seconds, 0) * 100.0 / m.duration_seconds) < ?))"
		args = append(args, progressPreferences.StartedThresholdPercent, progressPreferences.PlayedThresholdPercent)
		filterMode = "inProgress"
	case "favorite", "favorites":
		where += " AND ums.favorite = 1"
		filterMode = "favorites"
	case "unwatched":
		where += " AND COALESCE(ums.watched, 0) = 0"
	case "hdr", "4k", "uhd":
		where += " AND COALESCE(availability.has_hdr_source, 0) = 1"
		filterMode = "hdr"
	case "downloaded", "downloadable":
		where += " AND m.type NOT LIKE 'live%'"
		filterMode = "downloaded"
	case "recent":
		where += " AND m.added_at >= ?"
		args = append(args, time.Now().UTC().Add(-30*24*time.Hour).Format(time.RFC3339))
	case "matched":
		where += " AND EXISTS (SELECT 1 FROM media_provider_ids mpi WHERE mpi.media_id = m.id AND mpi.status = 'accepted')"
	case "unmatched":
		where += " AND NOT EXISTS (SELECT 1 FROM media_provider_ids mpi WHERE mpi.media_id = m.id AND mpi.status = 'accepted')"
	case "needsAttention", "needs-attention", "needs_attention":
		where += " AND (" + libraryNeedsAttentionSQL() + ")"
		filterMode = "needsAttention"
	case "missingArtwork", "missing-artwork", "missing_artwork":
		where += " AND (" + libraryMissingPosterSQL() + ")"
		filterMode = "missingArtwork"
	case "unavailable", "unavailableSource", "unavailable-source", "unavailable_source":
		where += " AND (" + libraryUnavailableSourceSQL() + ")"
		filterMode = "unavailable"
	case "duplicates", "duplicate":
		where += " AND EXISTS (" + libraryDuplicateSQL() + ")"
		filterMode = "duplicates"
	case "optimized", "optimizedVersions", "optimized-versions", "versions:optimized":
		where += " AND EXISTS (SELECT 1 FROM optimized_versions ov WHERE ov.media_id = m.id)"
		filterMode = "optimized"
	case "source:local", "local":
		where += " AND (" + librarySourceLocalSQL() + ")"
		filterMode = "source:local"
	case "source:remote", "remote":
		where += " AND (" + librarySourceRemoteSQL() + ")"
		filterMode = "source:remote"
	case "":
		filterMode = "all"
	default:
		if strings.HasPrefix(filterMode, "genre:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "genre:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND EXISTS (SELECT 1 FROM media_category_facets mcf WHERE mcf.media_id = m.id AND mcf.library_id = m.library_id AND mcf.facet_type = 'genre' AND mcf.sort_value = ?)"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "year:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "year:"))
			year, err := strconv.Atoi(value)
			if err != nil {
				filterMode = "all"
			} else {
				where += " AND m.year = ?"
				args = append(args, year)
			}
		} else if strings.HasPrefix(filterMode, "contentRating:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "contentRating:"))
			where += " AND m.content_rating = ?"
			args = append(args, value)
		} else if strings.HasPrefix(filterMode, "studio:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "studio:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_studio_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "artist:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "artist:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_artist_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "albumArtist:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "albumArtist:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_album_artist_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "trackArtist:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "trackArtist:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_track_artist_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "label:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "label:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_label_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "author:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "author:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_author_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "narrator:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "narrator:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_narrator_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "series:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "series:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_series_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "network:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "network:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND m.filter_network_key = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "show:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "show:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND lower(m.title) = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "season:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "season:"))
			if value == "" {
				filterMode = "all"
			} else {
				where = "WHERE m.library_id = ? AND lower(m.type) = 'season' AND lower(m.title) = ?"
				args = []any{libraryID, strings.ToLower(value)}
			}
		} else if strings.HasPrefix(filterMode, "country:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "country:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND lower(m.country) = ?"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "tag:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "tag:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND EXISTS (SELECT 1 FROM media_category_facets mcf WHERE mcf.media_id = m.id AND mcf.library_id = m.library_id AND mcf.facet_type = 'tag' AND mcf.sort_value = ?)"
				args = append(args, strings.ToLower(value))
			}
		} else if strings.HasPrefix(filterMode, "decade:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "decade:"))
			decade, err := strconv.Atoi(value)
			if err != nil {
				filterMode = "all"
			} else {
				where += " AND m.year >= ? AND m.year < ?"
				args = append(args, decade, decade+10)
			}
		} else if strings.HasPrefix(filterMode, "titleInitial:") {
			value := strings.ToUpper(strings.TrimSpace(strings.TrimPrefix(filterMode, "titleInitial:")))
			if value == "#" {
				where += " AND substr(upper(trim(m.sort_title)), 1, 1) GLOB '[0-9]'"
			} else if len(value) == 1 && value[0] >= 'A' && value[0] <= 'Z' {
				where += " AND substr(upper(trim(m.sort_title)), 1, 1) = ?"
				args = append(args, value)
			} else {
				filterMode = "all"
			}
		} else if strings.HasPrefix(filterMode, "rating:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "rating:"))
			if value == "top" {
				where += " AND (m.community_rating >= 8 OR m.critic_rating >= 85 OR COALESCE(ums.rating, 0) >= 8)"
			} else {
				filterMode = "all"
			}
		} else if strings.HasPrefix(filterMode, "audience:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "audience:"))
			if value == "family" {
				where += " AND upper(m.content_rating) IN ('G', 'PG', 'TV-G', 'TV-Y', 'TV-Y7', 'TV-PG')"
			} else {
				filterMode = "all"
			}
		} else if strings.HasPrefix(filterMode, "type:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "type:"))
			where = "WHERE m.library_id = ?"
			where += " AND lower(m.type) = ?"
			args = []any{libraryID, strings.ToLower(value)}
		} else if strings.HasPrefix(filterMode, "sourcePath:") {
			value := strings.TrimSpace(strings.TrimPrefix(filterMode, "sourcePath:"))
			if value == "" {
				filterMode = "all"
			} else {
				where += " AND (" + librarySourcePathSQL() + ")"
				pattern := sourcePathLikePattern(value)
				args = append(args, value, pattern, value, pattern, value, pattern)
				filterMode = "sourcePath:" + value
			}
		} else {
			filterMode = "all"
		}
	}
	if filterMode == "all" {
		return where, args, ""
	}
	return where, args, filterMode
}

func libraryNeedsAttentionSQL() string {
	return strings.Join([]string{
		"NOT EXISTS (SELECT 1 FROM media_provider_ids mpi WHERE mpi.media_id = m.id AND mpi.status = 'accepted')",
		libraryMissingPosterSQL(),
		"(m.type IN ('movie', 'episode', 'track', 'audiobook', 'extra') AND COALESCE(m.duration_seconds, 0) <= 0)",
		libraryUnavailableSourceSQL(),
		libraryRawTitleSQL("m.title"),
	}, " OR ")
}

func libraryMissingPosterSQL() string {
	return `
		m.type IN ('movie', 'show', 'season', 'album', 'artist', 'audiobook')
		AND trim(COALESCE(
			NULLIF(json_extract(CASE WHEN json_valid(m.artwork_json) THEN m.artwork_json ELSE '{}' END, '$.posterPath'), ''),
			NULLIF(json_extract(CASE WHEN json_valid(m.artwork_json) THEN m.artwork_json ELSE '{}' END, '$.poster'), ''),
			''
		)) = ''
		AND NOT EXISTS (SELECT 1 FROM media_images i WHERE i.media_id = m.id AND i.image_type = 'poster')`
}

func libraryUnavailableSourceSQL() string {
	return `
		m.type IN ('movie', 'episode', 'track', 'audiobook', 'extra')
		AND (
			COALESCE(availability.missing_file_count, 0) > 0
			OR (trim(COALESCE(m.source_url, '')) = '' AND COALESCE(availability.available_file_count, 0) = 0)
		)`
}

func libraryDuplicateSQL() string {
	return `
		SELECT 1
		FROM media_items d
		WHERE d.library_id = m.library_id
			AND d.id <> m.id
			AND lower(trim(d.type)) = lower(trim(m.type))
			AND lower(trim(COALESCE(NULLIF(d.sort_title, ''), d.title))) = lower(trim(COALESCE(NULLIF(m.sort_title, ''), m.title)))
			AND COALESCE(NULLIF(d.year, 0), 0) = COALESCE(NULLIF(m.year, 0), 0)`
}

func librarySourceLocalSQL() string {
	return `COALESCE(availability.has_local_source, 0) = 1`
}

func librarySourceRemoteSQL() string {
	return `COALESCE(availability.has_remote_source, 0) = 1`
}

func librarySourcePathSQL() string {
	return `
		EXISTS (
			SELECT 1 FROM media_files f
			WHERE f.media_id = m.id
				AND (
					trim(COALESCE(f.path, '')) = ?
					OR trim(COALESCE(f.path, '')) LIKE ? ESCAPE '\'
					OR trim(COALESCE(f.source, '')) = ?
					OR trim(COALESCE(f.source, '')) LIKE ? ESCAPE '\'
				)
		)
		OR trim(COALESCE(m.source_url, '')) = ?
		OR trim(COALESCE(m.source_url, '')) LIKE ? ESCAPE '\'`
}

func sourcePathLikePattern(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	if strings.Contains(value, "://") {
		if strings.HasSuffix(value, "://") {
			return sqlLikeEscape(value) + "%"
		}
		return sqlLikeEscape(strings.TrimRight(value, "/")+"/") + "%"
	}
	if strings.Contains(value, `\`) && !strings.Contains(value, `/`) {
		trimmed := strings.TrimRight(value, `\`)
		if trimmed == "" {
			return "%"
		}
		return sqlLikeEscape(trimmed+`\`) + "%"
	}
	trimmed := strings.TrimRight(value, "/")
	if trimmed == "" {
		return sqlLikeEscape("/") + "%"
	}
	return sqlLikeEscape(trimmed+"/") + "%"
}

func sqlLikeEscape(value string) string {
	var builder strings.Builder
	builder.Grow(len(value))
	for _, char := range value {
		if char == '\\' || char == '%' || char == '_' {
			builder.WriteRune('\\')
		}
		builder.WriteRune(char)
	}
	return builder.String()
}

func libraryRawTitleSQL(column string) string {
	return "(" + strings.Join([]string{
		"lower(" + column + ") LIKE '%.1080p.%'",
		"lower(" + column + ") LIKE '%.720p.%'",
		"lower(" + column + ") LIKE '%.2160p.%'",
		"lower(" + column + ") LIKE '%web-dl%'",
		"lower(" + column + ") LIKE '%webrip%'",
		"lower(" + column + ") LIKE '%bluray%'",
		"lower(" + column + ") LIKE '%x264%'",
		"lower(" + column + ") LIKE '%x265%'",
		"lower(" + column + ") LIKE '%h.264%'",
		"lower(" + column + ") LIKE '%h.265%'",
		"lower(" + column + ") LIKE '%dvdrip%'",
		"lower(" + column + ") LIKE '%hdrip%'",
		"lower(" + column + ") LIKE '%proper%'",
		"lower(" + column + ") LIKE '%repack%'",
	}, " OR ") + ")"
}

func sortDirection(orderMode, fallback string) string {
	switch strings.ToLower(strings.TrimSpace(orderMode)) {
	case "asc":
		return "ASC"
	case "desc":
		return "DESC"
	}
	if strings.EqualFold(fallback, "desc") {
		return "DESC"
	}
	return "ASC"
}

func mediaRandomKey(id string) string {
	hash := fnv.New64a()
	_, _ = hash.Write([]byte(strings.TrimSpace(id)))
	return fmt.Sprintf("%016x", hash.Sum64())
}

func (s *Server) countMediaForClause(userID, where string, args []any) (int, error) {
	return s.countMediaForClauseContext(context.Background(), userID, where, args)
}

func (s *Server) countMediaForClauseContext(ctx context.Context, userID, where string, args []any) (int, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	query := `
		SELECT COUNT(*)
		FROM media_items m
		LEFT JOIN user_media_state ums ON ums.media_id = m.id AND ums.profile_id = ?
		LEFT JOIN media_availability availability ON availability.media_id = m.id
		` + where
	_, profileID := s.accountAndProfileIDsContext(ctx, userID)
	queryArgs := append([]any{profileID}, args...)
	var total int
	err := s.queryUserRow(ctx, query, queryArgs...).Scan(&total)
	return total, err
}

type dashboardFilters struct {
	Mode      string
	Period    string
	UserID    string
	LibraryID string
	MediaType string
	Sections  []string
	Since     time.Time
}

type playbackHistoryFilters struct {
	UserID          string
	LibraryID       string
	MediaType       string
	Query           string
	Period          string
	Limit           int
	Offset          int
	Since           time.Time
	CountMode       string
	CursorStartedAt string
	CursorID        string
}

func dashboardFiltersFromRequest(r *http.Request) dashboardFilters {
	query := r.URL.Query()
	mode := strings.ToLower(strings.TrimSpace(query.Get("mode")))
	if mode != "history" {
		mode = "live"
	}
	period := strings.ToLower(strings.TrimSpace(query.Get("period")))
	if period == "" {
		if mode == "history" {
			period = "24h"
		} else {
			period = "5m"
		}
	}
	switch period {
	case "5m", "1h", "6h", "24h", "7d", "30d":
	default:
		if mode == "live" {
			period = "5m"
		} else {
			period = "24h"
		}
	}
	return dashboardFilters{
		Mode:      mode,
		Period:    period,
		UserID:    strings.TrimSpace(query.Get("userId")),
		LibraryID: strings.TrimSpace(query.Get("libraryId")),
		MediaType: strings.TrimSpace(query.Get("type")),
		Sections:  dashboardSectionsFromQuery(query.Get("sections")),
	}
}

func dashboardOverviewUsageFiltersFromRequest(r *http.Request, prefix string, section string, defaultPeriod string) dashboardFilters {
	query := r.URL.Query()
	period := strings.ToLower(strings.TrimSpace(query.Get(prefix + "Period")))
	if period == "" {
		period = defaultPeriod
	}
	switch period {
	case "1h", "6h", "24h", "7d", "30d":
	default:
		period = defaultPeriod
	}
	filters := dashboardFilters{
		Mode:      "history",
		Period:    period,
		UserID:    strings.TrimSpace(query.Get(prefix + "UserId")),
		LibraryID: strings.TrimSpace(query.Get(prefix + "LibraryId")),
		MediaType: strings.TrimSpace(query.Get(prefix + "Type")),
		Sections:  []string{section},
	}
	if filters.UserID == "all" {
		filters.UserID = ""
	}
	if filters.LibraryID == "all" {
		filters.LibraryID = ""
	}
	if filters.MediaType == "all" {
		filters.MediaType = ""
	}
	return filters
}

func dashboardSectionsFromQuery(value string) []string {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	allowed := map[string]string{
		"core":         "core",
		"overview":     "core",
		"live":         "core",
		"bandwidth":    "bandwidth",
		"sessions":     "sessions",
		"session":      "sessions",
		"active":       "sessions",
		"nowplaying":   "sessions",
		"now_playing":  "sessions",
		"topusers":     "topUsers",
		"top_users":    "topUsers",
		"users":        "topUsers",
		"playhistory":  "playHistory",
		"play_history": "playHistory",
		"history":      "playHistory",
		"topplayed":    "topPlayed",
		"top_played":   "topPlayed",
		"played":       "topPlayed",
	}
	seen := map[string]bool{}
	sections := []string{}
	for _, token := range strings.Split(value, ",") {
		key := strings.ToLower(strings.ReplaceAll(strings.TrimSpace(token), "-", ""))
		if key == "" {
			continue
		}
		section, ok := allowed[key]
		if !ok || seen[section] {
			continue
		}
		seen[section] = true
		sections = append(sections, section)
	}
	return sections
}

func (filters dashboardFilters) wantsDashboardSection(section string) bool {
	if len(filters.Sections) == 0 {
		return true
	}
	for _, candidate := range filters.Sections {
		if candidate == section {
			return true
		}
	}
	return false
}

func (filters dashboardFilters) wantsDashboardHistory() bool {
	return filters.wantsDashboardSection("topUsers") ||
		filters.wantsDashboardSection("playHistory") ||
		filters.wantsDashboardSection("topPlayed")
}

func dashboardSectionsCacheKey(sections []string) string {
	if len(sections) == 0 {
		return "all"
	}
	return strings.Join(sections, ",")
}

func playbackHistoryFiltersFromRequest(r *http.Request) playbackHistoryFilters {
	query := r.URL.Query()
	limit, offset := paginationFromRequest(r, 100, 500)
	filters := playbackHistoryFilters{
		UserID:    strings.TrimSpace(query.Get("userId")),
		LibraryID: strings.TrimSpace(query.Get("libraryId")),
		MediaType: strings.TrimSpace(query.Get("type")),
		Query:     strings.TrimSpace(query.Get("query")),
		Period:    strings.ToLower(strings.TrimSpace(query.Get("period"))),
		Limit:     limit,
		Offset:    offset,
		CountMode: strings.ToLower(strings.TrimSpace(query.Get("count"))),
	}
	if filters.CountMode != "exact" {
		filters.CountMode = "none"
	}
	if filters.Period == "" {
		filters.Period = "30d"
	}
	now := time.Now().UTC()
	switch filters.Period {
	case "24h":
		filters.Since = now.Add(-24 * time.Hour)
	case "7d":
		filters.Since = now.Add(-7 * 24 * time.Hour)
	case "30d":
		filters.Since = now.Add(-30 * 24 * time.Hour)
	case "90d":
		filters.Since = now.Add(-90 * 24 * time.Hour)
	case "all":
	default:
		filters.Period = "30d"
		filters.Since = now.Add(-30 * 24 * time.Hour)
	}
	return filters
}

func (filters dashboardFilters) withSince(now time.Time) dashboardFilters {
	switch filters.Period {
	case "5m":
		filters.Since = now.Add(-dashboardLivePeriod)
	case "1h":
		filters.Since = now.Add(-time.Hour)
	case "6h":
		filters.Since = now.Add(-6 * time.Hour)
	case "7d":
		filters.Since = now.Add(-7 * 24 * time.Hour)
	case "30d":
		filters.Since = now.Add(-30 * 24 * time.Hour)
	default:
		filters.Since = now.Add(-24 * time.Hour)
		filters.Period = "24h"
	}
	return filters
}

func (s *Server) cachedDashboard(ctx context.Context, user User, filters dashboardFilters) (DashboardResponse, error) {
	key := dashboardCacheKey(user, filters)
	if key == "" {
		return s.loadDashboardContext(ctx, user, filters)
	}
	now := time.Now()
	s.dashboardCacheMu.Lock()
	if entry, ok := s.dashboardCache[key]; ok && now.Before(entry.expiresAt) {
		response := entry.response
		s.dashboardCacheMu.Unlock()
		return response, nil
	}
	if s.dashboardInFlight == nil {
		s.dashboardInFlight = map[string]chan struct{}{}
	}
	if wait, ok := s.dashboardInFlight[key]; ok {
		s.dashboardCacheMu.Unlock()
		select {
		case <-wait:
		case <-ctx.Done():
			return DashboardResponse{}, ctx.Err()
		}
		s.dashboardCacheMu.Lock()
		if entry, ok := s.dashboardCache[key]; ok && time.Now().Before(entry.expiresAt) {
			response := entry.response
			s.dashboardCacheMu.Unlock()
			return response, nil
		}
		s.dashboardCacheMu.Unlock()
		return s.loadDashboardContext(ctx, user, filters)
	}
	wait := make(chan struct{})
	s.dashboardInFlight[key] = wait
	s.dashboardCacheMu.Unlock()

	response, err := s.loadDashboardContext(ctx, user, filters)
	s.dashboardCacheMu.Lock()
	if s.dashboardInFlight[key] == wait {
		delete(s.dashboardInFlight, key)
		close(wait)
	}
	if err != nil {
		s.dashboardCacheMu.Unlock()
		return DashboardResponse{}, err
	}
	if s.dashboardCache == nil {
		s.dashboardCache = map[string]dashboardCacheEntry{}
	}
	s.dashboardCache[key] = dashboardCacheEntry{
		response:  response,
		expiresAt: now.Add(dashboardCacheTTL(filters)),
	}
	s.dashboardCacheMu.Unlock()
	return response, nil
}

func (s *Server) cachedServerActivity(ctx context.Context) (ServerActivityResponse, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	now := time.Now()
	s.serverActivityMu.Lock()
	if now.Before(s.serverActivityCache.expiresAt) {
		response := s.serverActivityCache.response
		s.serverActivityMu.Unlock()
		return response, nil
	}
	if wait := s.serverActivityInFlight; wait != nil {
		s.serverActivityMu.Unlock()
		select {
		case <-wait:
		case <-ctx.Done():
			return ServerActivityResponse{}, ctx.Err()
		}
		s.serverActivityMu.Lock()
		if time.Now().Before(s.serverActivityCache.expiresAt) {
			response := s.serverActivityCache.response
			s.serverActivityMu.Unlock()
			return response, nil
		}
		s.serverActivityMu.Unlock()
		return s.loadServerActivityContext(ctx)
	}
	wait := make(chan struct{})
	s.serverActivityInFlight = wait
	s.serverActivityMu.Unlock()

	response, err := s.loadServerActivityContext(ctx)
	s.serverActivityMu.Lock()
	if s.serverActivityInFlight == wait {
		s.serverActivityInFlight = nil
		close(wait)
	}
	if err != nil {
		s.serverActivityMu.Unlock()
		return ServerActivityResponse{}, err
	}
	s.serverActivityCache = serverActivityCacheEntry{
		response:  response,
		expiresAt: now.Add(serverActivityCacheTTL),
	}
	s.serverActivityMu.Unlock()
	return response, nil
}

