func (s *Server) missingMediaLyricLookupSeedsContext(ctx context.Context, userID, libraryID string, limit int) ([]MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	libraryID = strings.TrimSpace(libraryID)
	if libraryID == "" {
		return nil, sql.ErrNoRows
	}
	if limit <= 0 {
		limit = 250
	}
	where, args := s.applyMediaVisibilityRestrictionSQL(userID, `
		m.library_id = ?
		AND m.type = 'track'
		AND NOT EXISTS (SELECT 1 FROM media_lyrics ml WHERE ml.media_id = m.id)`, []any{libraryID})
	where, args = s.applyLibraryCurationRestrictionSQL(ctx, userID, where, args)
	args = append(args, limit)
	rows, err := s.queryUserRead(ctx, `
		SELECT
			m.id, COALESCE(m.library_id, ''), m.type, m.title, m.sort_title, COALESCE(m.content_rating, ''),
			COALESCE(m.duration_seconds, 0), COALESCE(m.studio, ''), COALESCE(m.typed_metadata_json, '{}'),
			COALESCE(parent.title, ''), COALESCE(grandparent.title, '')
		FROM media_items m
		LEFT JOIN media_items parent ON parent.id = m.parent_id
		LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
		WHERE `+where+`
		ORDER BY m.added_at ASC
		LIMIT ?`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := make([]MediaItem, 0, limit)
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var item MediaItem
		var typedMetadataJSON string
		if err := rows.Scan(
			&item.ID, &item.LibraryID, &item.Type, &item.Title, &item.SortTitle, &item.ContentRating,
			&item.DurationSeconds, &item.Studio, &typedMetadataJSON, &item.ParentTitle, &item.GrandparentTitle,
		); err != nil {
			return nil, err
		}
		_ = json.Unmarshal([]byte(typedMetadataJSON), &item.TypedMetadata)
		item.TypedMetadata = sanitizeTypedMetadataForType(item.Type, normalizeTypedMetadataMap(item.TypedMetadata))
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

func (s *Server) getMediaPlaybackDetailForUser(ctx context.Context, user User, id string) (MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	user = s.hydratePlaybackVisibilityUserContext(ctx, user)
	id = strings.TrimSpace(id)
	if id == "" {
		return MediaItem{}, sql.ErrNoRows
	}
	where, args := s.applyMediaVisibilityRestrictionSQL(viewerProfileID(user), "m.id = ?", []any{id})
	where, args = s.applyLibraryCurationRestrictionSQL(ctx, viewerProfileID(user), where, args)
	query := `
		SELECT
			m.id, COALESCE(m.metadata_revision, 0), COALESCE(m.metadata_etag, ''), COALESCE(m.library_id, ''), COALESCE(m.parent_id, ''), m.type, m.title, m.sort_title,
			m.original_title, m.edition, m.year, m.duration_seconds, m.summary, m.tagline,
			m.content_rating, m.community_rating, m.critic_rating, m.studio, m.network, m.country,
			m.genres_json, m.tags_json, m.labels_json, m.added_at, m.season_number, m.episode_number,
			m.index_number, m.art_seed, COALESCE(m.artwork_json, '{}'), COALESCE(m.typed_metadata_json, '{}'), m.source_url,
			COALESCE(ums.watchlisted, 0), COALESCE(ums.favorite, 0), COALESCE(ums.liked, 0), COALESCE(ums.watched, 0), COALESCE(ums.progress_seconds, 0),
			COALESCE(ums.rating, 0), COALESCE(ums.last_played_at, ''),
			COALESCE(parent.title, ''), COALESCE(grandparent.id, ''), COALESCE(grandparent.title, ''),
			COALESCE(availability.file_count, 0),
			COALESCE(availability.missing_file_count, 0),
			COALESCE(m.sort_artist_key, ''), COALESCE(m.sort_album_artist_key, ''), COALESCE(m.sort_track_artist_key, ''),
			COALESCE(m.sort_author_key, ''), COALESCE(m.sort_narrator_key, ''), COALESCE(m.random_key, '')
		FROM media_items m
		LEFT JOIN user_media_state ums ON ums.media_id = m.id AND ums.profile_id = ?
		LEFT JOIN media_items parent ON parent.id = m.parent_id
		LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
		LEFT JOIN media_availability availability ON availability.media_id = m.id
		WHERE ` + where + `
		LIMIT 1`
	var item MediaItem
	var genresJSON string
	var tagsJSON string
	var labelsJSON string
	var artworkJSON string
	var typedMetadataJSON string
	var watchlisted, favorite, liked, watched int
	queryArgs := append([]any{viewerProfileID(user)}, args...)
	err := s.queryUserRow(ctx, query, queryArgs...).Scan(
		&item.ID, &item.MetadataRevision, &item.MetadataETag, &item.LibraryID, &item.ParentID, &item.Type, &item.Title, &item.SortTitle,
		&item.OriginalTitle, &item.Edition, &item.Year, &item.DurationSeconds, &item.Summary, &item.Tagline,
		&item.ContentRating, &item.CommunityRating, &item.CriticRating, &item.Studio, &item.Network, &item.Country,
		&genresJSON, &tagsJSON, &labelsJSON, &item.AddedAt, &item.SeasonNumber,
		&item.EpisodeNumber, &item.IndexNumber, &item.ArtSeed, &artworkJSON, &typedMetadataJSON, &item.SourceURL,
		&watchlisted, &favorite, &liked, &watched, &item.State.ProgressSeconds, &item.State.Rating, &item.State.LastPlayedAt,
		&item.ParentTitle, &item.GrandparentID, &item.GrandparentTitle,
		&item.FileCount, &item.MissingFileCount,
		&item.SortArtistKey, &item.SortAlbumArtistKey, &item.SortTrackArtistKey,
		&item.SortAuthorKey, &item.SortNarratorKey, &item.RandomKey,
	)
	if err != nil {
		return MediaItem{}, err
	}
	_ = json.Unmarshal([]byte(genresJSON), &item.Genres)
	_ = json.Unmarshal([]byte(tagsJSON), &item.Tags)
	_ = json.Unmarshal([]byte(labelsJSON), &item.Labels)
	_ = json.Unmarshal([]byte(artworkJSON), &item.Artwork)
	_ = json.Unmarshal([]byte(typedMetadataJSON), &item.TypedMetadata)
	item.TypedMetadata = sanitizeTypedMetadataForType(item.Type, normalizeTypedMetadataMap(item.TypedMetadata))
	item.State.Watchlisted = watchlisted == 1
	item.State.Favorite = favorite == 1
	item.State.Reaction = reactionName(liked)
	item.State.Watched = watched == 1
	item.Missing = item.FileCount > 0 && item.FileCount == item.MissingFileCount
	item.Images = imageSetFor(item.ID, item.ArtSeed, item.Title, item.Artwork)
	if !userCanSeeMediaItem(user, item) {
		return MediaItem{}, sql.ErrNoRows
	}
	if err := s.authorizeMappedDVRMediaForUser(ctx, user, item.ID); err != nil {
		return MediaItem{}, sql.ErrNoRows
	}
	applyPlaybackProgressDisplayPolicy(&item, user.Preferences.PlaybackProgress)
	streams, err := s.listStreamsContext(ctx, item.ID)
	if err != nil {
		return MediaItem{}, err
	}
	item.Streams = streams
	item.AudioNormalization = s.audioNormalizationForMediaContext(ctx, item.ID)
	item.MediaFiles = s.primaryMediaFileForPlaybackContext(ctx, item.ID, item.SourceURL)
	s.applyTVBackdropFallbacksContext(ctx, &item)
	applyMediaActionsToItem(&item, user)
	return item, nil
}

func (s *Server) hydratePlaybackVisibilityUserContext(ctx context.Context, user User) User {
	if strings.TrimSpace(user.ID) == "" {
		return user
	}
	if ctx == nil {
		ctx = context.Background()
	}
	accountID := accountIDForUser(user)
	profileID := viewerProfileID(user)
	if principal, err := s.resolveRequestPrincipalContext(ctx, accountID, profileID); err == nil {
		applyRequestPrincipal(&user, principal)
	}
	needsUserRow := strings.TrimSpace(user.Role) == "" || isEmptyPlaybackProgressPreferences(user.Preferences.PlaybackProgress)
	needsLibraries := user.Role != "owner" && len(user.LibraryIDs) == 0
	if !needsUserRow && !needsLibraries {
		return user
	}
	if needsUserRow {
		var role string
		var preferencesJSON string
		var maxContentRating string
		var maxActiveSessions int
		var maxActiveStreams int
		var remoteBitrateLimitMbps int
		err := s.queryUserRow(ctx, `
			SELECT role, preferences_json, COALESCE(max_content_rating, ''), COALESCE(max_active_sessions, 0), COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0)
			FROM users
			WHERE id = ?`, user.ID).Scan(&role, &preferencesJSON, &maxContentRating, &maxActiveSessions, &maxActiveStreams, &remoteBitrateLimitMbps)
		if err == nil {
			user.Role = role
			user.MaxContentRating = maxContentRating
			user.MaxActiveSessions = maxActiveSessions
			user.MaxActiveStreams = maxActiveStreams
			user.RemoteBitrateLimitMbps = remoteBitrateLimitMbps
			applyStoredUserPreferences(&user, preferencesJSON)
		}
	}
	if user.Role != "owner" && len(user.LibraryIDs) == 0 {
		if allowed, err := s.userLibraryAccessSetContext(ctx, user.ID); err == nil {
			user.LibraryIDs = make([]string, 0, len(allowed))
			for libraryID := range allowed {
				user.LibraryIDs = append(user.LibraryIDs, libraryID)
			}
			sort.Strings(user.LibraryIDs)
		}
	}
	return user
}

func userCanSeeMediaItem(user User, item MediaItem) bool {
	if strings.TrimSpace(user.ID) == "" {
		return true
	}
	if user.Role != "owner" && (len(user.LibraryIDs) == 0 || !stringListContains(user.LibraryIDs, item.LibraryID)) {
		return false
	}
	if !contentRatingAllowed(item.ContentRating, normalizeMaxContentRating(user.MaxContentRating)) {
		return false
	}
	if !mediaItemAllowedByTagPolicy(item, user.TagPolicy) {
		return false
	}
	if strings.TrimSpace(user.ProfileID) == "" {
		return true
	}
	return profileMediaPolicyAllows(RequestPrincipal{
		MaximumAgeRating: user.MaximumAgeRating,
		AllowUnrated:     user.AllowUnrated,
		BlockedLabels:    user.BlockedProfileLabels,
	}, item)
}

func stringListContains(values []string, needle string) bool {
	needle = strings.TrimSpace(needle)
	if needle == "" {
		return false
	}
	for _, value := range values {
		if strings.TrimSpace(value) == needle {
			return true
		}
	}
	return false
}

func (s *Server) getMediaDetailShell(userID, id string) (MediaItem, error) {
	return s.getMediaDetailWithOptions(userID, id, mediaDetailOptions{Recommendations: false})
}

func (s *Server) getMediaDetailShellContext(ctx context.Context, userID, id string) (MediaItem, error) {
	return s.getMediaDetailWithOptionsContext(ctx, userID, id, mediaDetailOptions{Recommendations: false})
}

type mediaDetailOptions struct {
	Recommendations bool
	Playback        bool
}

const (
	maxDetailDirectChildren         = 500
	maxDetailChildGroups            = 100
	maxDetailNestedChildrenTotal    = 500
	maxDetailNestedChildrenPerGroup = 100
)

func (s *Server) getMediaDetailWithOptions(userID, id string, options mediaDetailOptions) (MediaItem, error) {
	return s.getMediaDetailWithOptionsContext(context.Background(), userID, id, options)
}

func (s *Server) cachedMediaDetailWithOptionsContext(ctx context.Context, user User, id string, options mediaDetailOptions) (MediaItem, error) {
	userID := viewerProfileID(user)
	key := mediaDetailCacheKey(user, id, options)
	if key != "" && !options.Recommendations && !options.Playback {
		if hasState, err := s.profileHasMediaStateContext(ctx, userID); err == nil && !hasState {
			key = strings.Join([]string{emptyMediaStateCacheScope(user, false), strings.TrimSpace(id), "false", "false"}, "\x00")
		}
	}
	if key == "" {
		return s.getMediaDetailWithOptionsContext(ctx, userID, id, options)
	}
	now := time.Now()
	s.mediaDetailCacheMu.Lock()
	if entry, ok := s.mediaDetailCache[key]; ok && now.Before(entry.expiresAt) {
		item := entry.item
		s.mediaDetailCacheMu.Unlock()
		return item, nil
	}
	if s.mediaDetailInFlight == nil {
		s.mediaDetailInFlight = map[string]chan struct{}{}
	}
	if wait, ok := s.mediaDetailInFlight[key]; ok {
		s.mediaDetailCacheMu.Unlock()
		select {
		case <-wait:
		case <-ctx.Done():
			return MediaItem{}, ctx.Err()
		}
		s.mediaDetailCacheMu.Lock()
		if entry, ok := s.mediaDetailCache[key]; ok && time.Now().Before(entry.expiresAt) {
			item := entry.item
			s.mediaDetailCacheMu.Unlock()
			return item, nil
		}
		s.mediaDetailCacheMu.Unlock()
		return s.getMediaDetailWithOptionsContext(ctx, userID, id, options)
	}
	wait := make(chan struct{})
	s.mediaDetailInFlight[key] = wait
	s.mediaDetailCacheMu.Unlock()

	item, err := s.getMediaDetailWithOptionsContext(ctx, userID, id, options)
	s.mediaDetailCacheMu.Lock()
	if s.mediaDetailInFlight[key] == wait {
		delete(s.mediaDetailInFlight, key)
		close(wait)
	}
	if err == nil {
		if s.mediaDetailCache == nil {
			s.mediaDetailCache = map[string]mediaDetailCacheEntry{}
		}
		for cachedKey, entry := range s.mediaDetailCache {
			if !now.Before(entry.expiresAt) {
				delete(s.mediaDetailCache, cachedKey)
			}
		}
		for len(s.mediaDetailCache) >= 1024 {
			for cachedKey := range s.mediaDetailCache {
				delete(s.mediaDetailCache, cachedKey)
				break
			}
		}
		s.mediaDetailCache[key] = mediaDetailCacheEntry{item: item, expiresAt: time.Now().Add(mediaDetailCacheTTL)}
	}
	s.mediaDetailCacheMu.Unlock()
	return item, err
}

func mediaDetailCacheKey(user User, id string, options mediaDetailOptions) string {
	userID := strings.TrimSpace(viewerProfileID(user))
	id = strings.TrimSpace(id)
	if userID == "" || id == "" {
		return ""
	}
	return strings.Join([]string{
		userID,
		effectiveAuthorizationCacheFingerprint(user),
		id,
		strconv.FormatBool(options.Recommendations),
		strconv.FormatBool(options.Playback),
	}, "\x00")
}

func (s *Server) invalidateMediaDetailCache() {
	s.mediaDetailCacheMu.Lock()
	defer s.mediaDetailCacheMu.Unlock()
	if len(s.mediaDetailCache) > 0 {
		s.mediaDetailCache = map[string]mediaDetailCacheEntry{}
	}
}

func (s *Server) invalidateMediaDetailCacheForProfile(profileID string) {
	profileID = strings.TrimSpace(profileID)
	if profileID == "" {
		s.invalidateMediaDetailCache()
		return
	}
	prefix := profileID + "\x00"
	s.mediaDetailCacheMu.Lock()
	for key := range s.mediaDetailCache {
		if strings.HasPrefix(key, prefix) {
			delete(s.mediaDetailCache, key)
		}
	}
	s.mediaDetailCacheMu.Unlock()
}

func (s *Server) invalidateMediaDetailCacheForMedia(mediaID string) {
	mediaID = strings.TrimSpace(mediaID)
	if mediaID == "" {
		return
	}
	s.mediaDetailCacheMu.Lock()
	for key := range s.mediaDetailCache {
		parts := strings.Split(key, "\x00")
		if len(parts) >= 3 && parts[2] == mediaID {
			delete(s.mediaDetailCache, key)
		}
	}
	s.mediaDetailCacheMu.Unlock()
}

func (s *Server) getMediaDetailWithOptionsContext(ctx context.Context, userID, id string, options mediaDetailOptions) (MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if strings.HasPrefix(strings.TrimSpace(id), "aent_") {
		identity, identityErr := s.virtualAudiobookFacetIdentityContext(ctx, id)
		if identityErr == nil {
			return s.virtualAudiobookFacetDetailContext(ctx, userID, identity)
		}
		if !errors.Is(identityErr, sql.ErrNoRows) {
			return MediaItem{}, identityErr
		}
	}
	item, err := s.getMediaContext(ctx, userID, id)
	if err != nil {
		return MediaItem{}, err
	}
	streams, err := s.listStreamsContext(ctx, id)
	if err != nil {
		return MediaItem{}, err
	}
	item.Streams = streams
	item.AudioNormalization = s.audioNormalizationForMediaContext(ctx, item.ID)
	item.MediaFiles = s.mediaFilesWithStreamsContext(ctx, item.ID, item.SourceURL, streams)
	s.attachResumeInfo(&item)
	if !options.Playback {
		item.Attachments = s.attachmentsForMediaContext(ctx, item.ID)
		item.Segments = s.segmentsForMediaContext(ctx, item.ID)
		if versions, err := s.optimizedVersionsForMediaContext(ctx, item.ID); err == nil {
			item.OptimizedVersions = versions
		}
		children, truncated, err := s.childrenForDetail(ctx, userID, item)
		if err != nil {
			return MediaItem{}, err
		}
		if err := s.attachDetailChildNarrativesContext(ctx, children); err != nil {
			return MediaItem{}, err
		}
		extraChildren, err := s.extraChildrenForDetail(ctx, userID, item.ID)
		if err != nil {
			return MediaItem{}, err
		}
		if err := s.attachDetailChildNarrativesContext(ctx, extraChildren); err != nil {
			return MediaItem{}, err
		}
		item.Children = children
		item.ChildrenTruncated = truncated
		item.PlaybackTarget, err = s.mediaContainerPlaybackTargetContext(ctx, userID, item, children)
		if err != nil {
			return MediaItem{}, err
		}
		item.Extras = mediaExtraRelationships(extraChildren)
		item.Chapters = s.chaptersForMediaContext(ctx, item.ID)
		s.attachMediaMetadataEvidenceContext(ctx, &item)
	}
	if options.Recommendations {
		item.RecommendationRows = s.mediaRecommendationRowsContext(ctx, userID, item)
	}
	return item, nil
}

func (s *Server) virtualAudiobookFacetWhere(userID string, identity virtualAudiobookFacetIdentity) (string, []any, bool) {
	if identity.ID == "" || identity.LibraryID == "" {
		return "", nil, false
	}
	if _, ok := canonicalAudiobookFacetKind(identity.EntityKind); !ok {
		return "", nil, false
	}
	where := `WHERE m.library_id = ? AND lower(m.type) = 'audiobook' AND EXISTS (
		SELECT 1 FROM audiobook_browse_entity_members browse_member
		WHERE browse_member.entity_id = ? AND browse_member.entity_kind = ? AND browse_member.media_id = m.id
	)`
	args := []any{identity.LibraryID, identity.ID, identity.EntityKind}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	return where, args, true
}

func (s *Server) virtualAudiobookFacetDetailContext(ctx context.Context, userID string, identity virtualAudiobookFacetIdentity) (MediaItem, error) {
	where, args, ok := s.virtualAudiobookFacetWhere(userID, identity)
	if !ok {
		return MediaItem{}, sql.ErrNoRows
	}
	bookCount, err := s.countMediaForClauseContext(ctx, userID, where, args)
	if err != nil {
		return MediaItem{}, err
	}
	args = append(args, maxDetailDirectChildren+1)
	children, err := s.queryMediaListItemsContext(ctx, userID, where+` ORDER BY `+virtualAudiobookChildrenOrderSQL("m")+` LIMIT ?`, args)
	if err != nil {
		return MediaItem{}, err
	}
	if len(children) == 0 {
		return MediaItem{}, sql.ErrNoRows
	}
	truncated := len(children) > maxDetailDirectChildren
	if truncated {
		children = children[:maxDetailDirectChildren]
	}
	if err := s.attachDetailChildNarrativesContext(ctx, children); err != nil {
		return MediaItem{}, err
	}
	title := strings.TrimSpace(identity.Name)
	item := MediaItem{
		ID: identity.ID, LibraryID: identity.LibraryID, Type: identity.EntityKind, Title: title, SortTitle: title,
		Genres: []string{}, Tags: []string{}, Labels: []string{}, AddedAt: children[0].AddedAt,
		Images: children[0].Images, Artwork: children[0].Artwork, State: MediaState{}, Actions: []string{},
		Children: children, ChildrenTruncated: truncated,
		TypedMetadata: map[string]string{strings.TrimSuffix(identity.EntityKind, "-series"): title},
	}
	if identity.EntityKind == "audiobook-series" {
		item.TypedMetadata = map[string]string{"series": title}
	}
	item.Counts = &MediaHierarchyCounts{BookCount: intPointer(bookCount), ItemCount: intPointer(bookCount)}
	projection := []MediaItem{item}
	if err := s.populateMediaHierarchyProjectionContext(ctx, projection); err != nil {
		return MediaItem{}, err
	}
	item = projection[0]
	return item, nil
}

func intPointer(value int) *int { return &value }

// attachDetailChildNarrativesContext enriches the deliberately compact child
// projection with the narrative fields required by detail hierarchies. Keeping
// this as one bounded batch query avoids inflating every library browse payload
// or issuing one query per episode.
func (s *Server) attachDetailChildNarrativesContext(ctx context.Context, children []MediaItem) error {
	if len(children) == 0 {
		return nil
	}
	ids := make([]string, 0, len(children))
	seen := map[string]bool{}
	var collect func([]MediaItem)
	collect = func(items []MediaItem) {
		for _, item := range items {
			if item.ID != "" && !seen[item.ID] {
				seen[item.ID] = true
				ids = append(ids, item.ID)
			}
			collect(item.Children)
		}
	}
	collect(children)
	if len(ids) == 0 {
		return nil
	}
	args := make([]any, len(ids))
	for index, id := range ids {
		args[index] = id
	}
	placeholders := strings.TrimRight(strings.Repeat("?,", len(ids)), ",")
	rows, err := s.queryUserRead(ctx, `
		SELECT id, COALESCE(summary, ''), COALESCE(tagline, '')
		FROM media_items
		WHERE id IN (`+placeholders+`)`, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	type narrative struct {
		summary string
		tagline string
	}
	narratives := make(map[string]narrative, len(ids))
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return err
		}
		var id string
		var value narrative
		if err := rows.Scan(&id, &value.summary, &value.tagline); err != nil {
			return err
		}
		narratives[id] = value
	}
	if err := rows.Err(); err != nil {
		return err
	}
	var apply func([]MediaItem)
	apply = func(items []MediaItem) {
		for index := range items {
			if value, ok := narratives[items[index].ID]; ok {
				items[index].Summary = value.summary
				items[index].Tagline = value.tagline
			}
			apply(items[index].Children)
		}
	}
	apply(children)
	return nil
}

// mediaContainerPlaybackTarget exposes the exact playable child a client should
// resume or start without requiring every client to reconstruct Portico's
// hierarchy and progress policy. The returned value is already scoped to the
// requesting user because childrenForDetail projects that user's state,
// visibility restrictions, availability, and capabilities.
func mediaContainerPlaybackTarget(item MediaItem, children []MediaItem) *MediaItem {
	if item.Type != "show" && item.Type != "anime" {
		return nil
	}
	episodes := make([]MediaItem, 0)
	for _, child := range children {
		switch child.Type {
		case "episode":
			episodes = append(episodes, child)
		case "season":
			for _, episode := range child.Children {
				if episode.Type == "episode" {
					episodes = append(episodes, episode)
				}
			}
		}
	}
	for _, episode := range episodes {
		if episode.State.ProgressSeconds > 0 && !episode.State.Watched && slices.Contains(episode.Actions, mediaActionPlay) {
			target := episode
			return &target
		}
	}
	for _, episode := range episodes {
		if !episode.State.Watched && slices.Contains(episode.Actions, mediaActionPlay) {
			target := episode
			return &target
		}
	}
	for _, episode := range episodes {
		if slices.Contains(episode.Actions, mediaActionPlay) {
			target := episode
			return &target
		}
	}
	return nil
}

func (s *Server) mediaContainerPlaybackTargetContext(ctx context.Context, userID string, item MediaItem, preview []MediaItem) (*MediaItem, error) {
	if item.Type != "show" && item.Type != "anime" {
		return nil, nil
	}
	episodes, err := s.queryMediaListItemsContext(ctx, userID, `
		WHERE lower(m.type) = 'episode'
		  AND (m.parent_id = ? OR parent.parent_id = ?)
		ORDER BY m.season_number ASC, m.episode_number ASC, m.index_number ASC, m.sort_title COLLATE NOCASE ASC, m.id ASC`, []any{item.ID, item.ID})
	if err != nil {
		return nil, err
	}
	if target := mediaContainerPlaybackTarget(item, episodes); target != nil {
		enriched := []MediaItem{*target}
		if err := s.attachDetailChildNarrativesContext(ctx, enriched); err != nil {
			return nil, err
		}
		return &enriched[0], nil
	}
	return mediaContainerPlaybackTarget(item, preview), nil
}

func mediaExtraTypes() []string {
	return []string{"trailer", "featurette", "deleted_scene", "behind_the_scenes", "extra"}
}

func mediaExtraRelationships(children []MediaItem) []MediaExtraRelationship {
	groups := map[string][]MediaItem{}
	order := mediaExtraTypes()
	for _, child := range children {
		extraType := mediaExtraType(child)
		if extraType == "" {
			continue
		}
		groups[extraType] = append(groups[extraType], child)
	}
	relationships := make([]MediaExtraRelationship, 0, len(groups))
	for _, extraType := range order {
		items := groups[extraType]
		if len(items) == 0 {
			continue
		}
		relationships = append(relationships, MediaExtraRelationship{
			Type:  extraType,
			Label: mediaExtraTypeLabel(extraType),
			Items: items,
		})
	}
	return relationships
}

func mediaExtraType(item MediaItem) string {
	raw := strings.ToLower(strings.TrimSpace(firstNonEmpty(item.ArtSeed, item.Type)))
	switch raw {
	case "trailer", "featurette", "deleted_scene", "behind_the_scenes":
		return raw
	case "deleted scene", "deleted-scenes", "deleted scenes":
		return "deleted_scene"
	case "behind the scenes", "behind-the-scenes":
		return "behind_the_scenes"
	case "extra", "extras", "bonus", "bonus_features", "bonus features":
		return "extra"
	default:
		if item.Type == "extra" {
			return "extra"
		}
		return ""
	}
}

func mediaExtraTypeLabel(extraType string) string {
	switch extraType {
	case "trailer":
		return "Trailers"
	case "featurette":
		return "Featurettes"
	case "deleted_scene":
		return "Deleted Scenes"
	case "behind_the_scenes":
		return "Behind the Scenes"
	default:
		return "Extras"
	}
}

func mediaExtraSQLPredicate(alias string) string {
	if strings.TrimSpace(alias) == "" {
		alias = "m"
	}
	return `(LOWER(TRIM(COALESCE(` + alias + `.type, ''))) IN ('extra', 'trailer', 'featurette', 'deleted_scene', 'behind_the_scenes')
		OR LOWER(TRIM(COALESCE(` + alias + `.art_seed, ''))) IN ('extra', 'extras', 'bonus', 'bonus_features', 'bonus features', 'trailer', 'featurette', 'deleted_scene', 'deleted scene', 'deleted-scenes', 'deleted scenes', 'behind_the_scenes', 'behind the scenes', 'behind-the-scenes'))`
}

func (s *Server) audioNormalizationForMedia(mediaID string) *AudioNormalization {
	return s.audioNormalizationForMediaContext(context.Background(), mediaID)
}

func (s *Server) audioNormalizationForMediaContext(ctx context.Context, mediaID string) *AudioNormalization {
	if ctx == nil {
		ctx = context.Background()
	}
	var normalization AudioNormalization
	err := s.queryUserRow(ctx, `
		SELECT track_gain_db, track_peak, album_gain_db, album_peak, integrated_lufs, source, updated_at
		FROM audio_normalization
		WHERE media_id = ?`, mediaID).Scan(
		&normalization.TrackGainDB,
		&normalization.TrackPeak,
		&normalization.AlbumGainDB,
		&normalization.AlbumPeak,
		&normalization.IntegratedLUFS,
		&normalization.Source,
		&normalization.UpdatedAt,
	)
	if err != nil {
		return nil
	}
	return &normalization
}

func (s *Server) mediaFilesFor(mediaID, selectedPath string) []MediaFileVersion {
	return s.mediaFilesForContext(context.Background(), mediaID, selectedPath)
}

func (s *Server) mediaFilesForContext(ctx context.Context, mediaID, selectedPath string) []MediaFileVersion {
	if ctx == nil {
		ctx = context.Background()
	}
	allStreams, _ := s.listStreamsContext(ctx, mediaID)
	return s.mediaFilesWithStreamsContext(ctx, mediaID, selectedPath, allStreams)
}

func (s *Server) mediaFilesWithStreamsContext(ctx context.Context, mediaID, selectedPath string, allStreams []Stream) []MediaFileVersion {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT mf.id, mf.path, mf.quality, mf.container, mf.source_type, mf.version_label, mf.resolution, mf.source, mf.video_codec, mf.audio_codec, mf.dynamic_range,
			release_group, three_d, version_group, quality_rank,
			mf.size_bytes, mf.mod_time, mf.available, mf.missing_since,
			mf.duration_seconds, mf.bitrate, mf.width, mf.height, mf.frame_rate, mf.aspect_ratio,
			mf.video_profile, mf.video_level, mf.bit_depth, mf.pixel_format, mf.color_transfer,
			mf.color_primaries, mf.color_space, mf.chroma_location, mf.audio_channels,
			mf.audio_channel_layout, mf.audio_sample_rate, mf.audio_bitrate
		FROM media_files mf
		WHERE mf.media_id = ?
		ORDER BY mf.available DESC, mf.quality_rank DESC, mf.size_bytes DESC, mf.path ASC`, mediaID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	files := []MediaFileVersion{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return files
		}
		var file MediaFileVersion
		var available int
		var threeD int
		if err := rows.Scan(&file.ID, &file.Path, &file.Quality, &file.Container, &file.SourceType, &file.VersionLabel, &file.Resolution, &file.Source, &file.VideoCodec, &file.AudioCodec, &file.DynamicRange, &file.ReleaseGroup, &threeD, &file.VersionGroup, &file.QualityRank, &file.SizeBytes, &file.ModTime, &available, &file.MissingSince,
			&file.DurationSeconds, &file.Bitrate, &file.Width, &file.Height, &file.FrameRate, &file.AspectRatio,
			&file.VideoProfile, &file.VideoLevel, &file.BitDepth, &file.PixelFormat, &file.ColorTransfer,
			&file.ColorPrimaries, &file.ColorSpace, &file.ChromaLocation, &file.AudioChannels,
			&file.AudioChannelLayout, &file.AudioSampleRate, &file.AudioBitrate); err != nil {
			continue
		}
		file.OriginalFilename = filepath.Base(file.Path)
		file.Available = available == 1
		file.ThreeD = threeD == 1
		file.Selected = selectedPath != "" && file.Path == selectedPath
		file.Analysis = mediaFileStreamAnalysisStatus(file)
		for _, stream := range allStreams {
			if stream.FileID == file.ID {
				file.Streams = append(file.Streams, stream)
			}
		}
		files = append(files, file)
	}
	return files
}

func (s *Server) primaryMediaFileForPlaybackContext(ctx context.Context, mediaID, selectedPath string) []MediaFileVersion {
	if ctx == nil {
		ctx = context.Background()
	}
	where := `mf.media_id = ?`
	args := []any{mediaID}
	if strings.TrimSpace(selectedPath) != "" {
		where += ` AND mf.path = ?`
		args = append(args, selectedPath)
	}
	query := `
		SELECT mf.id, mf.path, mf.quality, mf.container, mf.source_type, mf.version_label, mf.resolution, mf.source, mf.video_codec, mf.audio_codec, mf.dynamic_range,
			release_group, three_d, version_group, quality_rank,
			mf.size_bytes, mf.mod_time, mf.available, mf.missing_since,
			mf.duration_seconds, mf.bitrate, mf.width, mf.height, mf.frame_rate, mf.aspect_ratio,
			mf.video_profile, mf.video_level, mf.bit_depth, mf.pixel_format, mf.color_transfer,
			mf.color_primaries, mf.color_space, mf.chroma_location, mf.audio_channels,
			mf.audio_channel_layout, mf.audio_sample_rate, mf.audio_bitrate
		FROM media_files mf
		WHERE ` + where + `
		ORDER BY mf.available DESC, mf.quality_rank DESC, mf.size_bytes DESC, mf.path ASC
		LIMIT 1`
	file, ok := s.scanPrimaryMediaFileForPlayback(ctx, query, args, selectedPath)
	if ok || strings.TrimSpace(selectedPath) == "" {
		if !ok {
			return nil
		}
		return []MediaFileVersion{file}
	}
	file, ok = s.scanPrimaryMediaFileForPlayback(ctx, strings.Replace(query, `WHERE `+where, `WHERE mf.media_id = ?`, 1), []any{mediaID}, selectedPath)
	if !ok {
		return nil
	}
	return []MediaFileVersion{file}
}

func (s *Server) scanPrimaryMediaFileForPlayback(ctx context.Context, query string, args []any, selectedPath string) (MediaFileVersion, bool) {
	var file MediaFileVersion
	var available int
	var threeD int
	err := s.queryUserRow(ctx, query, args...).Scan(
		&file.ID, &file.Path, &file.Quality, &file.Container, &file.SourceType, &file.VersionLabel, &file.Resolution, &file.Source, &file.VideoCodec, &file.AudioCodec, &file.DynamicRange,
		&file.ReleaseGroup, &threeD, &file.VersionGroup, &file.QualityRank, &file.SizeBytes, &file.ModTime, &available, &file.MissingSince,
		&file.DurationSeconds, &file.Bitrate, &file.Width, &file.Height, &file.FrameRate, &file.AspectRatio,
		&file.VideoProfile, &file.VideoLevel, &file.BitDepth, &file.PixelFormat, &file.ColorTransfer,
		&file.ColorPrimaries, &file.ColorSpace, &file.ChromaLocation, &file.AudioChannels,
		&file.AudioChannelLayout, &file.AudioSampleRate, &file.AudioBitrate,
	)
	if err != nil {
		return MediaFileVersion{}, false
	}
	file.Available = available == 1
	file.OriginalFilename = filepath.Base(file.Path)
	file.ThreeD = threeD == 1
	file.Selected = strings.TrimSpace(selectedPath) != "" && file.Path == selectedPath
	file.Analysis = mediaFileStreamAnalysisStatus(file)
	return file, true
}

func mediaFileStreamAnalysisStatus(file MediaFileVersion) string {
	if file.VideoCodec != "" || file.AudioCodec != "" || file.Container != "" {
		return "analyzed"
	}
	return "unknown"
}

func (s *Server) attachMediaMetadataEvidence(item *MediaItem) {
	s.attachMediaMetadataEvidenceContext(context.Background(), item)
}

func (s *Server) attachMediaMetadataEvidenceContext(ctx context.Context, item *MediaItem) {
	if item == nil || item.ID == "" {
		return
	}
	if ctx == nil {
		ctx = context.Background()
	}
	item.MetadataEvidence = s.currentMediaMetadataEvidenceContext(ctx, item.ID, item.MetadataRevision)
	rows, err := s.queryUserRead(ctx, `
		SELECT provider, external_id, external_type, confidence, source, updated_at
		FROM media_provider_ids
		WHERE media_id = ? AND status = 'accepted' AND evidence_revision = ?
		ORDER BY provider, external_type`, item.ID, item.MetadataRevision)
	if err == nil {
		for rows.Next() {
			if err := ctx.Err(); err != nil {
				_ = rows.Close()
				return
			}
			var providerID MediaProviderID
			if err := rows.Scan(&providerID.Provider, &providerID.ExternalID, &providerID.ExternalType, &providerID.Confidence, &providerID.Source, &providerID.UpdatedAt); err == nil {
				item.ProviderIDs = append(item.ProviderIDs, providerID)
			}
		}
		_ = rows.Close()
	}
	if err := ctx.Err(); err != nil {
		return
	}
	item.MediaImages = s.mediaImagesForContext(ctx, item.ID)
	item.Lyrics = s.mediaLyricsForContext(ctx, item.ID)
	item.People = s.mediaPeopleForDetailContext(ctx, *item)
	item.LockedFields = s.lockedFieldsForMediaContext(ctx, item.ID)
}

const (
	maxPublicMetadataValues        = 128
	maxPublicMetadataRelationships = 256
)

func (s *Server) currentMediaMetadataEvidenceContext(ctx context.Context, mediaID string, revision int) *MediaMetadataEvidence {
	if ctx == nil {
		ctx = context.Background()
	}
	if strings.TrimSpace(mediaID) == "" || revision <= 0 {
		return nil
	}
	evidence := &MediaMetadataEvidence{
		Revision: revision, Values: []MediaMetadataValue{}, Relationships: []MediaMetadataRelationship{},
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT f.field_key, f.ordinal, f.locale, f.value_json, f.source_kind,
		       f.provider, f.confidence, f.decision
		FROM media_metadata_field_values f
		JOIN media_metadata_revisions r ON r.id = f.revision_id
		WHERE f.media_id = ? AND r.media_id = f.media_id AND r.revision = ?
		  AND r.state = 'applied' AND f.decision IN ('accepted', 'locked')
		ORDER BY f.field_key COLLATE NOCASE, f.locale COLLATE NOCASE, f.ordinal, f.id
		LIMIT ?`, mediaID, revision, maxPublicMetadataValues)
	if err != nil {
		return nil
	}
	for rows.Next() {
		var value MediaMetadataValue
		var raw string
		if err := rows.Scan(&value.Field, &value.Order, &value.Locale, &raw, &value.SourceKind, &value.Provider, &value.Confidence, &value.Decision); err != nil {
			_ = rows.Close()
			return nil
		}
		value.Value = json.RawMessage(raw)
		evidence.Values = append(evidence.Values, value)
	}
	if err := rows.Close(); err != nil {
		return nil
	}
	if err := ctx.Err(); err != nil {
		return nil
	}
	rows, err = s.queryUserRead(ctx, `
		SELECT rel.relationship_type, rel.display_value, rel.target_kind,
		       rel.provider, rel.target_provider, rel.target_external_id, rel.language,
		       rel.country, rel.role, rel.ordinal, rel.source_kind,
		       rel.confidence, rel.decision
		FROM media_metadata_relationships rel
		JOIN media_metadata_revisions r ON r.id = rel.revision_id
		WHERE rel.media_id = ? AND r.media_id = rel.media_id AND r.revision = ?
		  AND r.state = 'applied' AND rel.decision IN ('accepted', 'locked')
		ORDER BY rel.relationship_type COLLATE NOCASE, rel.ordinal,
		         rel.display_value COLLATE NOCASE, rel.id
		LIMIT ?`, mediaID, revision, maxPublicMetadataRelationships)
	if err != nil {
		return nil
	}
	defer rows.Close()
	for rows.Next() {
		var relationship MediaMetadataRelationship
		if err := rows.Scan(
			&relationship.Type, &relationship.Name, &relationship.TargetKind,
			&relationship.Provider, &relationship.ExternalProvider, &relationship.ExternalID, &relationship.Locale,
			&relationship.Country, &relationship.Role, &relationship.Order,
			&relationship.SourceKind, &relationship.Confidence, &relationship.Decision,
		); err != nil {
			return nil
		}
		evidence.Relationships = append(evidence.Relationships, relationship)
	}
	if err := rows.Err(); err != nil {
		return nil
	}
	if len(evidence.Values) == 0 && len(evidence.Relationships) == 0 {
		return nil
	}
	return evidence
}

func (s *Server) matchCandidatesForMediaContext(ctx context.Context, mediaID string) []MatchCandidate {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT provider, external_id, external_type, source, score, CASE WHEN status = 'accepted' THEN 1 ELSE 0 END, reason_codes_json, raw_result_json, created_at
		FROM media_match_candidates
		WHERE media_id = ?
		ORDER BY datetime(created_at) DESC
		LIMIT 12`, mediaID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	candidates := []MatchCandidate{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return candidates
		}
		var candidate MatchCandidate
		var accepted int
		var reasonsJSON string
		var rawResultJSON string
		if err := rows.Scan(&candidate.Provider, &candidate.ExternalID, &candidate.ExternalType, &candidate.Source, &candidate.Score, &accepted, &reasonsJSON, &rawResultJSON, &candidate.CreatedAt); err != nil {
			continue
		}
		candidate.Accepted = accepted == 1
		_ = json.Unmarshal([]byte(reasonsJSON), &candidate.Reasons)
		enrichMatchCandidateFromRaw(&candidate, rawResultJSON)
		candidates = append(candidates, candidate)
	}
	return candidates
}

