func (s *Server) mediaMutationResponseContext(ctx context.Context, userID, id string, fallback MediaItem) MediaItem {
	item, err := s.getMediaListItemContext(ctx, userID, id)
	if err == nil {
		return item
	}
	if fallback.ID == "" {
		fallback.ID = id
	}
	if user, loadErr := s.mediaActionUserContext(ctx, userID); loadErr == nil {
		applyMediaActionsToItem(&fallback, user)
	} else if fallback.Actions == nil {
		fallback.Actions = []string{}
	}
	return fallback
}

func (s *Server) mediaMetadataResponseContext(ctx context.Context, userID, id string, fallback MediaItem) MediaItem {
	item, err := s.getMediaContext(ctx, userID, id)
	if err == nil {
		return item
	}
	if fallback.ID == "" {
		fallback.ID = id
	}
	if user, loadErr := s.mediaActionUserContext(ctx, userID); loadErr == nil {
		applyMediaActionsToItem(&fallback, user)
	} else if fallback.Actions == nil {
		fallback.Actions = []string{}
	}
	return fallback
}

func (s *Server) updateMedia(userID, id string, req UpdateMediaRequest) (MediaItem, error) {
	return s.updateMediaWithResponse(userID, id, req, true)
}

func (s *Server) updateMediaForMetadata(userID, id string, req UpdateMediaRequest) (MediaItem, error) {
	return s.updateMediaWithResponse(userID, id, req, false)
}

func (s *Server) updateMediaWithResponse(userID, id string, req UpdateMediaRequest, detailResponse bool) (MediaItem, error) {
	releaseMetadataArtwork := s.acquireMetadataArtworkCommitLock(id)
	defer releaseMetadataArtwork()
	ctx := context.Background()
	item, err := s.getMediaContext(ctx, userID, id)
	if err != nil {
		return MediaItem{}, err
	}
	expectedRevision := item.MetadataRevision
	if req.ExpectedRevision != nil {
		expectedRevision = *req.ExpectedRevision
	}
	origin := metadataSourceProvider
	source := "provider"
	// The public/editor path is manual even when a focused in-process caller
	// does not carry an actor ID. Provider/scanner writers use the explicitly
	// separate updateMediaForMetadata path and supply their origin below.
	if detailResponse {
		origin = metadataSourceManual
		source = "editor"
	}
	provider := normalizedMetadataProvider(req.metadataProvider)
	if req.metadataOrigin != "" {
		origin = req.metadataOrigin
	}
	if strings.TrimSpace(req.metadataSource) != "" {
		source = strings.TrimSpace(req.metadataSource)
	}
	if userID != "" {
		origin = metadataSourceManual
		source = "editor"
	}
	actorUserID := firstNonEmpty(strings.TrimSpace(req.metadataActor), strings.TrimSpace(userID))
	if err := s.prepareMetadataUpdateForIntent(ctx, id, &req, req.metadataIntent); err != nil {
		return MediaItem{}, err
	}
	stagedImages := []stagedMetadataImage(nil)
	stagedPeople := []MediaPerson(nil)
	if req.Artwork != nil {
		if provider == "" {
			provider = normalizedMetadataProvider((*req.Artwork)["source"])
		}
		if origin != metadataSourceManual {
			stagedImages = stageMetadataProviderArtwork(ctx, s, id, *req.Artwork)
		}
	}
	if req.People != nil && origin == metadataSourceProvider {
		people := stageMetadataProviderPeople(ctx, s, id, provider, *req.People)
		stagedPeople = people
		req.People = &people
	}
	if origin == metadataSourceProvider && req.metadataRich != nil {
		stageMetadataProviderRichOriginals(ctx, s, id, req.metadataRich)
	}
	result, err := s.applyMetadata(ctx, metadataApplyRequest{
		MediaID:          id,
		ExpectedRevision: expectedRevision,
		Origin:           origin,
		Source:           source,
		Provider:         provider,
		ActorUserID:      actorUserID,
		OperationID:      req.metadataOperation,
		MarkRefreshed:    req.metadataRefreshed,
		RefreshIntent:    req.metadataIntent,
		Update:           req,
		Identities:       req.metadataIdentities,
		ProviderRich:     req.metadataRich,
		StagedImages:     stagedImages,
	})
	if err != nil {
		s.cleanupUnreferencedStagedMetadataArtwork(stagedImages, req.metadataRich, stagedPeople)
		return MediaItem{}, err
	}
	item.MetadataRevision = result.Revision
	item.MetadataETag = result.ETag
	if !detailResponse {
		return s.mediaMetadataResponseContext(ctx, userID, id, item), nil
	}
	return s.getMediaDetailWithOptions(userID, id, mediaDetailOptions{Recommendations: false})
}

func (s *Server) applyMetadataLocksToUpdate(mediaID string, req *UpdateMediaRequest) {
	if req == nil {
		return
	}
	var currentTypedMetadata map[string]string
	for _, field := range s.lockedFieldsForMedia(mediaID) {
		if strings.HasPrefix(field, "typedMetadata.") {
			if req.TypedMetadata == nil {
				continue
			}
			if currentTypedMetadata == nil {
				currentTypedMetadata = s.typedMetadataForMedia(mediaID)
			}
			key := strings.TrimPrefix(field, "typedMetadata.")
			if current, ok := currentTypedMetadata[key]; ok {
				(*req.TypedMetadata)[key] = current
			} else {
				delete(*req.TypedMetadata, key)
			}
			continue
		}
		switch field {
		case "title":
			req.Title = nil
		case "sortTitle":
			req.SortTitle = nil
		case "originalTitle":
			req.OriginalTitle = nil
		case "edition":
			req.Edition = nil
		case "year":
			req.Year = nil
		case "durationSeconds":
			req.DurationSeconds = nil
		case "summary":
			req.Summary = nil
		case "tagline":
			req.Tagline = nil
		case "contentRating":
			req.ContentRating = nil
		case "communityRating":
			req.CommunityRating = nil
		case "criticRating":
			req.CriticRating = nil
		case "studio":
			req.Studio = nil
		case "network":
			req.Network = nil
		case "country":
			req.Country = nil
		case "genres":
			req.Genres = nil
		case "tags":
			req.Tags = nil
		case "labels":
			req.Labels = nil
		case "seasonNumber":
			req.SeasonNumber = nil
		case "episodeNumber":
			req.EpisodeNumber = nil
		case "indexNumber":
			req.IndexNumber = nil
		case "artwork":
			req.Artwork = nil
		case "people":
			req.People = nil
		case "typedMetadata":
			req.TypedMetadata = nil
		}
	}
}

func (s *Server) typedMetadataForMedia(mediaID string) map[string]string {
	var raw string
	if err := s.queryUserRow(context.Background(), `SELECT COALESCE(typed_metadata_json, '{}') FROM media_items WHERE id = ?`, mediaID).Scan(&raw); err != nil {
		return map[string]string{}
	}
	var metadata map[string]string
	if err := json.Unmarshal([]byte(raw), &metadata); err != nil || metadata == nil {
		return map[string]string{}
	}
	return normalizeTypedMetadataMap(metadata)
}

func (s *Server) queryMedia(userID, clause string, args []any) ([]MediaItem, error) {
	return s.queryMediaContext(context.Background(), userID, clause, args)
}

func (s *Server) queryMediaContext(ctx context.Context, userID, clause string, args []any) ([]MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	accountID, profileID := s.accountAndProfileIDsContext(ctx, userID)
	clause, args = s.applyMediaVisibilityRestrictionToClauseContext(ctx, profileID, clause, args)
	clause, args = s.applyLibraryCurationRestrictionToClause(ctx, accountID, clause, args)
	query := `
		SELECT
			m.id, COALESCE(m.metadata_revision, 0), COALESCE(m.metadata_etag, ''), COALESCE(m.library_id, ''), COALESCE(m.parent_id, ''), m.type, m.title, m.sort_title,
			m.original_title, m.edition, m.year, m.duration_seconds, m.summary, m.tagline,
			m.content_rating, m.community_rating, m.critic_rating, m.studio, m.network, m.country,
			m.genres_json, m.tags_json, m.labels_json, m.added_at, m.season_number, m.episode_number,
			m.index_number, m.art_seed, COALESCE(m.artwork_json, '{}'), COALESCE(m.typed_metadata_json, '{}'), m.source_url,
			COALESCE(ums.watchlisted, 0), COALESCE(ums.favorite, 0), COALESCE(ums.liked, 0), COALESCE(ums.watched, 0), COALESCE(ums.progress_seconds, 0),
			COALESCE(ums.rating, 0), COALESCE(ums.last_played_at, ''),
			COALESCE(parent.title, ''), COALESCE(grandparent.id, ''), COALESCE(grandparent.title, ''),
			COALESCE(availability.file_count, 0),
			COALESCE(availability.missing_file_count, 0),
			COALESCE(m.sort_artist_key, ''), COALESCE(m.sort_album_artist_key, ''), COALESCE(m.sort_track_artist_key, ''),
			COALESCE(m.sort_author_key, ''), COALESCE(m.sort_narrator_key, ''), COALESCE(m.random_key, '')
		FROM media_items m
		LEFT JOIN user_media_state ums ON ums.media_id = m.id AND ums.profile_id = ?
		LEFT JOIN media_items parent ON parent.id = m.parent_id
		LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
		LEFT JOIN media_availability availability ON availability.media_id = m.id
		` + clause
	queryArgs := append([]any{profileID}, args...)
	rows, err := s.queryUserRead(ctx, query, queryArgs...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var items []MediaItem
	progressPreferences := s.playbackProgressPreferencesForUserContext(ctx, profileID)
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var item MediaItem
		var genresJSON string
		var tagsJSON string
		var labelsJSON string
		var artworkJSON string
		var typedMetadataJSON string
		var watchlisted, favorite, liked, watched int
		if err := rows.Scan(
			&item.ID, &item.MetadataRevision, &item.MetadataETag, &item.LibraryID, &item.ParentID, &item.Type, &item.Title, &item.SortTitle,
			&item.OriginalTitle, &item.Edition, &item.Year, &item.DurationSeconds, &item.Summary, &item.Tagline,
			&item.ContentRating, &item.CommunityRating, &item.CriticRating, &item.Studio, &item.Network, &item.Country,
			&genresJSON, &tagsJSON, &labelsJSON, &item.AddedAt, &item.SeasonNumber,
			&item.EpisodeNumber, &item.IndexNumber, &item.ArtSeed, &artworkJSON, &typedMetadataJSON, &item.SourceURL,
			&watchlisted, &favorite, &liked, &watched, &item.State.ProgressSeconds, &item.State.Rating, &item.State.LastPlayedAt,
			&item.ParentTitle, &item.GrandparentID, &item.GrandparentTitle,
			&item.FileCount, &item.MissingFileCount,
			&item.SortArtistKey, &item.SortAlbumArtistKey, &item.SortTrackArtistKey,
			&item.SortAuthorKey, &item.SortNarratorKey, &item.RandomKey,
		); err != nil {
			return nil, err
		}
		_ = json.Unmarshal([]byte(genresJSON), &item.Genres)
		_ = json.Unmarshal([]byte(tagsJSON), &item.Tags)
		_ = json.Unmarshal([]byte(labelsJSON), &item.Labels)
		_ = json.Unmarshal([]byte(artworkJSON), &item.Artwork)
		_ = json.Unmarshal([]byte(typedMetadataJSON), &item.TypedMetadata)
		item.TypedMetadata = sanitizeTypedMetadataForType(item.Type, normalizeTypedMetadataMap(item.TypedMetadata))
		item.State.Watchlisted = watchlisted == 1
		item.State.Favorite = favorite == 1
		item.State.Reaction = reactionName(liked)
		item.State.Watched = watched == 1
		item.Missing = item.FileCount > 0 && item.FileCount == item.MissingFileCount
		item.Images = imageSetFor(item.ID, item.ArtSeed, item.Title, item.Artwork)
		applyPlaybackProgressDisplayPolicy(&item, progressPreferences)
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	for i := range items {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		s.attachResumeInfo(&items[i])
		s.applyTVBackdropFallbacksContext(ctx, &items[i])
	}
	items = s.applyUserContentRestrictionsContext(ctx, profileID, s.applyUserLibraryRestrictionsContext(ctx, accountID, items))
	items, err = s.applyMediaActionProjectionContext(ctx, profileID, items)
	if err != nil {
		return nil, err
	}
	if err := s.populateMediaHierarchyProjectionContext(ctx, items); err != nil {
		return nil, err
	}
	return items, nil
}

func (s *Server) queryMediaListItems(userID, clause string, args []any) ([]MediaItem, error) {
	return s.queryMediaListItemsContext(context.Background(), userID, clause, args)
}

func (s *Server) queryMediaListItemsContext(ctx context.Context, userID, clause string, args []any) ([]MediaItem, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	accountID, profileID := s.accountAndProfileIDsContext(ctx, userID)
	clause, args = s.applyMediaVisibilityRestrictionToClauseContext(ctx, profileID, clause, args)
	clause, args = s.applyLibraryCurationRestrictionToClause(ctx, accountID, clause, args)
	query := `
		SELECT
			m.id, COALESCE(m.metadata_revision, 0), COALESCE(m.metadata_etag, ''), COALESCE(m.library_id, ''), COALESCE(m.parent_id, ''), m.type, m.title, m.sort_title,
			m.year, m.duration_seconds, m.content_rating, m.community_rating, m.critic_rating,
			m.studio, m.network, m.country, m.genres_json, m.tags_json, m.labels_json, m.added_at,
			m.season_number, m.episode_number, m.index_number, m.art_seed,
			COALESCE(m.artwork_json, '{}'), COALESCE(m.typed_metadata_json, '{}'), ` + normalizedReleaseDateSQL("m") + `,
			COALESCE(ums.watchlisted, 0), COALESCE(ums.favorite, 0), COALESCE(ums.liked, 0),
			COALESCE(ums.watched, 0), COALESCE(ums.progress_seconds, 0), COALESCE(ums.rating, 0),
			COALESCE(ums.last_played_at, ''), COALESCE(parent.title, ''),
			COALESCE(grandparent.id, ''), COALESCE(grandparent.title, ''),
			COALESCE(availability.file_count, 0), COALESCE(availability.missing_file_count, 0),
			COALESCE(m.sort_artist_key, ''), COALESCE(m.sort_album_artist_key, ''), COALESCE(m.sort_track_artist_key, ''),
			COALESCE(m.sort_author_key, ''), COALESCE(m.sort_narrator_key, ''), COALESCE(m.random_key, '')
		FROM media_items m
		LEFT JOIN user_media_state ums ON ums.media_id = m.id AND ums.profile_id = ?
		LEFT JOIN media_items parent ON parent.id = m.parent_id
		LEFT JOIN media_items grandparent ON grandparent.id = parent.parent_id
		LEFT JOIN media_availability availability ON availability.media_id = m.id
		` + clause
	queryArgs := append([]any{profileID}, args...)
	rows, err := s.queryUserRead(ctx, query, queryArgs...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var items []MediaItem
	progressPreferences := s.playbackProgressPreferencesForUserContext(ctx, profileID)
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		item, err := scanMediaListItem(rows)
		if err != nil {
			return nil, err
		}
		applyPlaybackProgressDisplayPolicy(&item, progressPreferences)
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	items = s.applyUserContentRestrictionsContext(ctx, profileID, s.applyUserLibraryRestrictionsContext(ctx, accountID, items))
	items, err = s.applyMediaActionProjectionContext(ctx, profileID, items)
	if err != nil {
		return nil, err
	}
	if err := s.populateMediaHierarchyProjectionContext(ctx, items); err != nil {
		return nil, err
	}
	return items, nil
}

func (s *Server) applyMediaVisibilityRestrictionToClause(userID string, clause string, args []any) (string, []any) {
	return s.applyMediaVisibilityRestrictionToClauseContext(context.Background(), userID, clause, args)
}

func (s *Server) applyMediaVisibilityRestrictionToClauseContext(ctx context.Context, userID string, clause string, args []any) (string, []any) {
	restrictionSQL, restrictionArgs := s.mediaVisibilityRestrictionSQLContext(ctx, userID)
	if restrictionSQL == "" || strings.Contains(clause, "user_library_access ula") {
		return clause, args
	}
	insertAt := topLevelClauseSuffixIndex(clause)
	prefix := clause[:insertAt]
	suffix := clause[insertAt:]
	if !topLevelClauseHasKeyword(prefix, "WHERE") {
		prefix += " WHERE 1 = 1"
	}
	prefixPlaceholderCount := countSQLPlaceholders(prefix)
	if prefixPlaceholderCount >= len(args) {
		nextArgs := append([]any{}, args...)
		nextArgs = append(nextArgs, restrictionArgs...)
		return strings.TrimRight(prefix, " \t\r\n") + restrictionSQL + " " + strings.TrimLeft(suffix, " \t\r\n"), nextArgs
	}
	nextArgs := make([]any, 0, len(args)+len(restrictionArgs))
	nextArgs = append(nextArgs, args[:prefixPlaceholderCount]...)
	nextArgs = append(nextArgs, restrictionArgs...)
	nextArgs = append(nextArgs, args[prefixPlaceholderCount:]...)
	return strings.TrimRight(prefix, " \t\r\n") + restrictionSQL + " " + strings.TrimLeft(suffix, " \t\r\n"), nextArgs
}

func topLevelClauseSuffixIndex(clause string) int {
	best := len(clause)
	for _, keyword := range []string{"ORDER BY", "GROUP BY", "HAVING", "LIMIT"} {
		if index := topLevelSQLKeywordIndex(clause, keyword); index >= 0 && index < best {
			best = index
		}
	}
	return best
}

func topLevelClauseHasKeyword(clause string, keyword string) bool {
	return topLevelSQLKeywordIndex(clause, keyword) >= 0
}

func topLevelSQLKeywordIndex(sqlText string, keyword string) int {
	upper := strings.ToUpper(sqlText)
	keyword = strings.ToUpper(strings.TrimSpace(keyword))
	depth := 0
	inSingleQuote := false
	inDoubleQuote := false
	for index := 0; index < len(upper); index++ {
		char := upper[index]
		if inSingleQuote {
			if char == '\'' {
				if index+1 < len(upper) && upper[index+1] == '\'' {
					index++
					continue
				}
				inSingleQuote = false
			}
			continue
		}
		if inDoubleQuote {
			if char == '"' {
				inDoubleQuote = false
			}
			continue
		}
		switch char {
		case '\'':
			inSingleQuote = true
		case '"':
			inDoubleQuote = true
		case '(':
			depth++
		case ')':
			if depth > 0 {
				depth--
			}
		default:
			if depth == 0 && strings.HasPrefix(upper[index:], keyword) && sqlKeywordBoundary(upper, index-1) && sqlKeywordBoundary(upper, index+len(keyword)) {
				return index
			}
		}
	}
	return -1
}

func countSQLPlaceholders(sqlText string) int {
	count := 0
	inSingleQuote := false
	inDoubleQuote := false
	for index := 0; index < len(sqlText); index++ {
		char := sqlText[index]
		if inSingleQuote {
			if char == '\'' {
				if index+1 < len(sqlText) && sqlText[index+1] == '\'' {
					index++
					continue
				}
				inSingleQuote = false
			}
			continue
		}
		if inDoubleQuote {
			if char == '"' {
				inDoubleQuote = false
			}
			continue
		}
		switch char {
		case '\'':
			inSingleQuote = true
		case '"':
			inDoubleQuote = true
		case '?':
			count++
		}
	}
	return count
}

func sqlKeywordBoundary(sqlText string, index int) bool {
	if index < 0 || index >= len(sqlText) {
		return true
	}
	char := sqlText[index]
	return !(char == '_' || char >= '0' && char <= '9' || char >= 'A' && char <= 'Z' || char >= 'a' && char <= 'z')
}

type mediaListItemScanner interface {
	Scan(dest ...any) error
}

func scanMediaListItem(scanner mediaListItemScanner) (MediaItem, error) {
	var item MediaItem
	var genresJSON string
	var tagsJSON string
	var labelsJSON string
	var artworkJSON string
	var typedMetadataJSON string
	var watchlisted, favorite, liked, watched int
	if err := scanner.Scan(
		&item.ID, &item.MetadataRevision, &item.MetadataETag, &item.LibraryID, &item.ParentID, &item.Type, &item.Title, &item.SortTitle,
		&item.Year, &item.DurationSeconds, &item.ContentRating, &item.CommunityRating, &item.CriticRating,
		&item.Studio, &item.Network, &item.Country, &genresJSON, &tagsJSON, &labelsJSON, &item.AddedAt,
		&item.SeasonNumber, &item.EpisodeNumber, &item.IndexNumber, &item.ArtSeed, &artworkJSON, &typedMetadataJSON, &item.ReleaseDateKey,
		&watchlisted, &favorite, &liked, &watched, &item.State.ProgressSeconds, &item.State.Rating, &item.State.LastPlayedAt,
		&item.ParentTitle, &item.GrandparentID, &item.GrandparentTitle, &item.FileCount, &item.MissingFileCount,
		&item.SortArtistKey, &item.SortAlbumArtistKey, &item.SortTrackArtistKey,
		&item.SortAuthorKey, &item.SortNarratorKey, &item.RandomKey,
	); err != nil {
		return MediaItem{}, err
	}
	_ = json.Unmarshal([]byte(genresJSON), &item.Genres)
	_ = json.Unmarshal([]byte(tagsJSON), &item.Tags)
	_ = json.Unmarshal([]byte(labelsJSON), &item.Labels)
	_ = json.Unmarshal([]byte(artworkJSON), &item.Artwork)
	_ = json.Unmarshal([]byte(typedMetadataJSON), &item.TypedMetadata)
	item.TypedMetadata = sanitizeTypedMetadataForType(item.Type, normalizeTypedMetadataMap(item.TypedMetadata))
	item.State.Watchlisted = watchlisted == 1
	item.State.Favorite = favorite == 1
	item.State.Reaction = reactionName(liked)
	item.State.Watched = watched == 1
	item.Missing = item.FileCount > 0 && item.FileCount == item.MissingFileCount
	item.Images = imageSetFor(item.ID, item.ArtSeed, item.Title, item.Artwork)
	return item, nil
}

func (s *Server) attachResumeInfo(item *MediaItem) {
	if item == nil || item.State.ProgressSeconds <= 0 || item.State.Watched {
		return
	}
	resume := &ResumeInfo{
		PositionSeconds: item.State.ProgressSeconds,
	}
	if item.DurationSeconds > 0 && item.State.ProgressSeconds < item.DurationSeconds {
		resume.RemainingSeconds = item.DurationSeconds - item.State.ProgressSeconds
	}
	if item.Type == "audiobook" {
		chapters := item.Chapters
		if len(chapters) == 0 {
			chapters = s.chaptersForMedia(item.ID)
		}
		for index, chapter := range chapters {
			endSeconds := chapter.EndSeconds
			if endSeconds <= 0 && index+1 < len(chapters) {
				endSeconds = chapters[index+1].StartSeconds
			}
			if chapter.StartSeconds <= item.State.ProgressSeconds && (endSeconds <= 0 || item.State.ProgressSeconds < endSeconds) {
				resume.ChapterID = chapter.ID
				resume.ChapterTitle = chapter.Title
				resume.ChapterIndex = index + 1
				resume.ChapterStartSeconds = chapter.StartSeconds
				resume.ChapterEndSeconds = chapter.EndSeconds
				break
			}
		}
	}
	item.State.Resume = resume
}

func (s *Server) applyUserLibraryRestrictions(userID string, items []MediaItem) []MediaItem {
	return s.applyUserLibraryRestrictionsContext(context.Background(), userID, items)
}

func (s *Server) applyUserLibraryRestrictionsContext(ctx context.Context, userID string, items []MediaItem) []MediaItem {
	if strings.TrimSpace(userID) == "" || len(items) == 0 {
		return items
	}
	if ctx == nil {
		ctx = context.Background()
	}
	principal, err := s.requestPrincipalForIdentityContext(ctx, userID)
	if err != nil {
		return nil
	}
	if principal.MembershipEnvelope.Role == "owner" {
		return items
	}
	allowed := make(map[string]bool, len(principal.MembershipEnvelope.LibraryIDs))
	for _, libraryID := range principal.MembershipEnvelope.LibraryIDs {
		allowed[libraryID] = true
	}
	filtered := items[:0]
	for _, item := range items {
		if allowed[item.LibraryID] {
			filtered = append(filtered, item)
		}
	}
	return filtered
}

func (s *Server) applyUserContentRestrictions(userID string, items []MediaItem) []MediaItem {
	return s.applyUserContentRestrictionsContext(context.Background(), userID, items)
}

func (s *Server) applyUserContentRestrictionsContext(ctx context.Context, userID string, items []MediaItem) []MediaItem {
	if strings.TrimSpace(userID) == "" || len(items) == 0 {
		return items
	}
	principal, err := s.requestPrincipalForIdentityContext(ctx, userID)
	if err != nil {
		return nil
	}
	tagPolicy := principal.MembershipEnvelope.TagPolicy
	filtered := items[:0]
	for _, item := range items {
		if contentRatingAllowed(item.ContentRating, principal.MaxContentRating) && mediaItemAllowedByTagPolicy(item, tagPolicy) && profileMediaPolicyAllows(principal, item) {
			filtered = append(filtered, item)
		}
	}
	return filtered
}

func (s *Server) applyMediaVisibilityRestrictionSQL(userID, where string, args []any) (string, []any) {
	restrictionSQL, restrictionArgs := s.mediaVisibilityRestrictionSQL(userID)
	if restrictionSQL == "" {
		return where, args
	}
	nextArgs := append([]any{}, args...)
	nextArgs = append(nextArgs, restrictionArgs...)
	return where + restrictionSQL, nextArgs
}

func (s *Server) applyLibraryCurationRestrictionToClause(ctx context.Context, userID string, clause string, args []any) (string, []any) {
	restrictionSQL, restrictionArgs := s.libraryCurationRestrictionSQL(ctx, userID)
	if restrictionSQL == "" || strings.Contains(clause, "library_curation_") {
		return clause, args
	}
	insertAt := topLevelClauseSuffixIndex(clause)
	prefix := clause[:insertAt]
	suffix := clause[insertAt:]
	if !topLevelClauseHasKeyword(prefix, "WHERE") {
		prefix += " WHERE 1 = 1"
	}
	prefixPlaceholderCount := countSQLPlaceholders(prefix)
	if prefixPlaceholderCount >= len(args) {
		nextArgs := append([]any{}, args...)
		nextArgs = append(nextArgs, restrictionArgs...)
		return strings.TrimRight(prefix, " \t\r\n") + restrictionSQL + " " + strings.TrimLeft(suffix, " \t\r\n"), nextArgs
	}
	nextArgs := make([]any, 0, len(args)+len(restrictionArgs))
	nextArgs = append(nextArgs, args[:prefixPlaceholderCount]...)
	nextArgs = append(nextArgs, restrictionArgs...)
	nextArgs = append(nextArgs, args[prefixPlaceholderCount:]...)
	return strings.TrimRight(prefix, " \t\r\n") + restrictionSQL + " " + strings.TrimLeft(suffix, " \t\r\n"), nextArgs
}

func (s *Server) applyLibraryCurationRestrictionSQL(ctx context.Context, userID, where string, args []any) (string, []any) {
	restrictionSQL, restrictionArgs := s.libraryCurationRestrictionSQL(ctx, userID)
	if restrictionSQL == "" || strings.Contains(where, "library_curation_") {
		return where, args
	}
	nextArgs := append([]any{}, args...)
	nextArgs = append(nextArgs, restrictionArgs...)
	return where + restrictionSQL, nextArgs
}

type libraryCurationPolicy struct {
	LibraryID       string
	AllowedTags     []string
	BlockedTags     []string
	BlockedKeywords []string
}

func (policy libraryCurationPolicy) active() bool {
	return policy.LibraryID != "" && (len(policy.AllowedTags) > 0 || len(policy.BlockedTags) > 0 || len(policy.BlockedKeywords) > 0)
}

func libraryCurationPolicyFromLibrary(library Library) libraryCurationPolicy {
	return libraryCurationPolicy{
		LibraryID:       strings.TrimSpace(library.ID),
		AllowedTags:     normalizeLibraryCurationList(library.Settings["allowedTags"]),
		BlockedTags:     normalizeLibraryCurationList(library.Settings["blockedTags"]),
		BlockedKeywords: normalizeLibraryCurationList(library.Settings["blockedKeywords"]),
	}
}

func (s *Server) libraryCurationRestrictionSQL(ctx context.Context, userID string) (string, []any) {
	if strings.TrimSpace(userID) == "" {
		return "", nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	memo := requestReadMemoFromContext(ctx)
	if memo != nil {
		memo.mu.Lock()
		if cached, ok := memo.libraryRestrictions[userID]; ok {
			memo.mu.Unlock()
			return cached.clause, append([]any(nil), cached.args...)
		}
		memo.mu.Unlock()
	}
	libraries, err := s.listLibrariesContext(ctx)
	if err != nil {
		if memo != nil {
			memo.mu.Lock()
			if memo.libraryRestrictions == nil {
				memo.libraryRestrictions = map[string]sqlRestrictionMemo{}
			}
			memo.libraryRestrictions[userID] = sqlRestrictionMemo{clause: " AND 1 = 0"}
			memo.mu.Unlock()
		}
		return " AND 1 = 0", nil
	}
	clauses := []string{}
	args := []any{}
	for _, library := range libraries {
		policy := libraryCurationPolicyFromLibrary(library)
		if !policy.active() {
			continue
		}
		policyClauses := []string{}
		policyArgs := []any{policy.LibraryID}
		if len(policy.AllowedTags) > 0 {
			policyClauses = append(policyClauses, `EXISTS (
				SELECT 1
				FROM media_category_facets library_curation_allowed_tag
				WHERE library_curation_allowed_tag.media_id = m.id
					AND library_curation_allowed_tag.library_id = m.library_id
					AND library_curation_allowed_tag.facet_type = 'tag'
					AND library_curation_allowed_tag.sort_value IN (`+sqlPlaceholders(len(policy.AllowedTags))+`)
			)`)
			for _, value := range policy.AllowedTags {
				policyArgs = append(policyArgs, value)
			}
		}
		if len(policy.BlockedTags) > 0 {
			policyClauses = append(policyClauses, `NOT EXISTS (
				SELECT 1
				FROM media_category_facets library_curation_blocked_tag
				WHERE library_curation_blocked_tag.media_id = m.id
					AND library_curation_blocked_tag.library_id = m.library_id
					AND library_curation_blocked_tag.facet_type = 'tag'
					AND library_curation_blocked_tag.sort_value IN (`+sqlPlaceholders(len(policy.BlockedTags))+`)
			)`)
			for _, value := range policy.BlockedTags {
				policyArgs = append(policyArgs, value)
			}
		}
		for _, keyword := range policy.BlockedKeywords {
			policyClauses = append(policyClauses, `LOWER(
				COALESCE(m.title, '') || ' ' ||
				COALESCE(m.original_title, '') || ' ' ||
				COALESCE(m.sort_title, '') || ' ' ||
				COALESCE(m.summary, '') || ' ' ||
				COALESCE(m.tagline, '')
			) NOT LIKE ? ESCAPE '\'`)
			policyArgs = append(policyArgs, "%"+sqlLikeEscape(keyword)+"%")
		}
		clauses = append(clauses, `(COALESCE(m.library_id, '') <> ? OR (`+strings.Join(policyClauses, " AND ")+`))`)
		args = append(args, policyArgs...)
	}
	if len(clauses) == 0 {
		if memo != nil {
			memo.mu.Lock()
			if memo.libraryRestrictions == nil {
				memo.libraryRestrictions = map[string]sqlRestrictionMemo{}
			}
			memo.libraryRestrictions[userID] = sqlRestrictionMemo{}
			memo.mu.Unlock()
		}
		return "", nil
	}
	clause := " AND " + strings.Join(clauses, " AND ")
	if memo != nil {
		memo.mu.Lock()
		if memo.libraryRestrictions == nil {
			memo.libraryRestrictions = map[string]sqlRestrictionMemo{}
		}
		memo.libraryRestrictions[userID] = sqlRestrictionMemo{clause: clause, args: append([]any(nil), args...)}
		memo.mu.Unlock()
	}
	return clause, args
}

func (s *Server) mediaVisibilityRestrictionSQL(userID string) (string, []any) {
	return s.mediaVisibilityRestrictionSQLContext(context.Background(), userID)
}

func (s *Server) mediaVisibilityRestrictionSQLContext(ctx context.Context, userID string) (string, []any) {
	userID = strings.TrimSpace(userID)
	if userID == "" {
		return "", nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	principal, err := s.requestPrincipalForIdentityContext(ctx, userID)
	if err != nil {
		return " AND 1 = 0", nil
	}
	accountID, profileID := principal.AccountID, principal.ProfileID
	clauses := []string{}
	args := []any{}
	if principal.MembershipEnvelope.Role != "owner" {
		clauses = append(clauses, `EXISTS (SELECT 1 FROM user_library_access ula WHERE ula.user_id = ? AND ula.library_id = m.library_id)`)
		args = append(args, accountID)
	}
	if rating := principal.MaxContentRating; rating != "" {
		clauses = append(clauses, `(`+contentRatingRankSQL("m.content_rating")+`) BETWEEN 1 AND ?`)
		args = append(args, contentRatingRank(rating))
	}
	ratingRankSQL := `(` + contentRatingRankSQL("m.content_rating") + `)`
	if principal.MaximumAgeRating != nil {
		if principal.AllowUnrated {
			clauses = append(clauses, `(`+ratingRankSQL+` = 0 OR (`+ratingRankSQL+` > 0 AND (`+contentRatingMinimumAgeSQL("m.content_rating")+`) <= ?))`)
		} else {
			clauses = append(clauses, `(`+ratingRankSQL+` > 0 AND (`+contentRatingMinimumAgeSQL("m.content_rating")+`) <= ?)`)
		}
		args = append(args, *principal.MaximumAgeRating)
	} else if !principal.AllowUnrated {
		clauses = append(clauses, ratingRankSQL+` > 0`)
	}
	if blocked := normalizedPolicyValues(principal.BlockedLabels); len(blocked) > 0 {
		clauses = append(clauses, `NOT EXISTS (
			SELECT 1 FROM media_category_facets profile_blocked_label
			WHERE profile_blocked_label.media_id = m.id
				AND profile_blocked_label.library_id = m.library_id
				AND profile_blocked_label.facet_type = 'accessLabel'
				AND profile_blocked_label.sort_value IN (`+sqlPlaceholders(len(blocked))+`)
		)`)
		for _, label := range blocked {
			args = append(args, label)
		}
	}
	tagPolicy := principal.MembershipEnvelope.TagPolicy
	appendTermPolicy := func(facetType string, values []string, allowed bool) {
		normalizedValues := normalizedPolicyValues(values)
		if len(normalizedValues) == 0 {
			return
		}
		operator := "EXISTS"
		if !allowed {
			operator = "NOT EXISTS"
		}
		clauses = append(clauses, operator+` (
			SELECT 1
			FROM media_category_facets access_term
			WHERE access_term.media_id = m.id
				AND access_term.library_id = m.library_id
				AND access_term.facet_type = ?
				AND access_term.sort_value IN (`+sqlPlaceholders(len(normalizedValues))+`)
		)`)
		args = append(args, facetType)
		for _, value := range normalizedValues {
			args = append(args, value)
		}
	}
	appendTermPolicy("tag", tagPolicy.AllowedTags, true)
	appendTermPolicy("accessLabel", tagPolicy.AllowedLabels, true)
	appendTermPolicy("tag", tagPolicy.BlockedTags, false)
	appendTermPolicy("accessLabel", tagPolicy.BlockedLabels, false)
	canBrowseDVR := principal.Permissions["viewDVR"] || principal.Permissions["scheduleDVR"] || principal.Permissions["deleteDVRRecordings"] || principal.Permissions["manageDVR"]
	if !canBrowseDVR {
		clauses = append(clauses, `lower(m.type) <> 'recording'`)
	} else {
		dvrConditions := []string{
			`dvr_mapping.media_id = m.id`,
			`dvr_recording.user_id = ?`,
			`COALESCE(NULLIF(dvr_recording.profile_id, ''), dvr_recording.user_id) = ?`,
			`lower(dvr_recording.status) IN ('complete', 'completed')`,
			`dvr_channel.source_id = dvr_recording.source_id`,
		}
		dvrArgs := []any{accountID, profileID}
		channelPolicy := principal.MembershipEnvelope.ChannelPolicy
		if len(channelPolicy.AllowedChannelIDs) > 0 {
			dvrConditions = append(dvrConditions, `dvr_recording.channel_id IN (`+sqlPlaceholders(len(channelPolicy.AllowedChannelIDs))+`)`)
			for _, channelID := range channelPolicy.AllowedChannelIDs {
				dvrArgs = append(dvrArgs, channelID)
			}
		}
		if len(channelPolicy.BlockedChannelIDs) > 0 {
			dvrConditions = append(dvrConditions, `dvr_recording.channel_id NOT IN (`+sqlPlaceholders(len(channelPolicy.BlockedChannelIDs))+`)`)
			for _, channelID := range channelPolicy.BlockedChannelIDs {
				dvrArgs = append(dvrArgs, channelID)
			}
		}
		clauses = append(clauses, `(lower(m.type) <> 'recording' OR EXISTS (
			SELECT 1
			FROM dvr_recording_media dvr_mapping
			JOIN live_tv_recordings dvr_recording ON dvr_recording.id = dvr_mapping.recording_id
			JOIN live_tv_sources dvr_source ON dvr_source.id = dvr_recording.source_id
			JOIN live_tv_channels dvr_channel ON dvr_channel.id = dvr_recording.channel_id
			WHERE `+strings.Join(dvrConditions, " AND ")+`
		))`)
		args = append(args, dvrArgs...)
	}
	if len(clauses) == 0 {
		return "", nil
	}
	return " AND " + strings.Join(clauses, " AND "), args
}

func normalizedPolicyValues(values []string) []string {
	seen := map[string]bool{}
	normalized := []string{}
	for _, raw := range values {
		value := normalizeProfilePolicyComparable(raw)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		normalized = append(normalized, value)
	}
	return normalized
}

func (s *Server) userTagPolicy(userID string) UserTagPolicy {
	return s.userTagPolicyContext(context.Background(), userID)
}

func (s *Server) userTagPolicyContext(ctx context.Context, userID string) UserTagPolicy {
	if strings.TrimSpace(userID) == "" {
		return UserTagPolicy{}
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var role string
	var raw string
	if err := s.queryUserRow(ctx, `SELECT role, preferences_json FROM users WHERE id = ?`, userID).Scan(&role, &raw); err != nil {
		return UserTagPolicy{}
	}
	if role == "owner" {
		return UserTagPolicy{}
	}
	return decodeUserTagPolicy(raw)
}

func mediaItemAllowedByTagPolicy(item MediaItem, policy UserTagPolicy) bool {
	if len(policy.AllowedTags) == 0 && len(policy.BlockedTags) == 0 && len(policy.AllowedLabels) == 0 && len(policy.BlockedLabels) == 0 {
		return true
	}
	tags := normalizedMediaItemTags(item)
	labels := normalizedMediaItemLabels(item)
	if len(policy.AllowedTags) > 0 {
		allowed := false
		for _, tag := range policy.AllowedTags {
			if tags[tag] {
				allowed = true
				break
			}
		}
		if !allowed {
			return false
		}
	}
	if len(policy.AllowedLabels) > 0 {
		allowed := false
		for _, label := range policy.AllowedLabels {
			if labels[label] {
				allowed = true
				break
			}
		}
		if !allowed {
			return false
		}
	}
	for _, tag := range policy.BlockedTags {
		if tags[tag] {
			return false
		}
	}
	for _, label := range policy.BlockedLabels {
		if labels[label] {
			return false
		}
	}
	return true
}

func normalizedMediaItemTags(item MediaItem) map[string]bool {
	return normalizedMediaStringList(item.Tags)
}

func normalizedMediaItemLabels(item MediaItem) map[string]bool {
	return normalizedMediaStringList(item.Labels)
}

func normalizedMediaStringList(values []string) map[string]bool {
	tags := map[string]bool{}
	for _, raw := range values {
		value := normalizeProfilePolicyComparable(raw)
		if value != "" {
			tags[value] = true
		}
	}
	return tags
}

