func (s *Server) userPlaybackPolicyContext(ctx context.Context, userID string) (int, int) {
	if strings.TrimSpace(userID) == "" {
		return 0, 0
	}
	var maxActiveStreams int
	var remoteBitrateLimitMbps int
	if err := s.queryUserRow(ctx, `SELECT COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0) FROM users WHERE id = ?`, userID).Scan(&maxActiveStreams, &remoteBitrateLimitMbps); err != nil {
		return 0, 0
	}
	return normalizeMaxActiveStreams(maxActiveStreams), normalizeRemoteBitrateLimitMbps(remoteBitrateLimitMbps)
}

func (s *Server) userSessionLimitContext(ctx context.Context, userID string) int {
	if strings.TrimSpace(userID) == "" {
		return 0
	}
	var limit int
	if err := s.queryUserRow(ctx, `SELECT COALESCE(max_active_sessions, 0) FROM users WHERE id = ?`, userID).Scan(&limit); err != nil {
		return 0
	}
	return normalizeMaxActiveSessions(limit)
}

func (s *Server) enforceActiveSessionLimit(userID string) error {
	return s.enforceActiveSessionLimitContext(context.Background(), userID)
}

func (s *Server) enforceActiveSessionLimitContext(ctx context.Context, userID string) error {
	if ctx == nil {
		ctx = context.Background()
	}
	maxActiveSessions := s.userSessionLimitContext(ctx, userID)
	if maxActiveSessions <= 0 {
		return nil
	}
	var active int
	now := time.Now().UTC().Format(time.RFC3339)
	if err := s.queryUserRow(ctx, `SELECT COUNT(*) FROM sessions WHERE user_id = ? AND expires_at > ?`, userID, now).Scan(&active); err != nil {
		return err
	}
	if active >= maxActiveSessions {
		return errActiveSessionLimit
	}
	return nil
}

func enforceActiveSessionLimitTx(tx *sql.Tx, userID string, now time.Time) error {
	var maxActiveSessions int
	if err := tx.QueryRow(`SELECT COALESCE(max_active_sessions, 0) FROM users WHERE id = ?`, userID).Scan(&maxActiveSessions); err != nil {
		return err
	}
	maxActiveSessions = normalizeMaxActiveSessions(maxActiveSessions)
	if maxActiveSessions <= 0 {
		return nil
	}
	var active int
	if err := tx.QueryRow(`SELECT COUNT(*) FROM sessions WHERE user_id = ? AND expires_at > ?`, userID, now.UTC().Format(time.RFC3339)).Scan(&active); err != nil {
		return err
	}
	if active >= maxActiveSessions {
		return errActiveSessionLimit
	}
	return nil
}

func (s *Server) enforceActivePlaybackSessionLimit(userID string) error {
	return s.enforceActivePlaybackSessionLimitContext(context.Background(), userID)
}

func (s *Server) enforceActivePlaybackSessionLimitContext(ctx context.Context, userID string) error {
	maxActiveStreams, _ := s.userPlaybackPolicyContext(ctx, userID)
	if maxActiveStreams <= 0 {
		return nil
	}
	active, err := s.activePlaybackSessionCountForUserContext(ctx, userID)
	if err != nil {
		return err
	}
	if active >= maxActiveStreams {
		return errPlaybackSessionLimit
	}
	return nil
}

// enforcePlaybackSessionReplacementLimitContext treats an active session owned
// by the same stable client instance as the slot that the new session will
// replace. The previous session remains active until the replacement has a
// session row, media grant, and queue, so a failed start is non-destructive.
func (s *Server) enforcePlaybackSessionReplacementLimitContext(ctx context.Context, userID string, clientInstanceID string) error {
	maxActiveStreams, _ := s.userPlaybackPolicyContext(ctx, userID)
	if maxActiveStreams <= 0 {
		return nil
	}
	clientInstanceID = normalizePlaybackClientInstanceID(clientInstanceID)
	cutoff := time.Now().UTC().Add(-45 * time.Second).Format(time.RFC3339)
	var active int
	if err := s.queryUserRow(ctx, `
		SELECT COUNT(*)
		FROM playback_sessions
		WHERE user_id = ? AND ended_at = '' AND state NOT IN ('stopped', 'handoff_pending') AND last_seen_at >= ?
			AND (? = '' OR client_instance_id <> ?)`,
		userID, cutoff, clientInstanceID, clientInstanceID).Scan(&active); err != nil {
		return err
	}
	if active >= maxActiveStreams {
		return errPlaybackSessionLimit
	}
	return nil
}

func (s *Server) activePlaybackSessionCountForUser(userID string) (int, error) {
	return s.activePlaybackSessionCountForUserContext(context.Background(), userID)
}

func (s *Server) activePlaybackSessionCountForUserContext(ctx context.Context, userID string) (int, error) {
	var active int
	cutoff := time.Now().UTC().Add(-45 * time.Second).Format(time.RFC3339)
	if err := s.queryUserRow(ctx, `
		SELECT COUNT(*)
		FROM playback_sessions
		WHERE user_id = ? AND ended_at = '' AND state NOT IN ('stopped', 'handoff_pending') AND last_seen_at >= ?`,
		userID, cutoff).Scan(&active); err != nil {
		return 0, err
	}
	return active, nil
}

func (s *Server) applyUserPlaybackPolicy(user User, profile PlaybackClientProfile) PlaybackClientProfile {
	return s.applyUserPlaybackPolicyContext(context.Background(), user, profile)
}

func (s *Server) applyUserPlaybackPolicyContext(ctx context.Context, user User, profile PlaybackClientProfile) PlaybackClientProfile {
	limit := s.effectiveRemoteBitrateLimitMbpsContext(ctx, user)
	if limit <= 0 {
		return profile
	}
	maxBitrate := limit * 1000 * 1000
	if profile.MaxBitrate <= 0 || maxBitrate < profile.MaxBitrate {
		profile.MaxBitrate = maxBitrate
	}
	return profile
}

func (s *Server) applyPlaybackPolicyForRequest(ctx context.Context, r *http.Request, user User, profile PlaybackClientProfile) PlaybackClientProfile {
	if s.playbackNetworkClassForRequest(r) != playbackNetworkRemote {
		return profile
	}
	profile = s.applyUserPlaybackPolicyContext(ctx, user, profile)
	limit := s.remoteAccessBitrateLimitMbpsForRequest(r)
	if limit <= 0 {
		return profile
	}
	maxBitrate := limit * 1000 * 1000
	if profile.MaxBitrate <= 0 || maxBitrate < profile.MaxBitrate {
		profile.MaxBitrate = maxBitrate
	}
	return profile
}

func (s *Server) remoteAccessBitrateLimitMbpsForRequest(r *http.Request) int {
	if r == nil {
		return 0
	}
	settings, err := s.remoteAccessSettings()
	if err != nil || !settings.Enabled || settings.PublicPortMode == "disabled" {
		return 0
	}
	limit := normalizeRemoteBitrateLimitMbps(settings.RemoteBitrateLimitMbps)
	if limit <= 0 || s.playbackNetworkClassForRequest(r) != playbackNetworkRemote {
		return 0
	}
	return limit
}

func (s *Server) requestMatchesRemoteAccessEndpoint(r *http.Request, settings RemoteAccessSettings) bool {
	requestHost := normalizedRequestHostForPolicy(r, s.requestFromTrustedProxy(r))
	if requestHost == "" {
		return false
	}
	for _, host := range []string{
		settings.AssignedHostname,
		s.remotePublicEndpoint(settings).Host,
	} {
		if requestHost == normalizedHostnameForPolicy(host) {
			return true
		}
	}
	return false
}

func normalizedRequestHostForPolicy(r *http.Request, trustedProxy bool) string {
	if r == nil {
		return ""
	}
	host := strings.TrimSpace(r.Host)
	if trustedProxy {
		if forwardedHost := strings.TrimSpace(strings.Split(r.Header.Get("X-Forwarded-Host"), ",")[0]); forwardedHost != "" {
			host = forwardedHost
		}
	}
	return normalizedHostnameForPolicy(host)
}

func normalizedHostnameForPolicy(host string) string {
	host = strings.TrimSpace(strings.ToLower(host))
	if host == "" || strings.ContainsAny(host, "\r\n\t /\\") {
		return ""
	}
	if parsedHost, _, err := net.SplitHostPort(host); err == nil {
		host = parsedHost
	} else if strings.Count(host, ":") == 1 {
		if beforePort, _, found := strings.Cut(host, ":"); found {
			host = beforePort
		}
	}
	return strings.Trim(strings.Trim(host, "[]"), ".")
}

func (s *Server) effectiveRemoteBitrateLimitMbps(user User) int {
	return s.effectiveRemoteBitrateLimitMbpsContext(context.Background(), user)
}

func (s *Server) effectiveRemoteBitrateLimitMbpsContext(ctx context.Context, user User) int {
	limit := normalizeRemoteBitrateLimitMbps(user.RemoteBitrateLimitMbps)
	if limit <= 0 {
		_, limit = s.userPlaybackPolicyContext(ctx, user.ID)
	}
	deviceLimit := s.deviceRemoteBitrateLimitMbpsContext(ctx, user.DeviceID)
	if deviceLimit > 0 && (limit <= 0 || deviceLimit < limit) {
		limit = deviceLimit
	}
	return limit
}

func (s *Server) deviceRemoteBitrateLimitMbps(deviceID string) int {
	return s.deviceRemoteBitrateLimitMbpsContext(context.Background(), deviceID)
}

func (s *Server) deviceRemoteBitrateLimitMbpsContext(ctx context.Context, deviceID string) int {
	deviceID = strings.TrimSpace(deviceID)
	if deviceID == "" {
		return 0
	}
	var limit int
	if err := s.queryUserRow(ctx, `SELECT COALESCE(remote_bitrate_limit_mbps, 0) FROM devices WHERE id = ? AND revoked_at = ''`, deviceID).Scan(&limit); err != nil {
		return 0
	}
	return normalizeRemoteBitrateLimitMbps(limit)
}

func normalizeMaxActiveSessions(value int) int {
	if value < 0 {
		return 0
	}
	if value > 100 {
		return 100
	}
	return value
}

func normalizeMaxActiveStreams(value int) int {
	if value < 0 {
		return 0
	}
	if value > maxConcurrentStreamsPerUser {
		return maxConcurrentStreamsPerUser
	}
	return value
}

func normalizeRemoteBitrateLimitMbps(value int) int {
	if value < 0 {
		return 0
	}
	if value > 1000 {
		return 1000
	}
	return value
}

func normalizeMaxContentRating(value string) string {
	normalized := strings.ToUpper(strings.TrimSpace(value))
	normalized = strings.ReplaceAll(normalized, "_", "-")
	switch normalized {
	case "", "ALL", "NONE", "UNRESTRICTED":
		return ""
	case "G", "PG", "PG-13", "R", "NC-17", "TV-Y", "TV-Y7", "TV-G", "TV-PG", "TV-14", "TV-MA", "C", "C8", "14A", "18A", "A", "U", "12", "12A", "15", "18":
		return normalized
	default:
		return ""
	}
}

func validateUserPatchPolicyFields(req UserPatchRequest) error {
	if req.MaxActiveSessions != nil && (*req.MaxActiveSessions < 0 || *req.MaxActiveSessions > 100) {
		return invalidRequestField("maxActiveSessions", "maxActiveSessions must be between 0 and 100")
	}
	if req.MaxActiveStreams != nil && (*req.MaxActiveStreams < 0 || *req.MaxActiveStreams > maxConcurrentStreamsPerUser) {
		return invalidRequestField("maxActiveStreams", fmt.Sprintf("maxActiveStreams must be between 0 and %d", maxConcurrentStreamsPerUser))
	}
	if req.RemoteBitrateLimitMbps != nil && (*req.RemoteBitrateLimitMbps < 0 || *req.RemoteBitrateLimitMbps > 1000) {
		return invalidRequestField("remoteBitrateLimitMbps", "remoteBitrateLimitMbps must be between 0 and 1000")
	}
	if req.MaxContentRating != nil {
		raw := strings.ToUpper(strings.TrimSpace(*req.MaxContentRating))
		if raw != "" && normalizeMaxContentRating(raw) == "" && raw != "ALL" && raw != "NONE" && raw != "UNRESTRICTED" {
			return invalidRequestField("maxContentRating", "maxContentRating is not a supported rating")
		}
	}
	if req.AccessSchedule != nil {
		for _, day := range req.AccessSchedule.Days {
			if day < 0 || day > 6 {
				return invalidRequestField("accessSchedule.days", "access schedule days must be between 0 and 6")
			}
		}
		if req.AccessSchedule.StartMinute < 0 || req.AccessSchedule.StartMinute > 1439 {
			return invalidRequestField("accessSchedule.startMinute", "access schedule startMinute must be between 0 and 1439")
		}
		if req.AccessSchedule.EndMinute < 0 || req.AccessSchedule.EndMinute > 1439 {
			return invalidRequestField("accessSchedule.endMinute", "access schedule endMinute must be between 0 and 1439")
		}
	}
	if req.DevicePolicy != nil {
		mode := strings.ToLower(strings.TrimSpace(req.DevicePolicy.Mode))
		if mode != "" && mode != "any" && mode != "trusted" && mode != "allowlist" {
			return invalidRequestField("devicePolicy.mode", "device policy mode must be any, trusted, or allowlist")
		}
		if len(req.DevicePolicy.AllowedDeviceIDs) > 128 {
			return invalidRequestField("devicePolicy.allowedDeviceIds", "device allowlist must contain at most 128 devices")
		}
	}
	for field, values := range map[string][]string{
		"tagPolicy.allowedTags":   reqTagPolicyList(req.TagPolicy, func(policy UserTagPolicy) []string { return policy.AllowedTags }),
		"tagPolicy.blockedTags":   reqTagPolicyList(req.TagPolicy, func(policy UserTagPolicy) []string { return policy.BlockedTags }),
		"tagPolicy.allowedLabels": reqTagPolicyList(req.TagPolicy, func(policy UserTagPolicy) []string { return policy.AllowedLabels }),
		"tagPolicy.blockedLabels": reqTagPolicyList(req.TagPolicy, func(policy UserTagPolicy) []string { return policy.BlockedLabels }),
	} {
		if len(values) > 64 {
			return invalidRequestField(field, field+" must contain at most 64 values")
		}
	}
	if req.ChannelPolicy != nil {
		if len(req.ChannelPolicy.AllowedChannelIDs) > 128 {
			return invalidRequestField("channelPolicy.allowedChannelIds", "channel allowlist must contain at most 128 channels")
		}
		if len(req.ChannelPolicy.BlockedChannelIDs) > 128 {
			return invalidRequestField("channelPolicy.blockedChannelIds", "channel blocklist must contain at most 128 channels")
		}
	}
	return nil
}

func reqTagPolicyList(policy *UserTagPolicy, selectValues func(UserTagPolicy) []string) []string {
	if policy == nil {
		return nil
	}
	return selectValues(*policy)
}

func contentRatingAllowed(value string, maxRating string) bool {
	limit := contentRatingRank(normalizeMaxContentRating(maxRating))
	if limit == 0 {
		return true
	}
	rank := contentRatingRank(normalizeContentRating(value))
	return rank > 0 && rank <= limit
}

func profileMediaPolicyAllows(principal RequestPrincipal, item MediaItem) bool {
	rating := normalizeContentRating(item.ContentRating)
	rank := contentRatingRank(rating)
	if rank == 0 && !principal.AllowUnrated {
		return false
	}
	if principal.MaximumAgeRating != nil && rank > 0 && contentRatingMinimumAge(rating) > *principal.MaximumAgeRating {
		return false
	}
	if len(principal.BlockedLabels) > 0 {
		labels := normalizedMediaItemLabels(item)
		for _, blocked := range principal.BlockedLabels {
			if labels[normalizeProfilePolicyComparable(blocked)] {
				return false
			}
		}
	}
	return true
}

func contentRatingMinimumAge(value string) int {
	switch normalizeContentRating(value) {
	case "G", "TV-G", "U", "C":
		return 0
	case "TV-Y":
		return 2
	case "TV-Y7":
		return 7
	case "C8":
		return 8
	case "PG", "TV-PG":
		return 10
	case "12", "12A":
		return 12
	case "PG-13":
		return 13
	case "TV-14", "14A":
		return 14
	case "15":
		return 15
	case "R":
		return 17
	case "TV-MA", "NC-17", "18", "18A", "A":
		return 18
	default:
		return 0
	}
}

func contentRatingMinimumAgeSQL(column string) string {
	value := "UPPER(REPLACE(TRIM(COALESCE(" + column + ", '')), '_', '-'))"
	return `CASE ` + value + `
		WHEN 'G' THEN 0 WHEN 'TV-G' THEN 0 WHEN 'U' THEN 0 WHEN 'C' THEN 0
		WHEN 'TV-Y' THEN 2 WHEN 'TV-Y7' THEN 7 WHEN 'C8' THEN 8
		WHEN 'PG' THEN 10 WHEN 'TV-PG' THEN 10 WHEN '12' THEN 12 WHEN '12A' THEN 12
		WHEN 'PG-13' THEN 13 WHEN 'TV-14' THEN 14 WHEN '14A' THEN 14 WHEN '15' THEN 15
		WHEN 'R' THEN 17 WHEN 'TV-MA' THEN 18 WHEN 'NC-17' THEN 18 WHEN '18' THEN 18
		WHEN '18A' THEN 18 WHEN 'A' THEN 18 ELSE 0 END`
}

func normalizeContentRating(value string) string {
	normalized := strings.ToUpper(strings.TrimSpace(value))
	normalized = strings.ReplaceAll(normalized, "_", "-")
	return normalized
}

func contentRatingRank(value string) int {
	switch value {
	case "TV-Y", "TV-G", "G", "U", "C":
		return 1
	case "TV-Y7", "C8":
		return 2
	case "TV-PG", "PG":
		return 3
	case "TV-14", "PG-13", "12", "12A", "14A":
		return 4
	case "R", "15", "18A":
		return 5
	case "TV-MA", "NC-17", "18", "A":
		return 6
	default:
		return 0
	}
}

func (s *Server) childrenFor(userID string, item MediaItem) ([]MediaItem, error) {
	switch item.Type {
	case "show", "anime":
		seasons, err := s.queryMedia(userID, `WHERE m.parent_id = ? ORDER BY m.index_number ASC`, []any{item.ID})
		if err != nil {
			return nil, err
		}
		for i := range seasons {
			episodes, err := s.queryMedia(userID, `WHERE m.parent_id = ? ORDER BY m.index_number ASC`, []any{seasons[i].ID})
			if err != nil {
				return nil, err
			}
			seasons[i].Children = episodes
		}
		return seasons, nil
	case "artist":
		albums, err := s.queryMedia(userID, `WHERE m.parent_id = ? ORDER BY m.index_number ASC`, []any{item.ID})
		if err != nil {
			return nil, err
		}
		for i := range albums {
			tracks, err := s.queryMedia(userID, `WHERE m.parent_id = ? ORDER BY m.index_number ASC`, []any{albums[i].ID})
			if err != nil {
				return nil, err
			}
			albums[i].Children = tracks
		}
		return albums, nil
	case "movie", "season", "album", "audiobook":
		return s.queryMedia(userID, `WHERE m.parent_id = ? ORDER BY m.index_number ASC`, []any{item.ID})
	default:
		return nil, nil
	}
}

func (s *Server) childrenForDetail(ctx context.Context, userID string, item MediaItem) ([]MediaItem, bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	switch item.Type {
	case "show", "anime":
		return s.groupedChildrenForDetail(ctx, userID, item.ID, maxDetailChildGroups, maxDetailNestedChildrenTotal)
	case "artist":
		return s.groupedChildrenForDetail(ctx, userID, item.ID, maxDetailChildGroups, maxDetailNestedChildrenTotal)
	case "movie", "season", "album", "audiobook":
		children, truncated, err := s.detailChildPage(ctx, userID, item.ID, maxDetailDirectChildren)
		return children, truncated, err
	default:
		return nil, false, nil
	}
}

func (s *Server) extraChildrenForDetail(ctx context.Context, userID, parentID string) ([]MediaItem, error) {
	where := `WHERE m.parent_id = ? AND ` + mediaExtraSQLPredicate("m")
	args := []any{parentID}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	args = append(args, maxDetailDirectChildren)
	return s.queryMediaListItemsContext(ctx, userID, where+` ORDER BY m.index_number ASC, m.sort_title ASC, m.id ASC LIMIT ?`, args)
}

func (s *Server) groupedChildrenForDetail(ctx context.Context, userID, parentID string, maxGroups, childBudget int) ([]MediaItem, bool, error) {
	groups, groupsTruncated, err := s.detailChildPage(ctx, userID, parentID, maxGroups)
	if err != nil {
		return nil, false, err
	}
	truncated := groupsTruncated
	remaining := childBudget
	for i := range groups {
		if err := ctx.Err(); err != nil {
			return nil, truncated, err
		}
		if remaining <= 0 {
			groups[i].ChildrenTruncated = true
			truncated = true
			continue
		}
		limit := maxDetailNestedChildrenPerGroup
		if remaining < limit {
			limit = remaining
		}
		children, childrenTruncated, err := s.detailChildPage(ctx, userID, groups[i].ID, limit)
		if err != nil {
			return nil, truncated, err
		}
		groups[i].Children = children
		groups[i].ChildrenTruncated = childrenTruncated
		if childrenTruncated {
			truncated = true
		}
		remaining -= len(children)
	}
	return groups, truncated, nil
}

func (s *Server) detailChildPage(ctx context.Context, userID, parentID string, limit int) ([]MediaItem, bool, error) {
	if limit <= 0 {
		return nil, false, nil
	}
	where := `WHERE m.parent_id = ? AND NOT ` + mediaExtraSQLPredicate("m")
	args := []any{parentID}
	where, args = s.applyMediaVisibilityRestrictionSQL(userID, where, args)
	args = append(args, limit+1)
	items, err := s.queryMediaListItemsContext(ctx, userID, where+` ORDER BY m.index_number ASC, m.sort_title ASC, m.id ASC LIMIT ?`, args)
	if err != nil {
		return nil, false, err
	}
	if len(items) <= limit {
		return items, false, nil
	}
	return items[:limit], true, nil
}

func (s *Server) listStreams(mediaID string) ([]Stream, error) {
	return s.listStreamsContext(context.Background(), mediaID)
}

func (s *Server) listStreamsContext(ctx context.Context, mediaID string) ([]Stream, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT id, COALESCE(file_id, ''), COALESCE(source_kind, 'unknown'), COALESCE(NULLIF(storage_key, ''), id), kind, codec, language, channels, bitrate, width, height, display_title,
			COALESCE(source_url, ''), COALESCE(subtitle_offset_ms, 0),
			COALESCE(stream_index, 0), COALESCE(frame_rate, 0), COALESCE(aspect_ratio, ''),
			COALESCE(sample_rate, 0), COALESCE(channel_layout, ''),
			COALESCE(is_default, 0), COALESCE(is_forced, 0), COALESCE(hearing_impaired, 0),
			COALESCE(profile, ''), COALESCE(level, 0), COALESCE(pixel_format, ''), COALESCE(bit_depth, 0),
			COALESCE(color_transfer, ''), COALESCE(color_primaries, ''), COALESCE(color_space, ''),
			COALESCE(chroma_location, ''), COALESCE(field_order, ''), COALESCE(dynamic_range, ''),
			COALESCE(dolby_vision_profile, ''), COALESCE(exact_seek_safe, 0), COALESCE(keyframe_evidence_at, '')
		FROM media_streams
		WHERE media_id = ?
		ORDER BY CASE kind WHEN 'video' THEN 1 WHEN 'audio' THEN 2 ELSE 3 END,
			CASE source_kind WHEN 'ffprobe' THEN 0 WHEN 'sidecar' THEN 1 WHEN 'upload' THEN 2 ELSE 3 END,
			stream_index ASC, width DESC, height DESC, channels DESC, id`, mediaID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var streams []Stream
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return streams, err
		}
		var stream Stream
		var isDefault, isForced, hearingImpaired int
		if err := rows.Scan(&stream.ID, &stream.FileID, &stream.SourceKind, &stream.StorageKey, &stream.Kind, &stream.Codec, &stream.Language, &stream.Channels, &stream.Bitrate, &stream.Width, &stream.Height, &stream.DisplayTitle,
			&stream.SourceURL, &stream.SubtitleOffsetMs,
			&stream.Index, &stream.FrameRate, &stream.AspectRatio, &stream.SampleRate, &stream.ChannelLayout, &isDefault, &isForced, &hearingImpaired,
			&stream.Profile, &stream.Level, &stream.PixelFormat, &stream.BitDepth,
			&stream.ColorTransfer, &stream.ColorPrimaries, &stream.ColorSpace, &stream.ChromaLocation, &stream.FieldOrder,
			&stream.DynamicRange, &stream.DolbyVisionProfile, &stream.ExactSeekSafe, &stream.KeyframeEvidenceAt); err != nil {
			return nil, err
		}
		stream.Default = isDefault != 0
		stream.Forced = isForced != 0
		stream.HearingImpaired = hearingImpaired != 0
		if stream.Kind == "subtitle" && strings.TrimSpace(stream.SourceURL) != "" {
			stream.SourceURL = "/api/media/" + url.PathEscape(mediaID) + "/subtitles/" + url.PathEscape(stream.ID)
		}
		streams = append(streams, stream)
	}
	return streams, rows.Err()
}

func (s *Server) attachmentsForMedia(mediaID string) []MediaAttachment {
	return s.attachmentsForMediaContext(context.Background(), mediaID)
}

func (s *Server) attachmentsForMediaContext(ctx context.Context, mediaID string) []MediaAttachment {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `SELECT id, stream_id, filename, mime_type, codec, path, size_bytes FROM media_attachments WHERE media_id = ? ORDER BY filename ASC, id ASC`, mediaID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	attachments := []MediaAttachment{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return attachments
		}
		var attachment MediaAttachment
		var rawPath string
		if err := rows.Scan(&attachment.ID, &attachment.StreamID, &attachment.Filename, &attachment.MimeType, &attachment.Codec, &rawPath, &attachment.SizeBytes); err != nil {
			return attachments
		}
		if rawPath != "" {
			attachment.URL = "/api/media/" + url.PathEscape(mediaID) + "/attachments/" + url.PathEscape(attachment.ID)
		}
		attachments = append(attachments, attachment)
	}
	return attachments
}

func (s *Server) segmentsForMedia(mediaID string) []MediaSegment {
	return s.segmentsForMediaContext(context.Background(), mediaID)
}

func (s *Server) segmentsForMediaContext(ctx context.Context, mediaID string) []MediaSegment {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT id, segment_type, start_seconds, end_seconds, automatic_safe, source, provider, confidence, created_at
		FROM media_segments
		WHERE media_id = ?
		ORDER BY start_seconds ASC, end_seconds ASC, segment_type ASC`, mediaID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	segments := []MediaSegment{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return segments
		}
		var segment MediaSegment
		var automaticSafe int
		if err := rows.Scan(&segment.ID, &segment.Type, &segment.StartSeconds, &segment.EndSeconds, &automaticSafe, &segment.Source, &segment.Provider, &segment.Confidence, &segment.CreatedAt); err != nil {
			return segments
		}
		segment.AutomaticSafe = automaticSafe != 0
		segments = append(segments, segment)
	}
	return segments
}

func (s *Server) addMediaSegment(userID, mediaID string, req MediaSegmentRequest) (MediaItem, error) {
	item, err := s.getMediaListItem(userID, mediaID)
	if err != nil {
		return MediaItem{}, err
	}
	segmentType := normalizedMediaSegmentType(req.Type)
	if !allowedMediaSegmentType(segmentType) {
		return MediaItem{}, errors.New("Segment type must be intro or credits.")
	}
	if req.StartSeconds < 0 {
		return MediaItem{}, errors.New("Segment start must be zero or greater.")
	}
	if req.EndSeconds <= req.StartSeconds {
		return MediaItem{}, errors.New("Segment end must be after the start time.")
	}
	if item.DurationSeconds > 0 && req.EndSeconds > item.DurationSeconds {
		return MediaItem{}, errors.New("Segment end cannot be after the media runtime.")
	}
	provider := strings.TrimSpace(req.Provider)
	if provider == "" {
		provider = "editor"
	}
	confidence := req.Confidence
	if confidence <= 0 {
		confidence = 1
	}
	if confidence > 1 {
		confidence = 1
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if _, err := s.execUserWrite(context.Background(), `
		INSERT INTO media_segments (id, media_id, segment_type, start_seconds, end_seconds, automatic_safe, source, provider, confidence, created_at)
		VALUES (?, ?, ?, ?, ?, ?, 'manual', ?, ?, ?)`,
		randomOpaquePublicID(), mediaID, segmentType, req.StartSeconds, req.EndSeconds, boolInt(req.AutomaticSafe), provider, confidence, now); err != nil {
		return MediaItem{}, err
	}
	return s.getMediaDetailWithOptions(userID, mediaID, mediaDetailOptions{Recommendations: false})
}

func (s *Server) deleteMediaSegment(userID, mediaID, segmentID string) (MediaItem, error) {
	if _, err := s.getMediaListItem(userID, mediaID); err != nil {
		return MediaItem{}, err
	}
	result, err := s.execUserWrite(context.Background(), `DELETE FROM media_segments WHERE media_id = ? AND id = ?`, mediaID, segmentID)
	if err != nil {
		return MediaItem{}, err
	}
	if rowsAffected(result) == 0 {
		return MediaItem{}, sql.ErrNoRows
	}
	return s.getMediaDetailWithOptions(userID, mediaID, mediaDetailOptions{Recommendations: false})
}

func (s *Server) trickplaySetsForMedia(mediaID string) []MediaTrickplaySet {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id, media_id, width, height, tile_width, tile_height, interval_seconds, duration_seconds, tile_count, stale, created_at
		FROM media_trickplay_sets
		WHERE media_id = ?
		ORDER BY stale ASC, width DESC, interval_seconds ASC, created_at DESC`, mediaID)
	if err != nil {
		return nil
	}
	sets := []MediaTrickplaySet{}
	for rows.Next() {
		var set MediaTrickplaySet
		var stale int
		if err := rows.Scan(
			&set.ID,
			&set.MediaID,
			&set.Width,
			&set.Height,
			&set.TileWidth,
			&set.TileHeight,
			&set.IntervalSeconds,
			&set.DurationSeconds,
			&set.TileCount,
			&stale,
			&set.CreatedAt,
		); err != nil {
			return sets
		}
		set.Stale = stale != 0
		sets = append(sets, set)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil
	}
	_ = rows.Close()
	available := make([]MediaTrickplaySet, 0, len(sets))
	for _, set := range sets {
		if s.trickplaySetFilesAvailable(set.ID, set.TileCount) {
			available = append(available, set)
		}
	}
	return available
}

func (s *Server) trickplaySetFilesAvailable(setID string, expectedCount int) bool {
	if expectedCount <= 0 {
		return false
	}
	rows, err := s.queryUserRead(context.Background(), `
		SELECT path
		FROM media_trickplay_tiles
		WHERE set_id = ?
		ORDER BY tile_index ASC`, setID)
	if err != nil {
		return false
	}
	defer rows.Close()
	count := 0
	for rows.Next() {
		var path string
		if err := rows.Scan(&path); err != nil {
			return false
		}
		info, err := os.Stat(path)
		if err != nil || info.IsDir() || info.Size() <= 0 {
			return false
		}
		count++
	}
	return rows.Err() == nil && count >= expectedCount
}

func normalizedMediaSegmentType(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	if value == "outro" {
		return "credits"
	}
	return value
}

func mediaSegmentTypes() []string {
	return []string{"intro", "credits"}
}

func allowedMediaSegmentType(value string) bool {
	for _, candidate := range mediaSegmentTypes() {
		if value == candidate {
			return true
		}
	}
	return false
}

func (s *Server) refreshMediaSearch(item MediaItem) error {
	if _, err := s.execUserWrite(context.Background(), `DELETE FROM media_search WHERE media_id = ?`, item.ID); err != nil {
		return err
	}
	title, summary, keywords := mediaSearchDocument(item)
	_, err := s.execUserWrite(context.Background(), `INSERT INTO media_search (media_id, title, summary, genres) VALUES (?, ?, ?, ?)`,
		item.ID, title, summary, keywords)
	return err
}

func mediaSearchDocument(item MediaItem) (string, string, string) {
	titleParts := []string{item.Title, item.SortTitle, item.OriginalTitle, item.Edition}
	summaryParts := []string{item.Summary, item.Tagline}
	keywordParts := []string{
		item.Type,
		item.ContentRating,
		item.Studio,
		item.Network,
		item.Country,
		conditionalString(item.Year > 0, strconv.Itoa(item.Year)),
		conditionalString(item.SeasonNumber > 0, strconv.Itoa(item.SeasonNumber)),
		conditionalString(item.EpisodeNumber > 0, strconv.Itoa(item.EpisodeNumber)),
	}
	keywordParts = append(keywordParts, item.Genres...)
	keywordParts = append(keywordParts, item.Tags...)
	keywordParts = append(keywordParts, item.Labels...)
	keywordParts = append(keywordParts, item.ParentTitle, item.GrandparentTitle)
	for key, value := range item.TypedMetadata {
		keywordParts = append(keywordParts, key, value)
	}
	return strings.Join(nonEmptySearchParts(titleParts), " "), strings.Join(nonEmptySearchParts(summaryParts), " "), strings.Join(nonEmptySearchParts(keywordParts), " ")
}

func mediaSearchQuery(q string) string {
	terms := searchTerms(q)
	if len(terms) == 0 {
		return ""
	}
	if len(terms) > maxSearchTerms {
		terms = terms[:maxSearchTerms]
	}
	quoted := make([]string, 0, len(terms))
	for _, term := range terms {
		quoted = append(quoted, mediaSearchTermQuery(term))
	}
	return strings.Join(quoted, " ")
}

func searchTerms(value string) []string {
	value = truncateStringRunes(value, maxSearchQueryRunes)
	fields := strings.FieldsFunc(strings.ToLower(value), func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	})
	out := make([]string, 0, len(fields))
	for _, field := range fields {
		field = strings.TrimSpace(field)
		if field != "" {
			out = append(out, field)
		}
	}
	return out
}

func mediaSearchTermQuery(term string) string {
	if len(term) >= 3 {
		return term + "*"
	}
	return strconv.Quote(term)
}

func truncateStringRunes(value string, maxRunes int) string {
	if maxRunes <= 0 {
		return ""
	}
	count := 0
	for index := range value {
		if count == maxRunes {
			return value[:index]
		}
		count++
	}
	return value
}

func nonEmptySearchParts(values []string) []string {
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			out = append(out, value)
		}
	}
	return out
}

func (s *Server) upsertState(profileID, mediaID, column string, value int) error {
	if column != "watchlisted" && column != "favorite" && column != "liked" && column != "rating" {
		return errors.New("invalid state column")
	}
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	tags := []string{"media-state", "library-items", "home"}
	if column == "watchlisted" || column == "favorite" {
		tags = append(tags, "saved")
	}
	_, err = s.execUserWriteTaggedForViewer(context.Background(), accountID, profileID, tags, fmt.Sprintf(`
		INSERT INTO user_media_state (profile_id, user_id, media_id, %s, updated_at)
		VALUES (?, ?, ?, ?, ?)
		ON CONFLICT(profile_id, media_id) DO UPDATE SET %s = excluded.%s, updated_at = excluded.updated_at`, column, column, column),
		profileID, accountID, mediaID, value, now)
	if err == nil {
		s.invalidateHomeCacheForProfile(profileID)
	}
	return err
}

func (s *Server) bulkUpsertState(profileID string, mediaIDs []string, column string, value int) error {
	if column != "watchlisted" && column != "favorite" && column != "liked" && column != "rating" {
		return errors.New("invalid state column")
	}
	if len(mediaIDs) == 0 {
		return nil
	}
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	placeholders := make([]string, 0, len(mediaIDs))
	args := make([]any, 0, len(mediaIDs)*5)
	for _, mediaID := range mediaIDs {
		placeholders = append(placeholders, "(?, ?, ?, ?, ?)")
		args = append(args, profileID, accountID, mediaID, value, now)
	}
	tags := []string{"media-state", "library-items", "home"}
	if column == "watchlisted" || column == "favorite" {
		tags = append(tags, "saved")
	}
	_, err = s.execUserWriteTaggedForViewer(context.Background(), accountID, profileID, tags, fmt.Sprintf(`
		INSERT INTO user_media_state (profile_id, user_id, media_id, %s, updated_at)
		VALUES %s
		ON CONFLICT(profile_id, media_id) DO UPDATE SET %s = excluded.%s, updated_at = excluded.updated_at`,
		column, strings.Join(placeholders, ","), column, column), args...)
	if err == nil {
		s.invalidateHomeCacheForProfile(profileID)
	}
	return err
}

func normalizeUserReaction(value string) (string, bool) {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", "none", "clear":
		return "", true
	case "like", "liked":
		return "like", true
	case "dislike", "disliked":
		return "dislike", true
	default:
		return "", false
	}
}

func reactionValue(reaction string) int {
	switch reaction {
	case "like":
		return 1
	case "dislike":
		return -1
	default:
		return 0
	}
}

func reactionName(value int) string {
	switch {
	case value > 0:
		return "like"
	case value < 0:
		return "dislike"
	default:
		return ""
	}
}

func (s *Server) setWatched(profileID, mediaID string, watched bool) error {
	now := time.Now().UTC().Format(time.RFC3339)
	progress := 0
	if watched {
		progress = 0
	}
	ids, err := s.mediaSubtreePlayableIDs(mediaID)
	if err != nil {
		return err
	}
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return err
	}
	if err := s.withUserTxTaggedForViewer(context.Background(), accountID, profileID, []string{"media-state", "library-items", "home"}, func(tx *sql.Tx) error {
		for _, id := range ids {
			if _, err := tx.Exec(`
			INSERT INTO user_media_state (profile_id, user_id, media_id, watched, progress_seconds, updated_at)
			VALUES (?, ?, ?, ?, ?, ?)
			ON CONFLICT(profile_id, media_id) DO UPDATE SET watched = excluded.watched, progress_seconds = excluded.progress_seconds, updated_at = excluded.updated_at`,
				profileID, accountID, id, boolInt(watched), progress, now); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		return err
	}
	s.invalidateHomeCacheForProfile(profileID)
	return nil
}

func (s *Server) bulkSetWatched(profileID string, mediaIDs []string, watched bool) error {
	if len(mediaIDs) == 0 {
		return nil
	}
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	progress := 0
	values := make([]string, 0, len(mediaIDs))
	args := make([]any, 0, len(mediaIDs)+4)
	for _, mediaID := range mediaIDs {
		values = append(values, "(?)")
		args = append(args, mediaID)
	}
	args = append(args, profileID, accountID, boolInt(watched), progress, now)
	_, err = s.execUserWriteTaggedForViewer(context.Background(), accountID, profileID, []string{"media-state", "library-items", "home"}, `
		WITH RECURSIVE
		roots(root_id) AS (
			VALUES `+strings.Join(values, ",")+`
		),
		subtree(root_id, id, type) AS (
			SELECT roots.root_id, m.id, m.type
			FROM roots
			JOIN media_items m ON m.id = roots.root_id
			UNION ALL
			SELECT subtree.root_id, child.id, child.type
			FROM media_items child
			JOIN subtree ON child.parent_id = subtree.id
		),
		playable_targets(root_id, id) AS (
			SELECT root_id, id
			FROM subtree
			WHERE type NOT IN ('show', 'anime', 'season', 'album')
		),
		targets(id) AS (
			SELECT DISTINCT id FROM playable_targets
			UNION
			SELECT roots.root_id
			FROM roots
			WHERE NOT EXISTS (
				SELECT 1
				FROM playable_targets
				WHERE playable_targets.root_id = roots.root_id
			)
		)
		INSERT INTO user_media_state (profile_id, user_id, media_id, watched, progress_seconds, updated_at)
		SELECT ?, ?, id, ?, ?, ?
		FROM targets
		WHERE true
		ON CONFLICT(profile_id, media_id) DO UPDATE SET
			watched = excluded.watched,
			progress_seconds = excluded.progress_seconds,
			updated_at = excluded.updated_at`, args...)
	if err == nil {
		s.invalidateHomeCacheForProfile(profileID)
	}
	return err
}

type normalizedPlaybackProgressState struct {
	ProgressSeconds int
	Watched         bool
	Started         bool
}

func (s *Server) playbackProgressPreferencesForUser(userID string) PlaybackProgressPreferences {
	return s.playbackProgressPreferencesForUserContext(context.Background(), userID)
}

func (s *Server) playbackProgressPreferencesForUserContext(ctx context.Context, identityID string) PlaybackProgressPreferences {
	if strings.TrimSpace(identityID) == "" {
		return defaultPlaybackProgressPreferences()
	}
	if ctx == nil {
		ctx = context.Background()
	}
	memo := requestReadMemoFromContext(ctx)
	if memo != nil {
		memo.mu.Lock()
		if preferences, ok := memo.playbackProgress[identityID]; ok {
			memo.mu.Unlock()
			return preferences
		}
		memo.mu.Unlock()
	}
	_, profileID := s.accountAndProfileIDsContext(ctx, identityID)
	values, err := s.profileServerPreferenceValuesForProfileContext(ctx, profileID)
	if err != nil {
		preferences := defaultPlaybackProgressPreferences()
		if memo != nil {
			memo.mu.Lock()
			if memo.playbackProgress == nil {
				memo.playbackProgress = map[string]PlaybackProgressPreferences{}
			}
			memo.playbackProgress[identityID] = preferences
			memo.mu.Unlock()
		}
		return preferences
	}
	preferences := PlaybackProgressPreferences{
		StartedThresholdPercent: values.Playback.StartedThresholdPercent,
		PlayedThresholdPercent:  values.Playback.PlayedThresholdPercent,
	}
	if memo != nil {
		memo.mu.Lock()
		if memo.playbackProgress == nil {
			memo.playbackProgress = map[string]PlaybackProgressPreferences{}
		}
		memo.playbackProgress[identityID] = preferences
		memo.mu.Unlock()
	}
	return preferences
}

func (s *Server) userPrivacyPreferencesForUserContext(ctx context.Context, userID string) UserPrivacyPreferences {
	_, profileID := s.accountAndProfileIDsContext(ctx, userID)
	return s.userPrivacyPreferencesForProfileContext(ctx, profileID)
}

func (s *Server) userPrivacyPreferencesForProfileContext(ctx context.Context, profileID string) UserPrivacyPreferences {
	profileID = strings.TrimSpace(profileID)
	if profileID == "" {
		return defaultUserPrivacyPreferences()
	}
	if ctx == nil {
		ctx = context.Background()
	}
	values, err := s.profileServerPreferenceValuesForProfileContext(ctx, profileID)
	if err != nil {
		return defaultUserPrivacyPreferences()
	}
	return UserPrivacyPreferences{
		PauseWatchHistory:         values.Privacy.PauseWatchHistory,
		ShowActivityToMembers:     values.Privacy.ShowActivityToMembers,
		IncludeInWatchWithFriends: values.Privacy.IncludeInWatchWithFriends,
	}
}

func (s *Server) profileServerPreferenceValuesForProfileContext(ctx context.Context, profileID string) (profileServerPreferenceValues, error) {
	serverID, err := s.profileDirectoryServerIDContext(ctx)
	if err != nil {
		return profileServerPreferenceValues{}, err
	}
	var raw string
	err = s.queryUserRow(ctx, `SELECT values_json FROM viewer_preference_documents WHERE scope_type = 'profile-server' AND profile_id = ? AND server_id = ?`, profileID, serverID).Scan(&raw)
	if err != nil {
		return profileServerPreferenceValues{}, err
	}
	var values profileServerPreferenceValues
	if err := json.Unmarshal([]byte(raw), &values); err != nil {
		return profileServerPreferenceValues{}, err
	}
	return values, nil
}

func normalizePlaybackProgressState(progress int, watched bool, durationSeconds int, mediaType string, preferences PlaybackProgressPreferences) normalizedPlaybackProgressState {
	progress = max(0, progress)
	preferences = normalizePlaybackProgressPreferences(preferences)
	if mediaType == "track" {
		return normalizedPlaybackProgressState{ProgressSeconds: 0, Watched: false, Started: progress > 0 || watched}
	}
	if watched {
		return normalizedPlaybackProgressState{ProgressSeconds: 0, Watched: true, Started: true}
	}
	if progress <= 0 {
		return normalizedPlaybackProgressState{ProgressSeconds: 0, Watched: false, Started: false}
	}
	if durationSeconds <= 0 {
		return normalizedPlaybackProgressState{ProgressSeconds: progress, Watched: false, Started: true}
	}
	percent := float64(progress) / float64(durationSeconds) * 100
	if percent >= float64(preferences.PlayedThresholdPercent) {
		return normalizedPlaybackProgressState{ProgressSeconds: 0, Watched: true, Started: true}
	}
	if percent < float64(preferences.StartedThresholdPercent) {
		return normalizedPlaybackProgressState{ProgressSeconds: 0, Watched: false, Started: false}
	}
	return normalizedPlaybackProgressState{ProgressSeconds: min(progress, max(0, durationSeconds-1)), Watched: false, Started: true}
}

func applyPlaybackProgressDisplayPolicy(item *MediaItem, preferences PlaybackProgressPreferences) {
	if item == nil {
		return
	}
	normalized := normalizePlaybackProgressState(item.State.ProgressSeconds, item.State.Watched, item.DurationSeconds, item.Type, preferences)
	item.State.ProgressSeconds = normalized.ProgressSeconds
	item.State.Watched = normalized.Watched
	if !normalized.Started && !normalized.Watched && !(item.Type == "track" && strings.TrimSpace(item.State.LastPlayedAt) != "") {
		item.State.LastPlayedAt = ""
	}
	if item.State.ProgressSeconds <= 0 {
		item.State.Resume = nil
	}
}

func (s *Server) mediaSubtreePlayableIDs(mediaID string) ([]string, error) {
	rows, err := s.queryUserRead(context.Background(), `
		WITH RECURSIVE subtree(id, type) AS (
			SELECT id, type FROM media_items WHERE id = ?
			UNION ALL
			SELECT child.id, child.type
			FROM media_items child
			JOIN subtree parent ON child.parent_id = parent.id
		)
		SELECT id
		FROM subtree
		WHERE type NOT IN ('show', 'anime', 'season', 'album')
		ORDER BY id ASC`, mediaID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	ids := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if len(ids) == 0 {
		ids = append(ids, mediaID)
	}
	return ids, nil
}

func (s *Server) setProgress(profileID, mediaID string, progress int, watched bool) error {
	nowTime := time.Now().UTC()
	now := nowTime.Format(time.RFC3339)
	lastPlayedRefreshCutoff := nowTime.Add(-60 * time.Second).Format(time.RFC3339)
	var mediaType string
	var durationSeconds int
	_ = s.queryUserRow(context.Background(), `SELECT type, COALESCE(duration_seconds, 0) FROM media_items WHERE id = ?`, mediaID).Scan(&mediaType, &durationSeconds)
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return err
	}
	normalized := normalizePlaybackProgressState(progress, watched, durationSeconds, mediaType, s.playbackProgressPreferencesForUser(profileID))
	progress = normalized.ProgressSeconds
	watched = normalized.Watched
	lastPlayed := ""
	if mediaType == "track" || normalized.Started || normalized.Watched {
		lastPlayed = now
	}
	previousStarted := false
	previousWatched := 0
	var previousProgress int
	var previousLastPlayed string
	previousExists := s.queryUserRow(context.Background(), `
		SELECT watched, progress_seconds, COALESCE(last_played_at, '')
		FROM user_media_state
		WHERE profile_id = ? AND media_id = ?`, profileID, mediaID).Scan(&previousWatched, &previousProgress, &previousLastPlayed) == nil
	if previousExists {
		previousStarted = previousWatched != 0 || previousProgress > 0 || (mediaType == "track" && strings.TrimSpace(previousLastPlayed) != "")
	}
	nextStarted := normalized.Started || strings.TrimSpace(lastPlayed) != ""
	homeStateChanged := previousStarted != nextStarted || previousWatched != boolInt(watched)
	eventTags := []string{"playback-progress"}
	if (!previousExists && (nextStarted || watched)) || (previousExists && homeStateChanged) {
		eventTags = append(eventTags, "media-state", "library-items", "home")
	}
	_, err = s.execUserWriteTaggedForViewer(context.Background(), accountID, profileID, eventTags, `
		INSERT INTO user_media_state (profile_id, user_id, media_id, watched, progress_seconds, last_played_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(profile_id, media_id) DO UPDATE SET
			watched = excluded.watched,
			progress_seconds = excluded.progress_seconds,
			last_played_at = CASE
				WHEN excluded.last_played_at = '' THEN user_media_state.last_played_at
				WHEN user_media_state.last_played_at = '' THEN excluded.last_played_at
				WHEN user_media_state.last_played_at <= ? THEN excluded.last_played_at
				WHEN user_media_state.watched <> excluded.watched THEN excluded.last_played_at
				WHEN user_media_state.progress_seconds <> excluded.progress_seconds THEN excluded.last_played_at
				ELSE user_media_state.last_played_at
			END,
			updated_at = excluded.updated_at
		WHERE user_media_state.watched <> excluded.watched
			OR user_media_state.progress_seconds <> excluded.progress_seconds
			OR (excluded.last_played_at <> '' AND (user_media_state.last_played_at = '' OR user_media_state.last_played_at <= ?))`,
		profileID, accountID, mediaID, boolInt(watched), progress, lastPlayed, now, lastPlayedRefreshCutoff, lastPlayedRefreshCutoff)
	if err == nil && ((!previousExists && (nextStarted || watched)) || (previousExists && homeStateChanged)) {
		s.invalidateHomeCacheForProfile(profileID)
	}
	return err
}

func (s *Server) createPlaybackSession(r *http.Request, user User, item MediaItem, currentEntryID, sessionID string, decision PlaybackDecision, profile PlaybackClientProfile, intent PlaybackIntent, burnInSubtitleID, audioStreamID string, isLive bool, clientInstanceID string, sourceContext PlaybackSourceContext, repeatMode string) error {
	return s.createPlaybackSessionWithState(r, user, item, currentEntryID, sessionID, decision, profile, intent, burnInSubtitleID, audioStreamID, isLive, clientInstanceID, sourceContext, repeatMode, "playing")
}

func (s *Server) createPlaybackSessionWithState(r *http.Request, user User, item MediaItem, currentEntryID, sessionID string, decision PlaybackDecision, profile PlaybackClientProfile, intent PlaybackIntent, burnInSubtitleID, audioStreamID string, isLive bool, clientInstanceID string, sourceContext PlaybackSourceContext, repeatMode, initialState string) error {
	planBinding, planJSON, planErr := playbackPlanPersistence(decision)
	if planErr != nil {
		if !isLive {
			return planErr
		}
		planBinding, planJSON, planErr = livePlaybackPlanPersistence(item, decision)
		if planErr != nil {
			return planErr
		}
	} else {
		// PlaybackDecision is a wire/diagnostic projection only. Rebuild it from
		// the sealed execution authority before any durable session fields use it.
		decision, planErr = playbackDecisionFromExecutionPlan(planBinding, item)
		if planErr != nil {
			return planErr
		}
	}
	decision.PlanSchemaVersion = planBinding.SchemaVersion
	decision.PlanDigest = planBinding.Digest
	decision.SourceRevision = planBinding.Plan.SourceRevision
	decision.CapabilityEvidenceID = planBinding.Plan.CapabilityEvidenceID
	decision.Generation = planBinding.generation()
	now := time.Now().UTC().Format(time.RFC3339)
	cutoff := time.Now().UTC().Add(-45 * time.Second).Format(time.RFC3339)
	maxActiveStreams, _ := s.userPlaybackPolicy(user.ID)
	decisionLabel := playbackDecisionLabel(decision)
	clientIP := clientIPFromRequest(r)
	normalizedClientInstanceID := normalizePlaybackClientInstanceID(clientInstanceID)
	historyPaused := s.userPrivacyPreferencesForProfileContext(r.Context(), viewerProfileID(user)).PauseWatchHistory
	subtitleDecision := playbackSubtitleDecision(item, burnInSubtitleID)
	diagnostics := playbackDiagnosticsFor(decision, profile, burnInSubtitleID, subtitleDecision)
	diagnosticsJSON, err := json.Marshal(diagnostics)
	if err != nil {
		return err
	}
	sourceContext = normalizePlaybackSourceContext(sourceContext)
	sourceContextJSON, err := json.Marshal(sourceContext)
	if err != nil {
		return err
	}
	clientProfileJSON, err := json.Marshal(profile)
	if err != nil {
		return err
	}
	playbackIntentJSON, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	if normalized, ok := normalizePlaybackRepeatMode(repeatMode); ok {
		repeatMode = normalized
	} else {
		repeatMode = "off"
	}
	currentEntryID = strings.TrimSpace(currentEntryID)
	if currentEntryID == "" {
		currentEntryID = randomID("qentry")
	}
	if initialState != "handoff_pending" {
		initialState = "playing"
	}
	session := PlaybackSession{
		ID:               sessionID,
		UserID:           user.ID,
		User:             user.DisplayName,
		ClientInstanceID: normalizedClientInstanceID,
		Device:           clientDeviceLabel(profile),
		App:              "Portico Web",
		Location:         clientLocationLabel(clientIP),
		ClientIP:         clientIP,
		State:            initialState,
		Progress:         sessionProgressPercent(item.State.ProgressSeconds, item.DurationSeconds, isLive),
		PositionSeconds:  max(0, item.State.ProgressSeconds),
		BandwidthMbps:    estimatedBandwidthMbps(item, isLive),
		Decision:         decisionLabel,
		VideoDecision:    decisionLabel,
		VideoSource:      playbackVideoSourceLabel(item, isLive),
		VideoTarget:      playbackTargetLabel(decision, isLive, false),
		AudioDecision:    decisionLabel,
		AudioSource:      playbackAudioSourceLabel(item),
		AudioTarget:      playbackTargetLabel(decision, isLive, true),
		SubtitleDecision: subtitleDecision,
		Media:            item,
		StartedAt:        now,
		LastSeenAt:       now,
		IsLive:           isLive,
		Diagnostics:      diagnostics,
	}
	selectedVersionID := selectedPlaybackVersionID(item)
	selectedSubtitleMode := "off"
	if normalizeBurnInSubtitleID(burnInSubtitleID) != "" {
		selectedSubtitleMode = "burn_in"
	}
	result, err := s.execUserWriteTaggedForViewer(r.Context(), accountIDForUser(user), viewerProfileID(user), []string{"playback"}, `
		INSERT INTO playback_sessions (
			id, user_id, profile_id, api_key_id, current_entry_id, media_id, media_type, title, started_at, last_seen_at, client_ip, client_instance_id,
			device, app, location, state, progress, position_seconds, bandwidth_mbps, decision, video_decision,
			video_source, video_target, audio_decision, audio_source, audio_target,
			subtitle_decision, diagnostics_json, source_context_json, client_profile_json, playback_intent_json, history_paused, repeat_mode, queue_revision, is_live,
			selected_audio_stream_id, selected_subtitle_stream_id, selected_subtitle_mode, selected_version_id,
			plan_schema_version, plan_digest, plan_json, source_revision, media_facts_digest, capability_evidence_id, playback_generation
		)
		SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
		WHERE ? <= 0 OR (
			SELECT COUNT(*)
			FROM playback_sessions
			WHERE user_id = ? AND ended_at = '' AND state <> 'stopped' AND last_seen_at >= ?
				AND (? = '' OR client_instance_id <> ?)
		) < ?`,
		session.ID, session.UserID, viewerProfileID(user), strings.TrimSpace(user.APIKeyID), currentEntryID, item.ID, item.Type, item.Title, session.StartedAt, session.LastSeenAt, session.ClientIP, session.ClientInstanceID,
		session.Device, session.App, session.Location, session.State, session.Progress, session.PositionSeconds, session.BandwidthMbps, session.Decision, session.VideoDecision,
		session.VideoSource, session.VideoTarget, session.AudioDecision, session.AudioSource, session.AudioTarget,
		session.SubtitleDecision, string(diagnosticsJSON), string(sourceContextJSON), string(clientProfileJSON), string(playbackIntentJSON), boolInt(historyPaused), repeatMode, 0, boolInt(session.IsLive),
		normalizeSelectedAudioStreamID(audioStreamID), normalizeBurnInSubtitleID(burnInSubtitleID), selectedSubtitleMode, selectedVersionID,
		planBinding.SchemaVersion, planBinding.Digest, string(planJSON), planBinding.Plan.SourceRevision, planBinding.MediaFactsDigest, planBinding.Plan.CapabilityEvidenceID, planBinding.generation(),
		maxActiveStreams, user.ID, cutoff, normalizedClientInstanceID, normalizedClientInstanceID, maxActiveStreams)
	if err != nil {
		if initialState == "playing" && normalizedClientInstanceID != "" && isPlaybackActiveAuthorityConstraint(err) {
			return errPlaybackReplacementRequired
		}
		return err
	}
	count, _ := result.RowsAffected()
	if count == 0 {
		return errPlaybackSessionLimit
	}
	return nil
}

func (s *Server) touchPlaybackSession(user User, sessionID string, req PlaybackProgressEvent) (PlaybackProgressAcknowledgement, error) {
	nowTime := time.Now().UTC()
	if req.SelectionChanged {
		var selectedMediaID string
		if err := s.queryUserRow(context.Background(), `SELECT media_id FROM playback_sessions WHERE id = ? AND profile_id = ?`, sessionID, viewerProfileID(user)).Scan(&selectedMediaID); err == nil {
			req.AudioStreamID = s.resolveMediaStreamIDContext(context.Background(), selectedMediaID, req.AudioStreamID)
			req.SubtitleStreamID = s.resolveMediaStreamIDContext(context.Background(), selectedMediaID, req.SubtitleStreamID)
		}
	}
	var castOwned int
	if err := s.queryUserRow(context.Background(), `SELECT COUNT(1) FROM cast_receiver_sessions WHERE playback_session_id = ? AND status = 'active' AND expires_at > ?`, sessionID, nowTime.Format(time.RFC3339)).Scan(&castOwned); err == nil && castOwned > 0 && req.Authority != "receiver" {
		return PlaybackProgressAcknowledgement{}, errors.New("playback progress is owned by the Cast receiver")
	}
	if req.EventSequence <= 0 {
		var lastSequence int64
		if err := s.queryUserRow(context.Background(), `
			SELECT last_event_sequence
			FROM playback_sessions
			WHERE id = ? AND ended_at = '' AND profile_id = ?`,
			sessionID, viewerProfileID(user)).Scan(&lastSequence); err != nil {
			return PlaybackProgressAcknowledgement{}, err
		}
		req.EventSequence = lastSequence + 1
	}
	recordedAt := strings.TrimSpace(req.RecordedAt)
	if recordedAt == "" {
		recordedAt = nowTime.Format(time.RFC3339Nano)
	}
	state := strings.ToLower(strings.TrimSpace(req.State))
	switch state {
	case "playing", "paused", "buffering":
	default:
		if req.IsPlaying != nil && !*req.IsPlaying {
			state = "paused"
		} else {
			state = "playing"
		}
	}
	progressSeconds, hasProgressSeconds := playbackProgressEventSeconds(req)
	now := nowTime.Format(time.RFC3339Nano)
	profileID := viewerProfileID(user)
	accountID := accountIDForUser(user)
	preferences := s.playbackProgressPreferencesForUserContext(context.Background(), profileID)
	var accepted bool
	var highestSequence int64
	var currentState, endedAt string
	var currentGeneration int64
	err := s.withWorkClassTxTaggedForViewer(context.Background(), foundationcontract.WorkClassEstablishedPlayback, "playback_progress_tx", database.UserWriteRetry, accountID, profileID,
		[]string{"playback", "playback-progress", "media-state", "library-items", "home"}, func(tx *sql.Tx) error {
			var mediaID, mediaType string
			var liveInt, historyPaused, durationSeconds int
			if err := tx.QueryRow(`
				SELECT ps.media_id, ps.media_type, ps.is_live, ps.history_paused,
					COALESCE(m.duration_seconds, 0), ps.last_event_sequence, ps.state,
					ps.ended_at, ps.progress_generation
				FROM playback_sessions ps
				LEFT JOIN media_items m ON m.id = ps.media_id
				WHERE ps.id = ? AND ps.profile_id = ?`, sessionID, profileID).
				Scan(&mediaID, &mediaType, &liveInt, &historyPaused, &durationSeconds, &highestSequence, &currentState, &endedAt, &currentGeneration); err != nil {
				return err
			}
			if strings.TrimSpace(endedAt) != "" || currentState == "stopped" {
				return sql.ErrNoRows
			}
			if req.Generation <= 0 {
				req.Generation = currentGeneration
			}
			if req.Generation != currentGeneration {
				return errPlaybackGenerationStale
			}
			progress := -1
			positionSeconds := -1
			if hasProgressSeconds {
				positionSeconds = progressSeconds
				if req.DurationSeconds > 0 {
					durationSeconds = req.DurationSeconds
				}
				progress = 0
				if durationSeconds > 0 {
					progress = sessionProgressPercent(progressSeconds, durationSeconds, false)
				}
			}
			result, err := tx.Exec(`
				UPDATE playback_sessions
			SET last_seen_at = ?,
			state = ?,
			progress = CASE WHEN ? >= 0 THEN ? ELSE progress END,
			position_seconds = CASE WHEN ? >= 0 THEN ? ELSE position_seconds END,
			bandwidth_mbps = CASE WHEN ? > 0 THEN ? ELSE bandwidth_mbps END,
				subtitle_decision = CASE WHEN ? <> '' THEN ? ELSE subtitle_decision END,
				selected_audio_stream_id = CASE WHEN ? = 1 THEN ? ELSE selected_audio_stream_id END,
				selected_subtitle_stream_id = CASE WHEN ? = 1 THEN ? ELSE selected_subtitle_stream_id END,
				selected_subtitle_mode = CASE WHEN ? = 1 AND ? IN ('off', 'text', 'burn_in') THEN ? ELSE selected_subtitle_mode END,
				selected_version_id = CASE WHEN ? = 1 THEN ? ELSE selected_version_id END,
				last_event_sequence = ?,
				last_event_recorded_at = ?,
				last_event_received_at = ?
			WHERE id = ? AND ended_at = '' AND profile_id = ?
				AND progress_generation = ? AND last_event_sequence < ?`,
				now, state, progress, progress, positionSeconds, positionSeconds, req.BandwidthMbps, req.BandwidthMbps, strings.TrimSpace(req.SubtitleDecision), strings.TrimSpace(req.SubtitleDecision),
				boolInt(req.SelectionChanged), strings.TrimSpace(req.AudioStreamID),
				boolInt(req.SelectionChanged), strings.TrimSpace(req.SubtitleStreamID), boolInt(req.SelectionChanged), strings.TrimSpace(req.SubtitleMode), strings.TrimSpace(req.SubtitleMode), boolInt(req.SelectionChanged), strings.TrimSpace(req.VersionID),
				req.EventSequence, recordedAt, now,
				sessionID, profileID, req.Generation, req.EventSequence)
			if err != nil {
				return err
			}
			count, _ := result.RowsAffected()
			if count == 0 {
				return nil
			}
			accepted = true
			highestSequence = req.EventSequence
			currentState = state
			if !hasProgressSeconds || liveInt == 1 || historyPaused != 0 || strings.TrimSpace(mediaID) == "" {
				return nil
			}
			normalized := normalizePlaybackProgressState(progressSeconds, false, durationSeconds, mediaType, preferences)
			lastPlayed := ""
			if mediaType == "track" || normalized.Started || normalized.Watched {
				lastPlayed = nowTime.Format(time.RFC3339)
			}
			lastPlayedRefreshCutoff := nowTime.Add(-60 * time.Second).Format(time.RFC3339)
			_, err = tx.Exec(`
				INSERT INTO user_media_state (
					profile_id, user_id, media_id, watched, progress_seconds, last_played_at,
					updated_at, progress_session_id, progress_recorded_at
				) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
				ON CONFLICT(profile_id, media_id) DO UPDATE SET
					watched = excluded.watched,
					progress_seconds = excluded.progress_seconds,
					last_played_at = CASE
						WHEN excluded.last_played_at = '' THEN user_media_state.last_played_at
						WHEN user_media_state.last_played_at = '' THEN excluded.last_played_at
						WHEN user_media_state.last_played_at <= ? THEN excluded.last_played_at
						WHEN user_media_state.watched <> excluded.watched THEN excluded.last_played_at
						WHEN user_media_state.progress_seconds <> excluded.progress_seconds THEN excluded.last_played_at
						ELSE user_media_state.last_played_at
					END,
					updated_at = excluded.updated_at,
					progress_session_id = excluded.progress_session_id,
					progress_recorded_at = excluded.progress_recorded_at
				WHERE user_media_state.watched <> excluded.watched
					OR user_media_state.progress_seconds <> excluded.progress_seconds
					OR user_media_state.progress_session_id <> excluded.progress_session_id
					OR user_media_state.progress_recorded_at <> excluded.progress_recorded_at
					OR (excluded.last_played_at <> '' AND (user_media_state.last_played_at = '' OR user_media_state.last_played_at <= ?))`,
				profileID, accountID, mediaID, boolInt(normalized.Watched), normalized.ProgressSeconds, lastPlayed,
				nowTime.Format(time.RFC3339), sessionID, recordedAt, lastPlayedRefreshCutoff, lastPlayedRefreshCutoff)
			return err
		})
	if err != nil {
		return PlaybackProgressAcknowledgement{}, err
	}
	if !accepted {
		return PlaybackProgressAcknowledgement{
			Accepted:             false,
			Duplicate:            highestSequence == req.EventSequence,
			Stale:                highestSequence > req.EventSequence,
			HighestEventSequence: highestSequence,
			SessionState:         currentState,
			Generation:           currentGeneration,
		}, nil
	}
	s.heartbeatLiveTVTunerAllocation(context.Background(), sessionID)
	if hasProgressSeconds {
		s.invalidateHomeCacheForProfile(profileID)
	}
	if reason := strings.TrimSpace(req.ClientFallbackReason); reason != "" {
		s.patchPlaybackSessionDiagnostics(sessionID, PlaybackDiagnostics{ClientFallbackReason: reason})
	}
	return PlaybackProgressAcknowledgement{
		Accepted:             true,
		HighestEventSequence: req.EventSequence,
		SessionState:         state,
		AcceptedAt:           now,
		Generation:           currentGeneration,
	}, nil
}

func (s *Server) nextPlaybackProgressEventSequence(user User, sessionID string) int64 {
	var lastSequence int64
	if err := s.queryUserRow(context.Background(), `
		SELECT last_event_sequence
		FROM playback_sessions
		WHERE id = ? AND profile_id = ?`,
		sessionID, viewerProfileID(user)).Scan(&lastSequence); err != nil {
		return 1
	}
	if lastSequence < 0 {
		return 1
	}
	return lastSequence + 1
}

func playbackSessionActiveForUser(db *sql.DB, user User, sessionID string) bool {
	var exists int
	_ = db.QueryRow(`
		SELECT 1
		FROM playback_sessions
		WHERE id = ? AND ended_at = '' AND profile_id = ?
		LIMIT 1`,
		sessionID, viewerProfileID(user)).Scan(&exists)
	return exists == 1
}

func (s *Server) playbackSessionMediaDuration(user User, sessionID string) int {
	var durationSeconds int
	_ = s.queryUserRow(context.Background(), `
		SELECT COALESCE(m.duration_seconds, 0)
		FROM playback_sessions ps
		JOIN media_items m ON m.id = ps.media_id
		WHERE ps.id = ? AND ps.ended_at = '' AND (ps.profile_id = ? OR ? = 1)`,
		sessionID, viewerProfileID(user), boolInt(canInteractivelyManageServer(user))).Scan(&durationSeconds)
	return max(0, durationSeconds)
}

func playbackProgressEventSeconds(req PlaybackProgressEvent) (int, bool) {
	if req.ProgressSeconds != nil {
		return max(0, *req.ProgressSeconds), true
	}
	if req.PositionSeconds != nil {
		position := *req.PositionSeconds
		if !math.IsNaN(position) && !math.IsInf(position, 0) {
			return max(0, int(math.Round(position))), true
		}
	}
	return 0, false
}

func (s *Server) persistPlaybackSessionProgress(user User, sessionID string, progressSeconds int) error {
	return s.persistPlaybackSessionProgressEvent(user, sessionID, progressSeconds, false, time.Now().UTC().Format(time.RFC3339Nano))
}

func (s *Server) persistPlaybackSessionProgressEvent(user User, sessionID string, progressSeconds int, completed bool, recordedAt string) error {
	var mediaID string
	var liveInt int
	var historyPaused int
	err := s.queryUserRow(context.Background(), `
		SELECT media_id, is_live, history_paused
		FROM playback_sessions
		WHERE id = ? AND ended_at = '' AND (profile_id = ? OR ? = 1)`,
		sessionID, viewerProfileID(user), boolInt(canInteractivelyManageServer(user))).Scan(&mediaID, &liveInt, &historyPaused)
	if err != nil {
		return err
	}
	if liveInt == 1 || historyPaused != 0 || mediaID == "" {
		return nil
	}
	if err := s.setProgress(viewerProfileID(user), mediaID, progressSeconds, completed); err != nil {
		return err
	}
	// setProgress above already published the one authoritative, viewer-scoped
	// progress invalidation. These ordering markers are private bookkeeping;
	// deriving another SQL event here would duplicate it globally.
	_, err = s.execUserWriteTaggedForViewer(context.Background(), accountIDForUser(user), viewerProfileID(user), []string{}, `
		UPDATE user_media_state
		SET progress_session_id = ?, progress_recorded_at = ?
		WHERE profile_id = ? AND media_id = ?`,
		sessionID, strings.TrimSpace(recordedAt), viewerProfileID(user), mediaID)
	return err
}

func (s *Server) issuePlaybackCommand(user User, sessionID string, req PlaybackCommandRequest) (PlaybackCommand, error) {
	action := strings.ToLower(strings.TrimSpace(req.Action))
	switch action {
	case "play", "pause", "seek", "stop", "load":
	default:
		return PlaybackCommand{}, errors.New("Playback command action is not supported.")
	}
	if req.PositionSeconds < 0 {
		req.PositionSeconds = 0
	}
	mediaID := strings.TrimSpace(req.MediaID)
	message := truncateStringRunes(strings.TrimSpace(req.Message), playbackStopMessageMaxRunes)
	if action == "load" {
		if mediaID == "" {
			return PlaybackCommand{}, errors.New("Load commands require a media item.")
		}
		if _, err := s.getMediaAccessSummaryContext(context.Background(), viewerProfileID(user), mediaID); err != nil {
			return PlaybackCommand{}, errors.New("Load command media item is not accessible.")
		}
	}
	now := time.Now().UTC().Format(time.RFC3339)
	command := PlaybackCommand{
		ID:              randomID("pcmd"),
		Action:          action,
		MediaID:         mediaID,
		PositionSeconds: req.PositionSeconds,
		Message:         message,
		IssuedByUserID:  user.ID,
		IssuedAt:        now,
	}
	data, err := json.Marshal(command)
	if err != nil {
		return PlaybackCommand{}, err
	}
	err = s.withWorkClassTxTaggedForViewer(context.Background(), foundationcontract.WorkClassSecurityFence, "playback_command_tx", database.UserWriteRetry,
		accountIDForUser(user), viewerProfileID(user), []string{"playback"}, func(tx *sql.Tx) error {
			var committing int
			if err := tx.QueryRow(`SELECT COUNT(*) FROM playback_handoff_receipts WHERE source_session_id = ? AND state = 'committing'`, sessionID).Scan(&committing); err != nil {
				return err
			}
			if committing != 0 {
				return errPlaybackHandoffInProgress
			}
			result, updateErr := tx.Exec(`
			UPDATE playback_sessions
			SET command_json = ?, command_updated_at = ?, last_seen_at = ?
			WHERE id = ? AND ended_at = '' AND profile_id = ?
				AND NOT EXISTS (SELECT 1 FROM playback_handoff_receipts WHERE source_session_id = ? AND state = 'committing')`,
				string(data), now, now, sessionID, viewerProfileID(user), sessionID)
			if updateErr != nil {
				return updateErr
			}
			if rowsAffected(result) != 1 {
				return sql.ErrNoRows
			}
			return nil
		})
	if err != nil {
		return PlaybackCommand{}, err
	}
	s.notifyPlaybackCommand(sessionID)
	return command, nil
}

func (s *Server) playbackCommand(user User, sessionID string) (PlaybackCommand, error) {
	var raw string
	recentStopCommandCutoff := time.Now().UTC().Add(-2 * time.Minute).Format(time.RFC3339)
	err := s.queryUserRow(context.Background(), `
		SELECT command_json
		FROM playback_sessions
		WHERE id = ?
			AND (ended_at = '' OR (command_json <> '' AND command_updated_at >= ?))
			AND profile_id = ?`,
		sessionID, recentStopCommandCutoff, viewerProfileID(user)).Scan(&raw)
	if err != nil {
		return PlaybackCommand{}, err
	}
	return decodePlaybackCommand(raw), nil
}

func decodePlaybackCommand(raw string) PlaybackCommand {
	var command PlaybackCommand
	if strings.TrimSpace(raw) == "" {
		return command
	}
	_ = json.Unmarshal([]byte(raw), &command)
	return command
}

func playbackDiagnosticsFor(decision PlaybackDecision, profile PlaybackClientProfile, burnInSubtitleID string, subtitleDecision string) PlaybackDiagnostics {
	diagnostics := PlaybackDiagnostics{
		ClientProfile:  playbackClientProfileLabel(profile),
		MaxBitrateMbps: max(0, profile.MaxBitrate/1000),
		DecisionReason: strings.TrimSpace(decision.Reason),
		Protocol:       strings.TrimSpace(decision.Protocol),
		Container:      strings.TrimSpace(decision.Container),
		VideoCodec:     strings.TrimSpace(decision.VideoCodec),
		AudioCodec:     strings.TrimSpace(decision.AudioCodec),
	}
	if normalizeBurnInSubtitleID(burnInSubtitleID) != "" {
		diagnostics.SubtitleBurnIn = true
		diagnostics.SubtitleBurnInReason = firstNonEmpty(strings.TrimSpace(subtitleDecision), "Requested by playback client")
	}
	return diagnostics
}

func playbackSubtitleDecision(item MediaItem, burnInSubtitleID string) string {
	burnInSubtitleID = normalizeBurnInSubtitleID(burnInSubtitleID)
	if burnInSubtitleID == "" {
		return "None"
	}
	stream := streamByID(item.Streams, burnInSubtitleID)
	if stream.ID == "" || stream.Kind != "subtitle" {
		return "Burn in"
	}
	label := firstNonEmpty(strings.TrimSpace(stream.DisplayTitle), strings.TrimSpace(stream.Language), stream.ID)
	return "Burn in: " + label
}

func playbackClientProfileLabel(profile PlaybackClientProfile) string {
	parts := []string{}
	if profile.Device != "" {
		parts = append(parts, profile.Device)
	}
	if profile.Platform != "" && !strings.EqualFold(profile.Platform, profile.Device) {
		parts = append(parts, profile.Platform)
	}
	capabilities := []string{}
	if profile.SupportsHLS {
		capabilities = append(capabilities, "HLS")
	}
	if profile.SupportsMSE {
		capabilities = append(capabilities, "MSE")
	}
	if profile.SupportsHEVC {
		capabilities = append(capabilities, "HEVC")
	}
	if profile.SupportsHDR {
		capabilities = append(capabilities, "HDR")
	}
	if len(capabilities) > 0 {
		parts = append(parts, strings.Join(capabilities, "+"))
	}
	if len(parts) == 0 {
		return "Unknown client"
	}
	return strings.Join(parts, " · ")
}

func decodePlaybackDiagnostics(raw string) PlaybackDiagnostics {
	var diagnostics PlaybackDiagnostics
	if strings.TrimSpace(raw) == "" {
		return diagnostics
	}
	_ = json.Unmarshal([]byte(raw), &diagnostics)
	return diagnostics
}

func (s *Server) updatePlaybackTranscodeDiagnostics(mediaID string, patch PlaybackDiagnostics) {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id, diagnostics_json
		FROM playback_sessions
		WHERE media_id = ? AND ended_at = ''`, mediaID)
	if err != nil {
		return
	}
	type update struct {
		id   string
		json string
	}
	updates := []update{}
	for rows.Next() {
		var id, raw string
		if err := rows.Scan(&id, &raw); err != nil {
			continue
		}
		diagnostics := decodePlaybackDiagnostics(raw)
		if patch.TranscodeQuality != "" {
			diagnostics.TranscodeQuality = patch.TranscodeQuality
		}
		if patch.TranscodeMethod != "" {
			diagnostics.TranscodeMethod = patch.TranscodeMethod
		}
		if patch.TranscodeFilter != "" {
			diagnostics.TranscodeFilter = patch.TranscodeFilter
		}
		if patch.FFmpegContext != "" {
			diagnostics.FFmpegContext = patch.FFmpegContext
		}
		if patch.FFmpeg != nil {
			diagnostics.FFmpeg = patch.FFmpeg
		}
		if patch.SubtitleBurnIn {
			diagnostics.SubtitleBurnIn = true
			diagnostics.SubtitleBurnInReason = firstNonEmpty(patch.SubtitleBurnInReason, diagnostics.SubtitleBurnInReason)
		}
		if data, err := json.Marshal(diagnostics); err == nil {
			updates = append(updates, update{id: id, json: string(data)})
		}
	}
	_ = rows.Close()
	for _, update := range updates {
		_, _ = s.execUserWrite(context.Background(), `UPDATE playback_sessions SET diagnostics_json = ? WHERE id = ?`, update.json, update.id)
	}
}

func (s *Server) patchPlaybackSessionDiagnostics(sessionID string, patch PlaybackDiagnostics) {
	var raw string
	if err := s.queryUserRow(context.Background(), `SELECT diagnostics_json FROM playback_sessions WHERE id = ?`, sessionID).Scan(&raw); err != nil {
		return
	}
	diagnostics := decodePlaybackDiagnostics(raw)
	if patch.ClientFallbackReason != "" {
		diagnostics.ClientFallbackReason = patch.ClientFallbackReason
	}
	if data, err := json.Marshal(diagnostics); err == nil {
		_, _ = s.execUserWrite(context.Background(), `UPDATE playback_sessions SET diagnostics_json = ? WHERE id = ?`, string(data), sessionID)
	}
}

func normalizeReceiverSupportedCommands(commands []string) []string {
	normalized := normalizeNativeReceiverCommands(commands)
	if len(normalized) == 0 {
		return []string{"load"}
	}
	return normalized
}

func decodeReceiverSupportedCommands(raw string) []string {
	var commands []string
	if strings.TrimSpace(raw) != "" {
		_ = json.Unmarshal([]byte(raw), &commands)
	}
	return normalizeReceiverSupportedCommands(commands)
}

func sessionPlaybackCommands() []string {
	return []string{"play", "pause", "seek", "stop", "load"}
}

func receiverTargetDetail(receiver PlaybackReceiver) string {
	details := []string{}
	if receiver.App != "" {
		details = append(details, receiver.App)
	}
	if receiver.Platform != "" {
		details = append(details, receiver.Platform)
	}
	details = append(details, "Ready for media handoff")
	return strings.Join(details, " · ")
}

func limitPlaybackReceiverField(value string, limit int) string {
	value = strings.TrimSpace(value)
	if limit > 0 && len(value) > limit {
		return value[:limit]
	}
	return value
}

func (s *Server) listPlaybackTargets(user User, clientInstanceID string) ([]PlaybackTarget, error) {
	targets := []PlaybackTarget{}
	receivers, err := s.listAuthorizedPlaybackReceivers(context.Background(), user)
	if err != nil {
		return nil, err
	}
	for _, receiver := range receivers {
		targets = append(targets, PlaybackTarget{
			ID:                receiver.ID,
			Type:              "receiver",
			Name:              receiver.Name,
			Detail:            receiverTargetDetail(receiver),
			SupportedCommands: receiver.SupportedCommands,
			LastSeenAt:        receiver.LastSeenAt,
		})
	}
	cutoff := time.Now().UTC().Add(-90 * time.Second).Format(time.RFC3339)
	normalizedClientInstanceID := normalizePlaybackClientInstanceID(clientInstanceID)
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id, title, device, app, state, last_seen_at
		FROM playback_sessions
		WHERE ended_at = '' AND last_seen_at >= ? AND profile_id = ?
			AND (? <> '' AND client_instance_id = ?)
		ORDER BY last_seen_at DESC`, cutoff, viewerProfileID(user), normalizedClientInstanceID, normalizedClientInstanceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var target PlaybackTarget
		var title, device, app, state string
		if err := rows.Scan(&target.ID, &title, &device, &app, &state, &target.LastSeenAt); err != nil {
			return nil, err
		}
		target.Type = "session"
		target.Name = firstNonEmpty(device, "Active player")
		target.Detail = strings.TrimSpace(strings.Join([]string{firstNonEmpty(app, "Portico Web"), state, title}, " · "))
		target.SupportedCommands = sessionPlaybackCommands()
		targets = append(targets, target)
	}
	return targets, rows.Err()
}

func (s *Server) hasActivePlaybackForMedia(mediaID string) bool {
	var exists int
	cutoff := time.Now().UTC().Add(-45 * time.Second).Format(time.RFC3339)
	err := s.queryUserRow(context.Background(), `
		SELECT 1
		FROM playback_sessions
		WHERE media_id = ? AND ended_at = '' AND state <> 'stopped' AND last_seen_at >= ?
		LIMIT 1`,
		mediaID, cutoff).Scan(&exists)
	return err == nil && exists == 1
}

func playbackDecisionLabel(decision PlaybackDecision) string {
	if decision.Mode == "direct_stream" {
		return "Direct Stream"
	}
	if decision.RequiresTranscode || decision.Mode == "transcode_required" {
		return "Transcode"
	}
	return "Direct Play"
}

func playbackVideoSourceLabel(item MediaItem, isLive bool) string {
	if isLive {
		return "Provider stream"
	}
	return videoSourceLabel(item)
}

func playbackTargetLabel(decision PlaybackDecision, isLive bool, audio bool) string {
	if isLive {
		return "Original"
	}
	if decision.Mode == "direct_stream" {
		if audio && decision.AudioTranscode {
			return "AAC Stereo"
		}
		return "Original"
	}
	if decision.RequiresTranscode {
		if audio {
			return "AAC Stereo"
		}
		return "H.264"
	}
	return "Original"
}

func playbackAudioSourceLabel(item MediaItem) string {
	for _, stream := range item.Streams {
		if stream.Kind != "audio" {
			continue
		}
		if label := strings.TrimSpace(stream.DisplayTitle); label != "" {
			return label
		}
		parts := []string{strings.ToUpper(strings.TrimSpace(stream.Codec))}
		if stream.Channels == 1 {
			parts = append(parts, "Mono")
		} else if stream.Channels == 2 {
			parts = append(parts, "Stereo")
		} else if stream.Channels > 0 {
			parts = append(parts, fmt.Sprintf("%d channels", stream.Channels))
		}
		if label := strings.TrimSpace(strings.Join(parts, " ")); label != "" {
			return label
		}
	}
	return "No audio"
}

func estimatedBandwidthMbps(item MediaItem, isLive bool) float64 {
	if isLive {
		return 6
	}
	maxBitrate := 0
	for _, stream := range item.Streams {
		if stream.Bitrate > maxBitrate {
			maxBitrate = stream.Bitrate
		}
	}
	if maxBitrate > 0 {
		return math.Max(0.1, float64(maxBitrate)/1000)
	}
	switch item.Type {
	case "track", "album", "audiobook":
		return 0.4
	default:
		return 8
	}
}

func sessionProgressPercent(progressSeconds, durationSeconds int, isLive bool) int {
	if isLive || durationSeconds <= 0 {
		return 0
	}
	return min(100, max(0, int(math.Round(float64(progressSeconds)/float64(durationSeconds)*100))))
}

func normalizePlaybackClientInstanceID(value string) string {
	value = strings.TrimSpace(value)
	if len(value) > 120 {
		value = value[:120]
	}
	for _, char := range value {
		if !(char == '-' || char == '_' || char == '.' || char >= '0' && char <= '9' || char >= 'A' && char <= 'Z' || char >= 'a' && char <= 'z') {
			return ""
		}
	}
	return value
}

func clientDeviceLabel(profile PlaybackClientProfile) string {
	if strings.TrimSpace(profile.Platform) != "" {
		return strings.TrimSpace(profile.Platform)
	}
	if strings.TrimSpace(profile.Device) == "" {
		return "Unknown client"
	}
	device := strings.TrimSpace(profile.Device)
	switch {
	case strings.Contains(device, "iPhone"):
		return "iPhone"
	case strings.Contains(device, "iPad"):
		return "iPad"
	case strings.Contains(device, "Android"):
		return "Android"
	case strings.Contains(device, "AppleTV"):
		return "Apple TV"
	case strings.Contains(device, "Roku"):
		return "Roku"
	case strings.Contains(device, "Chrome"):
		return "Chrome"
	case strings.Contains(device, "Safari"):
		return "Safari"
	default:
		if len(device) > 42 {
			return device[:42] + "..."
		}
		return device
	}
}

func clientIPFromRequest(r *http.Request) string {
	host, _, err := net.SplitHostPort(strings.TrimSpace(r.RemoteAddr))
	if err == nil && host != "" {
		return host
	}
	return strings.TrimSpace(r.RemoteAddr)
}

func clientLocationLabel(ipValue string) string {
	ip := net.ParseIP(ipValue)
	if ip == nil {
		return "Unknown"
	}
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() {
		return "Local"
	}
	return "Remote"
}

func (s *Server) createJob(jobType, message string) (Job, error) {
	return s.createJobFor(jobType, message, "", "")
}

func (s *Server) createJobFor(jobType, message, resourceType, resourceID string) (Job, error) {
	return s.createJobForWithMetadata(jobType, message, resourceType, resourceID, nil)
}

func (s *Server) createJobForWithMetadata(jobType, message, resourceType, resourceID string, metadata map[string]string) (Job, error) {
	job, _, err := s.createJobForWithMetadataResult(jobType, message, resourceType, resourceID, metadata)
	return job, err
}

// createJobForWithMetadataResult reports whether an exclusive active key
// reused queued or running work. Operation-admission endpoints use this
// atomic result instead of racing an active-job read against insertion.
func (s *Server) createJobForWithMetadataResult(jobType, message, resourceType, resourceID string, metadata map[string]string) (job Job, reused bool, err error) {
	descriptor, supported := durableJobDescriptorForType(jobType)
	if !supported {
		return Job{}, false, fmt.Errorf("unsupported job type %q", jobType)
	}
	now := time.Now().UTC().Format(time.RFC3339)
	jobMetadata := normalizeJobMetadata(metadata)
	job = Job{
		ID: randomID("job"), Type: jobType, Status: "queued", Progress: 0,
		Message: message, ResourceType: resourceType, ResourceID: resourceID,
		Metadata: jobMetadata, Priority: descriptor.WorkClass, Phase: "queued",
		ActiveKey: jobActiveKeyFor(jobType, resourceType, resourceID, jobMetadata),
		CreatedAt: now, UpdatedAt: now,
	}
	metadataJSON := "{}"
	if len(jobMetadata) > 0 {
		if raw, err := json.Marshal(jobMetadata); err == nil {
			metadataJSON = string(raw)
		}
	}
	inserted := false
	var existing Job
	func() {
		durableJobEnqueueMu.Lock()
		defer durableJobEnqueueMu.Unlock()
		job, err = s.withJobAdmission(func() (Job, error) {
			return job, s.withWorkClassTxTaggedForViewer(context.Background(), job.Priority, "job_enqueue", durableJobEnqueueRetry, "", "", nil, func(tx *sql.Tx) error {
				loadExisting := func(query string, args ...any) (string, error) {
					var metadata string
					err := tx.QueryRowContext(context.Background(), query, args...).Scan(
						&existing.ID, &existing.Type, &existing.Status, &existing.Progress,
						&existing.Message, &existing.ResourceType, &existing.ResourceID,
						&metadata, &existing.AttemptCount, &existing.NextRunAt, &existing.LastError,
						&existing.FailureKind, &existing.CreatedAt, &existing.UpdatedAt)
					return metadata, err
				}
				_, insertErr := tx.ExecContext(context.Background(), `INSERT INTO jobs (
				id, type, status, progress, message, resource_type, resource_id, metadata_json,
				attempt_count, next_run_at, leased_by, lease_expires_at, last_error,
				parent_operation_id, idempotency_key, active_key, priority, phase,
				progress_current, progress_total, result_reference, error_code, retry_eligible,
				cancellation_requested_at, worker_acknowledged_at, interrupted_at, retention_until,
				created_at, updated_at
			) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, '', '', '', '', '', '', ?, ?, ?, ?, ?, '', '', 0, '', '', '', '', ?, ?)`,
					job.ID, job.Type, job.Status, job.Progress, job.Message, job.ResourceType,
					job.ResourceID, metadataJSON, job.ActiveKey, job.Priority, job.Phase,
					job.Progress, job.Progress, job.CreatedAt, job.UpdatedAt)
				if insertErr == nil {
					inserted = true
					return nil
				}
				if !isActiveJobUniqueConflict(insertErr) || job.ActiveKey == "" {
					return insertErr
				}
				metadata, scanErr := loadExisting(`
				SELECT id, type, status, progress, message, resource_type, resource_id,
					COALESCE(metadata_json, '{}'), attempt_count, next_run_at, last_error,
					failure_kind, created_at, updated_at
				FROM jobs WHERE active_key = ? AND status IN ('queued', 'running')
				ORDER BY created_at ASC, id ASC LIMIT 1`, job.ActiveKey)
				if scanErr != nil {
					return scanErr
				}
				existing.Metadata = decodeJobMetadata(metadata)
				if job.Type == "library_scan" {
					existing.Metadata = mergeLibraryScanMetadata(existing.Metadata, job.Metadata)
					encoded, marshalErr := json.Marshal(existing.Metadata)
					if marshalErr != nil {
						return marshalErr
					}
					// Preserve the active phase text for a running operation. The
					// promoted mode is durable in metadata and will be claimed before
					// completion; describing it as newly queued would be misleading.
					if existing.Status == "queued" {
						existing.Message = job.Message
					}
					existing.UpdatedAt = job.UpdatedAt
					if _, updateErr := tx.ExecContext(context.Background(), `
						UPDATE jobs SET metadata_json = ?, message = ?, updated_at = ?
						WHERE id = ? AND status IN ('queued', 'running')`, string(encoded), existing.Message, existing.UpdatedAt, existing.ID); updateErr != nil {
						return updateErr
					}
				} else if job.Type == remoteAccessCertificateMaintenanceJobType && strings.EqualFold(job.Metadata["force"], "true") {
					if existing.Metadata == nil {
						existing.Metadata = map[string]string{}
					}
					existing.Metadata["force"] = "true"
					existing.Metadata["latestTrigger"] = firstNonEmpty(job.Metadata["trigger"], "manual")
					encoded, marshalErr := json.Marshal(existing.Metadata)
					if marshalErr != nil {
						return marshalErr
					}
					if existing.Status == "queued" {
						existing.Message = job.Message
					}
					existing.UpdatedAt = job.UpdatedAt
					if _, updateErr := tx.ExecContext(context.Background(), `
						UPDATE jobs SET metadata_json = ?, message = ?, updated_at = ?
						WHERE id = ? AND status IN ('queued', 'running')`, string(encoded), existing.Message, existing.UpdatedAt, existing.ID); updateErr != nil {
						return updateErr
					}
				}
				return nil
			})
		})
	}()
	if err == nil && !inserted {
		job = existing
		s.hydrateJobEnvelope(&job)
	}
	if err == nil && inserted {
		s.recordLog("info", message, map[string]string{"job": job.ID, "type": job.Type})
		if s.jobWakeForTests != nil {
			s.jobWakeForTests()
		} else {
			s.signalJobWake()
		}
	}
	return job, !inserted, err
}

func normalizeJobMetadata(metadata map[string]string) map[string]string {
	if len(metadata) == 0 {
		return nil
	}
	normalized := map[string]string{}
	for key, value := range metadata {
		key = strings.TrimSpace(key)
		value = strings.TrimSpace(value)
		if key == "" || value == "" {
			continue
		}
		if len(key) > jobMaxMetadataKeyBytes {
			key = key[:jobMaxMetadataKeyBytes]
		}
		if len(value) > jobMaxMetadataValueBytes {
			value = value[:jobMaxMetadataValueBytes]
		}
		if key == "" || value == "" {
			continue
		}
		normalized[key] = value
		if len(normalized) >= jobMaxMetadataEntries {
			break
		}
	}
	if len(normalized) == 0 {
		return nil
	}
	return normalized
}

func decodeJobMetadata(raw string) map[string]string {
	raw = strings.TrimSpace(raw)
	if raw == "" || raw == "{}" {
		return nil
	}
	var metadata map[string]string
	if err := json.Unmarshal([]byte(raw), &metadata); err != nil {
		return nil
	}
	return normalizeJobMetadata(metadata)
}

func (s *Server) runJob(job Job) {
	release := s.acquireJobLane(job.Type)
	defer release()
	s.runJobWithLane(job)
}

func (s *Server) runJobWithLane(job Job) {
	admissionContext, releaseAdmission, admissionErr := s.restoreBarrier.acquire(context.Background())
	if admissionErr != nil {
		return
	}
	defer releaseAdmission()
	if admissionContext.Err() != nil {
		return
	}
	if !s.claimJobForRun(job.ID) {
		return
	}
	if hook := s.restoreJobRegistrationHook; hook != nil {
		hook(admissionContext)
	}
	// The barrier lease spans dispatcher claim through registration. If
	// quiescence wins between those two operations, the canceled parent
	// prevents the worker from becoming a new DB user after the snapshot.
	if admissionContext.Err() != nil {
		if !s.jobAdmissionIsClosed() {
			s.requeueRestoreInterruptedJob(job.ID)
		}
		return
	}
	ctx, done := s.registerRunningJobContext(job.ID, admissionContext)
	defer done()
	defer func() {
		// Restore quiescence cancels a job but the replacement generation must
		// be able to retry it. Full process shutdown closes job admission and
		// records interruption centrally after every worker has joined instead.
		if admissionContext.Err() != nil && !s.jobAdmissionIsClosed() && s.restoreBarrier.isBlocked() {
			s.requeueRestoreInterruptedJob(job.ID)
		}
		s.finalizeRequestedJobCancellation(job.ID)
	}()
	if ctx.Err() != nil {
		if !s.jobAdmissionIsClosed() {
			s.requeueRestoreInterruptedJob(job.ID)
		}
		return
	}
	if hook := s.jobExecutionHook; hook != nil {
		hook(ctx, job)
		return
	}
	if job.Type == "library_scan" && job.ResourceType == "library" && job.ResourceID != "" {
		library, err := s.getLibrary(job.ResourceID)
		if err != nil {
			_ = s.setJobMessage(job.ID, "failed", 100, "Scan failed because the library no longer exists.")
			return
		}
		s.scanLibrary(ctx, library, job.ID)
		return
	}
	if job.Type == "library_change_check" {
		s.runLibraryChangeCheck(ctx, job)
		return
	}
	if job.Type == "library_read_model_repair" {
		s.runLibraryReadModelRepair(ctx, job)
		return
	}
	if job.Type == remoteAccessCertificateMaintenanceJobType {
		s.runRemoteAccessCertificateMaintenanceJob(ctx, job)
		return
	}
	if job.Type == "database_backup" {
		s.runDatabaseBackup(ctx, job)
		return
	}
	if job.Type == "metadata_refresh" {
		s.runMetadataRefresh(ctx, job)
		return
	}
	if job.Type == "metadata_refresh_library" {
		s.runLibraryMetadataRefresh(ctx, job)
		return
	}
	if job.Type == "lyrics_fetch_missing" {
		s.runMissingLyricsFetch(ctx, job)
		return
	}
	if job.Type == "media_analyze" {
		s.runMediaAnalyze(ctx, job)
		return
	}
	if job.Type == downloadArtifactVerificationJobType {
		s.runDownloadArtifactVerification(ctx, job)
		return
	}
	if job.Type == "optimize_version" {
		s.runOptimizeVersion(ctx, job)
		return
	}
	if job.Type == "live_tv_refresh" {
		s.runLiveTVSourceRefresh(ctx, job)
		return
	}
	if job.Type == "tmdb_trending_refresh" {
		s.runTMDBTrendingRefresh(ctx, job)
		return
	}
	if job.Type == "library_trash_cleanup" {
		s.runLibraryTrashCleanup(ctx, job)
		return
	}
	if job.Type == "optimized_version_prune" {
		s.runOptimizedVersionPrune(ctx, job)
		return
	}
	if job.Type == "trickplay_prune" {
		s.runTrickplayPrune(ctx, job)
		return
	}
	if job.Type == "dvr_retention_cleanup" {
		s.runDVRRetentionCleanup(ctx, job)
		return
	}
	if job.Type == "system_storage_cleanup" {
		s.runSystemStorageCleanup(ctx, job)
		return
	}
	if job.Type == "dashboard_rollup_refresh" {
		s.runDashboardRollupRefresh(ctx, job)
		return
	}
	_ = s.setJobMessage(job.ID, "failed", 100, "Job failed because the job type is not supported.")
}

func (s *Server) requeueRestoreInterruptedJob(jobID string) {
	jobID = strings.TrimSpace(jobID)
	if jobID == "" {
		return
	}
	now := time.Now().UTC().Format(time.RFC3339)
	ctx, cancel := boundedJobWriteContext()
	defer cancel()
	if _, err := s.execBackgroundWrite(ctx, `
		UPDATE jobs
		SET status = 'queued', leased_by = '', lease_expires_at = '',
			next_run_at = ?,
			phase = 'queued', retry_eligible = 1, error_code = 'restore_interrupted',
			last_error = CASE WHEN last_error = '' THEN 'Restore admission interrupted job dispatch.' ELSE last_error END,
			failure_kind = CASE WHEN failure_kind = '' THEN 'restore_interrupted' ELSE failure_kind END,
			updated_at = ?
		WHERE id = ? AND status = 'running' AND leased_by = ? AND cancellation_requested_at = ''`, now, now, jobID, s.jobLeaseOwner(jobID)); err != nil {
		s.log.Warn("restore-interrupted job requeue failed", "job", jobID, "error", err)
	}
}

func (s *Server) runJobWorker(ctx context.Context) {
	if s.jobRecoveryReady != nil {
		select {
		case <-s.jobRecoveryReady:
		case <-ctx.Done():
			return
		}
	}
	s.runDueJobsOnce()
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-s.jobWake:
			s.runDueJobsOnce()
		case <-ticker.C:
			s.runDueJobsOnce()
		}
	}
}

func (s *Server) runDueJobsOnce() {
	if s.jobAdmissionIsClosed() || s.restoreBarrier.isBlocked() {
		return
	}
	nowTime := time.Now().UTC()
	now := nowTime.Format(time.RFC3339)
	if _, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'queued',
			next_run_at = CASE WHEN next_run_at = '' THEN ? ELSE next_run_at END,
			leased_by = '',
			lease_expires_at = '',
			last_error = CASE WHEN last_error = '' THEN 'Worker lease expired before completion.' ELSE last_error END,
			updated_at = ?
		WHERE status = 'running'
			AND cancellation_requested_at = ''
			AND lease_expires_at <> ''
			AND lease_expires_at <= ?
			AND leased_by NOT LIKE ?`,
		now, now, now, s.jobWorkerPrefix()); err != nil {
		s.log.Warn("job lease recovery failed", "error", err)
		return
	}
	staleCutoff := nowTime.Add(-2 * time.Hour).Format(time.RFC3339)
	if _, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'queued',
			next_run_at = CASE WHEN next_run_at = '' THEN ? ELSE next_run_at END,
			leased_by = '',
			lease_expires_at = '',
			last_error = CASE WHEN last_error = '' THEN 'Worker was running without a lease and became stale.' ELSE last_error END,
			updated_at = ?
		WHERE status = 'running'
			AND cancellation_requested_at = ''
			AND lease_expires_at = ''
			AND updated_at <= ?`,
		now, now, staleCutoff); err != nil {
		s.log.Warn("stale job recovery failed", "error", err)
		return
	}
	if s.shouldDeferBackgroundJobsForPressure() {
		return
	}
	if _, err := s.dispatchScannerBacklog(context.Background()); err != nil {
		s.log.Warn("scanner backlog dispatch failed", "error", err)
		return
	}
	jobs, err := s.dueQueuedJobsFair(now)
	if err != nil {
		s.log.Warn("job worker lookup failed", "error", err)
		return
	}
	for _, job := range jobs {
		if s.shouldDeferQueuedJobForForeground(job) {
			continue
		}
		release, ok := s.tryAcquireJobLane(job.Type)
		if !ok {
			continue
		}
		s.beginJobRun(job, release)
	}
}

func (s *Server) dueQueuedJobsFair(now string) ([]Job, error) {
	jobs := make([]Job, 0, 12)
	for _, definition := range jobLaneDefinitions() {
		laneJobs, err := s.dueQueuedJobsForLane(now, definition.id, jobLaneCapacity(definition.id))
		if err != nil {
			return nil, err
		}
		jobs = append(jobs, laneJobs...)
	}
	sort.SliceStable(jobs, func(i, j int) bool {
		leftPriority := jobs[i].Priority.Priority()
		rightPriority := jobs[j].Priority.Priority()
		if leftPriority != rightPriority {
			return leftPriority < rightPriority
		}
		if jobs[i].CreatedAt == jobs[j].CreatedAt {
			return jobs[i].ID < jobs[j].ID
		}
		return jobs[i].CreatedAt < jobs[j].CreatedAt
	})
	return jobs, nil
}

func (s *Server) dueQueuedJobsForLane(now, lane string, limit int) ([]Job, error) {
	types := jobTypesForLane(lane)
	if len(types) == 0 {
		return nil, nil
	}
	placeholders := make([]string, len(types))
	args := []any{now, now}
	for index, jobType := range types {
		placeholders[index] = "?"
		args = append(args, jobType)
	}
	args = append(args, max(1, limit))
	rows, err := s.queryUserRead(context.Background(), `
		SELECT `+durableJobSelectColumns+`
		FROM jobs
		WHERE status = 'queued'
			AND (next_run_at = '' OR next_run_at <= ?)
			AND (deferred_until = '' OR deferred_until <= ?)
			AND type IN (`+strings.Join(placeholders, ",")+`)
		ORDER BY created_at ASC, id ASC
		LIMIT ?`, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	jobs := []Job{}
	for rows.Next() {
		job, scanErr := scanDurableJob(rows)
		if scanErr != nil {
			return nil, scanErr
		}
		jobs = append(jobs, job)
	}
	return jobs, rows.Err()
}

func (s *Server) shouldDeferQueuedJobForForeground(job Job) bool {
	switch job.Type {
	case "media_analyze":
		return mediaAnalysisModeFromJob(job) == mediaAnalysisModeFull && s.shouldDeferAnalysisForForeground()
	case "optimize_version":
		return s.shouldDeferAnalysisForForeground()
	default:
		return false
	}
}

func (s *Server) acquireJobRunner() func() {
	return s.acquireJobLane(jobLaneBackground)
}

func (s *Server) acquireJobLane(jobType string) func() {
	tokens := s.jobLane(jobType)
	tokens <- struct{}{}
	return func() {
		<-tokens
	}
}

func (s *Server) tryAcquireJobLane(jobType string) (func(), bool) {
	tokens := s.jobLane(jobType)
	select {
	case tokens <- struct{}{}:
		return func() {
			<-tokens
		}, true
	default:
		return nil, false
	}
}

func (s *Server) jobLane(jobType string) chan struct{} {
	lane := jobLaneForType(jobType)
	capacity := jobLaneCapacity(lane)
	s.jobRunnerMu.Lock()
	defer s.jobRunnerMu.Unlock()
	if s.jobLaneTokens == nil {
		s.jobLaneTokens = map[string]chan struct{}{}
	}
	tokens := s.jobLaneTokens[lane]
	if tokens == nil || cap(tokens) != capacity {
		tokens = make(chan struct{}, capacity)
		s.jobLaneTokens[lane] = tokens
	}
	return tokens
}

func jobLaneDefinitions() []struct {
	id    string
	label string
} {
	return []struct {
		id    string
		label string
	}{
		{jobLaneWriteHeavy, "Write-heavy jobs"},
		{jobLaneMetadata, "Metadata jobs"},
		{jobLaneAnalysis, "Analysis jobs"},
		{jobLaneOptimized, "Optimized version jobs"},
		{jobLaneMaintenance, "Maintenance jobs"},
		{jobLaneBackground, "Background jobs"},
	}
}

func jobLaneCapacity(lane string) int {
	switch lane {
	case jobLaneMaintenance:
		return 1
	case jobLaneWriteHeavy:
		return 1
	case jobLaneMetadata:
		return 1
	case jobLaneAnalysis:
		return 1
	case jobLaneOptimized:
		return 4
	default:
		return 1
	}
}

func (s *Server) activeJobFor(jobType, resourceType, resourceID string) (Job, bool, error) {
	var job Job
	var metadataJSON string
	err := s.queryUserRow(context.Background(), `
		SELECT id, type, status, progress, message, resource_type, resource_id, COALESCE(metadata_json, '{}'),
			attempt_count, next_run_at, last_error, failure_kind, created_at, updated_at
		FROM jobs
		WHERE type = ?
			AND resource_type = ?
			AND resource_id = ?
			AND status IN ('queued', 'running')
		ORDER BY created_at ASC
		LIMIT 1`,
		jobType, resourceType, resourceID).Scan(&job.ID, &job.Type, &job.Status, &job.Progress, &job.Message, &job.ResourceType, &job.ResourceID, &metadataJSON, &job.AttemptCount, &job.NextRunAt, &job.LastError, &job.FailureKind, &job.CreatedAt, &job.UpdatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return Job{}, false, nil
	}
	if err != nil {
		return Job{}, false, err
	}
	job.Metadata = decodeJobMetadata(metadataJSON)
	s.hydrateJobEnvelope(&job)
	return job, true, nil
}

func (s *Server) dueQueuedJobs(now string, limit int) ([]Job, error) {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT `+durableJobSelectColumns+`
		FROM jobs
		WHERE status = 'queued'
			AND (next_run_at = '' OR next_run_at <= ?)
			AND (deferred_until = '' OR deferred_until <= ?)
		ORDER BY created_at ASC
		LIMIT ?`,
		now, now, max(1, limit))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	jobs := []Job{}
	for rows.Next() {
		job, err := scanDurableJob(rows)
		if err != nil {
			return nil, err
		}
		jobs = append(jobs, job)
	}
	return jobs, rows.Err()
}

func (s *Server) retryJobLater(jobID string, cause error) bool {
	return s.deferMaintenanceJob(jobID, cause)
}

const maintenanceMaxAttempts = 5

func (s *Server) deferMaintenanceJob(jobID string, cause error) bool {
	if s.jobAdmissionIsClosed() {
		return false
	}
	kind := maintenanceFailureKind(cause)
	if kind == "" {
		return false
	}
	var attemptCount int
	if err := s.queryUserRow(context.Background(), `SELECT attempt_count FROM jobs WHERE id = ?`, jobID).Scan(&attemptCount); err != nil {
		return false
	}
	if attemptCount >= maintenanceMaxAttempts {
		failureMessage := s.sanitizeJobErrorMessage(maintenanceFailureMessage(cause))
		message := fmt.Sprintf("Job failed after %d attempts: %s", attemptCount, failureMessage)
		_, err := s.execBackgroundWrite(context.Background(), `
			UPDATE jobs
			SET status = 'failed',
				phase = 'failed',
				progress = 100,
				progress_current = 100,
				message = ?,
				next_run_at = '',
				deferred_until = '',
				leased_by = '',
				lease_expires_at = '',
				last_error = ?,
				failure_kind = ?,
				error_code = ?,
				retry_eligible = 1,
				retention_until = ?,
				updated_at = ?
			WHERE id = ? AND status = 'running' AND leased_by = ?
				AND cancellation_requested_at = ''`,
			message, failureMessage, kind, kind, s.jobRetentionDeadline(time.Now().UTC()), time.Now().UTC().Format(time.RFC3339Nano), jobID, s.jobLeaseOwner(jobID))
		if err != nil {
			s.log.Warn("job terminal failure update failed", "job", jobID, "error", err)
			return false
		}
		s.log.Warn("maintenance job failed after retries", "job", jobID, "kind", kind, "error", cause)
		return true
	}
	nowTime := time.Now().UTC()
	now := nowTime.Format(time.RFC3339)
	backoff := maintenanceBackoff(attemptCount)
	if retryAfter := hostedRetryAfter(cause); retryAfter > backoff {
		backoff = retryAfter
	}
	nextRunAt := nowTime.Add(backoff).Format(time.RFC3339)
	message := fmt.Sprintf("Job delayed by %s; retrying in %s.", kind, backoff.Round(time.Second))
	result, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'queued',
			phase = 'queued',
			progress = CASE WHEN progress >= 100 THEN 99 ELSE progress END,
			progress_current = CASE WHEN progress >= 100 THEN 99 ELSE progress END,
			message = ?,
			next_run_at = ?,
			deferred_until = ?,
			leased_by = '',
			lease_expires_at = '',
			last_error = ?,
			failure_kind = ?,
			error_code = ?,
			retry_eligible = 1,
			updated_at = ?
		WHERE id = ?
			AND status = 'running' AND leased_by = ?
			AND cancellation_requested_at = ''`,
		message, nextRunAt, nextRunAt, s.sanitizeJobErrorMessage(maintenanceFailureMessage(cause)), kind, kind, now, jobID, s.jobLeaseOwner(jobID))
	if err != nil {
		s.log.Warn("job retry scheduling failed", "job", jobID, "error", err)
		return false
	}
	affected, _ := result.RowsAffected()
	if affected == 0 {
		return false
	}
	s.log.Warn("maintenance job delayed", "job", jobID, "kind", kind, "nextRunAt", nextRunAt, "error", cause)
	return true
}

func maintenanceFailureKind(err error) string {
	if err == nil {
		return ""
	}
	if database.IsRetryableLock(err) {
		return "sqlite_contention"
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return "timeout"
	}
	if errors.Is(err, context.Canceled) {
		return ""
	}
	var hostedErr *hostedHTTPError
	if errors.As(err, &hostedErr) {
		if hostedErr.StatusCode == http.StatusRequestTimeout || hostedErr.StatusCode == http.StatusTooEarly || hostedErr.StatusCode == http.StatusTooManyRequests || hostedErr.StatusCode >= 500 {
			return "hosted_transient"
		}
		return ""
	}
	if errors.Is(err, os.ErrNotExist) || errors.Is(err, os.ErrPermission) || errors.Is(err, os.ErrDeadlineExceeded) {
		return "io"
	}
	var netErr net.Error
	if errors.As(err, &netErr) {
		if netErr.Timeout() {
			return "timeout"
		}
		return "network"
	}
	msg := strings.ToLower(err.Error())
	switch {
	case strings.Contains(msg, "i/o timeout"), strings.Contains(msg, "timeout"), strings.Contains(msg, "deadline exceeded"):
		return "timeout"
	case strings.Contains(msg, "input/output error"), strings.Contains(msg, "device not configured"), strings.Contains(msg, "stale file handle"), strings.Contains(msg, "resource busy"), strings.Contains(msg, "permission denied"), strings.Contains(msg, "no such file"):
		return "io"
	case strings.Contains(msg, "exit status"):
		return "probe_failed"
	default:
		return ""
	}
}

func maintenanceFailureMessage(err error) string {
	if err == nil {
		return ""
	}
	msg := strings.TrimSpace(err.Error())
	if len(msg) > 600 {
		return msg[:600]
	}
	return msg
}

func maintenanceBackoff(attemptCount int) time.Duration {
	attemptCount = max(1, attemptCount)
	backoff := time.Duration(1<<min(attemptCount-1, 5)) * time.Minute
	if backoff > 30*time.Minute {
		return 30 * time.Minute
	}
	return backoff
}

func maintenanceJobTimeout(jobID string, db *sql.DB) time.Duration {
	var jobType string
	var metadataJSON string
	_ = db.QueryRow(`SELECT type, COALESCE(metadata_json, '{}') FROM jobs WHERE id = ?`, jobID).Scan(&jobType, &metadataJSON)
	switch jobType {
	case "library_scan":
		return 12 * time.Hour
	case "library_change_check":
		return 2 * time.Minute
	case "library_read_model_repair":
		return 10 * time.Minute
	case remoteAccessCertificateMaintenanceJobType:
		return 15 * time.Minute
	case "metadata_refresh", "lyrics_fetch_missing", "tmdb_trending_refresh", "live_tv_refresh":
		return 8 * time.Minute
	case "metadata_refresh_library":
		return 20 * time.Minute
	case "media_analyze":
		metadata := decodeJobMetadata(metadataJSON)
		if normalizeMediaAnalysisMode(metadata["analysisMode"]) == mediaAnalysisModeProbe {
			return 15 * time.Minute
		}
		return 6 * time.Hour
	case "optimize_version":
		return 12 * time.Hour
	case downloadArtifactVerificationJobType:
		return 12 * time.Hour
	case "library_trash_cleanup", "optimized_version_prune", "trickplay_prune", "dvr_retention_cleanup", "system_storage_cleanup":
		return 10 * time.Minute
	case "database_backup":
		return 15 * time.Minute
	default:
		return 5 * time.Minute
	}
}

func (s *Server) registerRunningJob(jobID string) (context.Context, func()) {
	return s.registerRunningJobContext(jobID, context.Background())
}

func (s *Server) registerRunningJobContext(jobID string, parent context.Context) (context.Context, func()) {
	if parent == nil {
		parent = context.Background()
	}
	timeout := maintenanceJobTimeout(jobID, s.db)
	ctx, cancel := context.WithTimeout(parent, timeout)
	heartbeatDone := make(chan struct{})
	s.jobCancelMu.Lock()
	if s.jobCancels == nil {
		s.jobCancels = map[string]context.CancelFunc{}
	}
	s.jobCancels[jobID] = cancel
	s.jobCancelMu.Unlock()
	// Close the dispatch-to-registration cancellation race: a queued
	// cancellation request may have landed before this worker published its
	// context, in which case there was no in-memory cancel function for
	// cancelJob to call.
	var cancellationRequestedAt string
	if err := s.queryBackgroundRow(context.Background(), `SELECT COALESCE(cancellation_requested_at, '') FROM jobs WHERE id = ?`, jobID).Scan(&cancellationRequestedAt); err == nil && cancellationRequestedAt != "" {
		cancel()
	}
	go func() {
		defer close(heartbeatDone)
		if hook := s.jobHeartbeatForTest; hook != nil {
			hook(ctx, jobID)
			return
		}
		s.heartbeatRunningJobLease(ctx, jobID)
	}()
	return ctx, func() {
		cancel()
		// Keep the job visible to restore quiescence until the heartbeat's
		// transaction loop has actually exited. Removing it first would let a
		// safety snapshot race a final lease update on the old DB handle.
		<-heartbeatDone
		s.jobCancelMu.Lock()
		delete(s.jobCancels, jobID)
		s.jobCancelMu.Unlock()
	}
}

func (s *Server) heartbeatRunningJobLease(ctx context.Context, jobID string) {
	ticker := time.NewTicker(5 * time.Minute)
	defer ticker.Stop()
	workerID := s.jobLeaseOwner(jobID)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			now := time.Now().UTC()
			leaseExpiresAt := now.Add(30 * time.Minute).Format(time.RFC3339)
			updatedAt := now.Format(time.RFC3339)
			err := s.withBackgroundTxTagged(ctx, nil, func(tx *sql.Tx) error {
				_, err := tx.ExecContext(ctx, `
					UPDATE jobs SET lease_expires_at = ?, updated_at = ?
					WHERE id = ? AND status = 'running' AND leased_by = ?`,
					leaseExpiresAt, updatedAt, jobID, workerID)
				return err
			})
			if err != nil && ctx.Err() == nil {
				s.log.Warn("job lease heartbeat failed", "job", jobID, "error", err)
			}
		}
	}
}

func (s *Server) claimJobForRun(jobID string) bool {
	now := time.Now().UTC().Format(time.RFC3339)
	workerID := s.jobLeaseOwner(jobID)
	leaseExpiresAt := time.Now().UTC().Add(30 * time.Minute).Format(time.RFC3339)
	var jobType string
	if err := s.queryUserRow(context.Background(), `SELECT type FROM jobs WHERE id = ?`, jobID).Scan(&jobType); err == nil && jobType == "optimize_version" {
		return s.claimOptimizeVersionJobForRun(jobID, workerID, leaseExpiresAt, now)
	}
	result, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'running',
			progress = CASE WHEN progress < 1 THEN 1 ELSE progress END,
			attempt_count = attempt_count + 1,
			leased_by = ?,
			lease_expires_at = ?,
			deferred_until = '',
			last_error = '',
			failure_kind = '',
			updated_at = ?
		WHERE id = ?
			AND status = 'queued'
			AND (next_run_at = '' OR next_run_at <= ?)`,
		workerID, leaseExpiresAt, now, jobID, now)
	if err != nil {
		s.log.Warn("job claim failed", "job", jobID, "error", err)
		return false
	}
	affected, _ := result.RowsAffected()
	return affected == 1
}

func (s *Server) claimOptimizeVersionJobForRun(jobID, workerID, leaseExpiresAt, now string) bool {
	limit := s.optimizedVersionSettings().MaxConcurrentJobs
	result, err := s.execBackgroundWrite(context.Background(), `
		UPDATE jobs
		SET status = 'running',
			progress = CASE WHEN progress < 1 THEN 1 ELSE progress END,
			attempt_count = attempt_count + 1,
			leased_by = ?,
			lease_expires_at = ?,
			deferred_until = '',
			last_error = '',
			failure_kind = '',
			updated_at = ?
		WHERE id = ?
			AND type = 'optimize_version'
			AND status = 'queued'
			AND (next_run_at = '' OR next_run_at <= ?)
			AND (
				SELECT COUNT(*)
				FROM jobs
				WHERE type = 'optimize_version'
					AND status = 'running'
			) < ?`,
		workerID, leaseExpiresAt, now, jobID, now, limit)
	if err != nil {
		s.log.Warn("optimized version job claim failed", "job", jobID, "error", err)
		return false
	}
	affected, _ := result.RowsAffected()
	return affected == 1
}

func (s *Server) cancelQueuedJob(jobID string) (Job, error) {
	return s.cancelJob(jobID)
}

func (s *Server) cancelJob(jobID string) (Job, error) {
	jobID = strings.TrimSpace(jobID)
	if jobID == "" {
		return Job{}, sql.ErrNoRows
	}
	now := time.Now().UTC().Format(time.RFC3339)
	state := ""
	transitioned := false
	err := s.withUserTxTagged(context.Background(), []string{"jobs"}, func(tx *sql.Tx) error {
		// Keep the queued-to-running claim transition and the cancellation
		// request in one SQLite write transaction. A read-then-write sequence
		// could observe queued, miss the claim, and leave a job admissible.
		result, err := tx.ExecContext(context.Background(), `
			UPDATE jobs
			SET status = 'cancelled', phase = 'cancelled', progress = 100,
				progress_current = 100, retry_eligible = 0, error_code = 'cancelled',
				message = 'Job cancelled before it started.',
				retention_until = CASE WHEN retention_until = '' THEN ? ELSE retention_until END,
				updated_at = ?
			WHERE id = ? AND status = 'queued'`, s.jobRetentionDeadline(time.Now().UTC()), now, jobID)
		if err != nil {
			return err
		}
		if affected, rowsErr := result.RowsAffected(); rowsErr != nil {
			return rowsErr
		} else if affected == 1 {
			state = "cancelled"
			transitioned = true
			return nil
		}
		result, err = tx.ExecContext(context.Background(), `
			UPDATE jobs
			SET phase = 'cancelling', message = ?, cancellation_requested_at = ?, updated_at = ?
			WHERE id = ? AND status = 'running'`, "Job cancellation requested.", now, now, jobID)
		if err != nil {
			return err
		}
		if affected, rowsErr := result.RowsAffected(); rowsErr != nil {
			return rowsErr
		} else if affected == 1 {
			state = "running"
			transitioned = true
			return nil
		}
		return tx.QueryRowContext(context.Background(), `SELECT status FROM jobs WHERE id = ?`, jobID).Scan(&state)
	})
	if err != nil {
		return Job{}, err
	}
	if state == "running" {
		s.jobCancelMu.Lock()
		cancel := s.jobCancels[jobID]
		s.jobCancelMu.Unlock()
		if cancel != nil {
			cancel()
		}
	}
	if state == "cancelled" && !transitioned {
		return Job{}, fmt.Errorf("Only queued or running jobs can be cancelled; this job is cancelled.")
	}
	if state != "running" && state != "cancelled" {
		return Job{}, fmt.Errorf("Only queued or running jobs can be cancelled; this job is %s.", state)
	}
	if transitioned {
		if err := s.cancelChildJobsForParent(jobID); err != nil {
			s.log.Warn("related job cancellation failed", "job", jobID, "error", err)
		}
	}
	return s.getJob(jobID)
}

func (s *Server) cancelJobsByType(jobType string) (JobCancelResponse, error) {
	jobType = strings.TrimSpace(jobType)
	if jobType == "" {
		return JobCancelResponse{}, errors.New("Job type is required.")
	}
	if !supportedJobType(jobType) {
		return JobCancelResponse{}, fmt.Errorf("unsupported job type %q", jobType)
	}
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id
		FROM jobs
		WHERE type = ?
			AND status IN ('queued', 'running')
		ORDER BY created_at ASC`, jobType)
	if err != nil {
		return JobCancelResponse{}, err
	}
	defer rows.Close()
	ids := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return JobCancelResponse{}, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return JobCancelResponse{}, err
	}
	if len(ids) == 0 {
		return JobCancelResponse{Items: []Job{}, Total: 0, Cancelled: 0, Type: jobType}, nil
	}
	jobs := make([]Job, 0, len(ids))
	for _, id := range ids {
		// Use the same per-row transaction as the single-job endpoint. Signaling
		// a worker before recording its durable cancellation request can let a
		// fast runner publish a terminal success behind a cancellation response.
		job, err := s.cancelJob(id)
		if err == nil {
			jobs = append(jobs, job)
		}
	}
	return JobCancelResponse{Items: jobs, Total: len(jobs), Cancelled: len(jobs), Type: jobType}, nil
}

func (s *Server) cancelChildJobsForParent(parentJobID string) error {
	rows, err := s.queryUserRead(context.Background(), `
		SELECT id
		FROM jobs
		WHERE status IN ('queued', 'running')
			AND parent_operation_id = ?
			AND id <> ?`, parentJobID, parentJobID)
	if err != nil {
		return err
	}
	defer rows.Close()
	childIDs := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return err
		}
		childIDs = append(childIDs, id)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	for _, childID := range childIDs {
		if _, err := s.cancelJob(childID); err != nil {
			return err
		}
	}
	return nil
}

func (s *Server) runDashboardRollupRefresh(ctx context.Context, job Job) {
	since := time.Now().UTC().Add(-30 * 24 * time.Hour)
	if raw := strings.TrimSpace(job.Metadata["since"]); raw != "" {
		if parsed, err := time.Parse(time.RFC3339, raw); err == nil {
			since = parsed
		}
	}
	_ = s.setJobMessage(job.ID, "running", 5, "Refreshing dashboard playback rollups.")
	total := int64(0)
	const batchSize = 1000
	const maxBatches = 100
	for batch := 0; batch < maxBatches; batch++ {
		if err := ctx.Err(); err != nil {
			_ = s.setJobMessage(job.ID, "failed", 100, "Dashboard rollup refresh was interrupted.")
			return
		}
		affected, err := s.refreshDashboardPlaybackRollupsContext(ctx, since, batchSize)
		if err != nil {
			if s.deferMaintenanceJob(job.ID, err) {
				return
			}
			message := fmt.Sprintf("Dashboard rollup refresh failed: %s", err.Error())
			_ = s.setJobMessage(job.ID, "failed", 100, message)
			s.recordLog("error", message, map[string]string{"job": job.ID})
			return
		}
		total += affected
		progress := min(95, 5+((batch+1)*90)/maxBatches)
		_ = s.setJobMessage(job.ID, "running", progress, fmt.Sprintf("Refreshed %d dashboard playback rollup%s.", total, pluralSuffix(int(total))))
		if affected == 0 {
			break
		}
	}
	message := fmt.Sprintf("Dashboard rollup refresh completed with %d updated session%s.", total, pluralSuffix(int(total)))
	_ = s.setJobMessage(job.ID, "complete", 100, message)
	s.invalidateDashboardCache()
}

func (s *Server) runMissingLyricsFetch(ctx context.Context, job Job) {
	if job.ResourceType != "library" || job.ResourceID == "" {
		_ = s.setJobMessage(job.ID, "failed", 100, "Missing lyric fetch failed because no library was selected.")
		return
	}
	library, err := s.getLibrary(job.ResourceID)
	if err != nil {
		_ = s.setJobMessage(job.ID, "failed", 100, "Missing lyric fetch failed because the library no longer exists.")
		return
	}
	if library.Type != "music" {
		_ = s.setJobMessage(job.ID, "failed", 100, "Missing lyric fetch is only available for music libraries.")
		return
	}
	_ = s.setJobMessage(job.ID, "running", 8, fmt.Sprintf("Finding tracks without lyrics in %s.", library.Name))
	result, err := s.fetchMissingLyricsForLibrary(ctx, library.ID, job.ID)
	if err != nil {
		if s.deferMaintenanceJob(job.ID, err) {
			return
		}
		message := fmt.Sprintf("Missing lyric fetch failed for %s: %s", library.Name, err.Error())
		_ = s.setJobMessage(job.ID, "failed", 100, message)
		s.recordLog("error", message, map[string]string{"job": job.ID, "library": library.ID})
		return
	}
	message := fmt.Sprintf("Missing lyric fetch completed for %s. Fetched %d, skipped %d, failed %d.", library.Name, result.Fetched, result.Skipped, result.Failed)
	_ = s.setJobMessage(job.ID, "complete", 100, message)
	s.recordLog("info", message, map[string]string{"job": job.ID, "library": library.ID})
}

type missingLyricsFetchResult struct {
	Fetched int
	Skipped int
	Failed  int
}

func (s *Server) fetchMissingLyricsForLibrary(ctx context.Context, libraryID string, jobID string) (missingLyricsFetchResult, error) {
	tracks, err := s.missingMediaLyricLookupSeedsContext(ctx, "", libraryID, 250)
	if err != nil {
		return missingLyricsFetchResult{}, err
	}
	result := missingLyricsFetchResult{}
	total := len(tracks)
	if total == 0 {
		if jobID != "" {
			_ = s.setJobMessage(jobID, "running", 95, "No tracks are missing lyrics.")
		}
		return result, nil
	}
	for idx, track := range tracks {
		select {
		case <-ctx.Done():
			return result, ctx.Err()
		default:
		}
		if jobID != "" {
			progress := 10 + int(float64(idx)/float64(total)*80)
			_ = s.setJobMessage(jobID, "running", progress, fmt.Sprintf("Fetching lyrics for %s.", track.Title))
		}
		if track.Type != "track" {
			result.Skipped++
			continue
		}
		lyric, err := s.fetchLRCLibLyrics(ctx, track)
		if err != nil {
			result.Failed++
			continue
		}
		if err := s.saveLRCLibLyrics(track.ID, lyric); err != nil {
			result.Failed++
			continue
		}
		result.Fetched++
	}
	return result, nil
}

func (s *Server) setJobProgress(jobID, status string, progress int, message string) error {
	nowTime := time.Now().UTC()
	now := nowTime.Format(time.RFC3339)
	if strings.TrimSpace(message) != "" {
		message = s.sanitizeJobErrorMessage(message)
	}
	leaseExpiresAt := ""
	leaseRefreshBefore := ""
	if status == "running" {
		leaseExpiresAt = nowTime.Add(30 * time.Minute).Format(time.RFC3339)
		leaseRefreshBefore = nowTime.Add(5 * time.Minute).Format(time.RFC3339)
	}
	terminal := isTerminalJobStatus(status)
	retryEligible := 0
	if status == "failed" || status == "interrupted" {
		retryEligible = 1
	}
	errorCode := ""
	if status == "cancelled" {
		errorCode = "cancelled"
	}
	terminalInt := 0
	if terminal {
		terminalInt = 1
	}
	ctx, cancel := boundedJobWriteContext()
	defer cancel()
	result, err := s.execBackgroundWrite(ctx, `
		UPDATE jobs
		SET status = ?,
			progress = ?,
			message = CASE
				WHEN ? = '' THEN message
				WHEN ? = 0 AND status = 'running' AND ? = 'running' AND progress = ? THEN message
				ELSE ?
			END,
			phase = CASE WHEN ? = 1 THEN lower(?) ELSE phase END,
			progress_current = CASE WHEN ? = 1 THEN ? ELSE progress_current END,
			retry_eligible = CASE WHEN ? = 1 THEN ? ELSE retry_eligible END,
			error_code = CASE WHEN ? <> '' THEN ? ELSE error_code END,
			retention_until = CASE WHEN ? = 1 AND retention_until = '' THEN ? ELSE retention_until END,
			lease_expires_at = CASE WHEN ? = 1 THEN '' WHEN ? <> '' AND lease_expires_at < ? THEN ? ELSE lease_expires_at END,
			leased_by = CASE WHEN ? = 1 THEN '' ELSE leased_by END,
			updated_at = ?
		WHERE id = ? AND status = 'running' AND leased_by = ?
			AND NOT (cancellation_requested_at <> '' AND status = 'running' AND ? IN ('complete', 'succeeded', 'failed', 'cancelled', 'interrupted', 'degraded'))
			AND (? = 1 OR status <> ? OR progress <> ? OR (? <> '' AND lease_expires_at < ?))
		`, status, progress, message, terminalInt, status, progress, message,
		terminalInt, status, terminalInt, progress, terminalInt, retryEligible,
		errorCode, errorCode, terminalInt, s.jobRetentionDeadline(nowTime),
		terminalInt, leaseExpiresAt, leaseRefreshBefore, leaseExpiresAt, terminalInt,
		now, jobID, s.jobLeaseOwner(jobID), status,
		terminalInt, status, progress, leaseExpiresAt, leaseRefreshBefore)
	if err == nil && terminal && rowsAffected(result) > 0 {
		s.signalJobWake()
	}
	return err
}

func (s *Server) setJobMessage(jobID, status string, progress int, message string) error {
	return s.setJobProgress(jobID, status, progress, message)
}

func (s *Server) discardFailedMaintenanceJob(jobID, fallbackType string) {
	jobID = strings.TrimSpace(jobID)
	if jobID == "" {
		return
	}
	var jobType, status, message, lastError, failureKind string
	err := s.queryUserRow(context.Background(), `
		SELECT type, status, message, last_error, failure_kind
		FROM jobs
		WHERE id = ?`, jobID).Scan(&jobType, &status, &message, &lastError, &failureKind)
	if errors.Is(err, sql.ErrNoRows) {
		return
	}
	if err != nil {
		s.log.Warn("failed maintenance job lookup failed", "job", jobID, "error", err)
		return
	}
	if fallbackType != "" && jobType == "" {
		jobType = fallbackType
	}
	if status != "failed" || !isMaintenanceJobType(jobType) {
		return
	}
	fields := map[string]string{"job": jobID, "type": jobType}
	if failureKind != "" {
		fields["failureKind"] = failureKind
	}
	if lastError != "" {
		fields["error"] = lastError
	} else if message != "" {
		fields["error"] = message
	}
	s.recordLog("warn", firstNonEmpty(message, "Maintenance job failed."), fields)
}

func (s *Server) purgeFailedMaintenanceJobs() {
	// Failed jobs are durable evidence. Bounded retention, not a scheduler
	// side-effect, is the only path that removes terminal job rows.
	if s.ownerRetentionSettings().JobHistoryDays <= 0 {
		return
	}
	if err := s.pruneJobsPastLimit(context.Background(), jobDefaultRetentionMax); err != nil {
		s.log.Warn("failed maintenance job retention prune failed", "error", err)
	}
}

func (s *Server) listJobs() ([]Job, error) {
	jobs, _, err := s.listJobsPageContext(context.Background(), 80, "", "")
	return jobs, err
}

func (s *Server) listJobsContext(ctx context.Context) ([]Job, error) {
	jobs, _, err := s.listJobsPageContext(ctx, 80, "", "")
	return jobs, err
}

func (s *Server) listJobsPageContext(ctx context.Context, limit int, cursorCreatedAt, cursorID string) ([]Job, string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	limit = max(1, min(250, limit))
	args := []any{}
	cursorWhere := ""
	if cursorCreatedAt != "" && cursorID != "" {
		cursorWhere = `
		AND (created_at < ? OR (created_at = ? AND id < ?))`
		args = append(args, cursorCreatedAt, cursorCreatedAt, cursorID)
	}
	args = append(args, limit+1)
	rows, err := s.queryUserRead(ctx, `
		SELECT `+durableJobSelectColumns+`
		FROM jobs
		WHERE 1 = 1
		`+cursorWhere+`
		ORDER BY created_at DESC, id DESC
		LIMIT ?`, args...)
	if err != nil {
		return nil, "", err
	}
	defer rows.Close()

	jobs := []Job{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, "", err
		}
		job, err := scanDurableJob(rows)
		if err != nil {
			return nil, "", err
		}
		jobs = append(jobs, job)
	}
	if err := rows.Err(); err != nil {
		return nil, "", err
	}
	nextCursor := ""
	if len(jobs) > limit {
		jobs = jobs[:limit]
		last := jobs[len(jobs)-1]
		nextCursor = encodeTimeIDCursor(last.CreatedAt, last.ID)
	}
	s.enrichMetadataRefreshJobsContext(ctx, jobs)
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return jobs, nextCursor, nil
}

func (s *Server) getJob(jobID string) (Job, error) {
	var job Job
	var metadataJSON string
	err := s.queryUserRow(context.Background(), `SELECT id, type, status, progress, message, resource_type, resource_id, COALESCE(metadata_json, '{}'), attempt_count, next_run_at, last_error, failure_kind, created_at, updated_at FROM jobs WHERE id = ?`, strings.TrimSpace(jobID)).
		Scan(&job.ID, &job.Type, &job.Status, &job.Progress, &job.Message, &job.ResourceType, &job.ResourceID, &metadataJSON, &job.AttemptCount, &job.NextRunAt, &job.LastError, &job.FailureKind, &job.CreatedAt, &job.UpdatedAt)
	job.Metadata = decodeJobMetadata(metadataJSON)
	s.hydrateJobEnvelope(&job)
	jobs := []Job{job}
	s.enrichMetadataRefreshJobs(jobs)
	job = jobs[0]
	return job, err
}

func (s *Server) enrichMetadataRefreshJobs(jobs []Job) {
	s.enrichMetadataRefreshJobsContext(context.Background(), jobs)
}

func (s *Server) enrichMetadataRefreshJobsContext(ctx context.Context, jobs []Job) {
	if ctx == nil {
		ctx = context.Background()
	}
	ids := []string{}
	jobIndexesByMediaID := map[string][]int{}
	for i := range jobs {
		if err := ctx.Err(); err != nil {
			return
		}
		job := &jobs[i]
		if job.Type != "metadata_refresh" || job.ResourceType != "media" || strings.TrimSpace(job.ResourceID) == "" {
			continue
		}
		if job.Metadata == nil {
			job.Metadata = map[string]string{}
		}
		if job.Metadata["libraryId"] != "" && job.Metadata["libraryName"] != "" {
			continue
		}
		mediaID := strings.TrimSpace(job.ResourceID)
		if len(jobIndexesByMediaID[mediaID]) == 0 {
			ids = append(ids, mediaID)
		}
		jobIndexesByMediaID[mediaID] = append(jobIndexesByMediaID[mediaID], i)
	}
	if len(ids) == 0 {
		return
	}
	args := make([]any, 0, len(ids))
	for _, id := range ids {
		args = append(args, id)
	}
	rows, err := s.queryUserRead(ctx, `
		SELECT m.id, COALESCE(m.title, ''), COALESCE(m.library_id, ''), COALESCE(l.name, '')
		FROM media_items m
		LEFT JOIN libraries l ON l.id = m.library_id
		WHERE m.id IN (`+sqlPlaceholders(len(ids))+`)`, args...)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return
		}
		var mediaID, title, libraryID, libraryName string
		if err := rows.Scan(&mediaID, &title, &libraryID, &libraryName); err != nil {
			continue
		}
		for _, index := range jobIndexesByMediaID[mediaID] {
			job := &jobs[index]
			if job.Metadata == nil {
				job.Metadata = map[string]string{}
			}
			if title != "" {
				job.Metadata["mediaTitle"] = title
			}
			if libraryID != "" {
				job.Metadata["libraryId"] = libraryID
			}
			if libraryName != "" {
				job.Metadata["libraryName"] = libraryName
			}
		}
	}
}

func (s *Server) recordLog(level, message string, fields map[string]string) LogEvent {
	level = strings.ToLower(strings.TrimSpace(level))
	if logLevelRank(level) == 0 {
		level = "info"
	}
	if logLevelRank(level) < logLevelRank(s.troubleshootingLogLevel()) {
		return LogEvent{}
	}
	event := LogEvent{
		ID:      randomID("log"),
		Time:    time.Now().UTC().Format(time.RFC3339),
		Level:   level,
		Message: s.sanitizeDiagnosticText(message, 4000),
		Fields:  s.sanitizeDiagnosticFields(fields),
	}
	if event.Level == "" {
		event.Level = "info"
	}
	if event.Message == "" {
		event.Message = "Event recorded"
	}

	s.logMu.Lock()
	s.logEvents = append(s.logEvents, event)
	s.pruneLogEventsLocked()
	for subscriber := range s.logSubscribers {
		select {
		case subscriber <- event:
		default:
			// A full console subscriber has lost continuity. Disconnect it so
			// the client must perform an authoritative paginated reset instead
			// of silently consuming a stream with an unknown gap.
			if s.logSubscribers[subscriber] {
				delete(s.logSubscribers, subscriber)
				close(subscriber)
			}
		}
	}
	s.logMu.Unlock()
	s.enqueueServerDiagnostic(event)
	return event
}

func (s *Server) troubleshootingLogLevel() string {
	settings, err := s.loadSettings()
	if err != nil {
		return "info"
	}
	group, _ := settings["troubleshooting"].(map[string]any)
	level := normalizeTroubleshootingLogLevel(settingString(group, "logLevel", "info"))
	if level != "debug" {
		return level
	}
	durationMinutes := max(5, min(1440, settingInt(group, "debugDurationMinutes", 60)))
	var updatedAt string
	if err := s.queryBackgroundRow(context.Background(), `SELECT updated_at FROM settings WHERE key = 'troubleshooting'`).Scan(&updatedAt); err != nil {
		return "info"
	}
	enabledAt, err := time.Parse(time.RFC3339, updatedAt)
	if err != nil || !s.operationalRetentionNow().Before(enabledAt.Add(time.Duration(durationMinutes)*time.Minute)) {
		return "info"
	}
	return "debug"
}

func normalizeTroubleshootingLogLevel(level string) string {
	switch strings.ToLower(strings.TrimSpace(level)) {
	case "debug", "info", "warn":
		return strings.ToLower(strings.TrimSpace(level))
	default:
		return "info"
	}
}

func (s *Server) logRetentionDays() int {
	return s.ownerRetentionSettings().DiagnosticHistoryDays
}

func (s *Server) pruneLogEventsLocked() {
	retentionDays := s.logRetentionDays()
	if retentionDays > 0 {
		cutoff := s.operationalRetentionNow().Add(-time.Duration(retentionDays) * 24 * time.Hour)
		filtered := s.logEvents[:0]
		for _, event := range s.logEvents {
			parsed, err := time.Parse(time.RFC3339, event.Time)
			if err == nil && parsed.Before(cutoff) {
				continue
			}
			filtered = append(filtered, event)
		}
		s.logEvents = filtered
	}
	if len(s.logEvents) > 500 {
		s.logEvents = append([]LogEvent(nil), s.logEvents[len(s.logEvents)-500:]...)
	}
}

func (s *Server) listLogEvents(limit int) []LogEvent {
	events, _ := s.listLogEventsPage(limit, "", "")
	return events
}

func (s *Server) listLogEventsPage(limit int, cursorTime, cursorID string) ([]LogEvent, string) {
	limit = normalizedLogLimit(limit)
	persisted := s.listPersistedServerDiagnosticEvents(limit, cursorTime, cursorID)
	s.logMu.Lock()
	events := make([]LogEvent, len(s.logEvents))
	copy(events, s.logEvents)
	s.logMu.Unlock()
	if len(persisted) > 0 {
		seen := make(map[string]struct{}, len(persisted)+len(events))
		for _, event := range persisted {
			seen[event.ID] = struct{}{}
		}
		for _, event := range events {
			if _, ok := seen[event.ID]; !ok {
				persisted = append(persisted, event)
			}
		}
		events = persisted
	}

	sort.SliceStable(events, func(i, j int) bool {
		if events[i].Time == events[j].Time {
			return events[i].ID > events[j].ID
		}
		return events[i].Time > events[j].Time
	})

	filtered := events[:0]
	for _, event := range events {
		if cursorTime != "" && cursorID != "" {
			if event.Time > cursorTime || (event.Time == cursorTime && event.ID >= cursorID) {
				continue
			}
		}
		filtered = append(filtered, event)
		if len(filtered) > limit {
			break
		}
	}

	nextCursor := ""
	if len(filtered) > limit {
		filtered = filtered[:limit]
		last := filtered[len(filtered)-1]
		nextCursor = encodeTimeIDCursor(last.Time, last.ID)
	}
	return append([]LogEvent(nil), filtered...), nextCursor
}

func normalizedLogLimit(limit int) int {
	if limit <= 0 {
		return 200
	}
	return max(1, min(500, limit))
}

func (s *Server) subscribeLogs() chan LogEvent {
	ch := make(chan LogEvent, 32)
	s.logMu.Lock()
	if s.logSubscribers == nil {
		s.logSubscribers = map[chan LogEvent]bool{}
	}
	s.logSubscribers[ch] = true
	s.logMu.Unlock()
	return ch
}

func (s *Server) unsubscribeLogs(ch chan LogEvent) {
	s.logMu.Lock()
	delete(s.logSubscribers, ch)
	s.logMu.Unlock()
}

func (s *Server) publishSQLDataChanged(query string) {
	tags := dataTagsForSQL(query)
	if len(tags) == 0 {
		return
	}
	s.publishDataChanged("data.changed", tags, "database", "", nil)
}

func (s *Server) publishDataChanged(eventType string, tags []string, resource, resourceID string, fields map[string]string) {
	s.publishDataChangedForViewer(eventType, tags, resource, resourceID, fields, "", "")
}

func (s *Server) publishDataChangedForViewer(eventType string, tags []string, resource, resourceID string, fields map[string]string, accountID, profileID string) {
	tags = uniqueStrings(tags)
	if len(tags) == 0 {
		return
	}
	if hasString(tags, "libraries") {
		s.invalidateLocalContentRoots()
	}
	if hasString(tags, "home") {
		if strings.TrimSpace(profileID) != "" {
			s.invalidateHomeCacheForProfile(profileID)
		} else {
			s.invalidateHomeCache()
		}
	}
	if hasString(tags, "media-state") {
		s.invalidateMediaStatePresence(profileID)
	}
	if hasString(tags, "media") || hasString(tags, "library-items") || hasString(tags, "libraries") || hasString(tags, "metadata") {
		s.invalidateMetadataHealthCache()
	}
	if hasString(tags, "media") || hasString(tags, "library-items") || hasString(tags, "libraries") || hasString(tags, "playlists") || hasString(tags, "media-state") {
		s.invalidateSmartPlaylistCache()
	}
	event := AppEvent{
		ID:                s.appEventSequence.Add(1),
		Type:              strings.TrimSpace(eventType),
		Tags:              tags,
		Resource:          strings.TrimSpace(resource),
		ResourceID:        strings.TrimSpace(resourceID),
		Fields:            fields,
		CreatedAt:         time.Now().UTC().Format(time.RFC3339),
		audienceAccountID: strings.TrimSpace(accountID),
		audienceProfileID: strings.TrimSpace(profileID),
	}
	if event.Type == "" {
		event.Type = "data.changed"
	}
	s.appEventMu.Lock()
	if s.appEventSubscribers == nil {
		s.appEventSubscribers = map[chan AppEvent]bool{}
	}
	for subscriber := range s.appEventSubscribers {
		if audience, ok := s.appEventSubscriberAudience[subscriber]; ok && !appEventAudienceMatchesSubscriber(event, audience) {
			continue
		}
		select {
		case subscriber <- event:
		default:
			// A full subscriber buffer means SSE continuity is already lost.
			// Disconnect instead of silently dropping an invalidation; Client
			// Core reconnects and performs an authoritative reset before it
			// publishes frames from the replacement stream.
			delete(s.appEventSubscribers, subscriber)
			delete(s.appEventSubscriberAudience, subscriber)
			close(subscriber)
		}
	}
	s.appEventMu.Unlock()
	if s.longPoll != nil {
		s.longPoll.broker.publishApp(event)
	}
}

// projectAppEventForUserContext is the sole application-event disclosure
// boundary used by both SSE and long-poll. Exact viewer events never cross
// account/profile scope. Resource-bearing server events are delivered only
// when the viewer can access the owning library. Events without a provable
// audience remain useful as content-free invalidations, but their identifiers
// and fields are stripped before crossing the API boundary.
func (s *Server) projectAppEventForUserContext(ctx context.Context, user User, event AppEvent) (AppEvent, bool) {
	if ctx == nil {
		ctx = context.Background()
	}
	if event.audienceAccountID != "" && event.audienceAccountID != accountIDForUser(user) {
		return AppEvent{}, false
	}
	if event.audienceProfileID != "" && event.audienceProfileID != viewerProfileID(user) {
		return AppEvent{}, false
	}
	exactAudience := event.audienceAccountID != "" || event.audienceProfileID != ""
	resource := strings.ToLower(strings.TrimSpace(event.Resource))
	resourceID := strings.TrimSpace(event.ResourceID)
	if resourceID != "" && resource == "library" {
		if !s.canAccessLibraryContext(ctx, user, resourceID) {
			return AppEvent{}, false
		}
		exactAudience = true
	}
	if resourceID != "" && resource == "media" {
		var libraryID string
		if err := s.queryUserRow(ctx, `SELECT COALESCE(library_id, '') FROM media_items WHERE id = ?`, resourceID).Scan(&libraryID); err != nil || strings.TrimSpace(libraryID) == "" {
			return AppEvent{}, false
		}
		if !s.canAccessLibraryContext(ctx, user, libraryID) {
			return AppEvent{}, false
		}
		exactAudience = true
	}
	if !exactAudience {
		event.ResourceID = ""
		event.Fields = nil
	}
	return event, true
}

func (s *Server) projectAppEventsForUserContext(ctx context.Context, user User, events []AppEvent) []AppEvent {
	projected := make([]AppEvent, 0, len(events))
	for _, event := range events {
		if visible, ok := s.projectAppEventForUserContext(ctx, user, event); ok {
			projected = append(projected, visible)
		}
	}
	return projected
}

func hasString(values []string, target string) bool {
	for _, value := range values {
		if value == target {
			return true
		}
	}
	return false
}

func (s *Server) subscribeAppEvents() chan AppEvent {
	return s.subscribeAppEventsForAudience(appEventSubscriberAudience{})
}

func (s *Server) subscribeAppEventsForUser(user User) chan AppEvent {
	return s.subscribeAppEventsForAudience(appEventSubscriberAudience{
		accountID: accountIDForUser(user),
		profileID: viewerProfileID(user),
	})
}

func (s *Server) subscribeAppEventsForAudience(audience appEventSubscriberAudience) chan AppEvent {
	ch := make(chan AppEvent, 64)
	s.appEventMu.Lock()
	if s.appEventSubscribers == nil {
		s.appEventSubscribers = map[chan AppEvent]bool{}
	}
	s.appEventSubscribers[ch] = true
	if s.appEventSubscriberAudience == nil {
		s.appEventSubscriberAudience = map[chan AppEvent]appEventSubscriberAudience{}
	}
	s.appEventSubscriberAudience[ch] = audience
	s.appEventMu.Unlock()
	return ch
}

func appEventAudienceMatchesSubscriber(event AppEvent, subscriber appEventSubscriberAudience) bool {
	// The zero audience is retained for internal/tests that intentionally
	// subscribe to the complete invalidation stream.
	if subscriber.accountID == "" && subscriber.profileID == "" {
		return true
	}
	if event.audienceAccountID != "" && event.audienceAccountID != subscriber.accountID {
		return false
	}
	if event.audienceProfileID != "" && event.audienceProfileID != subscriber.profileID {
		return false
	}
	return true
}

func (s *Server) unsubscribeAppEvents(ch chan AppEvent) {
	s.appEventMu.Lock()
	if s.appEventSubscribers != nil {
		if s.appEventSubscribers[ch] {
			delete(s.appEventSubscribers, ch)
			delete(s.appEventSubscriberAudience, ch)
			close(ch)
		}
	}
	s.appEventMu.Unlock()
}

func dataTagsForSQL(query string) []string {
	normalized := strings.ToLower(query)
	if !strings.Contains(normalized, "insert") && !strings.Contains(normalized, "update") && !strings.Contains(normalized, "delete") && !strings.Contains(normalized, "replace") {
		return nil
	}
	tags := []string{}
	add := func(values ...string) {
		tags = append(tags, values...)
	}
	if strings.Contains(normalized, "media_search") {
		add("search")
	}
	if strings.Contains(normalized, "media_items") || strings.Contains(normalized, "media_files") || strings.Contains(normalized, "media_images") || strings.Contains(normalized, "media_streams") || strings.Contains(normalized, "media_people") || strings.Contains(normalized, "media_segments") || strings.Contains(normalized, "media_chapters") || strings.Contains(normalized, "media_lyrics") || strings.Contains(normalized, "media_provider_ids") || strings.Contains(normalized, "media_trickplay_sets") || strings.Contains(normalized, "optimized_versions") {
		add("media", "metadata", "library-items")
	}
	if strings.Contains(normalized, "libraries") || strings.Contains(normalized, "library_paths") || strings.Contains(normalized, "media_category_facets") || strings.Contains(normalized, "user_library_navigation") {
		add("libraries", "home", "library-items")
	}
	if strings.Contains(normalized, "jobs") {
		add("jobs", "dashboard:jobs", "settings")
	}
	if strings.Contains(normalized, "settings") || strings.Contains(normalized, "user_display_preferences") {
		add("settings", "display-preferences", "remote-access")
	}
	if strings.Contains(normalized, "users") || strings.Contains(normalized, "profile_identities") || strings.Contains(normalized, "user_library_access") {
		add("users", "account", "settings")
	}
	if strings.Contains(normalized, "profiles") || strings.Contains(normalized, "profile_selection_grants") || strings.Contains(normalized, "automatic_profile_selection_trusts") || strings.Contains(normalized, "local_profile_pin_credentials") {
		add("profiles", "account")
	}
	if strings.Contains(normalized, "devices") || strings.Contains(normalized, "api_keys") || strings.Contains(normalized, "quick_connect_requests") {
		add("devices", "api-keys", "quick-connect", "settings")
	}
	if strings.Contains(normalized, "playback_sessions") {
		add("playback", "dashboard:live")
		if strings.Contains(normalized, "insert into playback_sessions") || strings.Contains(normalized, "delete from playback_sessions") || strings.Contains(normalized, "ended_at") {
			add("dashboard:history")
		}
	}
	if strings.Contains(normalized, "playback_session_history") || strings.Contains(normalized, "dashboard_playback_rollups") {
		add("playback", "dashboard:history")
	}
	if strings.Contains(normalized, "playback_receivers") || strings.Contains(normalized, "watch_with_friends_") {
		add("playback")
	}
	if strings.Contains(normalized, "playlists") || strings.Contains(normalized, "playlist_items") || strings.Contains(normalized, "playlist_shares") {
		add("playlists")
	}
	if strings.Contains(normalized, "collections") || strings.Contains(normalized, "collection_items") || strings.Contains(normalized, "collection_shares") {
		add("collections")
	}
	if strings.Contains(normalized, "user_media_state") {
		add("playback-progress")
		if strings.Contains(normalized, "watchlisted") || strings.Contains(normalized, "favorite") || strings.Contains(normalized, "watched") || strings.Contains(normalized, "rating") || strings.Contains(normalized, "reaction") {
			add("media-state")
		}
	}
	if strings.Contains(normalized, "viewer_notifications") || strings.Contains(normalized, "viewer_notification_receipts") || strings.Contains(normalized, "viewer_notification_revisions") {
		add("notifications")
	}
	if strings.Contains(normalized, "downloads") || strings.Contains(normalized, "media_download_grants") {
		add("downloads")
	}
	if strings.Contains(normalized, "live_tv_") {
		add("live-tv", "dvr", "dashboard:live")
	}
	if strings.Contains(normalized, "library_channel_") || strings.Contains(normalized, "library_channels") {
		add("library-channels", "live-tv", "settings", "dashboard:live")
	}
	if strings.Contains(normalized, "remote_access_members") {
		add("remote-access", "portico-members", "settings", "users")
	}
	if strings.Contains(normalized, "audit_events") {
		add("settings")
	}
	return uniqueStrings(tags)
}

func (s *Server) loadSettings() (map[string]any, error) {
	return s.loadSettingsContext(context.Background())
}

func (s *Server) loadSettingsContext(ctx context.Context) (map[string]any, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `SELECT key, value_json FROM settings ORDER BY key ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	settings := map[string]any{}
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var key string
		var raw string
		if err := rows.Scan(&key, &raw); err != nil {
			return nil, err
		}
		var value any
		if err := json.Unmarshal([]byte(raw), &value); err != nil {
			if s.log != nil {
				s.log.Warn("ignored quarantinable malformed setting", "key", key)
			}
			continue
		}
		settings[key] = value
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return settings, nil
}

type settingsRevisionEntry struct {
	Key       string `json:"key"`
	Value     any    `json:"value"`
	UpdatedAt string `json:"updatedAt"`
}

func loadSettingsSnapshotFromQuery(rows sqlRows, err error) (map[string]any, string, string, error) {
	if err != nil {
		return nil, "", "", err
	}
	defer rows.Close()
	settings := map[string]any{}
	entries := []settingsRevisionEntry{}
	latest := time.Time{}
	for rows.Next() {
		var key, raw, updatedAt string
		if err := rows.Scan(&key, &raw, &updatedAt); err != nil {
			return nil, "", "", err
		}
		var value any
		if err := json.Unmarshal([]byte(raw), &value); err != nil {
			continue
		}
		settings[key] = value
		if _, exposed := writableSettingSchemas[key]; !exposed {
			continue
		}
		revisionValue := value
		if secretSettingKeys[key] {
			revisionValue = map[string]bool{"present": true}
		}
		entries = append(entries, settingsRevisionEntry{Key: key, Value: revisionValue, UpdatedAt: updatedAt})
		if parsed, parseErr := time.Parse(time.RFC3339Nano, updatedAt); parseErr == nil && parsed.After(latest) {
			latest = parsed
		}
	}
	if err := rows.Err(); err != nil {
		return nil, "", "", err
	}
	bytes, err := json.Marshal(entries)
	if err != nil {
		return nil, "", "", err
	}
	sum := sha256.Sum256(bytes)
	revision := "settings_" + base64.RawURLEncoding.EncodeToString(sum[:18])
	updatedAt := latest.UTC().Format(time.RFC3339Nano)
	if latest.IsZero() {
		updatedAt = time.Unix(0, 0).UTC().Format(time.RFC3339Nano)
	}
	return settings, revision, updatedAt, nil
}

func (s *Server) loadSettingsSnapshotContext(ctx context.Context) (map[string]any, string, string, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := s.repairCanonicalSettingsContext(ctx); err != nil {
		return nil, "", "", err
	}
	return loadSettingsSnapshotFromQuery(s.queryUserRead(ctx, `SELECT key, value_json, updated_at FROM settings ORDER BY key ASC`))
}

func (s *Server) settingsDocumentForUser(ctx context.Context, user User, impact SettingsApplyImpact) (SettingsDocument, error) {
	settings, revision, updatedAt, err := s.loadSettingsSnapshotContext(ctx)
	if err != nil {
		return SettingsDocument{}, err
	}
	groups := s.clientSettingsForUser(user, settings)
	if groups == nil {
		groups = map[string]any{}
	}
	if impact.ChangedFields == nil {
		impact.ChangedFields = []string{}
	}
	if impact.RestartRequiredFields == nil {
		impact.RestartRequiredFields = []string{}
	}
	restartFields := allRestartRequiredSettingFields()
	return SettingsDocument{
		Revision:              revision,
		UpdatedAt:             updatedAt,
		Groups:                groups,
		RestartRequired:       impact.RestartRequired,
		RestartRequiredFields: restartFields,
		ApplyImpact:           impact,
		Generation:            SettingsGeneration{Mode: "next-operation", ActiveRevision: revision, Instruction: "New operations use this committed settings revision."},
	}, nil
}

func writeSettingsDocument(w http.ResponseWriter, status int, document SettingsDocument) {
	w.Header().Set("ETag", settingsETag(document.Revision))
	w.Header().Set("X-Portico-Settings-Revision", document.Revision)
	w.Header().Set("Cache-Control", "private, no-cache")
	writeJSON(w, status, document)
}

func settingsETag(revision string) string {
	return `"` + normalizeSettingsRevision(revision) + `"`
}

func normalizeSettingsRevision(revision string) string {
	revision = strings.TrimSpace(revision)
	revision = strings.TrimPrefix(revision, "W/")
	return strings.Trim(strings.TrimSpace(revision), `"`)
}

var restartRequiredSettingFields = map[string]bool{}

func allRestartRequiredSettingFields() []string {
	fields := make([]string, 0, len(restartRequiredSettingFields))
	for field := range restartRequiredSettingFields {
		fields = append(fields, field)
	}
	sort.Strings(fields)
	return fields
}

func changedRestartRequiredSettingFields(changed []string) []string {
	fields := []string{}
	for _, field := range changed {
		if restartRequiredSettingFields[field] {
			fields = append(fields, field)
		}
	}
	return uniqueStrings(fields)
}

const (
	tmdbReadAccessTokenSettingKey = "tmdbReadAccessToken"
	tmdbAPIKeySettingKey          = "tmdbAPIKey"
	tvdbAPIKeySettingKey          = "tvdbAPIKey"
)

var secretSettingKeys = map[string]bool{
	remoteAccessClaimTokenKey:     true,
	remoteAccessClaimReceiptKey:   true,
	remoteAccessCredentialKey:     true,
	remoteAccessPolicyStateKey:    true,
	hostedDocumentKeySetStateKey:  true,
	tmdbReadAccessTokenSettingKey: true,
	tmdbAPIKeySettingKey:          true,
	tvdbAPIKeySettingKey:          true,
}

var productOwnedSettingsHiddenFromClient = map[string]bool{
	"extras": true,
}

func (s *Server) clientSettings(settings map[string]any) map[string]any {
	client := applyCanonicalSettingDefaults(settings)
	for key, value := range client {
		client[key] = clientSettingValue(key, value)
	}
	group, _ := client["metadataAgents"].(map[string]any)
	// The secret controls represent owner overrides, not Portico's bundled
	// application credential. Removing an override returns to the included
	// default and must not immediately render as another removable secret.
	group["tmdbReadAccessToken"] = map[string]bool{"present": strings.TrimSpace(s.secretSetting(tmdbReadAccessTokenSettingKey)) != ""}
	group["tmdbAPIKey"] = map[string]bool{"present": strings.TrimSpace(s.secretSetting(tmdbAPIKeySettingKey)) != ""}
	group["tvdbAPIKey"] = map[string]bool{"present": strings.TrimSpace(s.secretSetting(tvdbAPIKeySettingKey)) != ""}
	return client
}

func clientSettingValue(key string, value any) any {
	group, ok := value.(map[string]any)
	if !ok {
		return value
	}
	schema, ok := writableSettingSchemas[key]
	if !ok {
		return value
	}
	filtered := make(map[string]any, len(group))
	for field, fieldValue := range group {
		if _, ok := schema[field]; ok {
			filtered[field] = fieldValue
		}
	}
	return filtered
}

func (s *Server) clientSettingsForUser(user User, settings map[string]any) map[string]any {
	client := s.clientSettings(settings)
	if hasPermission(user, "manageServer") {
		return client
	}
	filtered := map[string]any{}
	for _, key := range allowedSettingKeysForUser(user) {
		if value, ok := client[key]; ok {
			filtered[key] = value
		}
	}
	return filtered
}

func (s *Server) settingsSummary(settings map[string]any) SettingsSummaryResponse {
	now := time.Now().UTC().Format(time.RFC3339)
	groups := []SettingsGroupSummary{
		settingsGroup("server", "General", "configure", "Server identity and naming.", true, !isWritableSettingGroup("server"), settingDiffersFromDefaults(settings, "server")),
		settingsGroup("library-settings", "Library Rules", "configure", "Scanner, trash, and deletion safeguards.", true, !isWritableSettingGroup("library"), true),
		settingsGroup("metadata-agents", "Metadata Sources", "configure", "Remote metadata agents, local metadata, and provider credential overrides.", true, !isWritableSettingGroup("metadataAgents"), settingDiffersFromDefaults(settings, "metadataAgents") || s.tmdbReadAccessToken() != "" || s.tmdbAPIKey() != "" || strings.TrimSpace(s.secretSetting(tvdbAPIKeySettingKey)) != ""),
		settingsGroup("transcoder", "Streaming", "configure", "Transcode policy, hardware acceleration, remux, and cache location.", true, !isWritableSettingGroup("transcoder"), settingDiffersFromDefaults(settings, "transcoder")),
		settingsGroup("remote-access", "Remote Access", "configure", "Portico account link, DNS, TLS, and direct route health.", true, true, remoteAccessClaimed(settings)),
		settingsGroup("network", "Network", "configure", "Secure connection policy, LAN ranges, and custom access URLs.", true, !isWritableSettingGroup("network"), settingDiffersFromDefaults(settings, "network")),
		settingsGroup("languages", "Languages", "configure", "Audio, subtitle, forced-subtitle, and metadata language defaults.", true, !isWritableSettingGroup("languages"), settingDiffersFromDefaults(settings, "languages")),
		settingsGroup("dlna", "DLNA", "configure", "Local-network DLNA exposure and unauthenticated LAN warning.", true, !isWritableSettingGroup("dlna"), settingBoolFromDocument(settings, "dlna", "enabled")),
		settingsGroup("scheduled-tasks", "Automation", "configure", "Maintenance windows, scans, backups, cleanup, and analysis.", true, !isWritableSettingGroup("scheduledTasks"), settingBoolFromDocument(settings, "scheduledTasks", "enabled")),
		settingsGroup("optimized-versions", "Version Library", "configure", "Persistent optimized-version generation and retention policy.", true, !isWritableSettingGroup("optimizedVersions"), settingDiffersFromDefaults(settings, "optimizedVersions")),
		settingsGroup("notifications", "Operational alerts", "configure", "Dashboard health and maintenance alert visibility.", true, !isWritableSettingGroup("notifications"), settingBoolFromDocument(settings, "notifications", "enabled")),
		settingsGroup("viewer-feedback", "Viewer messages", "configure", "Viewer-to-owner messaging, owner responses, and privacy retention.", true, !isWritableSettingGroup("viewerFeedback"), settingBoolFromDocument(settings, "viewerFeedback", "enabled")),
		settingsGroup("libraries", "Media Libraries", "operate", "Library instances, paths, scanning, lyrics, and trash.", true, false, true),
		settingsGroup("live-tv", "Live Channels", "operate", "Live TV sources, guide cache, channel visibility, and provider health.", true, false, true),
		settingsGroup("dvr", "DVR", "operate", "Recording rules, timers, retention, and recording storage policy.", true, !isWritableSettingGroup("dvr"), settingDiffersFromDefaults(settings, "dvr")),
		settingsGroup("library-channels", "Library Channels", "operate", "Owner-managed virtual channels, programming rules, schedules, logos, and playout health.", true, false, true),
		settingsGroup("storage", "Storage", "operate", "Server-managed storage categories and cleanup.", true, true, true),
		settingsGroup("backups", "Backups", "operate", "SQLite backup, manifest verification, and restore staging.", true, false, true),
		settingsGroup("users", "People", "operate", "Local profiles, permissions, restrictions, and access policy.", true, false, true),
		settingsGroup("devices", "Devices", "operate", "Known devices, trust policy, Quick Connect, and revocation.", true, !isWritableSettingGroup("devices"), settingDiffersFromDefaults(settings, "devices")),
		settingsGroup("api-keys", "API Keys", "operate", "Admin automation keys and rotation reminders.", true, false, true),
		settingsGroup("troubleshooting", "Diagnostics", "support", "Runtime diagnostics, dependency checks, and client log consent.", true, !isWritableSettingGroup("troubleshooting"), true),
		settingsGroup("retention", "History & Retention", "support", "Owner-controlled retention for playback, security, authentication, device, and diagnostic history.", true, !isWritableSettingGroup("retention"), settingDiffersFromDefaults(settings, "retention")),
		settingsGroup("console", "Event Console", "support", "Application events and audit-oriented operator logs.", true, true, true),
	}
	for index := range groups {
		group := &groups[index]
		if group.ID == "remote-access" {
			group.RequiresPorticoClaim = true
			group.Status = boolStatus(group.Configured, "claimed", "not claimed")
		}
		if group.ID == "transcoder" || group.ID == "live-tv" || group.ID == "dvr" || group.ID == "library-channels" || group.ID == "troubleshooting" {
			group.RequiresRuntimeDependency = true
		}
		if group.ID == "libraries" || group.ID == "users" || group.ID == "devices" || group.ID == "api-keys" || group.ID == "backups" || group.ID == "storage" || group.ID == "dvr" {
			group.Dangerous = true
		}
		if group.Status == "" {
			group.Status = boolStatus(group.Configured, "configured", "default")
		}
		if group.ID == "dlna" || group.ID == "scheduled-tasks" || group.ID == "notifications" || group.ID == "viewer-feedback" {
			group.Status = boolStatus(group.Configured, "enabled", "disabled")
		}
		if group.ID == "updates" {
			group.Status = "unavailable"
		}
	}
	statusCards := []DashboardNotice{}
	if !remoteAccessClaimed(settings) {
		statusCards = append(statusCards, DashboardNotice{ID: "remote-access-unclaimed", Level: "warn", Title: "Remote Access Not Connected", Message: "Hosted direct-route management remains limited until the server is connected to a Portico account.", Time: now})
	}
	return SettingsSummaryResponse{Groups: groups, StatusCards: statusCards, GeneratedAt: now}
}

func (s *Server) settingsSummaryForUser(user User, settings map[string]any) SettingsSummaryResponse {
	summary := s.settingsSummary(settings)
	if hasPermission(user, "manageServer") {
		if !isLibraryChannelOwner(user) {
			groups := make([]SettingsGroupSummary, 0, len(summary.Groups))
			for _, group := range summary.Groups {
				if group.ID != "library-channels" {
					groups = append(groups, group)
				}
			}
			summary.Groups = groups
		}
		return summary
	}
	allowed := allowedSettingsSummaryIDsForUser(user)
	groups := make([]SettingsGroupSummary, 0, len(summary.Groups))
	for _, group := range summary.Groups {
		if allowed[group.ID] {
			groups = append(groups, group)
		}
	}
	summary.Groups = groups
	summary.StatusCards = []DashboardNotice{}
	return summary
}

func settingsGroup(id, label, category, summary string, implemented, readOnly, configured bool) SettingsGroupSummary {
	return SettingsGroupSummary{
		ID:            id,
		Label:         label,
		Category:      category,
		Summary:       summary,
		Implemented:   implemented,
		ReadOnly:      readOnly,
		RequiresAdmin: true,
		Configured:    configured,
	}
}

func settingBoolFromDocument(settings map[string]any, key, field string) bool {
	group, _ := settings[key].(map[string]any)
	value, _ := group[field].(bool)
	return value
}

func settingDiffersFromDefaults(settings map[string]any, key string) bool {
	definition, ok := canonicalSettingRegistry[key]
	if !ok {
		return false
	}
	effective := cloneSettingMap(definition.Defaults)
	if stored, ok := settings[key].(map[string]any); ok {
		for field, value := range stored {
			if _, supported := writableSettingSchemas[key][field]; supported {
				effective[field] = value
			}
		}
	}
	left, leftErr := json.Marshal(effective)
	right, rightErr := json.Marshal(definition.Defaults)
	return leftErr != nil || rightErr != nil || !bytes.Equal(left, right)
}

func boolStatus(value bool, trueStatus, falseStatus string) string {
	if value {
		return trueStatus
	}
	return falseStatus
}

func (s *Server) applyMetadataAgentSecrets(tx *sql.Tx, raw json.RawMessage, now string) (json.RawMessage, error) {
	var group map[string]any
	if err := json.Unmarshal(raw, &group); err != nil {
		return nil, err
	}
	if err := s.applySecretChangeField(tx, group, "tmdbReadAccessToken", tmdbReadAccessTokenSettingKey, now); err != nil {
		return nil, err
	}
	if err := s.applySecretChangeField(tx, group, "tmdbAPIKey", tmdbAPIKeySettingKey, now); err != nil {
		return nil, err
	}
	if err := s.applySecretChangeField(tx, group, "tvdbAPIKey", tvdbAPIKeySettingKey, now); err != nil {
		return nil, err
	}
	delete(group, "tmdbReadAccessToken")
	delete(group, "tmdbAPIKey")
	delete(group, "tvdbAPIKey")
	return json.Marshal(group)
}

func (s *Server) applySecretChangeField(tx *sql.Tx, group map[string]any, fieldKey, settingKey, now string) error {
	raw, exists := group[fieldKey]
	if !exists {
		return nil
	}
	change, ok := raw.(map[string]any)
	if !ok {
		return fmt.Errorf("metadataAgents.%s must be a secret change object", fieldKey)
	}
	for key := range change {
		if key != "replacement" && key != "remove" {
			return fmt.Errorf("metadataAgents.%s.%s is not supported", fieldKey, key)
		}
	}
	remove, _ := change["remove"].(bool)
	if rawRemove, exists := change["remove"]; exists {
		if _, ok := rawRemove.(bool); !ok {
			return fmt.Errorf("metadataAgents.%s.remove must be a boolean", fieldKey)
		}
	}
	replacement := ""
	if rawReplacement, exists := change["replacement"]; exists {
		value, ok := rawReplacement.(string)
		if !ok {
			return fmt.Errorf("metadataAgents.%s.replacement must be a string", fieldKey)
		}
		replacement = strings.TrimSpace(value)
		if replacement == "" {
			return fmt.Errorf("metadataAgents.%s.replacement must not be blank", fieldKey)
		}
	}
	if remove && replacement != "" {
		return fmt.Errorf("metadataAgents.%s cannot replace and remove a secret in the same change", fieldKey)
	}
	if remove {
		_, err := tx.Exec(`DELETE FROM settings WHERE key = ?`, settingKey)
		return err
	}
	if replacement == "" {
		return nil
	}
	bytes, err := s.encryptRemoteSecret(replacement)
	if err != nil {
		return err
	}
	_, err = tx.Exec(`INSERT INTO settings (key, value_json, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET value_json = excluded.value_json, updated_at = excluded.updated_at`, settingKey, string(bytes), now)
	return err
}

func (s *Server) systemIdentity() (SystemIdentityResponse, error) {
	return s.systemIdentityContext(context.Background())
}

func (s *Server) systemIdentityContext(ctx context.Context) (SystemIdentityResponse, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	settings, err := s.loadSettingsContext(ctx)
	if err != nil {
		return SystemIdentityResponse{}, err
	}
	serverIdentity, err := s.loadOrCreateServerIdentity()
	if err != nil {
		return SystemIdentityResponse{}, err
	}
	serverID, err := s.localServerIDContext(ctx, settings)
	if err != nil {
		return SystemIdentityResponse{}, err
	}
	friendlyName := serverFriendlyNameFromSettings(settings)
	return SystemIdentityResponse{
		ServerID:             serverID,
		FriendlyName:         friendlyName,
		Claimed:              remoteAccessClaimed(settings),
		PublicKeyFingerprint: serverIdentity.Fingerprint,
		TrustModel: []string{
			"Stable local server ID",
			"Persistent local Ed25519 server identity",
			"Portico claim identity and certificate-pinned remote clients",
		},
		Placeholder: false,
		Note:        "Server identity is generated and stored locally. Portico claims and certificate-pinned remote clients use this public key fingerprint.",
	}, nil
}

func remoteAccessClaimed(settings map[string]any) bool {
	group, _ := settings[remoteAccessSettingsKey].(map[string]any)
	serverID, _ := group["serverId"].(string)
	claimStatus, _ := group["claimStatus"].(string)
	return strings.TrimSpace(serverID) != "" && claimStatus == "claimed"
}

func defaultUserPreferences() UserPreferences {
	return UserPreferences{
		Locale:           "en-US",
		TimeZone:         "UTC",
		DateFormat:       "medium",
		HourCycle:        "auto",
		AudioLanguage:    "en",
		SubtitleLanguage: "en",
		SidebarOrder:     []string{},
		MusicPlayback:    defaultMusicPlaybackPreferences(),
		PlaybackProgress: defaultPlaybackProgressPreferences(),
		Privacy:          defaultUserPrivacyPreferences(),
	}
}

func defaultMusicPlaybackPreferences() MusicPlaybackPreferences {
	return MusicPlaybackPreferences{
		ShuffleDefault:    false,
		RepeatDefault:     "none",
		AutoplayDefault:   true,
		NormalizationMode: "off",
		CrossfadeSeconds:  0,
		Gapless:           true,
	}
}

func defaultPlaybackProgressPreferences() PlaybackProgressPreferences {
	return PlaybackProgressPreferences{
		StartedThresholdPercent: 5,
		PlayedThresholdPercent:  95,
	}
}

func defaultUserPrivacyPreferences() UserPrivacyPreferences {
	return UserPrivacyPreferences{
		PauseWatchHistory:         false,
		ShowActivityToMembers:     true,
		IncludeInWatchWithFriends: true,
	}
}

func decodeUserPreferences(raw string) UserPreferences {
	preferences := defaultUserPreferences()
	if strings.TrimSpace(raw) == "" {
		return preferences
	}
	var decoded struct {
		Locale           string                       `json:"locale"`
		TimeZone         string                       `json:"timeZone"`
		DateFormat       string                       `json:"dateFormat"`
		HourCycle        string                       `json:"hourCycle"`
		AudioLanguage    string                       `json:"audioLanguage"`
		SubtitleLanguage string                       `json:"subtitleLanguage"`
		SidebarOrder     []string                     `json:"sidebarOrder"`
		MusicPlayback    *MusicPlaybackPreferences    `json:"musicPlayback"`
		PlaybackProgress *PlaybackProgressPreferences `json:"playbackProgress"`
		Privacy          *UserPrivacyPreferences      `json:"privacy"`
	}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return preferences
	}
	if decoded.Locale != "" {
		preferences.Locale = decoded.Locale
	}
	if decoded.TimeZone != "" {
		preferences.TimeZone = decoded.TimeZone
	}
	if decoded.DateFormat != "" {
		preferences.DateFormat = decoded.DateFormat
	}
	if decoded.HourCycle != "" {
		preferences.HourCycle = decoded.HourCycle
	}
	if decoded.AudioLanguage != "" {
		preferences.AudioLanguage = decoded.AudioLanguage
	}
	if decoded.SubtitleLanguage != "" {
		preferences.SubtitleLanguage = decoded.SubtitleLanguage
	}
	preferences.SidebarOrder = normalizeSidebarOrder(decoded.SidebarOrder)
	if decoded.MusicPlayback != nil {
		preferences.MusicPlayback = normalizeMusicPlaybackPreferences(*decoded.MusicPlayback)
	}
	if decoded.PlaybackProgress != nil {
		preferences.PlaybackProgress = normalizePlaybackProgressPreferences(*decoded.PlaybackProgress)
	}
	if decoded.Privacy != nil {
		preferences.Privacy = normalizeUserPrivacyPreferences(*decoded.Privacy)
	}
	return preferences
}

func normalizeMusicPlaybackPreferences(input MusicPlaybackPreferences) MusicPlaybackPreferences {
	preferences := defaultMusicPlaybackPreferences()
	preferences.ShuffleDefault = input.ShuffleDefault
	repeatMode := strings.ToLower(strings.TrimSpace(input.RepeatDefault))
	if stringIn(repeatMode, []string{"none", "one", "all"}) {
		preferences.RepeatDefault = repeatMode
	}
	preferences.AutoplayDefault = input.AutoplayDefault
	normalization := strings.ToLower(strings.TrimSpace(input.NormalizationMode))
	if normalization == "attenuate" {
		preferences.NormalizationMode = "attenuate"
	}
	preferences.CrossfadeSeconds = min(12, max(0, input.CrossfadeSeconds))
	preferences.Gapless = input.Gapless
	if preferences.CrossfadeSeconds > 0 {
		preferences.Gapless = true
	}
	return preferences
}

func normalizePlaybackProgressPreferences(input PlaybackProgressPreferences) PlaybackProgressPreferences {
	preferences := defaultPlaybackProgressPreferences()
	if input.StartedThresholdPercent > 0 {
		preferences.StartedThresholdPercent = min(50, max(0, input.StartedThresholdPercent))
	}
	if input.PlayedThresholdPercent > 0 {
		preferences.PlayedThresholdPercent = min(100, max(50, input.PlayedThresholdPercent))
	}
	if preferences.PlayedThresholdPercent <= preferences.StartedThresholdPercent {
		preferences.PlayedThresholdPercent = min(100, preferences.StartedThresholdPercent+1)
	}
	return preferences
}

func normalizeUserPrivacyPreferences(input UserPrivacyPreferences) UserPrivacyPreferences {
	return UserPrivacyPreferences{
		PauseWatchHistory:         input.PauseWatchHistory,
		ShowActivityToMembers:     input.ShowActivityToMembers,
		IncludeInWatchWithFriends: input.IncludeInWatchWithFriends,
	}
}

func isEmptyMusicPlaybackPreferences(input MusicPlaybackPreferences) bool {
	return !input.ShuffleDefault &&
		input.RepeatDefault == "" &&
		!input.AutoplayDefault &&
		input.NormalizationMode == "" &&
		input.CrossfadeSeconds == 0 &&
		!input.Gapless
}

func isEmptyPlaybackProgressPreferences(input PlaybackProgressPreferences) bool {
	return input.StartedThresholdPercent == 0 && input.PlayedThresholdPercent == 0
}

func applyStoredUserPreferences(user *User, raw string) {
	if user == nil {
		return
	}
	user.Preferences = decodeUserPreferences(raw)
	user.AccessSchedule = decodeUserAccessSchedule(raw)
	user.TagPolicy = decodeUserTagPolicy(raw)
	user.DevicePolicy = decodeUserDevicePolicy(raw)
	user.ChannelPolicy = decodeUserChannelPolicy(raw)
}

func decodeUserAccessSchedule(raw string) UserAccessSchedule {
	if strings.TrimSpace(raw) == "" {
		return UserAccessSchedule{}
	}
	var decoded struct {
		AccessSchedule UserAccessSchedule `json:"accessSchedule"`
	}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return UserAccessSchedule{}
	}
	return normalizeUserAccessSchedule(decoded.AccessSchedule)
}

func decodeUserTagPolicy(raw string) UserTagPolicy {
	if strings.TrimSpace(raw) == "" {
		return UserTagPolicy{}
	}
	var decoded struct {
		TagPolicy UserTagPolicy `json:"tagPolicy"`
	}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return UserTagPolicy{}
	}
	return normalizeUserTagPolicy(decoded.TagPolicy)
}

func decodeUserDevicePolicy(raw string) UserDevicePolicy {
	if strings.TrimSpace(raw) == "" {
		return normalizeUserDevicePolicy(UserDevicePolicy{})
	}
	var decoded struct {
		DevicePolicy UserDevicePolicy `json:"devicePolicy"`
	}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return normalizeUserDevicePolicy(UserDevicePolicy{})
	}
	return normalizeUserDevicePolicy(decoded.DevicePolicy)
}

func decodeUserChannelPolicy(raw string) UserChannelPolicy {
	if strings.TrimSpace(raw) == "" {
		return UserChannelPolicy{}
	}
	var decoded struct {
		ChannelPolicy UserChannelPolicy `json:"channelPolicy"`
	}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return UserChannelPolicy{}
	}
	return normalizeUserChannelPolicy(decoded.ChannelPolicy)
}

func marshalUserPreferencesWithPolicies(preferences UserPreferences, schedule UserAccessSchedule, tagPolicy UserTagPolicy, devicePolicy UserDevicePolicy, channelPolicy UserChannelPolicy) ([]byte, error) {
	payload := map[string]any{}
	base, err := json.Marshal(preferences)
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(base, &payload); err != nil {
		return nil, err
	}
	payload["accessSchedule"] = normalizeUserAccessSchedule(schedule)
	payload["tagPolicy"] = normalizeUserTagPolicy(tagPolicy)
	payload["devicePolicy"] = normalizeUserDevicePolicy(devicePolicy)
	payload["channelPolicy"] = normalizeUserChannelPolicy(channelPolicy)
	return json.Marshal(payload)
}

func normalizeUserAccessSchedule(schedule UserAccessSchedule) UserAccessSchedule {
	normalized := UserAccessSchedule{
		Enabled:     schedule.Enabled,
		StartMinute: clampMinuteOfDay(schedule.StartMinute),
		EndMinute:   clampMinuteOfDay(schedule.EndMinute),
	}
	seen := map[int]bool{}
	for _, day := range schedule.Days {
		if day < 0 || day > 6 || seen[day] {
			continue
		}
		seen[day] = true
		normalized.Days = append(normalized.Days, day)
	}
	sort.Ints(normalized.Days)
	if !normalized.Enabled {
		normalized.Days = nil
		normalized.StartMinute = 0
		normalized.EndMinute = 0
	}
	return normalized
}

func clampMinuteOfDay(value int) int {
	if value < 0 {
		return 0
	}
	if value > 1439 {
		return 1439
	}
	return value
}

func userAccessScheduleAllows(schedule UserAccessSchedule, now time.Time) bool {
	schedule = normalizeUserAccessSchedule(schedule)
	if !schedule.Enabled {
		return true
	}
	minute := now.UTC().Hour()*60 + now.UTC().Minute()
	if schedule.StartMinute == schedule.EndMinute {
		return accessScheduleDayAllowed(schedule.Days, int(now.UTC().Weekday()))
	}
	if schedule.StartMinute < schedule.EndMinute {
		return minute >= schedule.StartMinute && minute < schedule.EndMinute && accessScheduleDayAllowed(schedule.Days, int(now.UTC().Weekday()))
	}
	if minute >= schedule.StartMinute {
		return accessScheduleDayAllowed(schedule.Days, int(now.UTC().Weekday()))
	}
	if minute < schedule.EndMinute {
		previousDay := (int(now.UTC().Weekday()) + 6) % 7
		return accessScheduleDayAllowed(schedule.Days, previousDay)
	}
	return false
}

func accessScheduleDayAllowed(days []int, weekday int) bool {
	if len(days) == 0 {
		return true
	}
	for _, day := range days {
		if day == weekday {
			return true
		}
	}
	return false
}

func normalizeUserTagPolicy(policy UserTagPolicy) UserTagPolicy {
	return UserTagPolicy{
		AllowedTags:   normalizePolicyTagList(policy.AllowedTags),
		BlockedTags:   normalizePolicyTagList(policy.BlockedTags),
		AllowedLabels: normalizePolicyTagList(policy.AllowedLabels),
		BlockedLabels: normalizePolicyTagList(policy.BlockedLabels),
	}
}

func normalizePolicyTagList(input []string) []string {
	if len(input) == 0 {
		return nil
	}
	seen := map[string]bool{}
	out := make([]string, 0, min(len(input), 64))
	for _, raw := range input {
		value := strings.ToLower(strings.TrimSpace(raw))
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
		if len(out) >= 64 {
			break
		}
	}
	sort.Strings(out)
	return out
}

func normalizeUserDevicePolicy(policy UserDevicePolicy) UserDevicePolicy {
	mode := strings.ToLower(strings.TrimSpace(policy.Mode))
	switch mode {
	case "trusted", "allowlist":
	default:
		mode = "any"
	}
	normalized := UserDevicePolicy{Mode: mode}
	if mode == "allowlist" {
		normalized.AllowedDeviceIDs = normalizePolicyIDList(policy.AllowedDeviceIDs)
	}
	return normalized
}

func normalizeUserChannelPolicy(policy UserChannelPolicy) UserChannelPolicy {
	return UserChannelPolicy{
		AllowedChannelIDs: normalizePolicyIDList(policy.AllowedChannelIDs),
		BlockedChannelIDs: normalizePolicyIDList(policy.BlockedChannelIDs),
	}
}

func normalizePolicyIDList(input []string) []string {
	if len(input) == 0 {
		return nil
	}
	seen := map[string]bool{}
	out := make([]string, 0, min(len(input), 128))
	for _, raw := range input {
		value := strings.TrimSpace(raw)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
		if len(out) >= 128 {
			break
		}
	}
	sort.Strings(out)
	return out
}

func (s *Server) userAccessScheduleAllowsNow(userID string, now time.Time) bool {
	return s.userAccessScheduleAllowsNowContext(context.Background(), userID, now)
}

func (s *Server) userAccessScheduleAllowsNowContext(ctx context.Context, userID string, now time.Time) bool {
	if ctx == nil {
		ctx = context.Background()
	}
	var raw string
	if err := s.queryUserRow(ctx, `SELECT preferences_json FROM users WHERE id = ?`, userID).Scan(&raw); err != nil {
		return false
	}
	return userAccessScheduleAllows(decodeUserAccessSchedule(raw), now)
}

func accountPreferencesRequestFromUserPreferences(preferences UserPreferences) AccountPreferencesRequest {
	privacy := normalizeUserPrivacyPreferences(preferences.Privacy)
	return AccountPreferencesRequest{
		Locale:           preferences.Locale,
		TimeZone:         preferences.TimeZone,
		DateFormat:       preferences.DateFormat,
		HourCycle:        preferences.HourCycle,
		AudioLanguage:    preferences.AudioLanguage,
		SubtitleLanguage: preferences.SubtitleLanguage,
		SidebarOrder:     append([]string(nil), preferences.SidebarOrder...),
		MusicPlayback:    preferences.MusicPlayback,
		PlaybackProgress: preferences.PlaybackProgress,
		Privacy:          &privacy,
	}
}

func validateUserPreferences(req AccountPreferencesRequest) (UserPreferences, error) {
	preferences := defaultUserPreferences()
	if req.Locale != "" {
		if !isSupportedLocale(req.Locale) {
			return UserPreferences{}, fmt.Errorf("locale is not supported")
		}
		preferences.Locale = req.Locale
	}
	if req.TimeZone != "" {
		if _, err := time.LoadLocation(req.TimeZone); err != nil {
			return UserPreferences{}, fmt.Errorf("time zone must be a valid IANA time zone")
		}
		preferences.TimeZone = req.TimeZone
	}
	if req.DateFormat != "" {
		if !stringIn(req.DateFormat, []string{"short", "medium", "long"}) {
			return UserPreferences{}, fmt.Errorf("date format is not supported")
		}
		preferences.DateFormat = req.DateFormat
	}
	if req.HourCycle != "" {
		if !stringIn(req.HourCycle, []string{"auto", "h12", "h23"}) {
			return UserPreferences{}, fmt.Errorf("hour cycle is not supported")
		}
		preferences.HourCycle = req.HourCycle
	}
	if req.AudioLanguage != "" {
		preferences.AudioLanguage = strings.TrimSpace(req.AudioLanguage)
	}
	if req.SubtitleLanguage != "" {
		preferences.SubtitleLanguage = strings.TrimSpace(req.SubtitleLanguage)
	}
	preferences.SidebarOrder = normalizeSidebarOrder(req.SidebarOrder)
	if !isEmptyMusicPlaybackPreferences(req.MusicPlayback) {
		preferences.MusicPlayback = normalizeMusicPlaybackPreferences(req.MusicPlayback)
	}
	if !isEmptyPlaybackProgressPreferences(req.PlaybackProgress) {
		preferences.PlaybackProgress = normalizePlaybackProgressPreferences(req.PlaybackProgress)
	}
	if req.Privacy != nil {
		preferences.Privacy = normalizeUserPrivacyPreferences(*req.Privacy)
	}
	return preferences, nil
}

func displayPreferenceRouteParts(path string) (string, string, bool) {
	rest := strings.TrimPrefix(path, "/api/display-preferences/")
	parts := strings.Split(rest, "/")
	if len(parts) != 2 {
		return "", "", false
	}
	client, err := url.PathUnescape(parts[0])
	if err != nil {
		return "", "", false
	}
	view, err := url.PathUnescape(parts[1])
	if err != nil {
		return "", "", false
	}
	client = normalizeDisplayPreferenceID(client)
	view = normalizeDisplayPreferenceID(view)
	return client, view, client != "" && view != ""
}

func normalizeDisplayPreferenceID(value string) string {
	value = strings.TrimSpace(value)
	if value == "" || len(value) > 128 || strings.ContainsAny(value, `/\`) {
		return ""
	}
	for _, char := range value {
		if char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' || char >= '0' && char <= '9' {
			continue
		}
		switch char {
		case '-', '_', '.', ':':
			continue
		default:
			return ""
		}
	}
	return value
}

func sanitizeDisplayPreferencePayload(input map[string]any) (map[string]any, error) {
	if input == nil {
		input = map[string]any{}
	}
	if len(input) > 50 {
		return nil, fmt.Errorf("display preferences contain too many fields")
	}
	bytes, err := json.Marshal(input)
	if err != nil {
		return nil, fmt.Errorf("display preferences must be valid JSON")
	}
	if len(bytes) > 8192 {
		return nil, fmt.Errorf("display preferences are too large")
	}
	var normalized map[string]any
	if err := json.Unmarshal(bytes, &normalized); err != nil {
		return nil, fmt.Errorf("display preferences must be a JSON object")
	}
	return normalized, nil
}

func (s *Server) displayPreference(profileID string, client string, view string) (DisplayPreference, error) {
	preference := DisplayPreference{
		Client:      client,
		View:        view,
		Preferences: map[string]any{},
	}
	var raw string
	var updatedAt string
	err := s.queryUserRow(context.Background(), `SELECT preferences_json, updated_at FROM user_display_preferences WHERE profile_id = ? AND client = ? AND view = ?`, profileID, client, view).Scan(&raw, &updatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return preference, nil
	}
	if err != nil {
		return DisplayPreference{}, err
	}
	if err := json.Unmarshal([]byte(raw), &preference.Preferences); err != nil {
		preference.Preferences = map[string]any{}
	}
	preference.UpdatedAt = updatedAt
	return preference, nil
}

func (s *Server) saveDisplayPreference(profileID string, client string, view string, preferences map[string]any) (DisplayPreference, error) {
	bytes, err := json.Marshal(preferences)
	if err != nil {
		return DisplayPreference{}, err
	}
	accountID, err := s.accountIDForProfileContext(context.Background(), profileID)
	if err != nil {
		return DisplayPreference{}, err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	_, err = s.execUserWrite(context.Background(), `
		INSERT INTO user_display_preferences (profile_id, user_id, client, view, preferences_json, updated_at)
		VALUES (?, ?, ?, ?, ?, ?)
		ON CONFLICT(profile_id, client, view) DO UPDATE SET
			preferences_json = excluded.preferences_json,
			updated_at = excluded.updated_at`,
		profileID, accountID, client, view, string(bytes), now)
	if err != nil {
		return DisplayPreference{}, err
	}
	return DisplayPreference{Client: client, View: view, Preferences: preferences, UpdatedAt: now}, nil
}

func normalizeSidebarOrder(input []string) []string {
	if len(input) == 0 {
		return []string{}
	}
	seen := make(map[string]bool, len(input))
	order := make([]string, 0, min(len(input), 160))
	for _, raw := range input {
		item := strings.TrimSpace(raw)
		if item == "" || item == "home" || seen[item] || !validSidebarOrderItem(item) {
			continue
		}
		seen[item] = true
		order = append(order, item)
		if len(order) >= 160 {
			break
		}
	}
	return order
}

func validSidebarOrderItem(item string) bool {
	switch item {
	case "watchlist", "playlists", "live", "discover":
		return true
	}
	const prefix = "library:"
	if !strings.HasPrefix(item, prefix) {
		return false
	}
	libraryID := strings.TrimPrefix(item, prefix)
	if libraryID == "" || len(libraryID) > 128 {
		return false
	}
	for _, char := range libraryID {
		if (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || (char >= '0' && char <= '9') || char == '_' || char == '-' {
			continue
		}
		return false
	}
	return true
}

func isSupportedLocale(locale string) bool {
	return stringIn(locale, []string{
		"en-US", "en-CA", "en-GB",
		"es-US", "es-ES", "es-MX",
		"fr-CA", "fr-FR",
		"de-DE", "it-IT",
		"pt-BR", "pt-PT",
		"nl-NL", "pl-PL",
		"sv-SE", "nb-NO", "da-DK",
		"ja-JP",
	})
}

func stringIn(value string, allowed []string) bool {
	for _, candidate := range allowed {
		if value == candidate {
			return true
		}
	}
	return false
}

func (s *Server) listUsers() ([]User, error) {
	where := ""
	if s.porticoAccountMode() {
		where = ` WHERE COALESCE(auth_origin, 'local') = 'portico'`
	}
	rows, err := s.queryUserRead(context.Background(), `SELECT id, username, email, display_name, COALESCE(profile_image_path, ''), COALESCE(profile_image_url, ''), role, COALESCE(auth_origin, 'local'), COALESCE(portico_user_id, ''), COALESCE(portico_membership_id, ''), password_hash IS NOT NULL AND password_hash <> '', permissions_json, preferences_json, COALESCE(max_content_rating, ''), COALESCE(max_active_sessions, 0), COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0) FROM users`+where+` ORDER BY created_at ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var users []User
	for rows.Next() {
		var user User
		var permissionsJSON string
		var preferencesJSON string
		var profileImagePath string
		var profileImageURL string
		if err := rows.Scan(&user.ID, &user.Username, &user.Email, &user.DisplayName, &profileImagePath, &profileImageURL, &user.Role, &user.AuthOrigin, &user.PorticoUserID, &user.PorticoMembershipID, &user.HasLocalPassword, &permissionsJSON, &preferencesJSON, &user.MaxContentRating, &user.MaxActiveSessions, &user.MaxActiveStreams, &user.RemoteBitrateLimitMbps); err != nil {
			return nil, err
		}
		_ = json.Unmarshal([]byte(permissionsJSON), &user.Permissions)
		applyStoredUserPreferences(&user, preferencesJSON)
		user.ProfileImageURL = profileImageURLForPath(profileImagePath, profileImageURL)
		users = append(users, user)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if err := s.attachUserLibraryIDs(users); err != nil {
		return nil, err
	}
	for index := range users {
		s.enrichUserAuthContext(&users[index], "")
	}
	return users, nil
}

func (s *Server) attachUserLibraryIDs(users []User) error {
	return s.attachUserLibraryIDsContext(context.Background(), users)
}

func (s *Server) attachUserLibraryIDsContext(ctx context.Context, users []User) error {
	if ctx == nil {
		ctx = context.Background()
	}
	libraries, err := s.libraryIDSetContext(ctx)
	if err != nil {
		return err
	}
	rows, err := s.queryUserRead(ctx, `SELECT user_id, library_id FROM user_library_access ORDER BY library_id ASC`)
	if err != nil {
		return err
	}
	defer rows.Close()
	access := map[string][]string{}
	for rows.Next() {
		var userID, libraryID string
		if err := rows.Scan(&userID, &libraryID); err != nil {
			return err
		}
		access[userID] = append(access[userID], libraryID)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	allIDs := make([]string, 0, len(libraries))
	for id := range libraries {
		allIDs = append(allIDs, id)
	}
	sort.Strings(allIDs)
	for index := range users {
		if users[index].Role == "owner" {
			users[index].LibraryIDs = append([]string(nil), allIDs...)
			continue
		}
		users[index].LibraryIDs = append([]string(nil), access[users[index].ID]...)
	}
	return nil
}

func (s *Server) populateUserLibraryIDs(user *User) {
	s.populateUserLibraryIDsContext(context.Background(), user)
}

func (s *Server) populateUserLibraryIDsContext(ctx context.Context, user *User) {
	if user == nil {
		return
	}
	users := []User{*user}
	if err := s.attachUserLibraryIDsContext(ctx, users); err != nil {
		s.log.Warn("attach user library access failed", "user", user.ID, "error", err)
		return
	}
	user.LibraryIDs = users[0].LibraryIDs
}

func (s *Server) getUser(userID string) (User, error) {
	row := s.queryUserRow(context.Background(), `SELECT id, username, email, display_name, COALESCE(profile_image_path, ''), COALESCE(profile_image_url, ''), role, COALESCE(auth_origin, 'local'), COALESCE(portico_user_id, ''), COALESCE(portico_membership_id, ''), password_hash IS NOT NULL AND password_hash <> '', permissions_json, preferences_json, COALESCE(max_content_rating, ''), COALESCE(max_active_sessions, 0), COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0) FROM users WHERE id = ?`, userID)
	var user User
	var permissionsJSON string
	var preferencesJSON string
	var profileImagePath string
	var profileImageURL string
	if err := row.Scan(&user.ID, &user.Username, &user.Email, &user.DisplayName, &profileImagePath, &profileImageURL, &user.Role, &user.AuthOrigin, &user.PorticoUserID, &user.PorticoMembershipID, &user.HasLocalPassword, &permissionsJSON, &preferencesJSON, &user.MaxContentRating, &user.MaxActiveSessions, &user.MaxActiveStreams, &user.RemoteBitrateLimitMbps); err != nil {
		return User{}, err
	}
	_ = json.Unmarshal([]byte(permissionsJSON), &user.Permissions)
	applyStoredUserPreferences(&user, preferencesJSON)
	user.ProfileImageURL = profileImageURLForPath(profileImagePath, profileImageURL)
	users := []User{user}
	if err := s.attachUserLibraryIDs(users); err != nil {
		return User{}, err
	}
	user = users[0]
	s.enrichUserAuthContext(&user, "")
	return user, nil
}

func (s *Server) createUser(req UserRequest) (User, error) {
	return s.createUserContext(context.Background(), req)
}

func (s *Server) createUserContext(ctx context.Context, req UserRequest) (User, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	req.Email = strings.ToLower(strings.TrimSpace(req.Email))
	req.Username = normalizeUsername(req.Username)
	req.DisplayName = strings.TrimSpace(req.DisplayName)
	role := normalizeUserRole(req.Role)
	if role == "" {
		role = "user"
	}
	if role == "owner" {
		return User{}, errors.New("only the setup flow can create the server owner")
	}
	if err := validateUserGrantablePermissions(req.Permissions); err != nil {
		return User{}, err
	}
	maxContentRating := ""
	if role == "user" {
		maxContentRating = normalizeMaxContentRating(req.MaxContentRating)
	}
	maxActiveSessions := normalizeMaxActiveSessions(req.MaxActiveSessions)
	maxActiveStreams := normalizeMaxActiveStreams(req.MaxActiveStreams)
	remoteBitrateLimitMbps := normalizeRemoteBitrateLimitMbps(req.RemoteBitrateLimitMbps)
	accessSchedule := normalizeUserAccessSchedule(req.AccessSchedule)
	if req.Username == "" && req.Email != "" {
		req.Username = normalizeUsername(strings.Split(req.Email, "@")[0])
	}
	if req.Username == "" {
		return User{}, errors.New("username must be 3 to 32 letters, numbers, dots, dashes, or underscores")
	}
	if !strings.Contains(req.Email, "@") {
		return User{}, errors.New("enter a valid email address")
	}
	if len(req.DisplayName) < 2 {
		return User{}, errors.New("display name must be at least two characters")
	}
	if !validAccountPassword(req.Password) {
		return User{}, errors.New(strings.ToLower(accountPasswordPolicyMessage))
	}
	libraryIDs, err := s.cleanLibraryIDs(req.LibraryIDs)
	if err != nil {
		return User{}, err
	}
	passwordHash, err := hashAccountPassword(ctx, kdfUserCreateHash, req.Password)
	if err != nil {
		return User{}, err
	}
	permissions := permissionsForRole(role)
	if len(req.Permissions) > 0 {
		permissions = sanitizePermissions(req.Permissions, role)
	}
	now := time.Now().UTC().Format(time.RFC3339)
	permissionsJSON, _ := json.Marshal(permissions)
	preferences := defaultUserPreferences()
	tagPolicy := normalizeUserTagPolicy(req.TagPolicy)
	devicePolicy := normalizeUserDevicePolicy(req.DevicePolicy)
	channelPolicy := normalizeUserChannelPolicy(req.ChannelPolicy)
	preferencesJSON, _ := marshalUserPreferencesWithPolicies(preferences, accessSchedule, tagPolicy, devicePolicy, channelPolicy)
	user := User{
		ID:                     randomID("usr"),
		Username:               req.Username,
		Email:                  req.Email,
		DisplayName:            req.DisplayName,
		Role:                   role,
		AuthOrigin:             "local",
		HasLocalPassword:       true,
		Permissions:            permissions,
		LibraryIDs:             libraryIDs,
		Preferences:            preferences,
		AccessSchedule:         accessSchedule,
		TagPolicy:              tagPolicy,
		DevicePolicy:           devicePolicy,
		ChannelPolicy:          channelPolicy,
		MaxContentRating:       maxContentRating,
		MaxActiveSessions:      maxActiveSessions,
		MaxActiveStreams:       maxActiveStreams,
		RemoteBitrateLimitMbps: remoteBitrateLimitMbps,
	}
	if err := s.withSecurityFenceTxTagged(ctx, []string{"users", "account", "profiles", "libraries", "home"}, func(tx *sql.Tx) error {
		if _, err := tx.Exec(`INSERT INTO users (id, username, email, display_name, password_hash, role, auth_origin, permissions_json, preferences_json, max_content_rating, max_active_sessions, max_active_streams, remote_bitrate_limit_mbps, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			user.ID, user.Username, user.Email, user.DisplayName, passwordHash, user.Role, user.AuthOrigin, string(permissionsJSON), string(preferencesJSON), user.MaxContentRating, user.MaxActiveSessions, user.MaxActiveStreams, user.RemoteBitrateLimitMbps, now, now); err != nil {
			return err
		}
		return replaceUserLibraries(tx, user.ID, libraryIDs, now)
	}); err != nil {
		return User{}, err
	}
	if seedErr := s.seedUserMediaState(user.ID); seedErr != nil {
		s.log.Warn("seed user media state failed", "error", seedErr)
	}
	s.enrichUserAuthContext(&user, "local")
	return user, nil
}

func (s *Server) updateUser(userID string, req UserPatchRequest) (User, error) {
	return s.updateUserContext(context.Background(), userID, req)
}

func (s *Server) updateUserContext(ctx context.Context, userID string, req UserPatchRequest) (User, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var libraryIDs []string
	var err error
	if req.LibraryIDs != nil {
		libraryIDs, err = s.cleanLibraryIDs(*req.LibraryIDs)
		if err != nil {
			return User{}, invalidRequestField("libraryIds", err.Error())
		}
	}
	var replacementPermissions map[string]bool
	if req.Permissions != nil {
		if err := validateUserGrantablePermissions(*req.Permissions); err != nil {
			return User{}, invalidRequestField("permissions", err.Error())
		}
		replacementPermissions = sanitizePermissions(*req.Permissions, "user")
	}
	passwordHash := ""
	if req.Password != nil {
		if !validAccountPassword(*req.Password) {
			return User{}, invalidRequestField("password", strings.ToLower(accountPasswordPolicyMessage))
		}
		passwordHash, err = hashAccountPassword(ctx, kdfUserUpdateHash, *req.Password)
		if err != nil {
			return User{}, err
		}
	}
	now := time.Now().UTC().Format(time.RFC3339Nano)
	authorityChanged := req.Password != nil || req.Permissions != nil || req.LibraryIDs != nil ||
		req.AccessSchedule != nil || req.TagPolicy != nil || req.DevicePolicy != nil || req.ChannelPolicy != nil ||
		req.MaxContentRating != nil || req.MaxActiveSessions != nil || req.MaxActiveStreams != nil || req.RemoteBitrateLimitMbps != nil
	if err := s.withUserTxTagged(ctx, []string{"users", "account", "profiles", "libraries", "home"}, func(tx *sql.Tx) error {
		var current User
		var permissionsJSON, preferencesJSON string
		if err := tx.QueryRowContext(ctx, `
			SELECT username, email, display_name, role, permissions_json, preferences_json,
			       COALESCE(max_content_rating, ''), COALESCE(max_active_sessions, 0),
			       COALESCE(max_active_streams, 0), COALESCE(remote_bitrate_limit_mbps, 0)
			FROM users WHERE id = ?`, userID).Scan(
			&current.Username, &current.Email, &current.DisplayName, &current.Role, &permissionsJSON, &preferencesJSON,
			&current.MaxContentRating, &current.MaxActiveSessions, &current.MaxActiveStreams, &current.RemoteBitrateLimitMbps); err != nil {
			return err
		}
		if current.Role == "owner" {
			return errors.New("the server owner is not a valid general user target")
		}
		_ = json.Unmarshal([]byte(permissionsJSON), &current.Permissions)
		applyStoredUserPreferences(&current, preferencesJSON)

		username, email, displayName := current.Username, current.Email, current.DisplayName
		if req.Username != nil {
			username = normalizeUsername(*req.Username)
		}
		if req.Email != nil {
			email = strings.ToLower(strings.TrimSpace(*req.Email))
		}
		if req.DisplayName != nil {
			displayName = strings.TrimSpace(*req.DisplayName)
		}
		if username == "" {
			return invalidRequestField("username", "username must be 3 to 32 letters, numbers, dots, dashes, or underscores")
		}
		if !validAccountEmail(email) {
			return invalidRequestField("email", "enter a valid email address")
		}
		if length := len([]rune(displayName)); length < 2 || length > 80 {
			return invalidRequestField("displayName", "display name must be 2 to 80 characters")
		}
		if err := validateUserPatchPolicyFields(req); err != nil {
			return err
		}

		permissions := current.Permissions
		if req.Permissions != nil {
			permissions = replacementPermissions
		}
		accessSchedule, tagPolicy := current.AccessSchedule, current.TagPolicy
		devicePolicy, channelPolicy := current.DevicePolicy, current.ChannelPolicy
		if req.AccessSchedule != nil {
			accessSchedule = normalizeUserAccessSchedule(*req.AccessSchedule)
		}
		if req.TagPolicy != nil {
			tagPolicy = normalizeUserTagPolicy(*req.TagPolicy)
		}
		if req.DevicePolicy != nil {
			devicePolicy = normalizeUserDevicePolicy(*req.DevicePolicy)
		}
		if req.ChannelPolicy != nil {
			channelPolicy = normalizeUserChannelPolicy(*req.ChannelPolicy)
		}
		encodedPermissions, _ := json.Marshal(permissions)
		encodedPreferences, err := marshalUserPreferencesWithPolicies(current.Preferences, accessSchedule, tagPolicy, devicePolicy, channelPolicy)
		if err != nil {
			return err
		}
		maxContentRating := current.MaxContentRating
		if req.MaxContentRating != nil {
			maxContentRating = normalizeMaxContentRating(*req.MaxContentRating)
		}
		maxActiveSessions := current.MaxActiveSessions
		if req.MaxActiveSessions != nil {
			maxActiveSessions = normalizeMaxActiveSessions(*req.MaxActiveSessions)
		}
		maxActiveStreams := current.MaxActiveStreams
		if req.MaxActiveStreams != nil {
			maxActiveStreams = normalizeMaxActiveStreams(*req.MaxActiveStreams)
		}
		remoteBitrateLimitMbps := current.RemoteBitrateLimitMbps
		if req.RemoteBitrateLimitMbps != nil {
			remoteBitrateLimitMbps = normalizeRemoteBitrateLimitMbps(*req.RemoteBitrateLimitMbps)
		}
		query := `UPDATE users SET username = ?, email = ?, display_name = ?, role = 'user', permissions_json = ?, preferences_json = ?, max_content_rating = ?, max_active_sessions = ?, max_active_streams = ?, remote_bitrate_limit_mbps = ?, updated_at = ?`
		args := []any{username, email, displayName, string(encodedPermissions), string(encodedPreferences), maxContentRating, maxActiveSessions, maxActiveStreams, remoteBitrateLimitMbps, now}
		if req.Password != nil {
			query += `, password_hash = ?`
			args = append(args, passwordHash)
		}
		query += ` WHERE id = ? AND role = 'user'`
		args = append(args, userID)
		result, err := tx.ExecContext(ctx, query, args...)
		if err != nil {
			return err
		}
		if rowsAffected(result) != 1 {
			return sql.ErrNoRows
		}
		if authorityChanged {
			if err := s.revokeAccountPolicyCredentialsTx(ctx, tx, userID, now); err != nil {
				return err
			}
		}
		if req.LibraryIDs != nil {
			return replaceUserLibraries(tx, userID, libraryIDs, now)
		}
		return nil
	}); err != nil {
		return User{}, err
	}
	return s.getUser(userID)
}

func (s *Server) deleteUser(userID string) (User, error) {
	return s.deleteUserContext(context.Background(), userID)
}

func (s *Server) deleteUserContext(ctx context.Context, userID string) (User, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	user, err := s.getUser(userID)
	if err != nil {
		return User{}, err
	}
	if user.Role == "owner" {
		return User{}, errors.New("the server owner cannot be deleted")
	}
	fences, err := s.beginAccountRuntimeErasureContext(ctx, userID)
	if err != nil {
		return User{}, err
	}
	defer finishProfileErasureFences(fences)
	now := time.Now().UTC().Format(time.RFC3339Nano)
	if err := s.withSecurityFenceTxTagged(ctx, []string{"users", "account", "profiles", "sessions", "native_refresh_tokens", "api_keys", "devices", "libraries", "home"}, func(tx *sql.Tx) error {
		if err := s.revokeAccountAuthorityTx(ctx, tx, userID, now); err != nil {
			return err
		}
		result, err := tx.Exec(`DELETE FROM users WHERE id = ? AND role = 'user'`, userID)
		if err != nil {
			return err
		}
		if affected, err := result.RowsAffected(); err == nil && affected == 0 {
			return sql.ErrNoRows
		}
		return nil
	}); err != nil {
		return User{}, err
	}
	return user, nil
}

func (s *Server) libraryIDSet() (map[string]bool, error) {
	return s.libraryIDSetContext(context.Background())
}

func (s *Server) libraryIDSetContext(ctx context.Context) (map[string]bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	rows, err := s.queryUserRead(ctx, `SELECT id FROM libraries ORDER BY sort_order ASC, name ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	ids := map[string]bool{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids[id] = true
	}
	return ids, rows.Err()
}

func (s *Server) cleanLibraryIDs(input []string) ([]string, error) {
	valid, err := s.libraryIDSet()
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	clean := []string{}
	for _, raw := range input {
		id := strings.TrimSpace(raw)
		if id == "" || seen[id] {
			continue
		}
		if !valid[id] {
			return nil, fmt.Errorf("library %s does not exist", id)
		}
		seen[id] = true
		clean = append(clean, id)
	}
	return clean, nil
}

func replaceUserLibraries(tx *sql.Tx, userID string, libraryIDs []string, now string) error {
	if _, err := tx.Exec(`DELETE FROM user_library_access WHERE user_id = ?`, userID); err != nil {
		return err
	}
	for _, libraryID := range libraryIDs {
		if _, err := tx.Exec(`INSERT INTO user_library_access (user_id, library_id, created_at) VALUES (?, ?, ?) ON CONFLICT(user_id, library_id) DO NOTHING`,
			userID, libraryID, now); err != nil {
			return err
		}
		if _, err := tx.Exec(`
			INSERT INTO user_library_navigation (profile_id, user_id, library_id, pinned, sort_order, created_at, updated_at)
			VALUES (?, ?, ?, 1, (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM user_library_navigation WHERE profile_id = ?), ?, ?)
			ON CONFLICT(profile_id, library_id) DO NOTHING`, userID, userID, libraryID, userID, now, now); err != nil {
			return err
		}
	}
	return nil
}

func imageSetFor(id, artSeed, title string, artwork map[string]string) ImageSet {
	versionSeed := artworkRenderVersion + id + artSeed + title
	if len(artwork) > 0 {
		if bytes, err := json.Marshal(artwork); err == nil {
			versionSeed += string(bytes)
		}
	}
	version := "2"
	if versionSeed != "" {
		sum := sha256.Sum256([]byte(versionSeed))
		version = hex.EncodeToString(sum[:4])
	}
	return ImageSet{
		Poster:   "/api/artwork/" + id + "/poster.svg?v=" + version,
		Backdrop: "/api/artwork/" + id + "/backdrop.svg?v=" + version,
		Thumb:    "/api/artwork/" + id + "/thumb.svg?v=" + version,
	}
}

func (s *Server) applyTVBackdropFallbacks(item *MediaItem) {
	s.applyTVBackdropFallbacksContext(context.Background(), item)
}

func (s *Server) applyTVBackdropFallbacksContext(ctx context.Context, item *MediaItem) {
	if ctx == nil {
		ctx = context.Background()
	}
	if item == nil || item.Images.Backdrop == "" || s.mediaHasArtworkCandidateContext(ctx, item.ID, "backdrop") {
		return
	}
	for _, fallbackID := range s.tvBackdropFallbackIDsContext(ctx, *item) {
		if fallbackID == "" || !s.mediaHasArtworkCandidateContext(ctx, fallbackID, "backdrop") {
			continue
		}
		seed := s.mediaArtworkVersionSeedContext(ctx, fallbackID, "backdrop")
		if seed == "" {
			continue
		}
		sum := sha256.Sum256([]byte(seed))
		if item.DisplayImages == nil {
			item.DisplayImages = &DisplayImageSet{}
		}
		item.DisplayImages.Backdrop = "/api/artwork/" + url.PathEscape(fallbackID) + "/backdrop.svg?v=" + hex.EncodeToString(sum[:4])
		return
	}
}

func (s *Server) tvBackdropFallbackIDs(item MediaItem) []string {
	return s.tvBackdropFallbackIDsContext(context.Background(), item)
}

func (s *Server) tvBackdropFallbackIDsContext(ctx context.Context, item MediaItem) []string {
	switch item.Type {
	case "season":
		return []string{strings.TrimSpace(item.ParentID)}
	case "episode":
		seasonID := strings.TrimSpace(item.ParentID)
		showID := strings.TrimSpace(item.GrandparentID)
		if showID == "" && seasonID != "" {
			if ctx == nil {
				ctx = context.Background()
			}
			_ = s.queryUserRow(ctx, `SELECT COALESCE(parent_id, '') FROM media_items WHERE id = ?`, seasonID).Scan(&showID)
		}
		return []string{seasonID, strings.TrimSpace(showID)}
	default:
		return nil
	}
}

func (s *Server) mediaArtworkVersionSeed(mediaID string, kind string) string {
	return s.mediaArtworkVersionSeedContext(context.Background(), mediaID, kind)
}

func (s *Server) mediaArtworkVersionSeedContext(ctx context.Context, mediaID string, kind string) string {
	mediaID = strings.TrimSpace(mediaID)
	kind = strings.TrimSpace(kind)
	if mediaID == "" || kind == "" {
		return ""
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var id, artSeed, title, artworkJSON string
	if err := s.queryUserRow(ctx, `
		SELECT id, COALESCE(art_seed, ''), title, COALESCE(artwork_json, '{}')
		FROM media_items
		WHERE id = ?`, mediaID).Scan(&id, &artSeed, &title, &artworkJSON); err != nil {
		return ""
	}
	seed := strings.Join([]string{id, artSeed, title, artworkJSON}, "\x00")
	rows, err := s.queryUserRead(ctx, `
		SELECT id, source, provider, path, remote_url, preferred, sort_order
		FROM media_images
		WHERE media_id = ? AND image_type = ?
		ORDER BY preferred DESC, sort_order ASC, id ASC`, mediaID, kind)
	if err != nil {
		return seed
	}
	defer rows.Close()
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			return seed
		}
		var imageID, source, provider, path, remoteURL string
		var preferred, sortOrder int
		if err := rows.Scan(&imageID, &source, &provider, &path, &remoteURL, &preferred, &sortOrder); err != nil {
			continue
		}
		seed += strings.Join([]string{imageID, source, provider, path, remoteURL, strconv.Itoa(preferred), strconv.Itoa(sortOrder)}, "\x00")
	}
	return seed
}

func appendArtworkVersionParam(raw string, key string, value string) string {
	if strings.TrimSpace(value) == "" || strings.Contains(raw, key+"=") {
		return raw
	}
	separator := "?"
	if strings.Contains(raw, "?") {
		separator = "&"
	}
	return raw + separator + url.QueryEscape(key) + "=" + url.QueryEscape(value)
}

func (s *Server) mediaHasArtworkCandidate(mediaID string, kind string) bool {
	return s.mediaHasArtworkCandidateContext(context.Background(), mediaID, kind)
}

func (s *Server) mediaHasArtworkCandidateContext(ctx context.Context, mediaID string, kind string) bool {
	if strings.TrimSpace(mediaID) == "" || strings.TrimSpace(kind) == "" {
		return false
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if _, ok := s.mediaImagePathContext(ctx, mediaID, kind); ok {
		return true
	}
	return false
}

func videoSourceLabel(item MediaItem) string {
	switch item.Type {
	case "movie":
		if item.Year >= 2025 {
			return "4K HDR HEVC"
		}
		return "1080p H.264"
	case "episode", "show", "anime":
		return "1080p H.264"
	case "album", "track", "audiobook":
		return "Audio"
	default:
		return "Original"
	}
}

func audioSourceLabel(item MediaItem) string {
	switch item.Type {
	case "album", "track", "audiobook":
		return "AAC Stereo"
	case "movie":
		return "TrueHD 7.1"
	default:
		return "EAC3 5.1"
	}
}

func ownerPermissions() map[string]bool {
	return map[string]bool{
		"playMedia":           true,
		"downloadMedia":       true,
		"editMetadata":        true,
		"manageLyrics":        true,
		"manageSubtitles":     true,
		"watchWithFriends":    true,
		"viewLiveTV":          true,
		"playLiveTV":          true,
		"viewDVR":             true,
		"scheduleDVR":         true,
		"manageDVR":           true,
		"deleteDVRRecordings": true,
		"deleteMedia":         true,
		"transcode":           true,
	}
}

func permissionsForRole(role string) map[string]bool {
	if role == "owner" {
		return ownerPermissions()
	}
	return map[string]bool{
		"playMedia":           true,
		"downloadMedia":       false,
		"editMetadata":        false,
		"manageLyrics":        false,
		"manageSubtitles":     false,
		"watchWithFriends":    false,
		"viewLiveTV":          true,
		"playLiveTV":          true,
		"viewDVR":             false,
		"scheduleDVR":         false,
		"manageDVR":           false,
		"deleteDVRRecordings": false,
		"deleteMedia":         false,
		"transcode":           true,
	}
}

func sanitizePermissions(input map[string]bool, role string) map[string]bool {
	permissions := permissionsForRole(role)
	if role == "owner" {
		return permissions
	}
	for key := range permissions {
		permissions[key] = input[key]
	}
	return permissions
}

func validateUserGrantablePermissions(input map[string]bool) error {
	grantable := map[string]bool{}
	for _, permission := range permissionCatalog() {
		grantable[permission] = true
	}
	for permission := range input {
		if !grantable[permission] {
			return fmt.Errorf("permissions.%s cannot be granted to a server user", permission)
		}
	}
	return nil
}

func permissionCatalog() []string {
	return foundationcontract.GrantablePermissionIDs()
}

func hasPermission(user User, permission string) bool {
	if canInteractivelyManageServer(user) {
		return true
	}
	if permission == "manageServer" || permission == "manageLibraries" || permission == "manageUsers" {
		return false
	}
	return user.Permissions[permission]
}

func canViewLiveTV(user User) bool {
	return hasPermission(user, "viewLiveTV") || hasPermission(user, "playLiveTV") || hasPermission(user, "manageDVR")
}

func canPlayLiveTV(user User) bool {
	return hasPermission(user, "playLiveTV")
}

func canManageLiveTV(user User) bool {
	return canManageLiveTVSources(user)
}

// Live TV source configuration and operational provider state are server
// administration. They require an interactive owner session: API keys remain
// automation principals and never receive source credentials, provider
// errors, or tuner configuration.
func canInteractivelyManageServer(user User) bool {
	return strings.EqualFold(strings.TrimSpace(user.Role), "owner") &&
		selectedProfileMayManageAccount(user) &&
		!strings.EqualFold(strings.TrimSpace(user.AuthProvider), "api_key") &&
		strings.TrimSpace(user.APIKeyID) == ""
}

func canManageLiveTVSources(user User) bool {
	return canInteractivelyManageServer(user)
}

func canViewDVR(user User) bool {
	return hasPermission(user, "viewDVR") || hasPermission(user, "scheduleDVR") || hasPermission(user, "deleteDVRRecordings") || hasPermission(user, "manageDVR")
}

func canScheduleDVR(user User) bool {
	return hasPermission(user, "scheduleDVR") || hasPermission(user, "manageDVR")
}

func canManageDVR(user User) bool {
	return hasPermission(user, "manageDVR")
}

func canDeleteDVRRecording(user User) bool {
	return hasPermission(user, "deleteDVRRecordings") || hasPermission(user, "manageDVR")
}

func canViewServerSettings(user User) bool {
	return canInteractivelyManageServer(user)
}

func canWriteSettingGroup(user User, key string) bool {
	return canInteractivelyManageServer(user)
}

func allowedSettingKeysForUser(user User) []string {
	if !canInteractivelyManageServer(user) {
		return []string{}
	}
	return []string{"server", "devices", "dlna", "dvr", "library", "languages", "metadataAgents", "network", "notifications", "viewerFeedback", "optimizedVersions", "retention", "scheduledTasks", "transcoder", "troubleshooting"}
}

func allowedSettingsSummaryIDsForUser(user User) map[string]bool {
	if canInteractivelyManageServer(user) {
		return map[string]bool{}
	}
	return map[string]bool{}
}

func canManageLyrics(user User) bool {
	return hasPermission(user, "editMetadata") || hasPermission(user, "manageLyrics")
}

func canManageSubtitles(user User) bool {
	return hasPermission(user, "editMetadata") || hasPermission(user, "manageSubtitles")
}

func normalizeUserRole(role string) string {
	switch strings.ToLower(strings.TrimSpace(role)) {
	case "owner":
		return "owner"
	case "admin", "administrator":
		return "user"
	case "":
		return ""
	case "regular", "regular_user", "user", "managed":
		return "user"
	default:
		return "user"
	}
}

func normalizeUsername(username string) string {
	username = strings.ToLower(strings.TrimSpace(username))
	if len(username) < 3 || len(username) > 32 {
		return ""
	}
	for _, char := range username {
		if (char >= 'a' && char <= 'z') || (char >= '0' && char <= '9') || char == '.' || char == '-' || char == '_' {
			continue
		}
		return ""
	}
	return username
}

func isWritableSettingGroup(key string) bool {
	_, ok := canonicalSettingRegistry[key]
	return ok
}

