func normalizeWritableSettingGroup(key string, raw json.RawMessage) (json.RawMessage, error) {
	var group map[string]any
	if err := json.Unmarshal(raw, &group); err != nil {
		return nil, fmt.Errorf("%s settings must be a JSON object", key)
	}
	schema, ok := writableSettingSchemas[key]
	if !ok {
		return nil, fmt.Errorf("%s settings are not writable", key)
	}
	for field, value := range group {
		kind, ok := schema[field]
		if !ok {
			return nil, fmt.Errorf("%s.%s is not a supported setting", key, field)
		}
		if err := validateSettingFieldValue(key, field, kind, value); err != nil {
			return nil, err
		}
	}
	if err := validateSettingGroupPolicy(key, group); err != nil {
		return nil, err
	}
	return json.Marshal(group)
}

func mergeAndNormalizeWritableSettingGroup(key string, current any, patch json.RawMessage) (json.RawMessage, error) {
	schema, ok := writableSettingSchemas[key]
	if !ok {
		return nil, fmt.Errorf("%s settings are not writable", key)
	}
	merged := map[string]any{}
	if currentGroup, ok := current.(map[string]any); ok {
		for field, value := range currentGroup {
			if _, supported := schema[field]; supported {
				merged[field] = value
			}
		}
	}
	var patchGroup map[string]any
	if err := json.Unmarshal(patch, &patchGroup); err != nil {
		return nil, fmt.Errorf("%s settings must be a JSON object", key)
	}
	for field, value := range patchGroup {
		merged[field] = value
	}
	bytes, err := json.Marshal(merged)
	if err != nil {
		return nil, err
	}
	return normalizeWritableSettingGroup(key, bytes)
}

func settingJSONEqual(current any, normalized json.RawMessage) bool {
	currentBytes, err := json.Marshal(current)
	if err != nil {
		return false
	}
	var normalizedValue any
	if err := json.Unmarshal(normalized, &normalizedValue); err != nil {
		return false
	}
	normalizedBytes, err := json.Marshal(normalizedValue)
	return err == nil && bytes.Equal(currentBytes, normalizedBytes)
}

func validateSettingFieldValue(group, field string, kind settingFieldType, value any) error {
	switch kind {
	case settingFieldBool:
		if _, ok := value.(bool); !ok {
			return fmt.Errorf("%s.%s must be a boolean", group, field)
		}
	case settingFieldNumber:
		number, ok := value.(float64)
		if !ok || math.IsNaN(number) || math.IsInf(number, 0) || math.Trunc(number) != number {
			return fmt.Errorf("%s.%s must be an integer", group, field)
		}
	case settingFieldString:
		text, ok := value.(string)
		if !ok || len([]rune(text)) > 8192 {
			return fmt.Errorf("%s.%s must be a string", group, field)
		}
	case settingFieldStringList:
		items, ok := value.([]any)
		if !ok || len(items) > 512 {
			return fmt.Errorf("%s.%s must be an array of strings", group, field)
		}
		seen := map[string]bool{}
		for _, item := range items {
			text, ok := item.(string)
			text = strings.TrimSpace(text)
			if !ok || text == "" || len([]rune(text)) > 256 || seen[text] {
				return fmt.Errorf("%s.%s must be an array of strings", group, field)
			}
			seen[text] = true
		}
	case settingFieldObject:
		object, ok := value.(map[string]any)
		if !ok {
			return fmt.Errorf("%s.%s must be an object", group, field)
		}
		if group == "scheduledTasks" && field == "taskTriggers" {
			for taskID, rawTrigger := range object {
				if !knownScheduledTaskID(taskID) {
					return fmt.Errorf("%s.%s contains unsupported task %s", group, field, taskID)
				}
				trigger, ok := rawTrigger.(map[string]any)
				if !ok {
					return fmt.Errorf("%s.%s.%s must be an object", group, field, taskID)
				}
				for triggerField, triggerValue := range trigger {
					switch triggerField {
					case "enabled":
						if _, ok := triggerValue.(bool); !ok {
							return fmt.Errorf("%s.%s.%s.enabled must be a boolean", group, field, taskID)
						}
					case "intervalHours":
						number, ok := triggerValue.(float64)
						if !ok || math.IsNaN(number) || math.IsInf(number, 0) || math.Trunc(number) != number || number < 1 || number > 8760 {
							return fmt.Errorf("%s.%s.%s.intervalHours must be an integer between 1 and 8760", group, field, taskID)
						}
					default:
						return fmt.Errorf("%s.%s.%s.%s is not a supported setting", group, field, taskID, triggerField)
					}
				}
			}
		}
	case settingFieldOptimizedTemplates:
		if err := validateOptimizedVersionTemplates(value); err != nil {
			return fmt.Errorf("%s.%s %w", group, field, err)
		}
	}
	return validateSettingFieldPolicy(group, field, value)
}

func validateSettingFieldPolicy(group, field string, value any) error {
	text, _ := value.(string)
	number, _ := value.(float64)
	switch group + "." + field {
	case "server.friendlyName":
		if len([]rune(strings.TrimSpace(text))) == 0 || len([]rune(text)) > 120 {
			return fmt.Errorf("%s.%s must be 1 to 120 characters", group, field)
		}
	case "server.operatorNote":
		if len([]rune(text)) > 500 {
			return fmt.Errorf("%s.%s must be at most 500 characters", group, field)
		}
	case "retention.playbackDetailDays", "retention.playbackHistoryDays", "retention.auditHistoryDays", "retention.diagnosticHistoryDays", "retention.clientDiagnosticHistoryDays", "retention.jobHistoryDays", "retention.authRequestDays", "retention.deviceIPDays":
		if number < 0 || number > 36500 {
			return fmt.Errorf("%s.%s must be between 0 (forever) and 36500", group, field)
		}
	case "metadataAgents.movies", "metadataAgents.tv":
		if !oneOfString(text, "TMDB", "TVDB", "None") {
			return fmt.Errorf("%s.%s must be TMDB, TVDB, or None", group, field)
		}
	case "metadataAgents.moviesFallback", "metadataAgents.tvFallback":
		if !oneOfString(text, "TMDB", "TVDB", "None") {
			return fmt.Errorf("%s.%s must be TMDB, TVDB, or None", group, field)
		}
	case "metadataAgents.anime":
		if !oneOfString(text, "AniList", "TMDB", "None") {
			return fmt.Errorf("%s.%s must be AniList, TMDB, or None", group, field)
		}
	case "metadataAgents.music":
		if !oneOfString(text, "MusicBrainz", "None") {
			return fmt.Errorf("%s.%s must be MusicBrainz or None", group, field)
		}
	case "metadataAgents.refreshDays", "scheduledTasks.backupRetentionDays", "scheduledTasks.libraryScanIntervalHours", "scheduledTasks.metadataRefreshDays", "optimizedVersions.maxConcurrentJobs", "optimizedVersions.maxPerItem", "dvr.defaultRetentionDays":
		if number < 1 {
			return fmt.Errorf("%s.%s must be at least 1", group, field)
		}
		if group == "optimizedVersions" && field == "maxConcurrentJobs" && number > 4 {
			return fmt.Errorf("%s.%s must be no more than 4", group, field)
		}
		if number > 36500 {
			return fmt.Errorf("%s.%s must be no more than 36500", group, field)
		}
	case "dvr.defaultGuideRefreshIntervalHours":
		if number < 1 || number > 168 {
			return fmt.Errorf("%s.%s must be between 1 and 168", group, field)
		}
	case "dvr.defaultMaxRecordingsPerSeries":
		if number < 0 || number > 10000 {
			return fmt.Errorf("%s.%s must be between 0 and 10000", group, field)
		}
	case "dvr.defaultStartPaddingMinutes", "dvr.defaultEndPaddingMinutes":
		if number < 0 || number > 1440 {
			return fmt.Errorf("%s.%s must be between 0 and 1440", group, field)
		}
	case "viewerFeedback.feedbackRetentionDays", "viewerFeedback.notificationRetentionDays":
		if number < 7 || number > 730 {
			return fmt.Errorf("%s.%s must be between 7 and 730", group, field)
		}
	case "library.trashRetentionDays", "scheduledTasks.trashRetentionDays", "scheduledTasks.trickplayRetentionDays", "optimizedVersions.retentionDays":
		if number < 0 || number > 36500 {
			return fmt.Errorf("%s.%s must be between 0 and 36500", group, field)
		}
	case "library.trickplayIntervalSeconds", "scheduledTasks.trickplayIntervalSeconds":
		if number < 0 || number > 3600 {
			return fmt.Errorf("%s.%s must be between 0 and 3600", group, field)
		}
	case "library.trickplayTileWidth", "scheduledTasks.trickplayTileWidth":
		if number < 96 || number > 640 {
			return fmt.Errorf("%s.%s must be between 96 and 640", group, field)
		}
	case "library.trickplayMaxTiles", "scheduledTasks.trickplayMaxTiles":
		if number < 24 || number > 2000 {
			return fmt.Errorf("%s.%s must be between 24 and 2000", group, field)
		}
	case "optimizedVersions.maxStorageMB", "scheduledTasks.trickplayMaxStorageMB":
		if number < 0 || number > 1_000_000_000 {
			return fmt.Errorf("%s.%s must be between 0 and 1000000000", group, field)
		}
	case "optimizedVersions.defaultProfile":
		if _, ok := optimized.Lookup(strings.TrimSpace(text)); !ok {
			return fmt.Errorf("%s.%s must be a supported optimized-version profile", group, field)
		}
	case "optimizedVersions.storageDirectory":
		if strings.TrimSpace(text) != "" && !filepath.IsAbs(filepath.Clean(strings.TrimSpace(text))) {
			return fmt.Errorf("%s.%s must be an absolute path or blank", group, field)
		}
	case "scheduledTasks.startHour", "scheduledTasks.endHour":
		if number < 0 || number > 23 {
			return fmt.Errorf("%s.%s must be between 0 and 23", group, field)
		}
	case "scheduledTasks.maintenanceWindow":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "overnight", "late-night", "always", "custom") {
			return fmt.Errorf("%s.%s must be overnight, late-night, always, or custom", group, field)
		}
	case "scheduledTasks.maintenanceDays":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "every-day", "weekdays", "weekends") {
			return fmt.Errorf("%s.%s must be every-day, weekdays, or weekends", group, field)
		}
	case "scheduledTasks.maintenanceTimezone":
		zone := strings.TrimSpace(text)
		if zone == "" {
			return fmt.Errorf("%s.%s must be an IANA timezone such as UTC or America/Halifax", group, field)
		}
		if _, err := time.LoadLocation(zone); err != nil {
			return fmt.Errorf("%s.%s must be a valid IANA timezone", group, field)
		}
	case "scheduledTasks.backupCadence", "scheduledTasks.libraryScanCadence", "scheduledTasks.metadataRefreshCadence", "scheduledTasks.analysisCadence":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "hourly", "daily", "weekly", "monthly", "custom") {
			return fmt.Errorf("%s.%s must be hourly, daily, weekly, monthly, or custom", group, field)
		}
	case "dvr.recordingProfile":
		if !oneOfString(text, "copy", "h264-1080p-8m", "h264-720p-4m") {
			return fmt.Errorf("%s.%s must be copy, h264-1080p-8m, or h264-720p-4m", group, field)
		}
	case "dvr.defaultFolder":
		if text != normalizeDVRFolder(text) {
			return fmt.Errorf("%s.%s must be a safe folder name of at most 80 characters", group, field)
		}
	case "dvr.recordingPathTemplate":
		if err := validateDVRRecordingPathTemplate(text); err != nil {
			return fmt.Errorf("%s.%s %w", group, field, err)
		}
	case "library.generateVideoPreview", "library.chapterThumbnailMode":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "never", "scheduled", "on-scan") {
			return fmt.Errorf("%s.%s must be never, scheduled, or on-scan", group, field)
		}
	case "library.analysisTier":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), analysisTierFileListOnly, analysisTierBasic, analysisTierComplete, analysisTierCustom) {
			return fmt.Errorf("%s.%s must be file_list_only, basic, complete, or custom", group, field)
		}
	case "metadataAgents.metadataLanguage":
		if !validMetadataLanguageSetting(text) {
			return fmt.Errorf("%s.%s must be a BCP-47 language tag", group, field)
		}
	case "network.secureConnections":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "preferred", "required", "disabled") {
			return fmt.Errorf("%s.%s must be preferred, required, or disabled", group, field)
		}
	case "network.lanNetworks":
		for _, item := range splitSettingsList(text) {
			if _, _, err := net.ParseCIDR(item); err != nil {
				return fmt.Errorf("%s.%s contains invalid CIDR %q", group, field, item)
			}
		}
	case "network.customAccessUrls":
		for _, item := range splitSettingsList(text) {
			parsed, err := url.Parse(item)
			if err != nil || parsed.Host == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.User != nil {
				return fmt.Errorf("%s.%s contains an invalid HTTP(S) URL", group, field)
			}
		}
	case "dlna.advertiseUrl":
		if strings.TrimSpace(text) != "" {
			parsed, err := url.Parse(text)
			if err != nil || parsed.Host == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.User != nil {
				return fmt.Errorf("%s.%s must be a valid HTTP(S) URL or blank", group, field)
			}
		}
	case "transcoder.temporaryDirectory":
		if strings.TrimSpace(text) != "" && !filepath.IsAbs(filepath.Clean(strings.TrimSpace(text))) {
			return fmt.Errorf("%s.%s must be an absolute path or blank", group, field)
		}
	case "notifications.minAlertLevel":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "info", "warn", "error") {
			return fmt.Errorf("%s.%s must be info, warn, or error", group, field)
		}
	case "troubleshooting.logLevel":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "debug", "info", "warn") {
			return fmt.Errorf("%s.%s must be debug, info, or warn", group, field)
		}
	case "troubleshooting.debugDurationMinutes":
		if number < 5 || number > 1440 {
			return fmt.Errorf("%s.%s must be between 5 and 1440", group, field)
		}
	case "devices.quickConnectApprovalMode":
		if !oneOfString(text, "allUsers", "ownerOnly") {
			return fmt.Errorf("%s.%s must be allUsers or ownerOnly", group, field)
		}
	case "languages.subtitleMode":
		if !oneOfString(text, "manual", "always", "foreignAudio") {
			return fmt.Errorf("%s.%s must be manual, always, or foreignAudio", group, field)
		}
	case "transcoder.maxConcurrentSessions", "transcoder.maxHardwareSessions", "transcoder.maxSoftwareSessions", "transcoder.maxBackgroundSessions":
		if number < 0 || number > 64 {
			return fmt.Errorf("%s.%s must be between 0 and 64", group, field)
		}
	case "transcoder.throttleBufferSeconds":
		if number < 10 || number > 3600 {
			return fmt.Errorf("%s.%s must be between 10 and 3600", group, field)
		}
	case "transcoder.playedRetentionSeconds":
		if number < 0 || number > 86400 {
			return fmt.Errorf("%s.%s must be between 0 and 86400", group, field)
		}
	case "transcoder.x264Preset":
		if !oneOfString(text, "ultrafast", "superfast", "veryfast", "faster", "fast", "medium", "slow", "slower") {
			return fmt.Errorf("%s.%s is not a supported H.264 preset", group, field)
		}
	case "transcoder.planningPolicy":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "maximum_fidelity", "maximum_compatibility", "minimize_server_work") {
			return fmt.Errorf("%s.%s must be maximum_fidelity, maximum_compatibility, or minimize_server_work", group, field)
		}
	case "transcoder.hardwareDevice":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "auto", "videotoolbox", "vaapi", "qsv", "cuda", "nvenc", "nvidia", "amf") {
			return fmt.Errorf("%s.%s is not a supported hardware device backend", group, field)
		}
	case "transcoder.hdrToneMappingAlgorithm":
		if !oneOfString(strings.ToLower(strings.TrimSpace(text)), "clip", "linear", "gamma", "hable", "reinhard", "mobius") {
			return fmt.Errorf("%s.%s is not a supported tone-mapping algorithm", group, field)
		}
	}
	return nil
}

func validateSettingGroupPolicy(group string, values map[string]any) error {
	switch group {
	case "optimizedVersions":
		defaultProfile, _ := values["defaultProfile"].(string)
		templates, _ := values["templates"].([]any)
		if defaultProfile != "" && len(templates) > 0 {
			foundEnabled := false
			for _, raw := range templates {
				if template, ok := raw.(map[string]any); ok && template["profile"] == defaultProfile && template["enabled"] == true {
					foundEnabled = true
				}
			}
			if !foundEnabled {
				return fmt.Errorf("%s.defaultProfile must reference an enabled template", group)
			}
		}
		if enabled, _ := values["autoDelete"].(bool); enabled {
			retention, _ := values["retentionDays"].(float64)
			perItem, _ := values["maxPerItem"].(float64)
			storage, _ := values["maxStorageMB"].(float64)
			if retention <= 0 && perItem <= 0 && storage <= 0 {
				return fmt.Errorf("%s.autoDelete requires at least one positive retention or storage limit", group)
			}
		}
	case "transcoder":
		// Hardware decode and encode are independent. Encode-only paths are
		// explicitly supported and admitted as hardware sessions.
	case "scheduledTasks":
		window, _ := values["maintenanceWindow"].(string)
		start, startOK := values["startHour"].(float64)
		end, endOK := values["endHour"].(float64)
		if strings.EqualFold(strings.TrimSpace(window), "custom") && startOK && endOK && start == end {
			return fmt.Errorf("%s.endHour must differ from startHour for a custom maintenance window", group)
		}
	case "library":
		if err := validateCustomAnalysisDependencies(values); err != nil {
			return err
		}
	}
	return nil
}

func validateCustomAnalysisDependencies(values map[string]any) error {
	if !strings.EqualFold(strings.TrimSpace(settingString(values, "analysisTier", analysisTierBasic)), analysisTierCustom) {
		return nil
	}
	probeStreams := settingBool(values, "probeStreams", false)
	for _, field := range []string{
		"readEmbeddedTags", "readEmbeddedIndexes", "generateRepresentativeThumbnail",
		"extractSelectedEmbeddedAssets", "validateSeekBehavior",
		"generateTrickplay", "generateChapterThumbnails", "generateWaveforms", "analyzeLoudness",
		"sonicFingerprinting", "detectSegments", "extractAllEmbeddedAttachments",
		"analyzeSTRMTarget",
	} {
		if settingBool(values, field, false) && !probeStreams {
			return fmt.Errorf("library.%s requires library.probeStreams in Custom", field)
		}
	}
	for _, field := range []string{"extractSelectedEmbeddedAssets", "generateChapterThumbnails", "detectSegments", "extractAllEmbeddedAttachments"} {
		if settingBool(values, field, false) && !settingBool(values, "readEmbeddedIndexes", false) {
			return fmt.Errorf("library.%s requires library.readEmbeddedIndexes in Custom", field)
		}
	}
	return nil
}

func validMetadataLanguageSetting(value string) bool {
	parts := strings.Split(strings.ReplaceAll(strings.TrimSpace(value), "_", "-"), "-")
	if len(parts) < 1 || len(parts) > 3 || len(parts[0]) < 2 || len(parts[0]) > 3 {
		return false
	}
	for index, part := range parts {
		if part == "" || index > 0 && len(part) < 2 || len(part) > 8 {
			return false
		}
		for _, char := range part {
			if char < 'A' || char > 'Z' && char < 'a' || char > 'z' {
				return false
			}
		}
	}
	return true
}

func validateDVRRecordingPathTemplate(value string) error {
	value = strings.TrimSpace(value)
	if value == "" || len(value) > 240 || normalizeDVRRecordingPathTemplate(value) != value {
		return errors.New("must be a normalized relative template of at most 240 characters")
	}
	allowed := []string{"{folder}", "{title}", "{id}", "{channel}", "{year}", "{month}", "{day}", "{start}"}
	remainder := value
	for _, token := range allowed {
		remainder = strings.ReplaceAll(remainder, token, "")
	}
	if strings.ContainsAny(remainder, "{}") {
		return errors.New("contains an unsupported placeholder")
	}
	last := value[strings.LastIndex(value, "/")+1:]
	if strings.TrimSpace(last) == "" || last == "{folder}" {
		return errors.New("must produce a recording filename")
	}
	return nil
}

func validateOptimizedVersionTemplates(value any) error {
	values, ok := value.([]any)
	registry := optimized.List()
	if !ok || len(values) != len(registry) {
		return errors.New("must contain the exact eight checked-in optimized presets")
	}
	for index, raw := range values {
		template, ok := raw.(map[string]any)
		if !ok {
			return fmt.Errorf("template %d must be an object", index+1)
		}
		for key := range template {
			if key != "id" && key != "name" && key != "profile" && key != "enabled" {
				return fmt.Errorf("template %d contains unsupported field %q", index+1, key)
			}
		}
		want := registry[index]
		id, idOK := template["id"].(string)
		name, nameOK := template["name"].(string)
		profile, profileOK := template["profile"].(string)
		isEnabled, enabledOK := template["enabled"].(bool)
		if !idOK || strings.TrimSpace(id) != "preset-"+want.ID || !nameOK || strings.TrimSpace(name) != want.Label ||
			!profileOK || strings.TrimSpace(profile) != want.ID || !enabledOK || !isEnabled {
			return fmt.Errorf("template %d must match checked-in preset %q", index+1, want.ID)
		}
	}
	return nil
}

func validUTCMaintenanceWindow(value string) bool {
	parts := strings.Split(strings.TrimSpace(value), "-")
	if len(parts) != 2 {
		return false
	}
	return validHHMM(parts[0]) && validHHMM(parts[1])
}

func validHHMM(value string) bool {
	parts := strings.Split(strings.TrimSpace(value), ":")
	if len(parts) != 2 {
		return false
	}
	hour, err := strconv.Atoi(parts[0])
	if err != nil || hour < 0 || hour > 23 || len(parts[0]) != 2 {
		return false
	}
	minute, err := strconv.Atoi(parts[1])
	return err == nil && minute >= 0 && minute <= 59 && len(parts[1]) == 2
}

func oneOfString(value string, allowed ...string) bool {
	for _, candidate := range allowed {
		if value == candidate {
			return true
		}
	}
	return false
}

func decodeJSON(w http.ResponseWriter, r *http.Request, target any) bool {
	defer r.Body.Close()
	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		var fieldErr *requestFieldValidationError
		if errors.As(err, &fieldErr) {
			writeProductErrorWithDetails(w, http.StatusBadRequest, "invalid_user_field", fieldErr.Detail, map[string]any{"fieldPath": fieldErr.FieldPath})
			return false
		}
		writeError(w, http.StatusBadRequest, "bad_json", "Request body must be valid JSON.")
		return false
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "bad_json", "Request body must contain exactly one JSON value.")
		return false
	}
	return true
}

func writeJSON(w http.ResponseWriter, status int, payload any) {
	if w.Header().Get("Content-Type") == "" {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
	}
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

func writeError(w http.ResponseWriter, status int, code string, message string) {
	writeProductError(w, status, code, message)
}

func randomID(prefix string) string {
	bytes := make([]byte, 12)
	if _, err := rand.Read(bytes); err != nil {
		panic(err)
	}
	return prefix + "_" + base64.RawURLEncoding.EncodeToString(bytes)
}

func randomOpaqueMediaID() string {
	bytes := make([]byte, 20)
	if _, err := rand.Read(bytes); err != nil {
		panic(err)
	}
	return hex.EncodeToString(bytes)
}

// randomOpaquePublicID is the canonical identifier generator for resources
// that cross the API boundary. Public IDs intentionally contain no type,
// ingestion, provider, or storage hint; the resource context supplies type.
func randomOpaquePublicID() string {
	return randomOpaqueMediaID()
}

func randomToken() string {
	bytes := make([]byte, 32)
	if _, err := rand.Read(bytes); err != nil {
		panic(err)
	}
	return base64.RawURLEncoding.EncodeToString(bytes)
}

func hashToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

func boolInt(value bool) int {
	if value {
		return 1
	}
	return 0
}

func titleize(value string) string {
	parts := strings.FieldsFunc(value, func(r rune) bool { return r == '_' || r == '-' })
	for i := range parts {
		if parts[i] == "" {
			continue
		}
		parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
	}
	return strings.Join(parts, " ")
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func sortMediaByTitle(items []MediaItem) {
	sort.Slice(items, func(i, j int) bool {
		return items[i].SortTitle < items[j].SortTitle
	})
}
